window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MAT"]={"book":"MAT","editions":{"dan-1819":[[1,1,"Jesu Christi, Davids Søns, Abrahams Søns, Slægtebog.","Jesu Christi, Davids Søns, Abrahams Søns, Slægtebog."],[1,2,"Abraham avlede Isaak; og Isaak avlede Jakob; og Jakob avlede Juda og hans Brødre;","Abraham avlede Isaak; og Isaak avlede Jakob; og Jakob avlede Juda og hans Brødre;"],[1,3,"og Juda avlede Phares og Zara med Thamar; og Phares avlede Esrom; og Esrom avlede Aram;","og Juda avlede Phares og Zara med Thamar; og Phares avlede Esrom; og Esrom avlede Aram;"],[1,4,"og Aram avlede Aminadab; og Aminadab avlede Naasson; og Naasson avlede Salmon;","og Aram avlede Aminadab; og Aminadab avlede Naasson; og Naasson avlede Salmon;"],[1,5,"og Salmon avlede Booz med Rachab; og Booz avlede Obed med Ruth; og Obed avlede Jessai;","og Salmon avlede Booz med Rachab; og Booz avlede Obed med Ruth; og Obed avlede Jessai;"],[1,6,"og Jessai avlede Kong David; og Kong David avlede Salomon med Urias’ Hustru;","og Jessai avlede Kong David; og Kong David avlede Salomon med Urias’ Hustru;"],[1,7,"og Salomon avlede Roboam; og Roboam avlede Abia; og Abia avlede Asa;","og Salomon avlede Roboam; og Roboam avlede Abia; og Abia avlede Asa;"],[1,8,"og Asa avlede Josaphat; og Josaphat avlede Joram; og Joram avlede Ozias;","og Asa avlede Josaphat; og Josaphat avlede Joram; og Joram avlede Ozias;"],[1,9,"og Ozias avlede Joatham; og Joatham avlede Achas; og Achas avlede Ezechias;","og Ozias avlede Joatham; og Joatham avlede Achas; og Achas avlede Ezechias;"],[1,10,"og Ezechias avlede Manasse; og Manasse avlede Amon; og Amon avlede Josias;","og Ezechias avlede Manasse; og Manasse avlede Amon; og Amon avlede Josias;"],[1,11,"og Josias avlede Jechonias og hans Brødre ved den babyloniske Udlændigheds Tid.","og Josias avlede Jechonias og hans Brødre ved den babyloniske Udlændigheds Tid."],[1,12,"Men efter den babyloniske Udlændighed avlede Jechonias Salathiel; og Salathiel avlede Zorobabel;","Men efter den babyloniske Udlændighed avlede Jechonias Salathiel; og Salathiel avlede Zorobabel;"],[1,13,"og Zorobabel avlede Abiud; og Abiud avlede Eliakim; og Eliakim avlede Azor;","og Zorobabel avlede Abiud; og Abiud avlede Eliakim; og Eliakim avlede Azor;"],[1,14,"og Azor avlede Sadok; og Sadok avlede Achim; og Achim avlede Eliud;","og Azor avlede Sadok; og Sadok avlede Achim; og Achim avlede Eliud;"],[1,15,"og Eliud avlede Eleazar; og Eleazar avlede Matthan; og Matthan avlede Jakob;","og Eliud avlede Eleazar; og Eleazar avlede Matthan; og Matthan avlede Jakob;"],[1,16,"og Jakob avlede Joseph, Marias Mand; af hende er Jesus født, som kaldes Christus.","og Jakob avlede Joseph, Marias Mand; af hende er Jesus født, som kaldes Christus."],[1,17,"Altsaa ere alle Led fra Abraham indtil David fjorten Led, og fra David indtil den babyloniske Udlændighed fjorten Led, og fra den babyloniske Udlændighed indtil Christus fjorten Led.","Altsaa ere alle Led fra Abraham indtil David fjorten Led, og fra David indtil den babyloniske Udlændighed fjorten Led, og fra den babyloniske Udlændighed indtil Christus fjorten Led."],[1,18,"Men Jesu Christi Fødsel gik saa til. Der Maria, hans Moder, var Joseph trolovet, befandtes hun, førend de kom sammen, at være frugtsommelig af den Hellig Aand.","Men Jesu Christi Fødsel gik saa til. Der Maria, hans Moder, var Joseph trolovet, befandtes hun, førend de kom sammen, at være frugtsommelig af den Hellig Aand."],[1,19,"Men Joseph, hendes Mand, efterdi han var retsindig og ikke vilde offentlig beskæmme hende, besluttede hemmelig at skille sig fra hende.","Men Joseph, hendes Mand, efterdi han var retsindig og ikke vilde offentlig beskæmme hende, besluttede hemmelig at skille sig fra hende."],[1,20,"Men idet han tænkte derpaa, see, da aabenbaredes Herrens Engel for ham i en Drøm og sagde: Joseph, Davids Søn! frygt ikke at annamme din Hustru Maria; thi det, som er avlet i hende er af den Hellig Aand.","Men idet han tænkte derpaa, see, da aabenbaredes Herrens Engel for ham i en Drøm og sagde: Joseph, Davids Søn! frygt ikke at annamme din Hustru Maria; thi det, som er avlet i hende er af den Hellig Aand."],[1,21,"Men hun skal føde en Søn, og du skal kalde hans Navn Jesus; thi han skal frelse sit Folk fra deres Synder.","Men hun skal føde en Søn, og du skal kalde hans Navn Jesus; thi han skal frelse sit Folk fra deres Synder."],[1,22,"Men dette skete altsammen, at det skulde fuldkommes, som er talet af Herren ved Propheten, som siger:","Men dette skete altsammen, at det skulde fuldkommes, som er talet af Herren ved Propheten, som siger:"],[1,23,"see, en Jomfru skal blive frugtsommelig og føde en Søn, og man skal kalde hans Navn Immanuel, hvilket er udlagt: Gud med os.","see, en Jomfru skal blive frugtsommelig og føde en Søn, og man skal kalde hans Navn Immanuel, hvilket er udlagt: Gud med os."],[1,24,"Men der Joseph vaagnede op af Søvnen, gjorde han, som Herrens Engel havde befalet ham, og han annammede sin Hustru.","Men der Joseph vaagnede op af Søvnen, gjorde han, som Herrens Engel havde befalet ham, og han annammede sin Hustru."],[1,25,"Og han kjendte hende ikke, indtil hun havde født sin Søn den førstefødte, og han kaldte hans Navn Jesus.","Og han kjendte hende ikke, indtil hun havde født sin Søn den førstefødte, og han kaldte hans Navn Jesus."],[2,1,"Men der Jesus var født i Bethlehem i Judæa, udi Kong Herodes’ Dage, see, da kom Vise af Østerland til Jerusalem og sagde:","Men der Jesus var født i Bethlehem i Judæa, udi Kong Herodes’ Dage, see, da kom Vise af Østerland til Jerusalem og sagde:"],[2,2,"hvor er den Jødernes Konge, som er født? thi vi have seet hans Stjerne i Øster, og ere komne at tilbede ham.","hvor er den Jødernes Konge, som er født? thi vi have seet hans Stjerne i Øster, og ere komne at tilbede ham."],[2,3,"Men der Kong Herodes det hørte, blev han forfærdet, og al Jerusalem med ham;","Men der Kong Herodes det hørte, blev han forfærdet, og al Jerusalem med ham;"],[2,4,"og der han havde forsamlet alle de Ypperstepræster og Skriftkloge iblandt Folket, adspurgte ham dem, hvor Christus skulde fødes.","og der han havde forsamlet alle de Ypperstepræster og Skriftkloge iblandt Folket, adspurgte ham dem, hvor Christus skulde fødes."],[2,5,"Men de sagde til ham: i Bethlehem i Judæa; thi der er saa skrevet ved Propheten:","Men de sagde til ham: i Bethlehem i Judæa; thi der er saa skrevet ved Propheten:"],[2,6,"og du, Bethlehem i Juda’ Land! er ingenlunde den mindste iblandt Juda’ Fyrster; thi af dig skal udgaae en Fyrste, som skal være mit Folks Israels Hyrde.","og du, Bethlehem i Juda’ Land! er ingenlunde den mindste iblandt Juda’ Fyrster; thi af dig skal udgaae en Fyrste, som skal være mit Folks Israels Hyrde."],[2,7,"Da kaldte Herodes de Vise hemmelig og udspurgte nøie Tiden af dem, naar Stjernen havde ladet sig tilsyne.","Da kaldte Herodes de Vise hemmelig og udspurgte nøie Tiden af dem, naar Stjernen havde ladet sig tilsyne."],[2,8,"Og han sendte dem til Bethlehem og sagde: gaaer hen og udspørger flittelig om Barnet; men naar I have fundet det, da forkynder mig det, at jeg og kan komme og tilbede det.","Og han sendte dem til Bethlehem og sagde: gaaer hen og udspørger flittelig om Barnet; men naar I have fundet det, da forkynder mig det, at jeg og kan komme og tilbede det."],[2,9,"Men der de havde hørt Kongen, droge de bort; og see, Stjernen, som de havde seet i Øster, gik hen for dem, indtil den kom og stod ovenover, hvor Barnet var.","Men der de havde hørt Kongen, droge de bort; og see, Stjernen, som de havde seet i Øster, gik hen for dem, indtil den kom og stod ovenover, hvor Barnet var."],[2,10,"Men der de saae Stjernen, bleve de saare meget glade.","Men der de saae Stjernen, bleve de saare meget glade."],[2,11,"Og de gik ind i Huset, og fandt Barnet med dets Moder Maria, og faldt ned og tilbade det, og oplode deres Liggendefæ og offrede det Gaver, Guld og Røgelse og Myrrha.","Og de gik ind i Huset, og fandt Barnet med dets Moder Maria, og faldt ned og tilbade det, og oplode deres Liggendefæ og offrede det Gaver, Guld og Røgelse og Myrrha."],[2,12,"Og der de vare blevne advarede af Gud i en Drøm, at de skulde ikke vende tilbage til Herodes, fore de ad en anden Vei bort til deres Land.","Og der de vare blevne advarede af Gud i en Drøm, at de skulde ikke vende tilbage til Herodes, fore de ad en anden Vei bort til deres Land."],[2,13,"Men der de vare bortfarne, see, da aabenbaredes Herrens Engel for Joseph i en Drøm og sagde: staa op, og tag Barnet og dets Moder, og fly til Ægypten, og bliv der, indtil jeg siger dig til; thi Herodes vil søge efter Barnet, for at omkomme det.","Men der de vare bortfarne, see, da aabenbaredes Herrens Engel for Joseph i en Drøm og sagde: staa op, og tag Barnet og dets Moder, og fly til Ægypten, og bliv der, indtil jeg siger dig til; thi Herodes vil søge efter Barnet, for at omkomme det."],[2,14,"Men han stod op, tog Barnet og dets Moder om Natten, og veg hen til Ægypten.","Men han stod op, tog Barnet og dets Moder om Natten, og veg hen til Ægypten."],[2,15,"Og han blev der, indtil Herodes var død, at det skulle fuldkommes, som var talet af Herren ved Propheten, som siger: fra Ægypten kaldte jeg min Søn.","Og han blev der, indtil Herodes var død, at det skulle fuldkommes, som var talet af Herren ved Propheten, som siger: fra Ægypten kaldte jeg min Søn."],[2,16,"Der Herodes da saae, at han var skuffet af de Vise, blev han saare vred og sendte hen og lod ihjelslaae alle Børn som vare i Bethlehem og i al dens Egn, fra to Aar og derunder, efter den Tid, som han havde udspurgt af de Vise.","Der Herodes da saae, at han var skuffet af de Vise, blev han saare vred og sendte hen og lod ihjelslaae alle Børn som vare i Bethlehem og i al dens Egn, fra to Aar og derunder, efter den Tid, som han havde udspurgt af de Vise."],[2,17,"Da blev det fuldkommet, som talet er af den Prophet Jeremias, som siger:","Da blev det fuldkommet, som talet er af den Prophet Jeremias, som siger:"],[2,18,"en Røst blev hørt udi Rama, Graad og Skrig og megen Hylen; Rachel begræd sine Børn og vilde ikke lade sig husvale, thi de ere ikke mere.","en Røst blev hørt udi Rama, Graad og Skrig og megen Hylen; Rachel begræd sine Børn og vilde ikke lade sig husvale, thi de ere ikke mere."],[2,19,"Men der Herodes var død, see, da aabenbaredes Herrens Engel i en Drøm for Joseph i Ægypten, sigende:","Men der Herodes var død, see, da aabenbaredes Herrens Engel i en Drøm for Joseph i Ægypten, sigende:"],[2,20,"staa op, og tag Barnet og dets Moder, og drag hen til Israels Land; thi de ere døde, som søgte efter Barnets Liv.","staa op, og tag Barnet og dets Moder, og drag hen til Israels Land; thi de ere døde, som søgte efter Barnets Liv."],[2,21,"Men han stod op og tog Barnet og dets Moder og kom til Israels Land.","Men han stod op og tog Barnet og dets Moder og kom til Israels Land."],[2,22,"Men der han hørte, at Archelaus regjerede i Judæa i sin Faders Herodes’ Sted, frygtede han at komme derhen; men han blev advaret af Gud i en Drøm og veg hen til Galilæas Egne.","Men der han hørte, at Archelaus regjerede i Judæa i sin Faders Herodes’ Sted, frygtede han at komme derhen; men han blev advaret af Gud i en Drøm og veg hen til Galilæas Egne."],[2,23,"Og han kom og boede i en Stad, som kaldes Nazareth, at det skulle fuldkommes, som sagt er ved Propheterne: han skal kaldes Nazaræer.","Og han kom og boede i en Stad, som kaldes Nazareth, at det skulle fuldkommes, som sagt er ved Propheterne: han skal kaldes Nazaræer."],[3,1,"Men i de samme Dage fremstod Johannes den Døber, som prædikede i Judæas Ørk og sagde:","Men i de samme Dage fremstod Johannes den Døber, som prædikede i Judæas Ørk og sagde:"],[3,2,"omvender Eder, thi Himmeriges Rige er kommet nær.","omvender Eder, thi Himmeriges Rige er kommet nær."],[3,3,"Thi han er den, om hvilken den Prophet Esaias haver talet, sigende: det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne.","Thi han er den, om hvilken den Prophet Esaias haver talet, sigende: det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne."],[3,4,"Men Johannes havde sit Klædebon af Kameelhaar og et Læderbelte om sin Lænd; men hans Mad var Græshopper og vild Honning.","Men Johannes havde sit Klædebon af Kameelhaar og et Læderbelte om sin Lænd; men hans Mad var Græshopper og vild Honning."],[3,5,"Da udgik Jerusalem til ham og det ganske Judæa og alt Landet omkring Jordanen.","Da udgik Jerusalem til ham og det ganske Judæa og alt Landet omkring Jordanen."],[3,6,"Og de døbtes af ham i Jordanen og bekjendte deres Synder.","Og de døbtes af ham i Jordanen og bekjendte deres Synder."],[3,7,"Men der han saae mange Pharisæer og Sadducæer komme til hans Daab, sagde han til dem: I Øgleunger! hvo viste Eder at flye fra den kommende Vrede?","Men der han saae mange Pharisæer og Sadducæer komme til hans Daab, sagde han til dem: I Øgleunger! hvo viste Eder at flye fra den kommende Vrede?"],[3,8,"Bærer da Omvendelsens værdige Frugter,","Bærer da Omvendelsens værdige Frugter,"],[3,9,"og mener ikke at ville sige ved Eder selv: vi have Abraham til Fader; thi jeg siger Eder, at Gud kan opvække Abraham Børn af disse Stene.","og mener ikke at ville sige ved Eder selv: vi have Abraham til Fader; thi jeg siger Eder, at Gud kan opvække Abraham Børn af disse Stene."],[3,10,"Men Øxen ligger allerede ved Roden af Træerne; derfor, hvert Træ, som ikke bærer god Frugt, skal afhugges og kastes i Ilden.","Men Øxen ligger allerede ved Roden af Træerne; derfor, hvert Træ, som ikke bærer god Frugt, skal afhugges og kastes i Ilden."],[3,11,"Jeg døber Eder vel med Vand til Omvendelse; men den, som kommer efter mig, er stærkere end jeg, hvis Skoe jeg ikke er værdig at bære; han skal døbe Eder med den Hellig Aand og Ild.","Jeg døber Eder vel med Vand til Omvendelse; men den, som kommer efter mig, er stærkere end jeg, hvis Skoe jeg ikke er værdig at bære; han skal døbe Eder med den Hellig Aand og Ild."],[3,12,"Hans Kasteskovl er i hans Haand, og han skal igjennemrense sin Lo og samle sin Hvede i Laden; men Avnerne skal han opbrænde med uslukkelig Ild.","Hans Kasteskovl er i hans Haand, og han skal igjennemrense sin Lo og samle sin Hvede i Laden; men Avnerne skal han opbrænde med uslukkelig Ild."],[3,13,"Da kom Jesus fra Galilæa til Jordanen til Johannes, at døbes af ham.","Da kom Jesus fra Galilæa til Jordanen til Johannes, at døbes af ham."],[3,14,"Men Johannes formeente ham det og sagde: Jeg haver behov at døbes af dig, og du kommer til mig!","Men Johannes formeente ham det og sagde: Jeg haver behov at døbes af dig, og du kommer til mig!"],[3,15,"Men Jesus svarede og sagde til ham: tilsted det nu; thi saaledes bør det os at fuldkomme Alt, hvad Ret er. Da tilstedte han ham.","Men Jesus svarede og sagde til ham: tilsted det nu; thi saaledes bør det os at fuldkomme Alt, hvad Ret er. Da tilstedte han ham."],[3,16,"Og der Jesus var døbt, steg han strax op af Vandet, og see, Himlene aabnedes ham, og han saae Guds Aand fare ned som en Due og komme over ham.","Og der Jesus var døbt, steg han strax op af Vandet, og see, Himlene aabnedes ham, og han saae Guds Aand fare ned som en Due og komme over ham."],[3,17,"Og see, der kom en Røst fra Himlene, som sagde: denne er min Søn den Elskelige, i hvilken jeg haver Behagelighed.","Og see, der kom en Røst fra Himlene, som sagde: denne er min Søn den Elskelige, i hvilken jeg haver Behagelighed."],[4,1,"Da blev Jesus ført af Aanden i Ørken, at fristes af Djævelen.","Da blev Jesus ført af Aanden i Ørken, at fristes af Djævelen."],[4,2,"Og der han havde fastet fyrretyve Dage og fyrretyve Nætter, hungrede han omsider.","Og der han havde fastet fyrretyve Dage og fyrretyve Nætter, hungrede han omsider."],[4,3,"Og Fristeren gik til ham og sagde: er du Guds Søn, da siig, at disse Stene blive Brød.","Og Fristeren gik til ham og sagde: er du Guds Søn, da siig, at disse Stene blive Brød."],[4,4,"Men han svarede og sagde: der er skrevet: Mennesket lever ikke alene af Brød, men ved hvert Ord, som udgaaer igjennem Guds Mund.","Men han svarede og sagde: der er skrevet: Mennesket lever ikke alene af Brød, men ved hvert Ord, som udgaaer igjennem Guds Mund."],[4,5,"Da tog Djævelen ham med sig til den hellige Stad og satte ham paa Tindingen af Templet og sagde til ham:","Da tog Djævelen ham med sig til den hellige Stad og satte ham paa Tindingen af Templet og sagde til ham:"],[4,6,"er du Guds Søn, da kast dig selv herned; thi der er skrevet: han skal give sine Engle Befaling om dig, og de skulle bære dig paa Hænderne, at du ikke skal støde din Fod paa nogen Steen.","er du Guds Søn, da kast dig selv herned; thi der er skrevet: han skal give sine Engle Befaling om dig, og de skulle bære dig paa Hænderne, at du ikke skal støde din Fod paa nogen Steen."],[4,7,"Da sagde Jesus til ham: der er atter skrevet: du skal ikke friste Herren din Gud.","Da sagde Jesus til ham: der er atter skrevet: du skal ikke friste Herren din Gud."],[4,8,"Atter tog Djævelen ham op med sig paa et saare høit Bjerg, og viste ham alle Verdens Riger og deres Herlighed, og sagde til ham:","Atter tog Djævelen ham op med sig paa et saare høit Bjerg, og viste ham alle Verdens Riger og deres Herlighed, og sagde til ham:"],[4,9,"Alt dette vil jeg give dig, om du vil falde ned og tilbede mig.","Alt dette vil jeg give dig, om du vil falde ned og tilbede mig."],[4,10,"Da sagde Jesus til ham: vig bort, Satan! thi der er skrevet: du skal tilbede Herren din Gud, og tjene ham alene.","Da sagde Jesus til ham: vig bort, Satan! thi der er skrevet: du skal tilbede Herren din Gud, og tjene ham alene."],[4,11,"Da forlod Djævelen ham, og see, Englene gik til ham og tjente ham.","Da forlod Djævelen ham, og see, Englene gik til ham og tjente ham."],[4,12,"Men der Jesus hørte, at Johannes var kastet i Fængsel, veg han hen til Galilæa.","Men der Jesus hørte, at Johannes var kastet i Fængsel, veg han hen til Galilæa."],[4,13,"Og han forlod Nazareth, og kom og boede i Capernaum, som ligger ved Søen, i Sebulons og Naphthalis Grændser,","Og han forlod Nazareth, og kom og boede i Capernaum, som ligger ved Søen, i Sebulons og Naphthalis Grændser,"],[4,14,"at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger:","at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger:"],[4,15,"Sebulons Land og Naphthalis Land, langs Søen paa denne Side Jordan, Hedningernes Galilæa,","Sebulons Land og Naphthalis Land, langs Søen paa denne Side Jordan, Hedningernes Galilæa,"],[4,16,"det Folk, som sad i Mørke, haver seet et stort Lys, og dem, som sadde i Dødens Land og Skygge, dem er opgaaet et Lys.","det Folk, som sad i Mørke, haver seet et stort Lys, og dem, som sadde i Dødens Land og Skygge, dem er opgaaet et Lys."],[4,17,"Fra den Tid begyndte Jesus at prædike og sige: omvender Eder, thi Himmerigets Rige er kommet nær.","Fra den Tid begyndte Jesus at prædike og sige: omvender Eder, thi Himmerigets Rige er kommet nær."],[4,18,"Men der Jesus vandrede ved den galilæiske Sø, saae han to Brødre, Simon, som kaldes Petrus, og Andreas, hans Broder, som kastede Garn i Søen; (thi de vare Fiskere).","Men der Jesus vandrede ved den galilæiske Sø, saae han to Brødre, Simon, som kaldes Petrus, og Andreas, hans Broder, som kastede Garn i Søen; (thi de vare Fiskere)."],[4,19,"Og han sagde til dem: følger efter mig, saa vil jeg gjøre Eder til Menneske-Fiskere.","Og han sagde til dem: følger efter mig, saa vil jeg gjøre Eder til Menneske-Fiskere."],[4,20,"Men de forlode strax Garnene og fulgte ham.","Men de forlode strax Garnene og fulgte ham."],[4,21,"Og der han gik frem derfra, saae han to andre Brødre, Jakobus, Zebedæus’ Søn, og Johannes, hans Broder, i Skibet med deres Fader Zebedæus, at de bødte deres Garn; og han kaldte dem.","Og der han gik frem derfra, saae han to andre Brødre, Jakobus, Zebedæus’ Søn, og Johannes, hans Broder, i Skibet med deres Fader Zebedæus, at de bødte deres Garn; og han kaldte dem."],[4,22,"Men de forlode strax Skibet og deres Fader og fulgte ham.","Men de forlode strax Skibet og deres Fader og fulgte ham."],[4,23,"Og Jesus gik omkring i det ganske Galilæa, lærte i deres Synagoger og prædikede Rigets Evangelium og helbredede al Sygdom og al Skrøbelighed iblandt Folket.","Og Jesus gik omkring i det ganske Galilæa, lærte i deres Synagoger og prædikede Rigets Evangelium og helbredede al Sygdom og al Skrøbelighed iblandt Folket."],[4,24,"Og hans Rygte kom ud over al Syria; og de førte ham alle dem, som lede ilde, som med adskillige Sygdomme og Piner vare behæftede, Besatte og Maanesyge og Værkbrudne; og han helbredede dem.","Og hans Rygte kom ud over al Syria; og de førte ham alle dem, som lede ilde, som med adskillige Sygdomme og Piner vare behæftede, Besatte og Maanesyge og Værkbrudne; og han helbredede dem."],[4,25,"Og der fulgte ham meget Folk fra Galilæa og Dekapolis og Jerusalem og Judæa og fra hiin Side Jordan.","Og der fulgte ham meget Folk fra Galilæa og Dekapolis og Jerusalem og Judæa og fra hiin Side Jordan."],[5,1,"Men der han saae Folket, steg han op paa et Bjerg; og der han havde sat sig, gik hans Disciple til ham.","Men der han saae Folket, steg han op paa et Bjerg; og der han havde sat sig, gik hans Disciple til ham."],[5,2,"Og han oplod sin Mund, lærte dem og sagde:","Og han oplod sin Mund, lærte dem og sagde:"],[5,3,"Salige ere de Fattige i Aanden, thi Himmeriges Rige er deres.","Salige ere de Fattige i Aanden, thi Himmeriges Rige er deres."],[5,4,"Salige ere de, som sørge, thi de skulle husvales.","Salige ere de, som sørge, thi de skulle husvales."],[5,5,"Salige ere de Sagtmodige, thi de skulle arve Jorden.","Salige ere de Sagtmodige, thi de skulle arve Jorden."],[5,6,"Salige ere de, som hungre og tørste efter Retfærdighed, thi de skulle mættes.","Salige ere de, som hungre og tørste efter Retfærdighed, thi de skulle mættes."],[5,7,"Salige ere de Barmhjertige, thi dem skal vederfares Barmhjertighed.","Salige ere de Barmhjertige, thi dem skal vederfares Barmhjertighed."],[5,8,"Salige ere de Rene af Hjertet, thi de skulle see Gud.","Salige ere de Rene af Hjertet, thi de skulle see Gud."],[5,9,"Salige ere de Fredsommelige, thi de skulle kaldes Guds Børn.","Salige ere de Fredsommelige, thi de skulle kaldes Guds Børn."],[5,10,"Salige ere de, som lide Forfølgelse for Retfærdigheds Skyld, thi Himmeriges Rige er deres.","Salige ere de, som lide Forfølgelse for Retfærdigheds Skyld, thi Himmeriges Rige er deres."],[5,11,"Salige ere I, naar man bespotter og forfølger Eder, og taler allehaande Ondt imod Eder for min Skyld, og lyver det.","Salige ere I, naar man bespotter og forfølger Eder, og taler allehaande Ondt imod Eder for min Skyld, og lyver det."],[5,12,"Glæder og fryder Eder, thi Eders Løn skal være megen i Himlene; thi saa have de forfulgt Propheterne, som vare for Eder.","Glæder og fryder Eder, thi Eders Løn skal være megen i Himlene; thi saa have de forfulgt Propheterne, som vare for Eder."],[5,13,"I ere Jordens Salt; men om Saltet mister sin Kraft, hvormed skal det saltes? Det duer til intet andet end at kastes ud og nedtrædes af Mennesker.","I ere Jordens Salt; men om Saltet mister sin Kraft, hvormed skal det saltes? Det duer til intet andet end at kastes ud og nedtrædes af Mennesker."],[5,14,"I ere Verdens Lys; den Stad, som ligger paa et Bjerg, kan ikke skjules.","I ere Verdens Lys; den Stad, som ligger paa et Bjerg, kan ikke skjules."],[5,15,"Man tænder og ikke et Lys, og sætter det under en Skjeppe, men paa en Lysestage; saa skinner det for alle dem, som ere i Huset.","Man tænder og ikke et Lys, og sætter det under en Skjeppe, men paa en Lysestage; saa skinner det for alle dem, som ere i Huset."],[5,16,"Lader saa Eders Lys skinne for Menneskene, at de see Eders gode Gjerninger og ære Eders Fader, som er i Himlene.","Lader saa Eders Lys skinne for Menneskene, at de see Eders gode Gjerninger og ære Eders Fader, som er i Himlene."],[5,17,"Mener ikke, at jeg er kommen, at opløse Loven eller Propheterne; jeg er ikke kommen at opløse, men at fuldkomme.","Mener ikke, at jeg er kommen, at opløse Loven eller Propheterne; jeg er ikke kommen at opløse, men at fuldkomme."],[5,18,"Thi sandelig siger jeg Eder: indtil Himmelen og Jorden forgaae, skal end ikke det mindste Bogstav eller en Tøddel forgaae af Loven, indtil det skeer altsammen.","Thi sandelig siger jeg Eder: indtil Himmelen og Jorden forgaae, skal end ikke det mindste Bogstav eller en Tøddel forgaae af Loven, indtil det skeer altsammen."],[5,19,"Derfor, hvo som løser eet af disse mindste Bud og lærer Menneskene saaledes, han skal kaldes den Mindste i Himmeriges Rige; men hvo som dem gjør og lærer, han skal kaldes stor i Himmeriges Rige.","Derfor, hvo som løser eet af disse mindste Bud og lærer Menneskene saaledes, han skal kaldes den Mindste i Himmeriges Rige; men hvo som dem gjør og lærer, han skal kaldes stor i Himmeriges Rige."],[5,20,"Thi jeg siger Eder: uden Eders Retfærdighed overgaaer de Skriftkloges og Pharisæers, komme I ingenlunde ind i Himmeriges Rige.","Thi jeg siger Eder: uden Eders Retfærdighed overgaaer de Skriftkloges og Pharisæers, komme I ingenlunde ind i Himmeriges Rige."],[5,21,"I have hørt, at der er sagt de Gamle: du skal ikke ihjelslaae, men hvo som ihjelslaaer, skal være skyldig for Dommen.","I have hørt, at der er sagt de Gamle: du skal ikke ihjelslaae, men hvo som ihjelslaaer, skal være skyldig for Dommen."],[5,22,"Men jeg siger Eder, at hver den, som er vred paa sin Broder uden Aarsag, skal være skyldig for Dommen; men hvo som siger til sin Broder: Raka! skal være skyldig for Raadet; men hvo som siger: du Daare! skal være skyldig til Helvedes Ild.","Men jeg siger Eder, at hver den, som er vred paa sin Broder uden Aarsag, skal være skyldig for Dommen; men hvo som siger til sin Broder: Raka! skal være skyldig for Raadet; men hvo som siger: du Daare! skal være skyldig til Helvedes Ild."],[5,23,"Derfor, naar du offrer din Gave paa Alteret og kommer der ihu, at din Broder haver noget imod dig,","Derfor, naar du offrer din Gave paa Alteret og kommer der ihu, at din Broder haver noget imod dig,"],[5,24,"saa lad blive din Gave der for Alteret, og gak hen, forlig dig først med din Broder, og kom da og offre din Gave.","saa lad blive din Gave der for Alteret, og gak hen, forlig dig først med din Broder, og kom da og offre din Gave."],[5,25,"Vær snart velvillig mod din Modstander, medens du er med ham paa Veien, at Modstanderen ikke skal overantvorde Dommeren dig, og Dommeren skal overantvorde Tjeneren dig, og du skal kastes i Fængsel.","Vær snart velvillig mod din Modstander, medens du er med ham paa Veien, at Modstanderen ikke skal overantvorde Dommeren dig, og Dommeren skal overantvorde Tjeneren dig, og du skal kastes i Fængsel."],[5,26,"Sandelig siger jeg dig: du skal slet ikke komme derudfra, førend du betaler den sidste Hvid.","Sandelig siger jeg dig: du skal slet ikke komme derudfra, førend du betaler den sidste Hvid."],[5,27,"I have hørt, at der er sagt de Gamle: du skal ikke bedrive Hoer.","I have hørt, at der er sagt de Gamle: du skal ikke bedrive Hoer."],[5,28,"Men jeg siger Eder, at hver den, som seer paa en Kvinde for at begjere hende, haver allerede bedrevet Hoer med hende i sit Hjerte.","Men jeg siger Eder, at hver den, som seer paa en Kvinde for at begjere hende, haver allerede bedrevet Hoer med hende i sit Hjerte."],[5,29,"Men dersom dit høire Øie forager dig, saa riv det ud, og kast det fra dig; thi det er dig gavnligt, at eet af dine Lemmer fordærves, og ikke dit ganske Legeme, skal kastes i Helvede.","Men dersom dit høire Øie forager dig, saa riv det ud, og kast det fra dig; thi det er dig gavnligt, at eet af dine Lemmer fordærves, og ikke dit ganske Legeme, skal kastes i Helvede."],[5,30,"Og om din høire Haand forarger dig, hug den af og kast den fra dig; thi det er dig gavnligt, at eet af dine Lemmer fordærves, og ikke dit ganske Legeme skal kastes i Helvede.","Og om din høire Haand forarger dig, hug den af og kast den fra dig; thi det er dig gavnligt, at eet af dine Lemmer fordærves, og ikke dit ganske Legeme skal kastes i Helvede."],[5,31,"Der er sagt, at hvo som skiller sig fra sin Hustru, skal give hende et Skilsmissebrev.","Der er sagt, at hvo som skiller sig fra sin Hustru, skal give hende et Skilsmissebrev."],[5,32,"Men jeg siger Eder, at hvo som skiller sig fra sin Hustru uden for Hoers Sag, gjør, at hun bedriver Hoer, og hvo som tager en Adskilt tilægte, bedriver Hoer.","Men jeg siger Eder, at hvo som skiller sig fra sin Hustru uden for Hoers Sag, gjør, at hun bedriver Hoer, og hvo som tager en Adskilt tilægte, bedriver Hoer."],[5,33,"I have fremdeles hørt, at der er sagt de Gamle: du skal ikke gjøre nogen falsk Ed, men du skal holde Herren dine Eder.","I have fremdeles hørt, at der er sagt de Gamle: du skal ikke gjøre nogen falsk Ed, men du skal holde Herren dine Eder."],[5,34,"Men jeg siger Eder, at I skulle aldeles ikke sværge, hverken ved Himmelen, thi den er Guds Stol,","Men jeg siger Eder, at I skulle aldeles ikke sværge, hverken ved Himmelen, thi den er Guds Stol,"],[5,35,"ei heller ved Jorden, thi den er hans Fodskammel, ei heller ved Jerusalem, thi det er den store Konges Stad.","ei heller ved Jorden, thi den er hans Fodskammel, ei heller ved Jerusalem, thi det er den store Konges Stad."],[5,36,"Du skal og ikke sværge ved dit Hoved, thi du kan ikke gjøre eet Haar hvidt eller sort.","Du skal og ikke sværge ved dit Hoved, thi du kan ikke gjøre eet Haar hvidt eller sort."],[5,37,"Men Eders Tale skal være ja, ja, nei, nei; men hvad der er over dette, er af det Onde.","Men Eders Tale skal være ja, ja, nei, nei; men hvad der er over dette, er af det Onde."],[5,38,"I have hørt, at der er sagt: Øie for Øie, og Tand for Tand.","I have hørt, at der er sagt: Øie for Øie, og Tand for Tand."],[5,39,"Men jeg siger Eder, at I skulle ikke sætte Eder imod det onde; men dersom Nogen giver dig et Slag paa det høire Kindbeen, vend ham det andet ogsaa til.","Men jeg siger Eder, at I skulle ikke sætte Eder imod det onde; men dersom Nogen giver dig et Slag paa det høire Kindbeen, vend ham det andet ogsaa til."],[5,40,"Og dersom Nogen vil gaae i Rette med dig og tage din Kjortel, lad ham og beholde Kappen.","Og dersom Nogen vil gaae i Rette med dig og tage din Kjortel, lad ham og beholde Kappen."],[5,41,"Og dersom Nogen tvinger dig til at gaae en Mil, gak to med ham.","Og dersom Nogen tvinger dig til at gaae en Mil, gak to med ham."],[5,42,"Giv den, som beder dig, og vend ikke fra den, som vil laane af dig.","Giv den, som beder dig, og vend ikke fra den, som vil laane af dig."],[5,43,"I have hørt, at der er sagt: du skal elske din Næste, og hade din Fjende.","I have hørt, at der er sagt: du skal elske din Næste, og hade din Fjende."],[5,44,"Men jeg siger Eder: elsker Eders Fjender, velsigner dem, som Eder forbande, gjører dem godt, som Eder hade, og beder for dem, som gjøre Eder Skade og forfølge Eder,","Men jeg siger Eder: elsker Eders Fjender, velsigner dem, som Eder forbande, gjører dem godt, som Eder hade, og beder for dem, som gjøre Eder Skade og forfølge Eder,"],[5,45,"paa det I skulle vorde Eders Faders Børn, som er i Himlene; thi han lader sin Sol opgaae over Onde og Gode og lader regne over Retfærdige og Uretfærdige.","paa det I skulle vorde Eders Faders Børn, som er i Himlene; thi han lader sin Sol opgaae over Onde og Gode og lader regne over Retfærdige og Uretfærdige."],[5,46,"Thi dersom I elske dem, som Eder elske, hvad have I da for Løn? Gjøre ikke ogsaa Toldere det Samme?","Thi dersom I elske dem, som Eder elske, hvad have I da for Løn? Gjøre ikke ogsaa Toldere det Samme?"],[5,47,"Og dersom I hilse Eders Brødre alene, hvad Stort gjøre I da? Gjøre ikke Toldere ligesaa?","Og dersom I hilse Eders Brødre alene, hvad Stort gjøre I da? Gjøre ikke Toldere ligesaa?"],[5,48,"Værer da fuldkomne, ligesom Eders Fader i Himlene er fuldkommen.","Værer da fuldkomne, ligesom Eders Fader i Himlene er fuldkommen."],[6,1,"Vogter Eder, at I ikke gjøre Eders Almisse for Menneskene, for at ansees af dem, ellers have I ikke Løn hos Eders Fader, som er i Himlene.","Vogter Eder, at I ikke gjøre Eders Almisse for Menneskene, for at ansees af dem, ellers have I ikke Løn hos Eders Fader, som er i Himlene."],[6,2,"Derfor, naar du gjør Almisse, skal du ikke lade blæse i Basune for dig, som Øienskalkene gjøre i Synagoger og paa Gader, paa det de kunne æres af Mennesker; sandelig siger jeg Eder: de have deres Løn borte.","Derfor, naar du gjør Almisse, skal du ikke lade blæse i Basune for dig, som Øienskalkene gjøre i Synagoger og paa Gader, paa det de kunne æres af Mennesker; sandelig siger jeg Eder: de have deres Løn borte."],[6,3,"Men naar du gjør Almisse, lad din venstre Haand ikke vide, hvad din høire gjør,","Men naar du gjør Almisse, lad din venstre Haand ikke vide, hvad din høire gjør,"],[6,4,"paa det din Almisse kan være i Løndom, og din Fader, som seer i Løndom, han skal betale dig aabenbare.","paa det din Almisse kan være i Løndom, og din Fader, som seer i Løndom, han skal betale dig aabenbare."],[6,5,"Og naar du beder, skal du ikke være som Øienskalkene; thi de staae gjerne og bede i Synagoger og paa Hjørner af Gader, paa det de kunne ansees af Menneskene; sandelig siger jeg Eder: de have deres Løn borte.","Og naar du beder, skal du ikke være som Øienskalkene; thi de staae gjerne og bede i Synagoger og paa Hjørner af Gader, paa det de kunne ansees af Menneskene; sandelig siger jeg Eder: de have deres Løn borte."],[6,6,"Men du, naar du beder, gak ind i dit Kammer, og luk din Dør, og bed til din Fader, som er i Løndom, og din Fader, som seer i Løndom, skal betale dig aabenbare.","Men du, naar du beder, gak ind i dit Kammer, og luk din Dør, og bed til din Fader, som er i Løndom, og din Fader, som seer i Løndom, skal betale dig aabenbare."],[6,7,"Men naar I bede, skulle I ikke bruge overflødige Ord som Hedningerne; thi de mene, at de blive bønhørte for deres mange Ord.","Men naar I bede, skulle I ikke bruge overflødige Ord som Hedningerne; thi de mene, at de blive bønhørte for deres mange Ord."],[6,8,"Derfor skulle I ikke vorde dem lige; thi Eders Fader veed, hvad I have behov, førend I bede ham.","Derfor skulle I ikke vorde dem lige; thi Eders Fader veed, hvad I have behov, førend I bede ham."],[6,9,"Derfor skulle I saaledes bede: Vor Fader, du som er i Himlene! Helliget vorde dit Navn;","Derfor skulle I saaledes bede: Vor Fader, du som er i Himlene! Helliget vorde dit Navn;"],[6,10,"komme dit Rige; skee din Villie som i Himmelen, saa og paa Jorden;","komme dit Rige; skee din Villie som i Himmelen, saa og paa Jorden;"],[6,11,"giv os i Dag vort daglige Brød;","giv os i Dag vort daglige Brød;"],[6,12,"og forlad os vor Skyld, som og vi forlade vore Skyldnere;","og forlad os vor Skyld, som og vi forlade vore Skyldnere;"],[6,13,"og led os ikke ind i Fristelse; men fri os fra det Onde; thi dit er Riget og Kraften og Herligheden i Evighed! Amen.","og led os ikke ind i Fristelse; men fri os fra det Onde; thi dit er Riget og Kraften og Herligheden i Evighed! Amen."],[6,14,"Thi forlade I Menneskene deres Overtrædelser, skal Eders himmelske Fader og forlade Eder;","Thi forlade I Menneskene deres Overtrædelser, skal Eders himmelske Fader og forlade Eder;"],[6,15,"men forlade I ikke Menneskene deres Overtrædelser, skal Eders Fader ikke heller forlade Eders Overtrædelser.","men forlade I ikke Menneskene deres Overtrædelser, skal Eders Fader ikke heller forlade Eders Overtrædelser."],[6,16,"Naar I faste, da seer ikke bedrøvede ud som Øienskalkene; thi de forvende deres Ansigt, paa det Menneskene kunne see dem faste; sandelig siger jeg Eder: de havde deres Løn borte.","Naar I faste, da seer ikke bedrøvede ud som Øienskalkene; thi de forvende deres Ansigt, paa det Menneskene kunne see dem faste; sandelig siger jeg Eder: de havde deres Løn borte."],[6,17,"Men naar du faster, da salv dit Hoved, og to dit Ansigt,","Men naar du faster, da salv dit Hoved, og to dit Ansigt,"],[6,18,"at ikke Menneskene skulle see dig faste, men din Fader, som er i Løndom, og din Fader, som seer i Løndom, skal betale dig aabenbare.","at ikke Menneskene skulle see dig faste, men din Fader, som er i Løndom, og din Fader, som seer i Løndom, skal betale dig aabenbare."],[6,19,"Samler Eder ikke Liggendefæ paa Jorden hvor Møl og Rust fordærve, og hvor Tyve igjennembryde og stjæle;","Samler Eder ikke Liggendefæ paa Jorden hvor Møl og Rust fordærve, og hvor Tyve igjennembryde og stjæle;"],[6,20,"samler Eder Liggendefæ i Himmelen, hvor hverken Møl, ei heller Rust fordærver, og hvor Tyve ikke igjennembryde, ei heller stjæle.","samler Eder Liggendefæ i Himmelen, hvor hverken Møl, ei heller Rust fordærver, og hvor Tyve ikke igjennembryde, ei heller stjæle."],[6,21,"Thi hvor Eders Liggendefæ er, der vil Eders Hjerte være.","Thi hvor Eders Liggendefæ er, der vil Eders Hjerte være."],[6,22,"Øiet er Legemets Lys; derfor, dersom dit Øie er sundt, bliver dit ganske Legeme lyst;","Øiet er Legemets Lys; derfor, dersom dit Øie er sundt, bliver dit ganske Legeme lyst;"],[6,23,"men dersom dit Øie er ondt, bliver dit ganske Legeme mørkt. Dersom derfor det Lys der er i dig, er Mørke, hvor stort bliver da Mørket!","men dersom dit Øie er ondt, bliver dit ganske Legeme mørkt. Dersom derfor det Lys der er i dig, er Mørke, hvor stort bliver da Mørket!"],[6,24,"Ingen kan tjene to Herrer; thi han maa enten hade den ene og elske den anden, eller holde sig til den ene og foragte den anden. I kunne ikke tjene Gud og Mammon.","Ingen kan tjene to Herrer; thi han maa enten hade den ene og elske den anden, eller holde sig til den ene og foragte den anden. I kunne ikke tjene Gud og Mammon."],[6,25,"Derfor siger jeg Eder: bekymrer Eder ikke for Eders Liv, hvad I skulle æde, og hvad I skulle drikke; ikke heller for Eders Legeme, hvad I skulle iføres. Er ikke Livet mere end Maden, og Legemet mere end Klæderne?","Derfor siger jeg Eder: bekymrer Eder ikke for Eders Liv, hvad I skulle æde, og hvad I skulle drikke; ikke heller for Eders Legeme, hvad I skulle iføres. Er ikke Livet mere end Maden, og Legemet mere end Klæderne?"],[6,26,"Seer til Himmelens Fugle; de saae ikke og høste ikke og sanke ikke i Lader, og Eders himmelske Fader føder dem; ere I ikke meget mere end de?","Seer til Himmelens Fugle; de saae ikke og høste ikke og sanke ikke i Lader, og Eders himmelske Fader føder dem; ere I ikke meget mere end de?"],[6,27,"Men hvo iblandt Eder kan lægge een Alen til sin Væxt, enddog han bekymrer sig derfor?","Men hvo iblandt Eder kan lægge een Alen til sin Væxt, enddog han bekymrer sig derfor?"],[6,28,"Og hvi bekymre I Eder for Klæderne? Betragter Lilierne paa Marken, hvorledes de voxe; de arbeide ikke, spinde ikke;","Og hvi bekymre I Eder for Klæderne? Betragter Lilierne paa Marken, hvorledes de voxe; de arbeide ikke, spinde ikke;"],[6,29,"men jeg siger Eder, at end ikke Salomon i al sin Herlighed var saa klædt, som een af dem.","men jeg siger Eder, at end ikke Salomon i al sin Herlighed var saa klædt, som een af dem."],[6,30,"Klæder da Gud saaledes det Græs paa Marken, som er i Dag og i Morgen kastes i Ovnen, skulde han ikke meget mere klæde Eder, I lidet troende?","Klæder da Gud saaledes det Græs paa Marken, som er i Dag og i Morgen kastes i Ovnen, skulde han ikke meget mere klæde Eder, I lidet troende?"],[6,31,"Derfor skulle I ikke bekymre Eder og sige: hvad skulle vi æde? eller: hvad skulle vi drikke? eller: hvormed skulle vi klæde os?","Derfor skulle I ikke bekymre Eder og sige: hvad skulle vi æde? eller: hvad skulle vi drikke? eller: hvormed skulle vi klæde os?"],[6,32,"Efter alt saadant søge Hedningerne; thi Eders Himmelske Fader veed, at I have alle disse Ting behov.","Efter alt saadant søge Hedningerne; thi Eders Himmelske Fader veed, at I have alle disse Ting behov."],[6,33,"Men søger først Guds Rige og hans Retfærdighed, saa skulle og alle disse Ting tillægges Eder.","Men søger først Guds Rige og hans Retfærdighed, saa skulle og alle disse Ting tillægges Eder."],[6,34,"Bekymrer Eder derfor ikke for den anden Morgen; thi den Dag i Morgen skal bekymre sig for sit Eget. Hver Dag haver nok i sin Plage.","Bekymrer Eder derfor ikke for den anden Morgen; thi den Dag i Morgen skal bekymre sig for sit Eget. Hver Dag haver nok i sin Plage."],[7,1,"Dømmer ikke, at I skulle ikke dømmes; thi med hvad Dom I dømme, skulle I dømmes,","Dømmer ikke, at I skulle ikke dømmes; thi med hvad Dom I dømme, skulle I dømmes,"],[7,2,"og med hvad Maal I maale, skal Eder igjen maales.","og med hvad Maal I maale, skal Eder igjen maales."],[7,3,"Men hvi seer du Skjæven, som er i din Broders Øie, men Bjelken i dit Øie bliver du ikke vaer.","Men hvi seer du Skjæven, som er i din Broders Øie, men Bjelken i dit Øie bliver du ikke vaer."],[7,4,"Eller hvorledes siger du til din Broder: lad mig drage Skjæven ud af dit Øie, og see, der er en Bjelke i dit Øie.","Eller hvorledes siger du til din Broder: lad mig drage Skjæven ud af dit Øie, og see, der er en Bjelke i dit Øie."],[7,5,"Du Øienskalk! drag først Bjelken ud af dit Øie, og da kan du see til at uddrage Skjæven af din Broders Øie.","Du Øienskalk! drag først Bjelken ud af dit Øie, og da kan du see til at uddrage Skjæven af din Broders Øie."],[7,6,"Giver ikke Hunde det Hellige, kaster ikke heller Eders Perler for Sviin, at de ikke skulle nedtræde dem med deres Fødder, og vende sig og sønderrive Eder.","Giver ikke Hunde det Hellige, kaster ikke heller Eders Perler for Sviin, at de ikke skulle nedtræde dem med deres Fødder, og vende sig og sønderrive Eder."],[7,7,"Beder, saa skal Eder gives; søger, saa skulle I finde; banker, saa skal Eder oplades.","Beder, saa skal Eder gives; søger, saa skulle I finde; banker, saa skal Eder oplades."],[7,8,"Thi hver den, som beder, han faar, og den, som søger, han finder, og den, som banker, ham skal oplades.","Thi hver den, som beder, han faar, og den, som søger, han finder, og den, som banker, ham skal oplades."],[7,9,"Eller hvilket Menneske er iblandt Eder, dersom hans Søn beder ham om Brød, mon han give ham en Steen?","Eller hvilket Menneske er iblandt Eder, dersom hans Søn beder ham om Brød, mon han give ham en Steen?"],[7,10,"Og dersom han beder ham om en Fisk, mon han give ham en Slange?","Og dersom han beder ham om en Fisk, mon han give ham en Slange?"],[7,11,"Dersom da I, som ere onde, vide at give Eders Børn gode Gaver, hvor meget mere skal Eders Fader, som er i Himlene, give dem gode Gaver, som ham bede!","Dersom da I, som ere onde, vide at give Eders Børn gode Gaver, hvor meget mere skal Eders Fader, som er i Himlene, give dem gode Gaver, som ham bede!"],[7,12,"Derfor, Alt hvad I ville, at Menneskene skulle gjøre imod Eder, det gjører I ogsaa mod dem; thi saadan er Loven og Propheterne.","Derfor, Alt hvad I ville, at Menneskene skulle gjøre imod Eder, det gjører I ogsaa mod dem; thi saadan er Loven og Propheterne."],[7,13,"Gaaer ind ad den snevre Port; thi den Port er vid, og de Vei er bred, som fører til Fordærvelsen, og de ere mange, som gaae ind igjennem den;","Gaaer ind ad den snevre Port; thi den Port er vid, og de Vei er bred, som fører til Fordærvelsen, og de ere mange, som gaae ind igjennem den;"],[7,14,"thi den Port er snever, og den Vei er trang, som fører til Livet, og de ere faa, som finde den.","thi den Port er snever, og den Vei er trang, som fører til Livet, og de ere faa, som finde den."],[7,15,"Men vogter Eder for de falske Propheter, som kommer til Eder i Faareklæder, men ere indvortes rivende Ulve.","Men vogter Eder for de falske Propheter, som kommer til Eder i Faareklæder, men ere indvortes rivende Ulve."],[7,16,"Af deres Frugter skulle I kjende dem. Kan man og sanke Viindruer af Torne, eller Figen af Tidsler?","Af deres Frugter skulle I kjende dem. Kan man og sanke Viindruer af Torne, eller Figen af Tidsler?"],[7,17,"Saaledes bærer hvert godt Træ gode Frugter, men et raaddent Træ bærer onde Frugter.","Saaledes bærer hvert godt Træ gode Frugter, men et raaddent Træ bærer onde Frugter."],[7,18,"Et godt Træ kan ikke bære onde Frugter, og et raaddent Træ kan ikke bære gode Frugter.","Et godt Træ kan ikke bære onde Frugter, og et raaddent Træ kan ikke bære gode Frugter."],[7,19,"Hvert Træ, som ikke bærer god Frugt, afhugges og kastes i Ilden.","Hvert Træ, som ikke bærer god Frugt, afhugges og kastes i Ilden."],[7,20,"Derfor skulle I kjende dem af deres Frugter.","Derfor skulle I kjende dem af deres Frugter."],[7,21,"Ikke enhver, som siger til mig: Herre, Herre! skal indgaae i Himmeriges Rige, men den, som gjør min Faders Villie, som er i Himlene.","Ikke enhver, som siger til mig: Herre, Herre! skal indgaae i Himmeriges Rige, men den, som gjør min Faders Villie, som er i Himlene."],[7,22,"Mange skulle sige til mig paa hiin Dag: Herre, Herre! have vi ikke propheteret ved dit Navn? og havde vi ikke uddrevet Djævle ved dit Navn? og have vi ikke gjort mange kraftige Gjerninger ved dit Navn?","Mange skulle sige til mig paa hiin Dag: Herre, Herre! have vi ikke propheteret ved dit Navn? og havde vi ikke uddrevet Djævle ved dit Navn? og have vi ikke gjort mange kraftige Gjerninger ved dit Navn?"],[7,23,"Og da vil jeg bekjende for dem: jeg kjendte Eder aldrig; viger bort fra mig, I, som beflitte Eder paa Uret!","Og da vil jeg bekjende for dem: jeg kjendte Eder aldrig; viger bort fra mig, I, som beflitte Eder paa Uret!"],[7,24,"Derfor, hver den, som Hører disse mine Ord og gjør efter dem, den vil jeg ligne ved en forstandig Mand, som byggede sit Huus paa en Klippe.","Derfor, hver den, som Hører disse mine Ord og gjør efter dem, den vil jeg ligne ved en forstandig Mand, som byggede sit Huus paa en Klippe."],[7,25,"Og en Skylregn nedfaldt, og Vandløbene kom, og Veirene blæste og faldt an paa samme Huus, og det faldt ikke; thi det var grundfæstet paa en Klippe.","Og en Skylregn nedfaldt, og Vandløbene kom, og Veirene blæste og faldt an paa samme Huus, og det faldt ikke; thi det var grundfæstet paa en Klippe."],[7,26,"Og hver, som hører disse mine Ord og gjør ikke efter dem, skal lignes ved en daarlig Mand, som byggede sit Huus paa Sand.","Og hver, som hører disse mine Ord og gjør ikke efter dem, skal lignes ved en daarlig Mand, som byggede sit Huus paa Sand."],[7,27,"Og en Skylregn nedfaldt, og Vandløbene kom, og Veirene blæste og stødte an paa samme Huus, og det faldt, og dets Fald var stort.","Og en Skylregn nedfaldt, og Vandløbene kom, og Veirene blæste og stødte an paa samme Huus, og det faldt, og dets Fald var stort."],[7,28,"Og det begav sig, der Jesus havde fuldendt disse Ord, forundrede Folket sig saare over hans Lærdom;","Og det begav sig, der Jesus havde fuldendt disse Ord, forundrede Folket sig saare over hans Lærdom;"],[7,29,"thi han lærte dem som den, der havde Myndighed, og ikke som de Skriftkloge.","thi han lærte dem som den, der havde Myndighed, og ikke som de Skriftkloge."],[8,1,"Men der han gik ned af Bjerget, fulgte ham meget Folk.","Men der han gik ned af Bjerget, fulgte ham meget Folk."],[8,2,"Og see, en Spedalsk kom, faldt ned for ham og sagde: Herre! om du vil, saa kan du rense mig.","Og see, en Spedalsk kom, faldt ned for ham og sagde: Herre! om du vil, saa kan du rense mig."],[8,3,"Og Jesus udrakte Haanden, rørte ved ham og sagde: jeg vil; vorde reen! Og hans Spedalskhed blev strax renset.","Og Jesus udrakte Haanden, rørte ved ham og sagde: jeg vil; vorde reen! Og hans Spedalskhed blev strax renset."],[8,4,"Og Jesus sagde til ham: see til, at du siger Ingen det; men gak hen, betee dig selv for Præsten, og offre den Gave, som Moses haver befalet, dem til et Vidnesbyrd.","Og Jesus sagde til ham: see til, at du siger Ingen det; men gak hen, betee dig selv for Præsten, og offre den Gave, som Moses haver befalet, dem til et Vidnesbyrd."],[8,5,"Men der Jesus gik ind i Capernaum, traadte en Høvedsmand til ham, bad ham og sagde:","Men der Jesus gik ind i Capernaum, traadte en Høvedsmand til ham, bad ham og sagde:"],[8,6,"Herre! min Dreng ligger hjemme værkbruden og pines svarligen.","Herre! min Dreng ligger hjemme værkbruden og pines svarligen."],[8,7,"Og Jesus sagde til ham: jeg vil komme og helbrede ham.","Og Jesus sagde til ham: jeg vil komme og helbrede ham."],[8,8,"Og Høvedsmanden svarede og sagde: Herre! jeg er ikke værd, at du skal gaae ind under mit Tag; men siig ikkun et Ord, saa bliver min Tjener helbredet.","Og Høvedsmanden svarede og sagde: Herre! jeg er ikke værd, at du skal gaae ind under mit Tag; men siig ikkun et Ord, saa bliver min Tjener helbredet."],[8,9,"Thi jeg er og et Menneske, som staar under Øvrighed og haver Stridsmænd under mig; og siger jeg til denne: gak! saa gaaer han; og til den anden: kom! saa kommer han; og til min Tjener: gjør det! saa gjør han det.","Thi jeg er og et Menneske, som staar under Øvrighed og haver Stridsmænd under mig; og siger jeg til denne: gak! saa gaaer han; og til den anden: kom! saa kommer han; og til min Tjener: gjør det! saa gjør han det."],[8,10,"Men der Jesus det hørte, forundrede han sig og sagde til dem, som fulgte: sandelig siger jeg Eder, end ikke i Israel haver jeg fundet saadan Tro.","Men der Jesus det hørte, forundrede han sig og sagde til dem, som fulgte: sandelig siger jeg Eder, end ikke i Israel haver jeg fundet saadan Tro."],[8,11,"Men jeg siger Eder, at Mange skulle komme fra Øster og Vester, og sidde tilbords med Abraham og Isaak og Jakob i Himmeriges Rige.","Men jeg siger Eder, at Mange skulle komme fra Øster og Vester, og sidde tilbords med Abraham og Isaak og Jakob i Himmeriges Rige."],[8,12,"Men Rigets Børn skulle udkastes i det yderste Mørke; der skal være Graad og Tænders Gnidsel.","Men Rigets Børn skulle udkastes i det yderste Mørke; der skal være Graad og Tænders Gnidsel."],[8,13,"Og Jesus sagde til Høvedsmanden: gak bort, og dig skee, som du troede! Og hans Dreng blev helbredet i den samme Time.","Og Jesus sagde til Høvedsmanden: gak bort, og dig skee, som du troede! Og hans Dreng blev helbredet i den samme Time."],[8,14,"Og Jesus kom i Peters Huus og saae, at hans Hustrus Moder laa og havde Feber.","Og Jesus kom i Peters Huus og saae, at hans Hustrus Moder laa og havde Feber."],[8,15,"Og han rørte ved hendes Haand, og Feberen forlod hende, og hun stod op og tjente dem.","Og han rørte ved hendes Haand, og Feberen forlod hende, og hun stod op og tjente dem."],[8,16,"Men der det var blevet Aften, førte de mange Besatte til ham, og han uddrev Aanderne med et Ord, og helbredte dem alle, som vare syge;","Men der det var blevet Aften, førte de mange Besatte til ham, og han uddrev Aanderne med et Ord, og helbredte dem alle, som vare syge;"],[8,17,"at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger: han tog vore Skrøbeligheder og bar vore Sygdomme.","at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger: han tog vore Skrøbeligheder og bar vore Sygdomme."],[8,18,"Men der Jesus saae meget Folk omkring sig, befoel han at fare over til hiin Side.","Men der Jesus saae meget Folk omkring sig, befoel han at fare over til hiin Side."],[8,19,"Og der gik en Skriftklog frem og sagde til ham: Mester! jeg vil følge dig, hvor du gaaer hen.","Og der gik en Skriftklog frem og sagde til ham: Mester! jeg vil følge dig, hvor du gaaer hen."],[8,20,"Og Jesus sagde til ham: Ræve have Huler og Himmelens Fugle Reder; men Menneskens Søn haver ikke det, hvortil han kan hælde sit Hoved.","Og Jesus sagde til ham: Ræve have Huler og Himmelens Fugle Reder; men Menneskens Søn haver ikke det, hvortil han kan hælde sit Hoved."],[8,21,"Men en anden af hans Disciple sagde til ham: Herre! tilsted mig, at jeg først maa gaae hen og begrave min Fader.","Men en anden af hans Disciple sagde til ham: Herre! tilsted mig, at jeg først maa gaae hen og begrave min Fader."],[8,22,"Men Jesus sagde til ham: følg mig, og lad de Døde begrave deres Døde.","Men Jesus sagde til ham: følg mig, og lad de Døde begrave deres Døde."],[8,23,"Og han gik i Skibet, og hans Disciple fulgte ham.","Og han gik i Skibet, og hans Disciple fulgte ham."],[8,24,"Og see, der blev en stor Storm paa Søen, saa at Skibet skjultes af Bølgerne; men han sov.","Og see, der blev en stor Storm paa Søen, saa at Skibet skjultes af Bølgerne; men han sov."],[8,25,"Og hans Disciple gik til ham, vakte ham op og sagde: Herre, frels os! vi forgaae.","Og hans Disciple gik til ham, vakte ham op og sagde: Herre, frels os! vi forgaae."],[8,26,"Og han sagde til dem: hvi ere I frygtagtige, I lidet Troende? Da stod han op og truede Veirene og Søen, og det blev ganske blikstille.","Og han sagde til dem: hvi ere I frygtagtige, I lidet Troende? Da stod han op og truede Veirene og Søen, og det blev ganske blikstille."],[8,27,"Men Menneskene forundrede sig og sagde: hvo er dog denne, at baade Veirene og Søen ere ham lydige?","Men Menneskene forundrede sig og sagde: hvo er dog denne, at baade Veirene og Søen ere ham lydige?"],[8,28,"Og der han kom paa hiin Side til de Gergeseners Land, mødte to Besatte ham, som kom ud fra Gravene, og vare saare vilde, saa at Ingen kunde vandre ad den Vei.","Og der han kom paa hiin Side til de Gergeseners Land, mødte to Besatte ham, som kom ud fra Gravene, og vare saare vilde, saa at Ingen kunde vandre ad den Vei."],[8,29,"Og see, de raabte og sagde: Jesus, du Guds Søn! hvad have vi med dig at gjøre? er du kommen hid for Tiden at pine os.","Og see, de raabte og sagde: Jesus, du Guds Søn! hvad have vi med dig at gjøre? er du kommen hid for Tiden at pine os."],[8,30,"Men der var langt fra dem en stor Hjord Sviin, som græssede.","Men der var langt fra dem en stor Hjord Sviin, som græssede."],[8,31,"Men Djævelene bade ham og sagde: dersom du uddriver os, da tilsted os at fare i Svinehjorden.","Men Djævelene bade ham og sagde: dersom du uddriver os, da tilsted os at fare i Svinehjorden."],[8,32,"Og han sagde til dem: farer hen! Men der de vare udfarne, fore de hen i Svinehjorden; og see, den ganske Svinehjord styrtede sig af Brinken i Søen, og døde i Vandet.","Og han sagde til dem: farer hen! Men der de vare udfarne, fore de hen i Svinehjorden; og see, den ganske Svinehjord styrtede sig af Brinken i Søen, og døde i Vandet."],[8,33,"Men Hyrderne flyede og gik hen i Staden og kundgjorde det altsammen, og hvorledes det var gaaet til med de Besatte.","Men Hyrderne flyede og gik hen i Staden og kundgjorde det altsammen, og hvorledes det var gaaet til med de Besatte."],[8,34,"Og see, den ganske Stad gik ud at møde Jesus; og der de saae ham, bade de ham, at han vilde vige fra deres Grændser.","Og see, den ganske Stad gik ud at møde Jesus; og der de saae ham, bade de ham, at han vilde vige fra deres Grændser."],[9,1,"Og han traadte ind i Skibet, og foer over, og kom til sin egen Stad.","Og han traadte ind i Skibet, og foer over, og kom til sin egen Stad."],[9,2,"Og see, de førte en Værkbruden til ham, som laa paa en Seng; og der Jesus saae deres Tro, sagde han til den Værkbrudne: Søn! vær frimodig, dine Synder ere dig forladne.","Og see, de førte en Værkbruden til ham, som laa paa en Seng; og der Jesus saae deres Tro, sagde han til den Værkbrudne: Søn! vær frimodig, dine Synder ere dig forladne."],[9,3,"Og see, nogle af de Skriftkloge sagde ved sig selv: denne bespotter Gud.","Og see, nogle af de Skriftkloge sagde ved sig selv: denne bespotter Gud."],[9,4,"Og der Jesus saae deres Tanker, sagde han: hvi tænke I saa ondt i Eders Hjerter?","Og der Jesus saae deres Tanker, sagde han: hvi tænke I saa ondt i Eders Hjerter?"],[9,5,"Thi hvilket er lettere, at sige: dine Synder ere dig forladne? eller at sige: staa op og vandre?","Thi hvilket er lettere, at sige: dine Synder ere dig forladne? eller at sige: staa op og vandre?"],[9,6,"Men at I skulle vide, at Menneskens Søn haver Magt paa Jorden at forlader Synder, da siger han til den Værkbrudne: staa op, og tag din Seng op, og gak til dit Huus.","Men at I skulle vide, at Menneskens Søn haver Magt paa Jorden at forlader Synder, da siger han til den Værkbrudne: staa op, og tag din Seng op, og gak til dit Huus."],[9,7,"Og han stod op og gik bort til sit Huus.","Og han stod op og gik bort til sit Huus."],[9,8,"Men der Folket det saae, forundrede de sig, og prisede Gud, som havde givet Menneskene saadan Magt.","Men der Folket det saae, forundrede de sig, og prisede Gud, som havde givet Menneskene saadan Magt."],[9,9,"Og der Jesus gik bort derfra, saae han et Menneske sidde i Toldboden, han hed Matthæus; og han siger til ham: følg mig! Og han stod op og fulgte ham.","Og der Jesus gik bort derfra, saae han et Menneske sidde i Toldboden, han hed Matthæus; og han siger til ham: følg mig! Og han stod op og fulgte ham."],[9,10,"Og det skete, der han sad tilbords i Huset, see, da kom og mange Toldere og Syndere og sadde tilbords med Jesus og hans Disciple.","Og det skete, der han sad tilbords i Huset, see, da kom og mange Toldere og Syndere og sadde tilbords med Jesus og hans Disciple."],[9,11,"Og der Pharisæerne saae det, sagde de til hans Disciple: hvi æder Eders Mester med Toldere og Syndere?","Og der Pharisæerne saae det, sagde de til hans Disciple: hvi æder Eders Mester med Toldere og Syndere?"],[9,12,"Men der Jesus det hørte, sagde han til dem: de Karske have ikke Lægen behov, men de, som lide ilde.","Men der Jesus det hørte, sagde han til dem: de Karske have ikke Lægen behov, men de, som lide ilde."],[9,13,"Men gaaer hen og lærer, hvad det er: Jeg vil Miskundhed og ikke Offer; thi jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse.","Men gaaer hen og lærer, hvad det er: Jeg vil Miskundhed og ikke Offer; thi jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse."],[9,14,"Da kom Johannes’ Disciple til ham og sagde: hvi faste vi og Pharisæerne meget, men dine Disciple faste ikke?","Da kom Johannes’ Disciple til ham og sagde: hvi faste vi og Pharisæerne meget, men dine Disciple faste ikke?"],[9,15,"Og Jesus sagde til dem: kunne Bryllupsfolkene sørge, saalænge Brudgommen er hos dem? Men de Dage skulle komme, naar Brudgommen skal borttages fra dem, og da skulle de faste.","Og Jesus sagde til dem: kunne Bryllupsfolkene sørge, saalænge Brudgommen er hos dem? Men de Dage skulle komme, naar Brudgommen skal borttages fra dem, og da skulle de faste."],[9,16,"Men Ingen sætter en Klud af nyt Klæde paa et gammelt Klædebon; thi Kluden river Noget fra Klædebonnet, og Hullet bliver være.","Men Ingen sætter en Klud af nyt Klæde paa et gammelt Klædebon; thi Kluden river Noget fra Klædebonnet, og Hullet bliver være."],[9,17,"Man lader og ikke ny Viin i gamle Læderflasker, ellers briste Læderflaskerne, og Viinen spildes, og Læderflaskerne fordærves; men man lader ny Viin i nye Læderflasker, saa blive de begge bevarede.","Man lader og ikke ny Viin i gamle Læderflasker, ellers briste Læderflaskerne, og Viinen spildes, og Læderflaskerne fordærves; men man lader ny Viin i nye Læderflasker, saa blive de begge bevarede."],[9,18,"Der han dette talede til dem, see, da kom en Øverste og faldt ned for ham og sagde: min Datter er just nu død; men kom og læg din Haand paa hende, saa bliver hun levende.","Der han dette talede til dem, see, da kom en Øverste og faldt ned for ham og sagde: min Datter er just nu død; men kom og læg din Haand paa hende, saa bliver hun levende."],[9,19,"Og Jesus stod op og fulgte ham med sine Disciple.","Og Jesus stod op og fulgte ham med sine Disciple."],[9,20,"Og see, en Kvinde, som havde tolv Aar havt Blodflod, traadte til bag fra og rørte ved Sømmen af hans Klædebon;","Og see, en Kvinde, som havde tolv Aar havt Blodflod, traadte til bag fra og rørte ved Sømmen af hans Klædebon;"],[9,21,"thi hun sagde ved sig selv: dersom jeg ikkun rører ved hans Klædebon, da bliver jeg helbredet.","thi hun sagde ved sig selv: dersom jeg ikkun rører ved hans Klædebon, da bliver jeg helbredet."],[9,22,"Men Jesus vendte sig om, og da han saae hende, sagde hen: Datter! vær frimodig, din tro haver frelst dig. Og Kvinden blev helbredet fra den samme Stund.","Men Jesus vendte sig om, og da han saae hende, sagde hen: Datter! vær frimodig, din tro haver frelst dig. Og Kvinden blev helbredet fra den samme Stund."],[9,23,"Og der Jesus kom i den Øverstes Huus, og saae Piberne og Folket, som buldrede, sagde han til dem:","Og der Jesus kom i den Øverstes Huus, og saae Piberne og Folket, som buldrede, sagde han til dem:"],[9,24,"viger bort, thi Pigen er ikke død, men hun sover. Og de beloe ham.","viger bort, thi Pigen er ikke død, men hun sover. Og de beloe ham."],[9,25,"Men der Folket var uddrevet, gik han ind og tog hende fat ved Haanden, da stod Pigen op.","Men der Folket var uddrevet, gik han ind og tog hende fat ved Haanden, da stod Pigen op."],[9,26,"Og dette Rygte kom ud i det ganske Land.","Og dette Rygte kom ud i det ganske Land."],[9,27,"Og der Jesus gik frem derfra, fulgte ham to Blinde, som raabte og sagde: du Davids Søn! forbarme dig over os.","Og der Jesus gik frem derfra, fulgte ham to Blinde, som raabte og sagde: du Davids Søn! forbarme dig over os."],[9,28,"Men der han kom i Huset, gik de Blinde til ham, og Jesus siger til dem: troe I, at jeg kan gjøre dette? De sige til ham: ja, Herre!","Men der han kom i Huset, gik de Blinde til ham, og Jesus siger til dem: troe I, at jeg kan gjøre dette? De sige til ham: ja, Herre!"],[9,29,"Da rørte han ved deres Øine og sagde: Eder skee efter Eders Tro!","Da rørte han ved deres Øine og sagde: Eder skee efter Eders Tro!"],[9,30,"Og deres Øine bleve aabnede. Og Jesus bød dem strengeligen og sagde: seer til, at Ingen faar det at vide.","Og deres Øine bleve aabnede. Og Jesus bød dem strengeligen og sagde: seer til, at Ingen faar det at vide."],[9,31,"Men da de gik ud, udspredte de hans Rygte i det ganske Land.","Men da de gik ud, udspredte de hans Rygte i det ganske Land."],[9,32,"Men der disse vare udgangne, see, da førte de et stumt Menneske til ham, som var besat.","Men der disse vare udgangne, see, da førte de et stumt Menneske til ham, som var besat."],[9,33,"Og der Djævelen var uddreven, talede den Stumme. Og Folket forundrede sig og sagde: aldrig er saadant seet i Israel.","Og der Djævelen var uddreven, talede den Stumme. Og Folket forundrede sig og sagde: aldrig er saadant seet i Israel."],[9,34,"Men Pharisæerne sagde: han uddriver Djævle ved Djævlenes Øverste.","Men Pharisæerne sagde: han uddriver Djævle ved Djævlenes Øverste."],[9,35,"Og Jesus gik omkring i alle Stæder og Byer, og lærte i deres Synagoger og prædikede Rigets Evangelium, og Helbredte al Sygdom og al Skrøbelighed iblandt Folket.","Og Jesus gik omkring i alle Stæder og Byer, og lærte i deres Synagoger og prædikede Rigets Evangelium, og Helbredte al Sygdom og al Skrøbelighed iblandt Folket."],[9,36,"Men der han saae Folket, ynkedes han inderligen over dem; thi de vare forsmægtede og adspredte som Faar, der ikke have Hyrde.","Men der han saae Folket, ynkedes han inderligen over dem; thi de vare forsmægtede og adspredte som Faar, der ikke have Hyrde."],[9,37,"Da sagde han til sine Disciple: Høsten er vel stor, men Arbeiderne faa;","Da sagde han til sine Disciple: Høsten er vel stor, men Arbeiderne faa;"],[9,38,"beder derfor Høstens Herre, at han udsender Arbeidere i sin Høst.","beder derfor Høstens Herre, at han udsender Arbeidere i sin Høst."],[10,1,"Og han kaldte sine tolv Disciple til sig, og gav dem Magt over de urene Aander, at uddrive dem, og at helbrede al Sygdom og al Skrøbelighed.","Og han kaldte sine tolv Disciple til sig, og gav dem Magt over de urene Aander, at uddrive dem, og at helbrede al Sygdom og al Skrøbelighed."],[10,2,"Men disse ere de tolv Apostlers Navne: den første, Simon, som kaldes Petrus, og Andreas, hans Broder; Jakobus, Zebedæus’ Søn, og Johannes, hans Broder;","Men disse ere de tolv Apostlers Navne: den første, Simon, som kaldes Petrus, og Andreas, hans Broder; Jakobus, Zebedæus’ Søn, og Johannes, hans Broder;"],[10,3,"Philippus og Bartholomæus; Thomas, og Matthæus den Tolder; Jakobus, Alphæus’ Søn, og Lebbæus med Tilnavnet Thaddæus;","Philippus og Bartholomæus; Thomas, og Matthæus den Tolder; Jakobus, Alphæus’ Søn, og Lebbæus med Tilnavnet Thaddæus;"],[10,4,"Simon Cananites, og Judas Ischariotes, som og forraadte ham.","Simon Cananites, og Judas Ischariotes, som og forraadte ham."],[10,5,"Disse Tolv udsendte Jesus, bød dem og sagde: gaaer ikke hen paa Hedningernes Vei, og gaaer ikke ind i de Samaritaners Stad.","Disse Tolv udsendte Jesus, bød dem og sagde: gaaer ikke hen paa Hedningernes Vei, og gaaer ikke ind i de Samaritaners Stad."],[10,6,"Men gaaer hellere hen til de fortabte Faar af Israels Huus.","Men gaaer hellere hen til de fortabte Faar af Israels Huus."],[10,7,"Og naar I gaae ud, da prædiker og siger, at Himmeriges Rige er kommet nær.","Og naar I gaae ud, da prædiker og siger, at Himmeriges Rige er kommet nær."],[10,8,"Helbreder de Syge, renser de spedalske, opvækker de Døde, uddriver Djævle. I have annammet det for Intet, giver det for Intet.","Helbreder de Syge, renser de spedalske, opvækker de Døde, uddriver Djævle. I have annammet det for Intet, giver det for Intet."],[10,9,"I skulle ikke have Guld, ei Sølv, ei Kobber i Eders Belter;","I skulle ikke have Guld, ei Sølv, ei Kobber i Eders Belter;"],[10,10,"ei Taske til at reise med, ei heller to Kjortler, ei heller Skoe, ei heller Stav; thi en Arbeider er sin Føde værd.","ei Taske til at reise med, ei heller to Kjortler, ei heller Skoe, ei heller Stav; thi en Arbeider er sin Føde værd."],[10,11,"Men hvilken Stad eller By I komme ind udi, udspørger, hvem der er i den, som er det værd, og bliver der, indtil I drage bort.","Men hvilken Stad eller By I komme ind udi, udspørger, hvem der er i den, som er det værd, og bliver der, indtil I drage bort."],[10,12,"Men naar I gaae ind i et Huus, da hilser det;","Men naar I gaae ind i et Huus, da hilser det;"],[10,13,"og dersom samme Huus er det værd, da komme Eders Fred over det; men dersom det ikke er det værd, da vende Eders Fred til Eder igjen,","og dersom samme Huus er det værd, da komme Eders Fred over det; men dersom det ikke er det værd, da vende Eders Fred til Eder igjen,"],[10,14,"og dersom Nogen ikke vil annamme Eder, og ei høre Eders Taler, gaaer ud af det Huus eller den Stad, og afryster Støvet af Eders Fødder.","og dersom Nogen ikke vil annamme Eder, og ei høre Eders Taler, gaaer ud af det Huus eller den Stad, og afryster Støvet af Eders Fødder."],[10,15,"Sandelig siger jeg Eder, det skal gaae de Sodomiters og Gomorriters Land lideligere paa Dommens Dag end denne Stad.","Sandelig siger jeg Eder, det skal gaae de Sodomiters og Gomorriters Land lideligere paa Dommens Dag end denne Stad."],[10,16,"See, jeg sender Eder som Faar midt iblandt Ulve, vorder derfor snilde som Slanger og eenfoldige som Duer.","See, jeg sender Eder som Faar midt iblandt Ulve, vorder derfor snilde som Slanger og eenfoldige som Duer."],[10,17,"Vogter Eder for Menneskene; thi de skulle overantvorde Eder til Raadet og hudstryge Eder i deres Synagoger.","Vogter Eder for Menneskene; thi de skulle overantvorde Eder til Raadet og hudstryge Eder i deres Synagoger."],[10,18,"I skulle og føres for Fyrster og Konger for min Skyld, dem og Hedningerne til et Vidnesbyrd.","I skulle og føres for Fyrster og Konger for min Skyld, dem og Hedningerne til et Vidnesbyrd."],[10,19,"Men naar de overantvorde Eder, da bekymrer Eder ikke for, hvorledes eller hvad I skulle tale; thi det skal gives Eder i den samme Time, hvad I skulle tale.","Men naar de overantvorde Eder, da bekymrer Eder ikke for, hvorledes eller hvad I skulle tale; thi det skal gives Eder i den samme Time, hvad I skulle tale."],[10,20,"Thi I ere ikke de, som tale, men det er Eders Faders Aand, som taler i Eder.","Thi I ere ikke de, som tale, men det er Eders Faders Aand, som taler i Eder."],[10,21,"Men en Broder skal forraade den anden til Døden, og en Fader sit Barn, og Børn skulle sætte sig op mod Forældre og aflive dem.","Men en Broder skal forraade den anden til Døden, og en Fader sit Barn, og Børn skulle sætte sig op mod Forældre og aflive dem."],[10,22,"Og I skulle hades af Alle for mit Navns Skyld; men den, som bliver bestandig indtil Enden, han skal blive salig.","Og I skulle hades af Alle for mit Navns Skyld; men den, som bliver bestandig indtil Enden, han skal blive salig."],[10,23,"Men naar de forfølge Eder i een Stad, da flyer til en anden; thi sandelig siger jeg Eder: I skulle ikke komme til Ende med Israels Stæder, førend Menneskens Søn kommer.","Men naar de forfølge Eder i een Stad, da flyer til en anden; thi sandelig siger jeg Eder: I skulle ikke komme til Ende med Israels Stæder, førend Menneskens Søn kommer."],[10,24,"Disciplen er ikke over Mesteren, ei heller Tjeneren over sin Herre.","Disciplen er ikke over Mesteren, ei heller Tjeneren over sin Herre."],[10,25,"Det er Disciplen nok, at han bliver som hans Mester, og Tjeneren som hans Herre; have de kaldet Huusbonden Beelzebul, hvor meget mere hans Huusfolk?","Det er Disciplen nok, at han bliver som hans Mester, og Tjeneren som hans Herre; have de kaldet Huusbonden Beelzebul, hvor meget mere hans Huusfolk?"],[10,26,"Frygter derfor ikke for dem; thi Intet er skjult, som jo skal aabenbares, og Intet er lønligt, som man jo skal faae at vide.","Frygter derfor ikke for dem; thi Intet er skjult, som jo skal aabenbares, og Intet er lønligt, som man jo skal faae at vide."],[10,27,"Hvad jeg siger Eder i Mørket, det taler i Lyset; og hvad der siges Eder i Øret, det prædiker paa Tagene.","Hvad jeg siger Eder i Mørket, det taler i Lyset; og hvad der siges Eder i Øret, det prædiker paa Tagene."],[10,28,"Og frygter ikke for dem, som slaae Legemet ihjel, men kunne ikke slaae Sjælen ihjel; men frygter hellere for den, som kan fordærve baade Sjæl og Legeme i Helvede.","Og frygter ikke for dem, som slaae Legemet ihjel, men kunne ikke slaae Sjælen ihjel; men frygter hellere for den, som kan fordærve baade Sjæl og Legeme i Helvede."],[10,29,"Sælges ikke to Spurve for en Penning? og ikke een af dem falder til Jorden uden Eders Faders Villie.","Sælges ikke to Spurve for en Penning? og ikke een af dem falder til Jorden uden Eders Faders Villie."],[10,30,"Ja, endog alle Eders Hovedhaar ere talte.","Ja, endog alle Eders Hovedhaar ere talte."],[10,31,"Frygter derfor ikke; I ere bedre end mange Spurve.","Frygter derfor ikke; I ere bedre end mange Spurve."],[10,32,"Derfor, hvo som vil bekjende mig for Menneskene, den vil jeg og bekjende for min Fader, som er i Himlene.","Derfor, hvo som vil bekjende mig for Menneskene, den vil jeg og bekjende for min Fader, som er i Himlene."],[10,33,"Men hvosomhelst vil negte mig for Menneskene, den vil jeg og negte for min Fader, som er i Himlene.","Men hvosomhelst vil negte mig for Menneskene, den vil jeg og negte for min Fader, som er i Himlene."],[10,34,"I skulle ikke mene, at jeg er kommen at bringe Fred paa Jorden; jeg er ikke kommen at bringe Fred, men Sværd.","I skulle ikke mene, at jeg er kommen at bringe Fred paa Jorden; jeg er ikke kommen at bringe Fred, men Sværd."],[10,35,"Thi jeg er kommen at tvistiggjøre et Menneske imod sin Fader, og Datteren imod sin Moder, og Sønnens Hustru imod hendes Mands Moder,","Thi jeg er kommen at tvistiggjøre et Menneske imod sin Fader, og Datteren imod sin Moder, og Sønnens Hustru imod hendes Mands Moder,"],[10,36,"og en Mands Huusfolk skulle være hans Fjender.","og en Mands Huusfolk skulle være hans Fjender."],[10,37,"Hvo som elsker Fader eller Moder mere end mig, er mig ikke værd; og hvo som elsker Søn eller Datter mere end mig, er mig ikke værd;","Hvo som elsker Fader eller Moder mere end mig, er mig ikke værd; og hvo som elsker Søn eller Datter mere end mig, er mig ikke værd;"],[10,38,"og hvo som ikke tager sit Kors, og følger efter mig, er mig ikke værd.","og hvo som ikke tager sit Kors, og følger efter mig, er mig ikke værd."],[10,39,"Hvo som finder sit Liv, skal miste det; og hvo som mister sit Liv for min Skyld, skal finde det.","Hvo som finder sit Liv, skal miste det; og hvo som mister sit Liv for min Skyld, skal finde det."],[10,40,"Hvo som annammer Eder, annammer mig; og hvo mig annammer, annammer den, som haver udsendt mig.","Hvo som annammer Eder, annammer mig; og hvo mig annammer, annammer den, som haver udsendt mig."],[10,41,"Hvo som annammer en Prophet, fordi han er en Prophet, skal faae en Prophets Løn; og hvo som annammer en Retfærdig, fordi han er en Retfærdig, skal faae en Retfærdigs Løn.","Hvo som annammer en Prophet, fordi han er en Prophet, skal faae en Prophets Løn; og hvo som annammer en Retfærdig, fordi han er en Retfærdig, skal faae en Retfærdigs Løn."],[10,42,"Og hvo som giver een af disse Ringe ikkun et Bæger koldt Vand at drikke, fordi han er en Discipel, sandelig siger jeg Eder, han skal ingenlunde miste sin Løn.","Og hvo som giver een af disse Ringe ikkun et Bæger koldt Vand at drikke, fordi han er en Discipel, sandelig siger jeg Eder, han skal ingenlunde miste sin Løn."],[11,1,"Og det skete, der Jesus havde fuldendt denne Befaling til sine tolv Disciple, gik han frem derfra, at lære og prædike i deres Stæder.","Og det skete, der Jesus havde fuldendt denne Befaling til sine tolv Disciple, gik han frem derfra, at lære og prædike i deres Stæder."],[11,2,"Men der Johannes hørte i Fængslet Christi Gjerninger, sendte han to af sine Disciple, og lod ham sige:","Men der Johannes hørte i Fængslet Christi Gjerninger, sendte han to af sine Disciple, og lod ham sige:"],[11,3,"er du den, som kommer, eller skulle vi vente en Anden?","er du den, som kommer, eller skulle vi vente en Anden?"],[11,4,"Og Jesus svarede og sagde til dem: gaaer hen, og forkynder Johannes de Ting, som I høre og see:","Og Jesus svarede og sagde til dem: gaaer hen, og forkynder Johannes de Ting, som I høre og see:"],[11,5,"Blinde see og Halte gaae, Spedalske renses og Døve høre, Døde staae op, og Evangelium prædikes for Fattige!","Blinde see og Halte gaae, Spedalske renses og Døve høre, Døde staae op, og Evangelium prædikes for Fattige!"],[11,6,"og salig er den, som ikke forarges paa mig.","og salig er den, som ikke forarges paa mig."],[11,7,"Men der disse gik bort, begyndte Jesus at sige til Folket om Johannes: hvad ere I udgangne i Ørken at skue? et Rør, som bevæges hid og did af Veiret?","Men der disse gik bort, begyndte Jesus at sige til Folket om Johannes: hvad ere I udgangne i Ørken at skue? et Rør, som bevæges hid og did af Veiret?"],[11,8,"Eller hvad ere I udgangne et see? et Menneske, iført bløde Klæder? See, de, som bære bløde Klæder, ere i Kongers Huse.","Eller hvad ere I udgangne et see? et Menneske, iført bløde Klæder? See, de, som bære bløde Klæder, ere i Kongers Huse."],[11,9,"Eller hvad ere I udgangne at see? en Prophet? Ja, jeg siger Eder, endog langt mere end en Prophet.","Eller hvad ere I udgangne at see? en Prophet? Ja, jeg siger Eder, endog langt mere end en Prophet."],[11,10,"Thi han er den, om hvem der er skrevet: see, jeg sender min Engel for dit Ansigt, som skal berede din Vei for dig.","Thi han er den, om hvem der er skrevet: see, jeg sender min Engel for dit Ansigt, som skal berede din Vei for dig."],[11,11,"Sandelig siger jeg Eder: iblandt dem, som ere fødte af Kvinder, er ingen Større opstanden end Johannes den Døber; men den Mindste i Himmeriges Rige er større end han.","Sandelig siger jeg Eder: iblandt dem, som ere fødte af Kvinder, er ingen Større opstanden end Johannes den Døber; men den Mindste i Himmeriges Rige er større end han."],[11,12,"Men fra Johannes den Døbers Dage indtil nu trænger man med Vold ind i Himmeriges Rige, og de, som trænge ind, rive det til sig.","Men fra Johannes den Døbers Dage indtil nu trænger man med Vold ind i Himmeriges Rige, og de, som trænge ind, rive det til sig."],[11,13,"Thi alle Propheter og Loven spaaede indtil Johannes.","Thi alle Propheter og Loven spaaede indtil Johannes."],[11,14,"Og dersom I ville tro det: han er Elias, som skal komme.","Og dersom I ville tro det: han er Elias, som skal komme."],[11,15,"Hvo som haver Øren at høre med, han høre!","Hvo som haver Øren at høre med, han høre!"],[11,16,"Men hvem skal jeg ligne denne Slægt ved? Den er lig de smaa Børn, som sidde paa Torvene og raabe til deres Stalbrødre og sige:","Men hvem skal jeg ligne denne Slægt ved? Den er lig de smaa Børn, som sidde paa Torvene og raabe til deres Stalbrødre og sige:"],[11,17,"vi fløitede for Eder, og I vilde ikke dandse; vi sang klagelig for Eder, og I vilde ikke græde.","vi fløitede for Eder, og I vilde ikke dandse; vi sang klagelig for Eder, og I vilde ikke græde."],[11,18,"Thi Johannes kom, som hverken aad eller drak, og de sige: han haver Djævelen.","Thi Johannes kom, som hverken aad eller drak, og de sige: han haver Djævelen."],[11,19,"Menneskens Søn kom, som æder og drikker, og de sige: see, en Fraadser og en Viindranker, Tolderes og Synderes Ven! Dog, Viisdommen er retfærdiggjort af sine Børn.","Menneskens Søn kom, som æder og drikker, og de sige: see, en Fraadser og en Viindranker, Tolderes og Synderes Ven! Dog, Viisdommen er retfærdiggjort af sine Børn."],[11,20,"Da begyndte han at skamme de Stæder ud, i hvilke hans fleste kraftige Gjerninger vare gjorte, fordi de ikke havde omvendt sig.","Da begyndte han at skamme de Stæder ud, i hvilke hans fleste kraftige Gjerninger vare gjorte, fordi de ikke havde omvendt sig."],[11,21,"Vee dig, Chorazin! vee dig, Bethsaida; thi havde de kraftige Gjerninger været gjorte i Tyrus og Sidon, som ere gjorte i Eder, da havde de længe siden omvendt sig i Sæk og Aske.","Vee dig, Chorazin! vee dig, Bethsaida; thi havde de kraftige Gjerninger været gjorte i Tyrus og Sidon, som ere gjorte i Eder, da havde de længe siden omvendt sig i Sæk og Aske."],[11,22,"Men jeg siger Eder: det skal gaae Tyrus og Sidon lideligere paa Dommens Dag end Eder.","Men jeg siger Eder: det skal gaae Tyrus og Sidon lideligere paa Dommens Dag end Eder."],[11,23,"Og du, Capernaum! som er ophøiet indtil Himmelen, du skal nedstødes indtil Helvede; thi dersom de kraftige Gjerninger havde været gjorte i Sodoma, som ere gjorte i dig, var den bleven indtil denne Dag.","Og du, Capernaum! som er ophøiet indtil Himmelen, du skal nedstødes indtil Helvede; thi dersom de kraftige Gjerninger havde været gjorte i Sodoma, som ere gjorte i dig, var den bleven indtil denne Dag."],[11,24,"Men jeg siger Eder: det skal gaae Sodomas Land lideligere paa Dommens Dag end dig.","Men jeg siger Eder: det skal gaae Sodomas Land lideligere paa Dommens Dag end dig."],[11,25,"Paa den samme Tid udbrød Jesus og sagde: jeg priser dig, Fader, Himmelens og Jordens Herre! at du haver skjult dette for de Vise og Forstandige, og aabenbaret det for de Umyndige.","Paa den samme Tid udbrød Jesus og sagde: jeg priser dig, Fader, Himmelens og Jordens Herre! at du haver skjult dette for de Vise og Forstandige, og aabenbaret det for de Umyndige."],[11,26,"Ja, Fader! thi det var saaledes behageligt for dig.","Ja, Fader! thi det var saaledes behageligt for dig."],[11,27,"Alle Ting ere mig overgivne af min Fader; og Ingen kjender Sønnen uden Faderen, og Ingen kjender Faderen uden Sønnen, og den, som Sønnen vil det aabenbare.","Alle Ting ere mig overgivne af min Fader; og Ingen kjender Sønnen uden Faderen, og Ingen kjender Faderen uden Sønnen, og den, som Sønnen vil det aabenbare."],[11,28,"Kommer hid til mig Alle, som arbeide og ere besværede! og jeg vil give Eder Hvile.","Kommer hid til mig Alle, som arbeide og ere besværede! og jeg vil give Eder Hvile."],[11,29,"Tager mit Aag paa Eder, og lærer af mig, thi jeg er sagtmodig og ydmyg af Hjertet: saa skulle I finde Hvile for Eders Sjæle.","Tager mit Aag paa Eder, og lærer af mig, thi jeg er sagtmodig og ydmyg af Hjertet: saa skulle I finde Hvile for Eders Sjæle."],[11,30,"Thi mit Aag er gavnligt, og min Byrde er let.","Thi mit Aag er gavnligt, og min Byrde er let."],[12,1,"Paa den samme Tid gik Jesus igjennem Sæden paa Sabbaten; men hans Disciple hungrede og begyndte at plukke Ax, og at æde.","Paa den samme Tid gik Jesus igjennem Sæden paa Sabbaten; men hans Disciple hungrede og begyndte at plukke Ax, og at æde."],[12,2,"Men der Pharisæerne saae det, sagde de til ham: see, dine Disciple gjøre det, som ikke er tilladt at gjøre paa Sabbaten.","Men der Pharisæerne saae det, sagde de til ham: see, dine Disciple gjøre det, som ikke er tilladt at gjøre paa Sabbaten."],[12,3,"Men han sagde til dem: have I ikke læst, hvad David gjorde, der han hungrede, og de, som vare med ham?","Men han sagde til dem: have I ikke læst, hvad David gjorde, der han hungrede, og de, som vare med ham?"],[12,4,"Hvorledes han gik ind i Guds Huus og aad Skuebrødene, hvilke det ikke var ham tilladt at æde, ei heller dem, som vare med ham, men alene Præsterne?","Hvorledes han gik ind i Guds Huus og aad Skuebrødene, hvilke det ikke var ham tilladt at æde, ei heller dem, som vare med ham, men alene Præsterne?"],[12,5,"Eller have I ikke læst i Loven, at Præsterne vanhellige Sabbaten i Templet paa Sabbaterne, og ere uskyldige?","Eller have I ikke læst i Loven, at Præsterne vanhellige Sabbaten i Templet paa Sabbaterne, og ere uskyldige?"],[12,6,"Men jeg siger Eder, at den er her, som er større end Templet.","Men jeg siger Eder, at den er her, som er større end Templet."],[12,7,"Men dersom I havde vidst, hvad det er: jeg haver Villie til Miskundhed, og ikke til Offer, da havde I ikke fordømt de Uskyldige.","Men dersom I havde vidst, hvad det er: jeg haver Villie til Miskundhed, og ikke til Offer, da havde I ikke fordømt de Uskyldige."],[12,8,"Thi Menneskens Søn er Herre, ogsaa over Sabbaten.","Thi Menneskens Søn er Herre, ogsaa over Sabbaten."],[12,9,"Og han gik frem derfra og kom i deres Synagoge.","Og han gik frem derfra og kom i deres Synagoge."],[12,10,"Og see, der var et Menneske, som havde en vissen Haand; og de spurgte ham ad og sagde: er det tilladt at helbrede paa Sabbaten? at de kunde anklage ham.","Og see, der var et Menneske, som havde en vissen Haand; og de spurgte ham ad og sagde: er det tilladt at helbrede paa Sabbaten? at de kunde anklage ham."],[12,11,"Men han sagde til dem: hvilket Menneske er blandt Eder, som haver eet Faar og ikke, dersom det falder i en Grav paa Sabbaten, tager fat paa det og løfter det op?","Men han sagde til dem: hvilket Menneske er blandt Eder, som haver eet Faar og ikke, dersom det falder i en Grav paa Sabbaten, tager fat paa det og løfter det op?"],[12,12,"Hvor meget bedre er nu et Menneske end et Faar? Altsaa er det tilladt, at gjøre vel paa Sabbaten.","Hvor meget bedre er nu et Menneske end et Faar? Altsaa er det tilladt, at gjøre vel paa Sabbaten."],[12,13,"Da sagde han til Mennesket: udræk din Haand! og han rakte den ud, og den blev igjen sund som den anden.","Da sagde han til Mennesket: udræk din Haand! og han rakte den ud, og den blev igjen sund som den anden."],[12,14,"Men Pharisæerne gik ud og holdt Raad mod ham, hvorledes de kunde omkomme ham.","Men Pharisæerne gik ud og holdt Raad mod ham, hvorledes de kunde omkomme ham."],[12,15,"Men der Jesus mærkede det, veg han bort derfra; og meget Folk fulgte ham, og han helbredte dem alle.","Men der Jesus mærkede det, veg han bort derfra; og meget Folk fulgte ham, og han helbredte dem alle."],[12,16,"Og han bød dem strengeligen, at de ikke maatte aabenbare ham;","Og han bød dem strengeligen, at de ikke maatte aabenbare ham;"],[12,17,"at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger:","at det skulde fuldkommes, som er talet ved Propheten Esaias, som siger:"],[12,18,"see, min Tjener, som jeg haver udvalgt, min Elskelige, til hvilken min Sjæl haver Velbehagelighed! jeg vil give min Aand i ham, og han skal forkynde Hedningerne Ret.","see, min Tjener, som jeg haver udvalgt, min Elskelige, til hvilken min Sjæl haver Velbehagelighed! jeg vil give min Aand i ham, og han skal forkynde Hedningerne Ret."],[12,19,"Han skal ikke trætte og ei raabe, og der skal ikke Nogen høre hans Røst paa Gaderne.","Han skal ikke trætte og ei raabe, og der skal ikke Nogen høre hans Røst paa Gaderne."],[12,20,"Han skal ikke sønderbryde det knusede Rør, og ei udslukke den rygende Taande, indtil han udfører Retten til Seier.","Han skal ikke sønderbryde det knusede Rør, og ei udslukke den rygende Taande, indtil han udfører Retten til Seier."],[12,21,"Og Hedningerne skulle haabe paa hans Navn.","Og Hedningerne skulle haabe paa hans Navn."],[12,22,"Da blev en Besat ført til ham, som var blind og stum; og han helbredte ham, saa at den Blinde og Stumme baade talede og saae.","Da blev en Besat ført til ham, som var blind og stum; og han helbredte ham, saa at den Blinde og Stumme baade talede og saae."],[12,23,"Og alt Folket forfærdedes og sagde: mon denne ikke er den Davids Søn?","Og alt Folket forfærdedes og sagde: mon denne ikke er den Davids Søn?"],[12,24,"Men der Pharisæerne det hørte, sagde de: denne uddriver ikke Djævle, uden ved Beelzebul, Djævelens Øverste.","Men der Pharisæerne det hørte, sagde de: denne uddriver ikke Djævle, uden ved Beelzebul, Djævelens Øverste."],[12,25,"Men saasom Jesus vidste deres Tanker, sagde han til dem: hvert Rige, som er splidagtigt med sig selv, bliver øde; og hver Stad eller Huus, som er splidagtigt med sig selv, kan ikke bestaae.","Men saasom Jesus vidste deres Tanker, sagde han til dem: hvert Rige, som er splidagtigt med sig selv, bliver øde; og hver Stad eller Huus, som er splidagtigt med sig selv, kan ikke bestaae."],[12,26,"Hvis da Satan uddriver Satan, saa er han splidagtig med sig selv; hvorledes kan da hans Rige bestaae?","Hvis da Satan uddriver Satan, saa er han splidagtig med sig selv; hvorledes kan da hans Rige bestaae?"],[12,27,"Og om jeg uddriver Djævle ved Beelzebul, ved hvem uddrive da Eders Børn dem? Derfor skulle de være Eders Dommere.","Og om jeg uddriver Djævle ved Beelzebul, ved hvem uddrive da Eders Børn dem? Derfor skulle de være Eders Dommere."],[12,28,"Men dersom jeg uddriver Djævle ved Guds Aand, er jo Guds Rige kommet til Eder.","Men dersom jeg uddriver Djævle ved Guds Aand, er jo Guds Rige kommet til Eder."],[12,29,"Eller hvorledes kan Nogen gaae ind i den Stærkes Huus, og røve ham hans Redskaber fra, uden at han først binder den Stærke? Da kan han plyndre hans Huus.","Eller hvorledes kan Nogen gaae ind i den Stærkes Huus, og røve ham hans Redskaber fra, uden at han først binder den Stærke? Da kan han plyndre hans Huus."],[12,30,"Hvo som ikke er med mig, er imod mig; og hvo som ikke samler med mig, adspreder.","Hvo som ikke er med mig, er imod mig; og hvo som ikke samler med mig, adspreder."],[12,31,"Derfor siger jeg Eder: al Synd og Bespottelse skal forlades Menneskene, men Bespottelse imod Anden skal ikke forlades Menneskene.","Derfor siger jeg Eder: al Synd og Bespottelse skal forlades Menneskene, men Bespottelse imod Anden skal ikke forlades Menneskene."],[12,32,"Og hvo som taler Noget imod Menneskens Søn, det skal forlades ham; men hvo som taler imod den Hellig Aand, han skal det ikke forlades, hverken i denne Verden, ei heller i den tilkommende.","Og hvo som taler Noget imod Menneskens Søn, det skal forlades ham; men hvo som taler imod den Hellig Aand, han skal det ikke forlades, hverken i denne Verden, ei heller i den tilkommende."],[12,33,"Lader enten Træet være godt, og dets Frugt god; eller lader Træet være raaddent, og dets Frugt raadden; thi Træet kjendes paa Frugten.","Lader enten Træet være godt, og dets Frugt god; eller lader Træet være raaddent, og dets Frugt raadden; thi Træet kjendes paa Frugten."],[12,34,"I Øgleunger! hvorledes kunne I tale godt, I som ere onde? thi af Hjertets Overflødighed taler Munden.","I Øgleunger! hvorledes kunne I tale godt, I som ere onde? thi af Hjertets Overflødighed taler Munden."],[12,35,"Et godt Menneske fremfører gode Ting af Hjertets gode Forraad; og et ondt Menneske fremfører onde Ting af det onde Forraad.","Et godt Menneske fremfører gode Ting af Hjertets gode Forraad; og et ondt Menneske fremfører onde Ting af det onde Forraad."],[12,36,"Men jeg siger Eder, at Menneskene skulle gjøre Regnskab paa Dommens Dag for hvert utilbørligt Ord, som de have talet.","Men jeg siger Eder, at Menneskene skulle gjøre Regnskab paa Dommens Dag for hvert utilbørligt Ord, som de have talet."],[12,37,"Thi af dine Ord skal du kjendes retfærdig, og af dine Ord skal du fordømmes.","Thi af dine Ord skal du kjendes retfærdig, og af dine Ord skal du fordømmes."],[12,38,"Da svarede nogle af de Skriftkloge og Pharisæer og sagde: Mester! vi ville see et Tegn af dig.","Da svarede nogle af de Skriftkloge og Pharisæer og sagde: Mester! vi ville see et Tegn af dig."],[12,39,"Men han svarede og sagde til dem: den onde og vanartige Slægt begjerer Tegn, men den skal intet Tegn gives, uden Jonas’ Prophetens Tegn.","Men han svarede og sagde til dem: den onde og vanartige Slægt begjerer Tegn, men den skal intet Tegn gives, uden Jonas’ Prophetens Tegn."],[12,40,"Thi ligesom Jonas var tre Dage og tre Nætter i Hvalfiskens Bug, saaledes skal Menneskens Søn være tre Dage og tre Nætter i Jordens Skjød.","Thi ligesom Jonas var tre Dage og tre Nætter i Hvalfiskens Bug, saaledes skal Menneskens Søn være tre Dage og tre Nætter i Jordens Skjød."],[12,41,"De Mænd af Ninive skulle opstaae ved Dommen imod denne Slægt, og fordømme den; thi de omvendte sig ved Jonas’ Prædiken; og see, her er Mere end Jonas.","De Mænd af Ninive skulle opstaae ved Dommen imod denne Slægt, og fordømme den; thi de omvendte sig ved Jonas’ Prædiken; og see, her er Mere end Jonas."],[12,42,"Dronningen fra Sønden skal opstaae ved Dommen imod denne Slægt, og fordømme den; thi hun kom fra Jordens Grændser at høre Salomons Viisdom; og see, her er Mere end Salomon.","Dronningen fra Sønden skal opstaae ved Dommen imod denne Slægt, og fordømme den; thi hun kom fra Jordens Grændser at høre Salomons Viisdom; og see, her er Mere end Salomon."],[12,43,"Men naar den urene Aand er udfaren af Mennesket, vandrer han igjennem tørre Steder, søger Hvile, og finder den ikke.","Men naar den urene Aand er udfaren af Mennesket, vandrer han igjennem tørre Steder, søger Hvile, og finder den ikke."],[12,44,"Da siger han: jeg vil vende om til mit Huus, som jeg gik ud af; og naar han kommer, finder han det ledigt, feiet og prydet.","Da siger han: jeg vil vende om til mit Huus, som jeg gik ud af; og naar han kommer, finder han det ledigt, feiet og prydet."],[12,45,"Saa gaaer han hen, og tager syv andre Aander tillige med sig, som ere værre end han selv, og naar de ere komne derind, boe de der; og det Sidste bliver værre med dette Menneske end det Første. Saaledes skal det og gaae denne onde Slægt.","Saa gaaer han hen, og tager syv andre Aander tillige med sig, som ere værre end han selv, og naar de ere komne derind, boe de der; og det Sidste bliver værre med dette Menneske end det Første. Saaledes skal det og gaae denne onde Slægt."],[12,46,"Men der han endnu talede til Folket, see, da stode hans Moder og hans Brødre udenfor og begjerede at tale med ham.","Men der han endnu talede til Folket, see, da stode hans Moder og hans Brødre udenfor og begjerede at tale med ham."],[12,47,"Da sagde En til ham: see, din Moder og dine Brødre staae udenfor og begjere at tale med dig.","Da sagde En til ham: see, din Moder og dine Brødre staae udenfor og begjere at tale med dig."],[12,48,"Men han svarede og sagde til den, som sagde ham det: hvo er min Moder? og hvilke ere mine Brødre?","Men han svarede og sagde til den, som sagde ham det: hvo er min Moder? og hvilke ere mine Brødre?"],[12,49,"Og han rakte sin Haand ud over sine Disciple og sagde: see, min Moder og mine Brødre!","Og han rakte sin Haand ud over sine Disciple og sagde: see, min Moder og mine Brødre!"],[12,50,"Thi hvo som gjør min Faders Villie, som er i Himlene, den er min Broder og Søster og Moder.","Thi hvo som gjør min Faders Villie, som er i Himlene, den er min Broder og Søster og Moder."],[13,1,"Paa den samme Dag gik Jesus ud af Huset og satte sig ved Søen.","Paa den samme Dag gik Jesus ud af Huset og satte sig ved Søen."],[13,2,"Og meget Folk forsamledes til ham, saa han steg i Skibet og satte sig; og alt Folket stod paa Strandbredden.","Og meget Folk forsamledes til ham, saa han steg i Skibet og satte sig; og alt Folket stod paa Strandbredden."],[13,3,"Og han talede meget til dem ved Lignelser og sagde: see, en Sædemand gik ud at saae.","Og han talede meget til dem ved Lignelser og sagde: see, en Sædemand gik ud at saae."],[13,4,"Og idet han saaede, faldt Noget ved Veien; og Fuglene kom, og aade det op.","Og idet han saaede, faldt Noget ved Veien; og Fuglene kom, og aade det op."],[13,5,"Men Noget faldt paa Steengrund, hvor det ikke havde megen Jord; og det voxte snart op, fordi det ikke havde dyb Jord.","Men Noget faldt paa Steengrund, hvor det ikke havde megen Jord; og det voxte snart op, fordi det ikke havde dyb Jord."],[13,6,"Men der Solen gik op, blev det forbrændt, og fordi det ikke havde Rod, visnede det.","Men der Solen gik op, blev det forbrændt, og fordi det ikke havde Rod, visnede det."],[13,7,"Men Noget faldt iblandt Torne; og Tornene voxte op og kvalte det.","Men Noget faldt iblandt Torne; og Tornene voxte op og kvalte det."],[13,8,"Men Noget faldt i god Jord, og bar Frugt; Noget hundrede Fold, men Noget tresindstyve Fold, men Noget tredive Fold.","Men Noget faldt i god Jord, og bar Frugt; Noget hundrede Fold, men Noget tresindstyve Fold, men Noget tredive Fold."],[13,9,"Hvo som haver Øren at høre med, han høre!","Hvo som haver Øren at høre med, han høre!"],[13,10,"Og Disciplene gik til ham og sagde til ham: hvi taler du til dem ved Lignelser?","Og Disciplene gik til ham og sagde til ham: hvi taler du til dem ved Lignelser?"],[13,11,"Men han svarede og sagde til dem: Eder er det givet at forstaae Himmeriges Riges Hemmeligheder; men dem er det ikke givet.","Men han svarede og sagde til dem: Eder er det givet at forstaae Himmeriges Riges Hemmeligheder; men dem er det ikke givet."],[13,12,"Thi hvo som haver, han skal gives, og han skal have til Overflod; men hvo som ikke haver, ham skal endog fratages det, han haver.","Thi hvo som haver, han skal gives, og han skal have til Overflod; men hvo som ikke haver, ham skal endog fratages det, han haver."],[13,13,"Derfor taler jeg til dem ved Lignelser, fordi de, skjøndt seende, dog ikke see, og hørende dog ikke høre, og forstaae ikke heller.","Derfor taler jeg til dem ved Lignelser, fordi de, skjøndt seende, dog ikke see, og hørende dog ikke høre, og forstaae ikke heller."],[13,14,"Og i dem fuldkommes Esaias’ Spaadom, som siger: med Eders Øren skulle I høre, og dog ikke forstaae, og see med Eders Øine, og ikke fatte.","Og i dem fuldkommes Esaias’ Spaadom, som siger: med Eders Øren skulle I høre, og dog ikke forstaae, og see med Eders Øine, og ikke fatte."],[13,15,"Thi dette Folks Hjerte er blevet forhærdet, og med Ørene høre de tungt, og deres Øine have de tillukt, paa det de ikke skulle komme til at see med Øinene og høre med Ørene og forstaae med Hjertet, og omvende sig, at jeg maatte helbrede dem.","Thi dette Folks Hjerte er blevet forhærdet, og med Ørene høre de tungt, og deres Øine have de tillukt, paa det de ikke skulle komme til at see med Øinene og høre med Ørene og forstaae med Hjertet, og omvende sig, at jeg maatte helbrede dem."],[13,16,"Men salige ere Eders Øine, at de see, og Eders Øren, at de høre.","Men salige ere Eders Øine, at de see, og Eders Øren, at de høre."],[13,17,"Thi sandelig siger jeg Eder: mange Propheter og Retfærdige begjerede at see det, I see, og saae det ikke; og at høre det, I høre, og hørte det ikke.","Thi sandelig siger jeg Eder: mange Propheter og Retfærdige begjerede at see det, I see, og saae det ikke; og at høre det, I høre, og hørte det ikke."],[13,18,"Saa hører I nu den Lignelse om Sædemanden.","Saa hører I nu den Lignelse om Sædemanden."],[13,19,"Naar Nogen hører Rigets Ord, og forstaar det ikke, da kommer den Onde, og river det bort, som er saaet i hans Hjerte, denne er det, som er saaet ved Veien.","Naar Nogen hører Rigets Ord, og forstaar det ikke, da kommer den Onde, og river det bort, som er saaet i hans Hjerte, denne er det, som er saaet ved Veien."],[13,20,"Men det, som er saaet paa Steengrund, er den, som hører Ordet, og annammer det strax med Glæde.","Men det, som er saaet paa Steengrund, er den, som hører Ordet, og annammer det strax med Glæde."],[13,21,"Men han haver ikke Rod i sig, og bliver kun ved til en Tid; men naar Trængsel eller Forfølgelse kommer for Ordets Skyld, forarges han strax.","Men han haver ikke Rod i sig, og bliver kun ved til en Tid; men naar Trængsel eller Forfølgelse kommer for Ordets Skyld, forarges han strax."],[13,22,"Men det, som er saaet iblandt Torne, er den, som hører Ordet; og denne Verdens Bekymring og Rigdoms Forførelse kvæler Ordet, og det bliver uden Frugt.","Men det, som er saaet iblandt Torne, er den, som hører Ordet; og denne Verdens Bekymring og Rigdoms Forførelse kvæler Ordet, og det bliver uden Frugt."],[13,23,"Men det, som er saaet i god Jord, er den, som hører Ordet, og forstaae det, som ogsaa bærer Frugt, En hundrede Fold, en Anden tresindstyve Fold, en Anden tredive Fold.","Men det, som er saaet i god Jord, er den, som hører Ordet, og forstaae det, som ogsaa bærer Frugt, En hundrede Fold, en Anden tresindstyve Fold, en Anden tredive Fold."],[13,24,"Han fremsatte en anden Lignelse for dem og sagde: Himmeriges Rige lignes ved et Menneske, som saaede god Sæd i sin Ager.","Han fremsatte en anden Lignelse for dem og sagde: Himmeriges Rige lignes ved et Menneske, som saaede god Sæd i sin Ager."],[13,25,"Men der Folkene sov, kom hans Fjende, og saaede Klinte iblandt Hveden, og gik bort.","Men der Folkene sov, kom hans Fjende, og saaede Klinte iblandt Hveden, og gik bort."],[13,26,"Men der Grøden voxte og bar Frugt, da lod ogsaa Klinten sig tilsyne.","Men der Grøden voxte og bar Frugt, da lod ogsaa Klinten sig tilsyne."],[13,27,"Men Huusbondens Tjenere kom frem og sagde til ham: Herre, saaede du ikke god Sæd i din Ager? Hvorfra haver den da Klinten?","Men Huusbondens Tjenere kom frem og sagde til ham: Herre, saaede du ikke god Sæd i din Ager? Hvorfra haver den da Klinten?"],[13,28,"Han sagde til ham: det haver et fjendsk Menneske gjort. Da sagde Tjeneren til ham: vil du da, at vi skulle gaae hen og luge den af?","Han sagde til ham: det haver et fjendsk Menneske gjort. Da sagde Tjeneren til ham: vil du da, at vi skulle gaae hen og luge den af?"],[13,29,"Men han sagde: nei, paa det I ikke skulle tillige med den rykke Hveden op, naar I luge Klinten af.","Men han sagde: nei, paa det I ikke skulle tillige med den rykke Hveden op, naar I luge Klinten af."],[13,30,"Lader dem begge voxe tilsammen indtil Høsten; og i Høstens Tid vil jeg sige til Høstfolkene: sanker først Klinten tilsammen, og binder den i Knipper, at opbrænde den; men samler Hveden i min lade.","Lader dem begge voxe tilsammen indtil Høsten; og i Høstens Tid vil jeg sige til Høstfolkene: sanker først Klinten tilsammen, og binder den i Knipper, at opbrænde den; men samler Hveden i min lade."],[13,31,"Han fremsatte en anden Lignelse for dem og sagde: Himmeriges Rige ligner et Sennepskorn, som et Menneske tog og saaede i sin Ager.","Han fremsatte en anden Lignelse for dem og sagde: Himmeriges Rige ligner et Sennepskorn, som et Menneske tog og saaede i sin Ager."],[13,32,"Dette er vel mindre end alt andet Frø; men naar det voxer op, er det større end Urterne, og bliver et Træ, saa at Himmelens Fugle komme og bygge Rede i dets Grene.","Dette er vel mindre end alt andet Frø; men naar det voxer op, er det større end Urterne, og bliver et Træ, saa at Himmelens Fugle komme og bygge Rede i dets Grene."],[13,33,"Han sagde dem en anden Lignelse: Himmeriges Rige ligner en Suurdeig, hvilken en Kvinde tog og nedlagde i tre Maader Meel, indtil det blev syret altsammen.","Han sagde dem en anden Lignelse: Himmeriges Rige ligner en Suurdeig, hvilken en Kvinde tog og nedlagde i tre Maader Meel, indtil det blev syret altsammen."],[13,34,"Alt dette talede Jesus til Folket ved Lignelser, og uden Lignelse talede han Intet til dem;","Alt dette talede Jesus til Folket ved Lignelser, og uden Lignelse talede han Intet til dem;"],[13,35,"at det skulde fuldkommes, som er talet ved Propheten, som siger: jeg vil oplade min Mund i Lignelser; jeg vil udsige det, som haver været skjult fra Verdens Grundvold blev lagt.","at det skulde fuldkommes, som er talet ved Propheten, som siger: jeg vil oplade min Mund i Lignelser; jeg vil udsige det, som haver været skjult fra Verdens Grundvold blev lagt."],[13,36,"Da lod Jesus Folket fare og kom til sit Huus; og hans Disciple gik til ham og sagde: forklar os den Lignelse om Klinten paa Ageren.","Da lod Jesus Folket fare og kom til sit Huus; og hans Disciple gik til ham og sagde: forklar os den Lignelse om Klinten paa Ageren."],[13,37,"Men han svarede og sagde til dem: den, som saaer den gode Sæd, er Menneskens Søn.","Men han svarede og sagde til dem: den, som saaer den gode Sæd, er Menneskens Søn."],[13,38,"Men Ageren er Verden; og den gode Sæd er Rigets Børn; og Klinten er den Ondes Børn;","Men Ageren er Verden; og den gode Sæd er Rigets Børn; og Klinten er den Ondes Børn;"],[13,39,"og Fjenden, som den saaede, er Djævelen; og Høsten er Verdens Ende; og Høstfolkene ere Englene.","og Fjenden, som den saaede, er Djævelen; og Høsten er Verdens Ende; og Høstfolkene ere Englene."],[13,40,"Derfor, ligesom Klinten sankes og opbrændes med Ild, saa skal det og skee ved denne Verdens Ende.","Derfor, ligesom Klinten sankes og opbrændes med Ild, saa skal det og skee ved denne Verdens Ende."],[13,41,"Menneskens Søn skal udsende sine Engle, og de skulle sanke af hans Rige alle Forargelser og dem, som gjøre Uret.","Menneskens Søn skal udsende sine Engle, og de skulle sanke af hans Rige alle Forargelser og dem, som gjøre Uret."],[13,42,"Og de skulle kaste dem i Ild-Ovnen; der skal være Graad og Tænders Gnidsel.","Og de skulle kaste dem i Ild-Ovnen; der skal være Graad og Tænders Gnidsel."],[13,43,"Da skulle de Retfærdige skinne som Solen i deres Faders Rige. Hvo som haver Øren at høre med, han høre.","Da skulle de Retfærdige skinne som Solen i deres Faders Rige. Hvo som haver Øren at høre med, han høre."],[13,44,"Atter lignes Himmerigets Rige ved et Liggendefæ, skjult i en Ager, hvilket et Menneske fandt og skjulte, og gik hen af Glæde derover og solgte alt det, han havde, og kjøbte den Ager.","Atter lignes Himmerigets Rige ved et Liggendefæ, skjult i en Ager, hvilket et Menneske fandt og skjulte, og gik hen af Glæde derover og solgte alt det, han havde, og kjøbte den Ager."],[13,45,"Atter lignes Himmeriges Rige ved en Kjøbmand, som søgte efter gode Perler;","Atter lignes Himmeriges Rige ved en Kjøbmand, som søgte efter gode Perler;"],[13,46,"hvilken, der han fandt en meget kostelig Perle, gik hen og solgte alt det, han havde, og købte samme.","hvilken, der han fandt en meget kostelig Perle, gik hen og solgte alt det, han havde, og købte samme."],[13,47,"Atter er Himmerigets Rige ligt en Vod, som kastes i Havet, og som samler af alle slags Fisk.","Atter er Himmerigets Rige ligt en Vod, som kastes i Havet, og som samler af alle slags Fisk."],[13,48,"Naar den er fuld, drage de den op paa Strandbredden, og sidde og sanke de gode tilsammen i Kar, men de raadne kaste de ud.","Naar den er fuld, drage de den op paa Strandbredden, og sidde og sanke de gode tilsammen i Kar, men de raadne kaste de ud."],[13,49,"Saaledes skal det gaae ved Verdens Ende. Englene skulle udgaae, og skille de Onde ud fra de Retfærdige,","Saaledes skal det gaae ved Verdens Ende. Englene skulle udgaae, og skille de Onde ud fra de Retfærdige,"],[13,50,"og kaste dem i Ild-Ovnen; der skal være Graad og Tænders Gnidsel.","og kaste dem i Ild-Ovnen; der skal være Graad og Tænders Gnidsel."],[13,51,"Jesus siger til dem: forstode I dette altsammen? De sige til ham: ja, Herre!","Jesus siger til dem: forstode I dette altsammen? De sige til ham: ja, Herre!"],[13,52,"Men han sagde til dem: saaledes er hver Skriftklog, som er oplært til Himmeriges Rige, ligesom en Huusbonde, der bringer frem af sit Forraad Nyt og Gammelt.","Men han sagde til dem: saaledes er hver Skriftklog, som er oplært til Himmeriges Rige, ligesom en Huusbonde, der bringer frem af sit Forraad Nyt og Gammelt."],[13,53,"Og det begav sig, der Jesus havde fuldendt disse Lignelser, drog han bort derfra.","Og det begav sig, der Jesus havde fuldendt disse Lignelser, drog han bort derfra."],[13,54,"Og han kom til sit Fædreneland, og lærte dem i deres Synagoge, saa at de forundrede sig saare og sagde: hveden haver denne saadan Viisdom og de kraftige Gjerninger?","Og han kom til sit Fædreneland, og lærte dem i deres Synagoge, saa at de forundrede sig saare og sagde: hveden haver denne saadan Viisdom og de kraftige Gjerninger?"],[13,55,"Er denne ikke den Tømmermands Søn? hedder ikke hans Moder Maria? og hans Brødre Jakob og Joses og Simon og Judas?","Er denne ikke den Tømmermands Søn? hedder ikke hans Moder Maria? og hans Brødre Jakob og Joses og Simon og Judas?"],[13,56,"Og ere ikke alle hans Søstre hos os? hveden haver denne da alt dette?","Og ere ikke alle hans Søstre hos os? hveden haver denne da alt dette?"],[13,57,"Og de forargedes paa ham. Men Jesus sagde til dem: en Prophet er ikke foragtet, uden i sit Fædreneland og i sit Huus.","Og de forargedes paa ham. Men Jesus sagde til dem: en Prophet er ikke foragtet, uden i sit Fædreneland og i sit Huus."],[13,58,"Og han gjorde der ikke mange kraftige Gjerninger formedelst deres Vantro.","Og han gjorde der ikke mange kraftige Gjerninger formedelst deres Vantro."],[14,1,"Paa den samme Tid hørte Herodes, den Fjerdingsfyrste, Rygtet om Jesus.","Paa den samme Tid hørte Herodes, den Fjerdingsfyrste, Rygtet om Jesus."],[14,2,"Og han sagde til sine Tjenere: denne er Johannes den Døber; han er opreist fra de Døde, derfor tee sig og de kraftige Gjerninger i ham.","Og han sagde til sine Tjenere: denne er Johannes den Døber; han er opreist fra de Døde, derfor tee sig og de kraftige Gjerninger i ham."],[14,3,"Thi Herodes havde grebet Johannes og bundet ham og kastet ham i Fængsel for Herodias’, sin Broder Philips Hustrues, Skyld.","Thi Herodes havde grebet Johannes og bundet ham og kastet ham i Fængsel for Herodias’, sin Broder Philips Hustrues, Skyld."],[14,4,"Thi Johannes sagde til ham: det er dig ikke tilladt at have hende.","Thi Johannes sagde til ham: det er dig ikke tilladt at have hende."],[14,5,"Og han havde gjerne slaget ham ihjel, men frygtede for Folket, thi de holdt, ham for en Prophet.","Og han havde gjerne slaget ham ihjel, men frygtede for Folket, thi de holdt, ham for en Prophet."],[14,6,"Men der Herodes holdt sin Fødselsdag, dansede Herodias’ Datter for dem; og hun behagede Herodes.","Men der Herodes holdt sin Fødselsdag, dansede Herodias’ Datter for dem; og hun behagede Herodes."],[14,7,"Derfor lovede han med en Ed at give hende, hvad hun begjerede.","Derfor lovede han med en Ed at give hende, hvad hun begjerede."],[14,8,"Men da hun var tilforn underviist af sin Moder, sagde hun: giv mig hid Johannes den Døbers Hoved paa et Fad.","Men da hun var tilforn underviist af sin Moder, sagde hun: giv mig hid Johannes den Døbers Hoved paa et Fad."],[14,9,"Og Kongen blev bedrøvet; men for de Eders og for Gjesternes Skyld befoel han det at gives hende.","Og Kongen blev bedrøvet; men for de Eders og for Gjesternes Skyld befoel han det at gives hende."],[14,10,"Og han sendte hen og lod Johannes halshugge i Fængslet,","Og han sendte hen og lod Johannes halshugge i Fængslet,"],[14,11,"og hans Hoved blev baaret paa et Fad og givet Pigen; og hun bar det til sin Moder.","og hans Hoved blev baaret paa et Fad og givet Pigen; og hun bar det til sin Moder."],[14,12,"Da kom hans Disciple og toge Legemet og jordede det, og de kom og forkyndte Jesus det.","Da kom hans Disciple og toge Legemet og jordede det, og de kom og forkyndte Jesus det."],[14,13,"Og der Jesus det hørte, veg han bort derfra udi et Skib til et øde Sted afsides; og der Folket det hørte, fulgte de ham tillands fra Stæderne.","Og der Jesus det hørte, veg han bort derfra udi et Skib til et øde Sted afsides; og der Folket det hørte, fulgte de ham tillands fra Stæderne."],[14,14,"Og der Jesus gik frem, saae han meget Folk, og han ynkedes inderligen over dem og helbredte deres Syge.","Og der Jesus gik frem, saae han meget Folk, og han ynkedes inderligen over dem og helbredte deres Syge."],[14,15,"Men der det var blevet Aften, gik hans Disciple til ham og sagde: Stedet er øde, og Tiden er allerede forløben; lad Folket fare, at de kunne gaae hen i Byerne og kjøbe sig Mad.","Men der det var blevet Aften, gik hans Disciple til ham og sagde: Stedet er øde, og Tiden er allerede forløben; lad Folket fare, at de kunne gaae hen i Byerne og kjøbe sig Mad."],[14,16,"Men Jesus sagde til dem: de have ikke behov at gaae bort; giver I dem at æde.","Men Jesus sagde til dem: de have ikke behov at gaae bort; giver I dem at æde."],[14,17,"Men de sagde til ham: vi have her ikke uden fem Brød og to Fiske.","Men de sagde til ham: vi have her ikke uden fem Brød og to Fiske."],[14,18,"Men han sagde: henter mig dem hid.","Men han sagde: henter mig dem hid."],[14,19,"Og han bød Folket sætte sig ned paa Græsset, og tog de fem Brød og de to Fiske, saae op til Himmelen, og velsignede dem; og han brød dem, og gav sine Disciple Brødene, men Disciplene gave Folket dem.","Og han bød Folket sætte sig ned paa Græsset, og tog de fem Brød og de to Fiske, saae op til Himmelen, og velsignede dem; og han brød dem, og gav sine Disciple Brødene, men Disciplene gave Folket dem."],[14,20,"Og de aade alle og bleve mætte; og de opsamlede de overblevne Stykker, tolv Kurve fulde.","Og de aade alle og bleve mætte; og de opsamlede de overblevne Stykker, tolv Kurve fulde."],[14,21,"Men de, som aade, vare ved fem tusinde Mænd, foruden Kvinder og Børn.","Men de, som aade, vare ved fem tusinde Mænd, foruden Kvinder og Børn."],[14,22,"Og strax nødte Jesus sine Disciple til at gaae i Skibet, og i Forveien sætte over til hiin Side, indtil han fik ladet Folket fare.","Og strax nødte Jesus sine Disciple til at gaae i Skibet, og i Forveien sætte over til hiin Side, indtil han fik ladet Folket fare."],[14,23,"Og der han havde ladet Folket fare, gik han paa et Bjerg afsides for at bede. Men der det var blevet Aften, var han alene der.","Og der han havde ladet Folket fare, gik han paa et Bjerg afsides for at bede. Men der det var blevet Aften, var han alene der."],[14,24,"Men Skibet var allerede midt paa Søen, og led Nød af Bølgerne; thi Veiret var dem imod.","Men Skibet var allerede midt paa Søen, og led Nød af Bølgerne; thi Veiret var dem imod."],[14,25,"Men i den fjerde Nattevagt kom Jesus til dem, vandrende paa Søen.","Men i den fjerde Nattevagt kom Jesus til dem, vandrende paa Søen."],[14,26,"Og der Disciplene saae ham vandre paa Søen, bleve de forskrækkede og sagde: det er et Spøgelse; og de skrege af Frygt.","Og der Disciplene saae ham vandre paa Søen, bleve de forskrækkede og sagde: det er et Spøgelse; og de skrege af Frygt."],[14,27,"Men Jesus talede strax til dem og sagde: værer frimodige; det er mig, frygter ikke.","Men Jesus talede strax til dem og sagde: værer frimodige; det er mig, frygter ikke."],[14,28,"Men Peter svarede ham og sagde: Herre! dersom det er dig, da byd mig komme til dig paa Vandet.","Men Peter svarede ham og sagde: Herre! dersom det er dig, da byd mig komme til dig paa Vandet."],[14,29,"Men han sagde: kom! Og Peter traadte ned af Skibet og vandrede paa Vandet, for at komme til Jesus.","Men han sagde: kom! Og Peter traadte ned af Skibet og vandrede paa Vandet, for at komme til Jesus."],[14,30,"Men der han saae det stærke Veir, frygtede han; og da han begyndte at synke, raabte han og sagde: Herre, frels mig!","Men der han saae det stærke Veir, frygtede han; og da han begyndte at synke, raabte han og sagde: Herre, frels mig!"],[14,31,"Og Jesus udrakte strax Haanden, og tog fat paa ham og sagde til ham: du lidet Troende, hvi tvivlede du?","Og Jesus udrakte strax Haanden, og tog fat paa ham og sagde til ham: du lidet Troende, hvi tvivlede du?"],[14,32,"Og der de stege ind i Skibet, stilledes Veiret.","Og der de stege ind i Skibet, stilledes Veiret."],[14,33,"Men de, som vare i Skibet, kom og faldt ned for ham og sagde: du er sandelig Guds Søn.","Men de, som vare i Skibet, kom og faldt ned for ham og sagde: du er sandelig Guds Søn."],[14,34,"Og da de vare farne over, kom de til Genezareths Land.","Og da de vare farne over, kom de til Genezareths Land."],[14,35,"Og der Folket paa samme sted kjendte ham, sendte de ud i det ganske Land, trindt omkring, og førte alle de Syge til ham.","Og der Folket paa samme sted kjendte ham, sendte de ud i det ganske Land, trindt omkring, og førte alle de Syge til ham."],[14,36,"Og de bade ham, at de maatte ikkun røre ved Sømmen paa hans Klædebon; og alle de, som rørte derved, bleve helbredede.","Og de bade ham, at de maatte ikkun røre ved Sømmen paa hans Klædebon; og alle de, som rørte derved, bleve helbredede."],[15,1,"Da kom Skriftkloge og Pharisæer af Jerusalem til Jesus og sagde:","Da kom Skriftkloge og Pharisæer af Jerusalem til Jesus og sagde:"],[15,2,"hvi overtræde dine Disciple de Gamles Vedtægt? thi de toe ikke deres Hænder, idet de æde Brødet.","hvi overtræde dine Disciple de Gamles Vedtægt? thi de toe ikke deres Hænder, idet de æde Brødet."],[15,3,"Men han svarede og sagde til dem: hvi overtræde og I Guds Bud for Eders Vedtægts Skyld?","Men han svarede og sagde til dem: hvi overtræde og I Guds Bud for Eders Vedtægts Skyld?"],[15,4,"Thi Gud haver budet, sigende: ær Fader og Moder; og hvo som bander Fader eller Moder, skal visselig døe.","Thi Gud haver budet, sigende: ær Fader og Moder; og hvo som bander Fader eller Moder, skal visselig døe."],[15,5,"Men I sige: hvo som siger til Fader eller Moder: det, hvormed jeg kunde hjulpet dig, er en Gave, han behøver ikke at ære sin Fader eller sin Moder.","Men I sige: hvo som siger til Fader eller Moder: det, hvormed jeg kunde hjulpet dig, er en Gave, han behøver ikke at ære sin Fader eller sin Moder."],[15,6,"Saaledes have I tilintetgjort Guds Bud for Eders Vedtægts Skyld.","Saaledes have I tilintetgjort Guds Bud for Eders Vedtægts Skyld."],[15,7,"I Øienskalke! Esaias spaaede retteligen om Eder, da han sagde:","I Øienskalke! Esaias spaaede retteligen om Eder, da han sagde:"],[15,8,"dette Folk holder sig nær til mig med sin Mund, og ærer mig med Læberne; men deres Hjerte er langt fra mig.","dette Folk holder sig nær til mig med sin Mund, og ærer mig med Læberne; men deres Hjerte er langt fra mig."],[15,9,"Men de dyrke mig forgjeves, idet de lære saadanne Lærdomme, som ere Menneskers Bud.","Men de dyrke mig forgjeves, idet de lære saadanne Lærdomme, som ere Menneskers Bud."],[15,10,"Og han kaldte Folket til sig og sagde til dem: hører til og forstaaer!","Og han kaldte Folket til sig og sagde til dem: hører til og forstaaer!"],[15,11,"Ikke det, som indkommer i Munden, gjør Mennesket ureent, men det, som udgaaer af Munden, dette gjør Mennesket ureent.","Ikke det, som indkommer i Munden, gjør Mennesket ureent, men det, som udgaaer af Munden, dette gjør Mennesket ureent."],[15,12,"Da gik hans Disciple frem og sagde til ham: veed du, at Pharisæerne have forarget sig, der de hørte denne Tale?","Da gik hans Disciple frem og sagde til ham: veed du, at Pharisæerne have forarget sig, der de hørte denne Tale?"],[15,13,"Men han svarede og sagde: hver Plantning, som min himmelske Fader ikke haver plantet, skal med Rod oprykkes.","Men han svarede og sagde: hver Plantning, som min himmelske Fader ikke haver plantet, skal med Rod oprykkes."],[15,14,"Lader dem fare, Blinde ere Blindes Veiledere; men naar en Blind leder en Blind, da falde de begge i Graven.","Lader dem fare, Blinde ere Blindes Veiledere; men naar en Blind leder en Blind, da falde de begge i Graven."],[15,15,"Men Peter svarede og sagde til ham: forklar os denne Lignelse.","Men Peter svarede og sagde til ham: forklar os denne Lignelse."],[15,16,"Men Jesus sagde: ere og I endnu uforstandige?","Men Jesus sagde: ere og I endnu uforstandige?"],[15,17,"Forstaae I ikke endnu, at alt det, som indkommer i Munden, gaaer I Bugen og udføres ad den naturlige Gang?","Forstaae I ikke endnu, at alt det, som indkommer i Munden, gaaer I Bugen og udføres ad den naturlige Gang?"],[15,18,"Men det, som udgaaer af Munden, kommer ud af Hjertet, og det gjør Mennesket ureent.","Men det, som udgaaer af Munden, kommer ud af Hjertet, og det gjør Mennesket ureent."],[15,19,"Thi af Hjertet udkomme onde Tanker, Mord, Hoer, Skjørlevnet, Tyverier, falske Vidnesbyrd, Bespottelser.","Thi af Hjertet udkomme onde Tanker, Mord, Hoer, Skjørlevnet, Tyverier, falske Vidnesbyrd, Bespottelser."],[15,20,"Disse ere de Ting, som gjøre Mennesket ureent; men at æde med utoede Hænder, gjør ikke Mennesket ureent.","Disse ere de Ting, som gjøre Mennesket ureent; men at æde med utoede Hænder, gjør ikke Mennesket ureent."],[15,21,"Og Jesus gik bort derfra og drog til Thyrus’ og Sidons Egne.","Og Jesus gik bort derfra og drog til Thyrus’ og Sidons Egne."],[15,22,"Og see, en cananæisk Kvinde kom fra de samme Grændser, raabte og sagde til ham: Herre, Davids Søn! forbarm dig over mig! min Datter plages ilde af Djævelen.","Og see, en cananæisk Kvinde kom fra de samme Grændser, raabte og sagde til ham: Herre, Davids Søn! forbarm dig over mig! min Datter plages ilde af Djævelen."],[15,23,"Men han svarede hende ikke et Ord. Da traadte hans Disciple til ham, bade ham og sagde: skil dig af med hende, thi hun raaber efter os.","Men han svarede hende ikke et Ord. Da traadte hans Disciple til ham, bade ham og sagde: skil dig af med hende, thi hun raaber efter os."],[15,24,"Men han svarede og sagde: jeg er ikke udsendt uden til de fortabte Faar af Israels Huus.","Men han svarede og sagde: jeg er ikke udsendt uden til de fortabte Faar af Israels Huus."],[15,25,"Men hun kom og faldt ned for ham og sagde: Herre, hjælp mig!","Men hun kom og faldt ned for ham og sagde: Herre, hjælp mig!"],[15,26,"Men han svarede og sagde: det er ikke smukt at tage Børnenes Brød og kaste det for smaa Hunde.","Men han svarede og sagde: det er ikke smukt at tage Børnenes Brød og kaste det for smaa Hunde."],[15,27,"Men hun sagde: jo, Herre! Hunde æde dog og af de Smuler, som falde af deres Herres Bord.","Men hun sagde: jo, Herre! Hunde æde dog og af de Smuler, som falde af deres Herres Bord."],[15,28,"Da svarede Jesus og sagde til hende: o Kvinde, din Tro er stor, dig skee, som du vil! Og hendes Datter blev karsk fra den samme Time.","Da svarede Jesus og sagde til hende: o Kvinde, din Tro er stor, dig skee, som du vil! Og hendes Datter blev karsk fra den samme Time."],[15,29,"Og Jesus gik frem derfra og kom til den galilæiske Sø, og han gik op paa et Bjerg og satte sig der.","Og Jesus gik frem derfra og kom til den galilæiske Sø, og han gik op paa et Bjerg og satte sig der."],[15,30,"Og meget Folk kom til ham og havde med sig Halte, Blinde, Stumme, Krøblinger og mange andre; og de lagde dem for Jesu Fødder, og han helbredte dem,","Og meget Folk kom til ham og havde med sig Halte, Blinde, Stumme, Krøblinger og mange andre; og de lagde dem for Jesu Fødder, og han helbredte dem,"],[15,31,"saa at Folket forundrede sig, der de saae, at de Stumme talede, Krøblinger vare helbredede, Halte gik, og Blinde saae; og de prisede Israels Gud.","saa at Folket forundrede sig, der de saae, at de Stumme talede, Krøblinger vare helbredede, Halte gik, og Blinde saae; og de prisede Israels Gud."],[15,32,"Men Jesus kaldte sine Disciple til sig og sagde: mig ynkes inderligen over Folket, thi de have nu tøvet hos mig tre Dage, og have Intet at æde; og lade dem fastende fare vil jeg ikke, paa det de ikke skulle forsmægte paa Veien.","Men Jesus kaldte sine Disciple til sig og sagde: mig ynkes inderligen over Folket, thi de have nu tøvet hos mig tre Dage, og have Intet at æde; og lade dem fastende fare vil jeg ikke, paa det de ikke skulle forsmægte paa Veien."],[15,33,"Og hans Disciple sagde til ham: hveden skulle vi faae saa mange Brød i Ørken, at vi kunne mætte saa meget Folk?","Og hans Disciple sagde til ham: hveden skulle vi faae saa mange Brød i Ørken, at vi kunne mætte saa meget Folk?"],[15,34,"Og Jesus sagde til dem: hvor mange Brød have I? Men de sagde: syv, og faa smaa Fiske.","Og Jesus sagde til dem: hvor mange Brød have I? Men de sagde: syv, og faa smaa Fiske."],[15,35,"Og han bød Folket sætte sig ned paa Jorden.","Og han bød Folket sætte sig ned paa Jorden."],[15,36,"Og han tog de syv Brød og Fiskene, takkede, brød dem og gav sine Disciple dem, men Disciplene Folket.","Og han tog de syv Brød og Fiskene, takkede, brød dem og gav sine Disciple dem, men Disciplene Folket."],[15,37,"Og de aade alle og bleve mættede; og de samlede de overblevne Stykker, syv Kurve fulde.","Og de aade alle og bleve mættede; og de samlede de overblevne Stykker, syv Kurve fulde."],[15,38,"Men de, som aade, vare fire tusinde Mænd, foruden Kvinder og Børn.","Men de, som aade, vare fire tusinde Mænd, foruden Kvinder og Børn."],[15,39,"Og der han havde ladet Folket fare, gik han i et Skib og kom til Magdalas Grændser.","Og der han havde ladet Folket fare, gik han i et Skib og kom til Magdalas Grændser."],[16,1,"Og Pharisæerne og Sadducæerne gik frem, fristede ham og begjerede, at han vilde vise dem et Tegn af Himmelen.","Og Pharisæerne og Sadducæerne gik frem, fristede ham og begjerede, at han vilde vise dem et Tegn af Himmelen."],[16,2,"Men han svarede og sagde til dem: om Aftenen sige I: det bliver en skjøn Dag, thi Himmelen er rød;","Men han svarede og sagde til dem: om Aftenen sige I: det bliver en skjøn Dag, thi Himmelen er rød;"],[16,3,"og om Morgenen: det bliver Storm i Dag, thi Himmelen er rød og mørk. I Øienskalke! om Himmelens Skikkelse vide I at dømme, men om Tidernes Tegn kunne I ikke.","og om Morgenen: det bliver Storm i Dag, thi Himmelen er rød og mørk. I Øienskalke! om Himmelens Skikkelse vide I at dømme, men om Tidernes Tegn kunne I ikke."],[16,4,"Den onde og vanartige Slægt begjerer Tegn, og den skal intet Tegn gives uden Jonas Prophetens Tegn. Og han forlod dem og gik bort.","Den onde og vanartige Slægt begjerer Tegn, og den skal intet Tegn gives uden Jonas Prophetens Tegn. Og han forlod dem og gik bort."],[16,5,"Og der hans Disciple fore over til hiin Side, havde de glemt at tage Brød med.","Og der hans Disciple fore over til hiin Side, havde de glemt at tage Brød med."],[16,6,"Og Jesus sagde til dem: seer til og tager Eder vare for Pharisæernes og Sadducæernes Suurdeig.","Og Jesus sagde til dem: seer til og tager Eder vare for Pharisæernes og Sadducæernes Suurdeig."],[16,7,"Da tænkte de ved sig selv og sagde: det er, fordi vi ikke toge Brød med.","Da tænkte de ved sig selv og sagde: det er, fordi vi ikke toge Brød med."],[16,8,"Men som Jesus det vidste, sagde han til dem: I lidet Troende! hvi tænkte I ved Eder selv derpaa, at I ikke toge Brød med?","Men som Jesus det vidste, sagde han til dem: I lidet Troende! hvi tænkte I ved Eder selv derpaa, at I ikke toge Brød med?"],[16,9,"Forstaae I ikke endnu? komme I ikke heller ihu de fem Brød iblandt de fem Tusinde, og hvor mange Kurve I da toge op?","Forstaae I ikke endnu? komme I ikke heller ihu de fem Brød iblandt de fem Tusinde, og hvor mange Kurve I da toge op?"],[16,10,"Ikke heller de syv Brød iblandt de fire Tusinde, hvor mange Kurve I da toge op?","Ikke heller de syv Brød iblandt de fire Tusinde, hvor mange Kurve I da toge op?"],[16,11,"Hvorledes forstaae I da ikke, det ei var om Brød jeg sagde til Eder, at I skulde tage Eder vare for Pharisæernes og Sadducæernes Suurdeig?","Hvorledes forstaae I da ikke, det ei var om Brød jeg sagde til Eder, at I skulde tage Eder vare for Pharisæernes og Sadducæernes Suurdeig?"],[16,12,"Da forstode de, at han havde ikke sagt, at de skulde tage sig vare for Brødets Suurdeig, men for Pharisæernes og Sadducæernes Lærdom.","Da forstode de, at han havde ikke sagt, at de skulde tage sig vare for Brødets Suurdeig, men for Pharisæernes og Sadducæernes Lærdom."],[16,13,"Men der Jesus var kommen i Egnen af Cæsarea Philippi, spurgte han sine Disciple ad og sagde: hvad sige Menneskene mig, Menneskens Søn, at være?","Men der Jesus var kommen i Egnen af Cæsarea Philippi, spurgte han sine Disciple ad og sagde: hvad sige Menneskene mig, Menneskens Søn, at være?"],[16,14,"Men de sagde: Nogle sige, at du er Johannes den Døber; men Andre, Elias; men Andre, Jeremias eller een af Propheterne.","Men de sagde: Nogle sige, at du er Johannes den Døber; men Andre, Elias; men Andre, Jeremias eller een af Propheterne."],[16,15,"Han siger til dem: men I, hvem sige I mig at være?","Han siger til dem: men I, hvem sige I mig at være?"],[16,16,"Da svarede Simon Petrus og sagde: du er Christus, den levende Guds Søn?","Da svarede Simon Petrus og sagde: du er Christus, den levende Guds Søn?"],[16,17,"Og Jesus svarede og sagde til ham: salig er du, Simon Jonas’ Søn! thi Kjød og Blod haver ikke aabenbaret dig det, men min Fader, som er i Himlene.","Og Jesus svarede og sagde til ham: salig er du, Simon Jonas’ Søn! thi Kjød og Blod haver ikke aabenbaret dig det, men min Fader, som er i Himlene."],[16,18,"Men jeg siger dig ogsaa, at du er Petrus, og paa denne Klippe vil jeg bygge min Menighed, og Helvedes Porte skulde ikke faae Overhaand over den.","Men jeg siger dig ogsaa, at du er Petrus, og paa denne Klippe vil jeg bygge min Menighed, og Helvedes Porte skulde ikke faae Overhaand over den."],[16,19,"Og jeg vil give dig Himmerigets Riges Nøgler, og hvad du binder paa Jorden, det skal være bundet i Himlene, og hvad du løser paa Jorden, det skal være løst i Himlene.","Og jeg vil give dig Himmerigets Riges Nøgler, og hvad du binder paa Jorden, det skal være bundet i Himlene, og hvad du løser paa Jorden, det skal være løst i Himlene."],[16,20,"Da bød han sine Disciple, at de skulde ingen Sige, at han var Christus.","Da bød han sine Disciple, at de skulde ingen Sige, at han var Christus."],[16,21,"Fra den Tid begyndte Jesus at give sine Disciple tilkjende, at ham burde at gaae til Jerusalem, og lide meget af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae tredie Dag.","Fra den Tid begyndte Jesus at give sine Disciple tilkjende, at ham burde at gaae til Jerusalem, og lide meget af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae tredie Dag."],[16,22,"Og Peter tog ham tilside, begyndte at straffe ham, og sagde: Herre, spar dig selv; dette skee dig ingenlunde!","Og Peter tog ham tilside, begyndte at straffe ham, og sagde: Herre, spar dig selv; dette skee dig ingenlunde!"],[16,23,"Men han vendte sig og sagde til Peter: vig bag mig, Satan! du er mig en Forargelse; thi du sandser ikke, hvad Guds er, men hvad Menneskens er.","Men han vendte sig og sagde til Peter: vig bag mig, Satan! du er mig en Forargelse; thi du sandser ikke, hvad Guds er, men hvad Menneskens er."],[16,24,"Da sagde Jesus til sine Disciple: vil Nogen komme efter mig, han fornegte sig selv, og tage sit Kors, og følge mig.","Da sagde Jesus til sine Disciple: vil Nogen komme efter mig, han fornegte sig selv, og tage sit Kors, og følge mig."],[16,25,"Thi hvo som vil frelse sit Liv, skal miste det; og hvo som mister sit Liv for min Skyld, skal finde det.","Thi hvo som vil frelse sit Liv, skal miste det; og hvo som mister sit Liv for min Skyld, skal finde det."],[16,26,"Thi hvad gavner det Mennesket, om han vinder den ganske Verden, men tager Skade paa sin Sjæl? Eller hvad kan et Menneske give til Vederlag for sin Sjæl?","Thi hvad gavner det Mennesket, om han vinder den ganske Verden, men tager Skade paa sin Sjæl? Eller hvad kan et Menneske give til Vederlag for sin Sjæl?"],[16,27,"Thi Menneskens Søn skal komme i sin Faders Herlighed med sine Engle; og da skal han betale hver efter sin Gjerning.","Thi Menneskens Søn skal komme i sin Faders Herlighed med sine Engle; og da skal han betale hver efter sin Gjerning."],[16,28,"Sandelig siger jeg Eder: der ere Nogle, som her staae, som ingenlunde skulle smage Døden, førend de see Menneskens Søn komme i sit Rige.","Sandelig siger jeg Eder: der ere Nogle, som her staae, som ingenlunde skulle smage Døden, førend de see Menneskens Søn komme i sit Rige."],[17,1,"Og sex Dage derefter tog Jesus Peter og Jakob og Johannes, hans Broder, til sig, og førte dem afsides op paa et høit Bjerg.","Og sex Dage derefter tog Jesus Peter og Jakob og Johannes, hans Broder, til sig, og førte dem afsides op paa et høit Bjerg."],[17,2,"Og han blev forvandlet for dem, og hans Ansigt skinnede som Solen, men hans Klæder blev hvide som Lyset.","Og han blev forvandlet for dem, og hans Ansigt skinnede som Solen, men hans Klæder blev hvide som Lyset."],[17,3,"Og see, Moses og Elias viste sig for dem og talede med ham.","Og see, Moses og Elias viste sig for dem og talede med ham."],[17,4,"Da svarede Peter og sagde til Jesus: Herre! her er godt at være; vil du, da ville vi gjøre tre Boliger her, dig een, og Moses een, og Elias een.","Da svarede Peter og sagde til Jesus: Herre! her er godt at være; vil du, da ville vi gjøre tre Boliger her, dig een, og Moses een, og Elias een."],[17,5,"Der han endnu talede, see, da overskyggede dem en klar Sky; og see, en Røst kom fra Skyen, som sagde: denne er min Søn, den Elskelige, i hvilken jeg haver Behagelighed; hører ham!","Der han endnu talede, see, da overskyggede dem en klar Sky; og see, en Røst kom fra Skyen, som sagde: denne er min Søn, den Elskelige, i hvilken jeg haver Behagelighed; hører ham!"],[17,6,"Og der Disciplene hørte det, faldt de paa deres Ansigt og frygtede saare.","Og der Disciplene hørte det, faldt de paa deres Ansigt og frygtede saare."],[17,7,"Og Jesus traadte frem, rørte ved dem og sagde: staar op, og frygter ikke.","Og Jesus traadte frem, rørte ved dem og sagde: staar op, og frygter ikke."],[17,8,"Men der de opløftede deres Øine, saae de Ingen, uden Jesus alene.","Men der de opløftede deres Øine, saae de Ingen, uden Jesus alene."],[17,9,"Og der de gik ned ad Bjerget, bød Jesus dem og sagde: I skulle Ingen sige dette Syn, førend Menneskens Søn er opstanden fra de Døde.","Og der de gik ned ad Bjerget, bød Jesus dem og sagde: I skulle Ingen sige dette Syn, førend Menneskens Søn er opstanden fra de Døde."],[17,10,"Og hans Disciple spurgte ham og sagde: hvad er det da, de Skriftkloge sige; at Elias bør først komme?","Og hans Disciple spurgte ham og sagde: hvad er det da, de Skriftkloge sige; at Elias bør først komme?"],[17,11,"Men Jesus svarede og sagde til dem: Elias kommer vel først, og skal skikke alting tilrette.","Men Jesus svarede og sagde til dem: Elias kommer vel først, og skal skikke alting tilrette."],[17,12,"Men jeg siger Eder, at Elias er alt kommen, og de erkjendte ham ikke, men gjorde mod ham, hvad de vilde; saa skal ogsaa Menneskens Søn lide af dem.","Men jeg siger Eder, at Elias er alt kommen, og de erkjendte ham ikke, men gjorde mod ham, hvad de vilde; saa skal ogsaa Menneskens Søn lide af dem."],[17,13,"Da forstode Disciplene, at han havde talet til dem om Johannes den Døber.","Da forstode Disciplene, at han havde talet til dem om Johannes den Døber."],[17,14,"Og der de kom til Folket, gik et Menneske til ham, og faldt paa Knæ for ham og sagde:","Og der de kom til Folket, gik et Menneske til ham, og faldt paa Knæ for ham og sagde:"],[17,15,"Herre! forbarm dig over min Søn! thi han er maanesyg, og lider meget Ondt; thi han falder ofte i Ild og ofte i Vand;","Herre! forbarm dig over min Søn! thi han er maanesyg, og lider meget Ondt; thi han falder ofte i Ild og ofte i Vand;"],[17,16,"og jeg ledte ham til dine Disciple, og de kunde ikke helbrede ham.","og jeg ledte ham til dine Disciple, og de kunde ikke helbrede ham."],[17,17,"Men Jesus svarede og sagde: o du vantro og forvendte Slægt! hvor længe skal jeg taale Eder? Leder mig ham hid.","Men Jesus svarede og sagde: o du vantro og forvendte Slægt! hvor længe skal jeg taale Eder? Leder mig ham hid."],[17,18,"Og Jesus tiltalede ham haardeligen, og Djævelen foer ud af ham, og Drengen blev karsk fra den samme Stund.","Og Jesus tiltalede ham haardeligen, og Djævelen foer ud af ham, og Drengen blev karsk fra den samme Stund."],[17,19,"Da gik Disciplene til Jesus afsides og sagde: hvi kunde vi ikke uddrive ham?","Da gik Disciplene til Jesus afsides og sagde: hvi kunde vi ikke uddrive ham?"],[17,20,"Men Jesus sagde til dem: for Eders Vantroes Skyld; thi sandelig siger jeg Eder: dersom I have Tro som et Senepskorn, da kunne I sige til dette Bjerg: flyt dig herfra derhen, saa skal det flytte sig; og Eder skal intet være umuligt.","Men Jesus sagde til dem: for Eders Vantroes Skyld; thi sandelig siger jeg Eder: dersom I have Tro som et Senepskorn, da kunne I sige til dette Bjerg: flyt dig herfra derhen, saa skal det flytte sig; og Eder skal intet være umuligt."],[17,21,"Men dette Slags farer ikke ud uden ved Bøn og Faste.","Men dette Slags farer ikke ud uden ved Bøn og Faste."],[17,22,"Der de vandrede i Galilæa, sagde Jesus til dem: Menneskens Søn skal overantvordes i Menneskers Hænder;","Der de vandrede i Galilæa, sagde Jesus til dem: Menneskens Søn skal overantvordes i Menneskers Hænder;"],[17,23,"og de skulle slaae ham ihjel, og han skal opreises paa den tredie Dag. Og de bleve saare bedrøvede.","og de skulle slaae ham ihjel, og han skal opreises paa den tredie Dag. Og de bleve saare bedrøvede."],[17,24,"Men der de kom til Capernaum, gik de, som oppebare Skattens Penninge, til Peter og sagde: betaler Eders Mester ikke Skattens Penninge?","Men der de kom til Capernaum, gik de, som oppebare Skattens Penninge, til Peter og sagde: betaler Eders Mester ikke Skattens Penninge?"],[17,25,"Han sagde: jo. Og der han kom ind i Huset, forekom Jesus ham og sagde: hvad tykkes dig, Simon? af hvem tage Konger paa Jorden Told eller Skat? af deres egne Børn eller af Fremmede?","Han sagde: jo. Og der han kom ind i Huset, forekom Jesus ham og sagde: hvad tykkes dig, Simon? af hvem tage Konger paa Jorden Told eller Skat? af deres egne Børn eller af Fremmede?"],[17,26,"Peter siger til ham: af Fremmede. Jesus sagde til ham: saa ere jo Børnene frie.","Peter siger til ham: af Fremmede. Jesus sagde til ham: saa ere jo Børnene frie."],[17,27,"Men paa det vi ikke skulle forarge dem, gak hen til Havet, kast en Krog, og tag den første Fisk, som kommer op; og naar du aabner dens Mund, skal du finde en Stater; tag denne og giv dem den for dig og for mig.","Men paa det vi ikke skulle forarge dem, gak hen til Havet, kast en Krog, og tag den første Fisk, som kommer op; og naar du aabner dens Mund, skal du finde en Stater; tag denne og giv dem den for dig og for mig."],[18,1,"I den samme Stund gik Disciplene til Jesus og sagde: hvo er den Største i Himmeriges Rige?","I den samme Stund gik Disciplene til Jesus og sagde: hvo er den Største i Himmeriges Rige?"],[18,2,"Og Jesus kaldte et Barn til sig og stillede det midt iblandt dem,","Og Jesus kaldte et Barn til sig og stillede det midt iblandt dem,"],[18,3,"og sagde: sandelig siger jeg Eder: uden I omvende Eder, og blive som Børn, komme I ingenlunde ind i Himmeriges Rige.","og sagde: sandelig siger jeg Eder: uden I omvende Eder, og blive som Børn, komme I ingenlunde ind i Himmeriges Rige."],[18,4,"Derfor, hvo sig selv fornedrer som dette Barn, han er den Største i Himmeriges Rige.","Derfor, hvo sig selv fornedrer som dette Barn, han er den Største i Himmeriges Rige."],[18,5,"Og hvo som annammer et saadant Barn i mit Navn, annammer mig.","Og hvo som annammer et saadant Barn i mit Navn, annammer mig."],[18,6,"Men hvo som forarger een af disse Smaa, som troe paa mig, ham var det bedre, at der var hængt en Møllesteen om hans Hals, og han var sænket i Havets Dybhed.","Men hvo som forarger een af disse Smaa, som troe paa mig, ham var det bedre, at der var hængt en Møllesteen om hans Hals, og han var sænket i Havets Dybhed."],[18,7,"Vee Verden for Forargelser! Vel er det fornødent, at Forargelser skulle komme; dog vee det Menneske, ved hvilket Forargelse kommer!","Vee Verden for Forargelser! Vel er det fornødent, at Forargelser skulle komme; dog vee det Menneske, ved hvilket Forargelse kommer!"],[18,8,"Men dersom din Haand eller din Fod forarger dig, da hug den af og kast den fra dig. Det er dig bedre, at gaae halt eller en Krøbling ind til Livet, end at have to Hænder og to Fødder, og kastes i den evige Ild.","Men dersom din Haand eller din Fod forarger dig, da hug den af og kast den fra dig. Det er dig bedre, at gaae halt eller en Krøbling ind til Livet, end at have to Hænder og to Fødder, og kastes i den evige Ild."],[18,9,"Og dersom dit Øie forarger dig, da riv det ud og kast det fra dig. Det er dig bedre, at gaae eenøiet ind til Livet, end at have to Øine, og kastes i Helvedes Ild.","Og dersom dit Øie forarger dig, da riv det ud og kast det fra dig. Det er dig bedre, at gaae eenøiet ind til Livet, end at have to Øine, og kastes i Helvedes Ild."],[18,10,"Seer til, at I ikke foragte een af disse Smaa; thi jeg siger Eder: deres Engle i Himlene see altid min Faders Ansigt, som er i Himlene.","Seer til, at I ikke foragte een af disse Smaa; thi jeg siger Eder: deres Engle i Himlene see altid min Faders Ansigt, som er i Himlene."],[18,11,"Thi Menneskens Søn er kommen at frelse det, som var fortabt.","Thi Menneskens Søn er kommen at frelse det, som var fortabt."],[18,12,"Hvad tykkes Eder? Om et Menneske havde hundrede Faar, og eet af dem foer vild, forlader han ikke de ni og halvfemsindstyve, og gaaer paa Bjergene, og leder efter det, som var faret vild?","Hvad tykkes Eder? Om et Menneske havde hundrede Faar, og eet af dem foer vild, forlader han ikke de ni og halvfemsindstyve, og gaaer paa Bjergene, og leder efter det, som var faret vild?"],[18,13,"Og hænder det sig, at han finder det, sandelig siger jeg Eder, at han glæder sig mere over det, end over de ni og halvfemsindstyve, som ikke fore vild.","Og hænder det sig, at han finder det, sandelig siger jeg Eder, at han glæder sig mere over det, end over de ni og halvfemsindstyve, som ikke fore vild."],[18,14,"Saaledes er det ikke Eders himmelske Faders Villie, at een af disse Smaa skal fortabes.","Saaledes er det ikke Eders himmelske Faders Villie, at een af disse Smaa skal fortabes."],[18,15,"Men om din Broder synder imod dig, gak hen, og straf ham imellem dig og ham alene; hører han dig, da haver du vundet din Broder.","Men om din Broder synder imod dig, gak hen, og straf ham imellem dig og ham alene; hører han dig, da haver du vundet din Broder."],[18,16,"Men hører han dig ikke, da tag endnu Een eller To med dig, paa det at Sagen maa blive fast efter to eller tre Vidners Mund.","Men hører han dig ikke, da tag endnu Een eller To med dig, paa det at Sagen maa blive fast efter to eller tre Vidners Mund."],[18,17,"Men hører han dem ikke, da siig Menigheden det; men hører han ikke Menigheden, da skal han være for dig ligesom en Hedning og Tolder.","Men hører han dem ikke, da siig Menigheden det; men hører han ikke Menigheden, da skal han være for dig ligesom en Hedning og Tolder."],[18,18,"Sandelig siger jeg Eder: hvadsomhelst I binde paa Jorden, skal være bundet i Himmelen; og hvadsomhelst I løse paa Jorden, skal være løst i Himmelen.","Sandelig siger jeg Eder: hvadsomhelst I binde paa Jorden, skal være bundet i Himmelen; og hvadsomhelst I løse paa Jorden, skal være løst i Himmelen."],[18,19,"Atter siger jeg Eder, at dersom To af Eder blive enige paa Jorden, om hvad for en Sag det er, at de ville bede, det skal vederfares dem af min Fader, som er i Himlene.","Atter siger jeg Eder, at dersom To af Eder blive enige paa Jorden, om hvad for en Sag det er, at de ville bede, det skal vederfares dem af min Fader, som er i Himlene."],[18,20,"Thi hvor To eller Tre ere forsamlede i mit Navn, der er jeg midt iblandt dem.","Thi hvor To eller Tre ere forsamlede i mit Navn, der er jeg midt iblandt dem."],[18,21,"Da gik Peter frem til ham og sagde: Herre! hvor ofte skal jeg forlade min Broder, som synder imod mig? indtil syv Gange?","Da gik Peter frem til ham og sagde: Herre! hvor ofte skal jeg forlade min Broder, som synder imod mig? indtil syv Gange?"],[18,22,"Jesus sagde til ham: jeg siger dig, ikke indtil syv Gange, men indtil halvfjerdsindstyve Gange syv Gange.","Jesus sagde til ham: jeg siger dig, ikke indtil syv Gange, men indtil halvfjerdsindstyve Gange syv Gange."],[18,23,"Derfor er Himmeriges Rige lignet ved en Konge, som vilde holde Regnskab med sine Tjenere.","Derfor er Himmeriges Rige lignet ved en Konge, som vilde holde Regnskab med sine Tjenere."],[18,24,"Men der han begyndte at holde Regnskab, blev Een ført frem for ham, som var ti Tusinde Talenter skyldig.","Men der han begyndte at holde Regnskab, blev Een ført frem for ham, som var ti Tusinde Talenter skyldig."],[18,25,"Men der han Intet havde at betale med, bød hans Herre ham at sælges og hans Hustru og Børn og alt det, han havde, og Gjelden at betales.","Men der han Intet havde at betale med, bød hans Herre ham at sælges og hans Hustru og Børn og alt det, han havde, og Gjelden at betales."],[18,26,"Da faldt Tjeneren ned for hans Fødder og sagde: Herre! vær langmodig med mig, og jeg vil betale det altsammen.","Da faldt Tjeneren ned for hans Fødder og sagde: Herre! vær langmodig med mig, og jeg vil betale det altsammen."],[18,27,"Da ynkedes samme Tjeners Herre inderligen over ham, og gav ham løs og forlod ham Gjelden.","Da ynkedes samme Tjeners Herre inderligen over ham, og gav ham løs og forlod ham Gjelden."],[18,28,"Men den samme Tjener gik ud og fandt en af sine Medtjenere, som var ham hundrede Penninge skyldig; og han greb fat paa ham og vilde kvæle ham, og sagde: betal mig det, du er skyldig.","Men den samme Tjener gik ud og fandt en af sine Medtjenere, som var ham hundrede Penninge skyldig; og han greb fat paa ham og vilde kvæle ham, og sagde: betal mig det, du er skyldig."],[18,29,"Da faldt hans Medtjener ned for hans Fødder, og bad ham og sagde: vær langmodig med mig, og jeg vil betale dig det altsammen.","Da faldt hans Medtjener ned for hans Fødder, og bad ham og sagde: vær langmodig med mig, og jeg vil betale dig det altsammen."],[18,30,"Men han vilde ikke, men gik hen og kastede ham i Fængsel, indtil han betalte det, han var skyldig.","Men han vilde ikke, men gik hen og kastede ham i Fængsel, indtil han betalte det, han var skyldig."],[18,31,"Men der hans Medtjenere saae det, som skeet var, bleve de saare bedrøvede, og kom og aabenbarede for deres Herre alt det, som skeet var.","Men der hans Medtjenere saae det, som skeet var, bleve de saare bedrøvede, og kom og aabenbarede for deres Herre alt det, som skeet var."],[18,32,"Da kaldte hans Herre ham for sig og sagde til ham: du onde Tjener! al den Gjeld forlod jeg dig, fordi du bad mig.","Da kaldte hans Herre ham for sig og sagde til ham: du onde Tjener! al den Gjeld forlod jeg dig, fordi du bad mig."],[18,33,"Burde dig ikke og at forbarme dig over din Medtjener, ligesom jeg og haver forbarmet mig over dig?","Burde dig ikke og at forbarme dig over din Medtjener, ligesom jeg og haver forbarmet mig over dig?"],[18,34,"Og hans Herre blev vred, og overantvordede ham til Bødlerne, indtil han betalte alt det, han var ham skyldig.","Og hans Herre blev vred, og overantvordede ham til Bødlerne, indtil han betalte alt det, han var ham skyldig."],[18,35,"Saa skal og min himmelske Fader gjøre mod Eder, om I ikke forlade af Eders Hjerter, hver sin Broder hans Brøst.","Saa skal og min himmelske Fader gjøre mod Eder, om I ikke forlade af Eders Hjerter, hver sin Broder hans Brøst."],[19,1,"Og det skete, der Jesus havde endt disse Ord, drog han bort af Galilæa, og kom til Judæas Grændser paa hiin Side Jordan.","Og det skete, der Jesus havde endt disse Ord, drog han bort af Galilæa, og kom til Judæas Grændser paa hiin Side Jordan."],[19,2,"Og meget Folk fulgte ham, og han helbredte dem der.","Og meget Folk fulgte ham, og han helbredte dem der."],[19,3,"Og Pharisæerne traadte til ham, fristede ham og sagde til ham: er det en Mand tilladt at skille sig fra sin Hustru for hvilkensomhelst Sag?","Og Pharisæerne traadte til ham, fristede ham og sagde til ham: er det en Mand tilladt at skille sig fra sin Hustru for hvilkensomhelst Sag?"],[19,4,"Men han svarede og sagde til dem: have I ikke læst, at den, som gjorde dem af Begyndelsen, gjorde dem Mand og Kvinde,","Men han svarede og sagde til dem: have I ikke læst, at den, som gjorde dem af Begyndelsen, gjorde dem Mand og Kvinde,"],[19,5,"og sagde: derfor skal et Menneske forlade Fader og Moder, og blive fast hos sin Hustru, og de To skulle være til eet Kjød.","og sagde: derfor skal et Menneske forlade Fader og Moder, og blive fast hos sin Hustru, og de To skulle være til eet Kjød."],[19,6,"Saa at de ere ikke længere to, men eet Kjød. Derfor, hvad Gud har tilsammenføiet, skal Mennesket ikke adskille.","Saa at de ere ikke længere to, men eet Kjød. Derfor, hvad Gud har tilsammenføiet, skal Mennesket ikke adskille."],[19,7,"De sagde til ham: hvorfor bød da Moses at give et Skilsmissebrev, og skille sig fra hende?","De sagde til ham: hvorfor bød da Moses at give et Skilsmissebrev, og skille sig fra hende?"],[19,8,"Og han sagde til dem: Moses tilstedte Eder, at skille Eder fra Eders Hustruer, for Eders Hjerters Haardheds Skyld; men af Begyndelsen haver det ikke saaledes været.","Og han sagde til dem: Moses tilstedte Eder, at skille Eder fra Eders Hustruer, for Eders Hjerters Haardheds Skyld; men af Begyndelsen haver det ikke saaledes været."],[19,9,"Men jeg siger Eder, at hvo som skiller sig fra sin Hustru uden for Hoers Skyld, og tager en anden tilægte, han bedriver Hoer; og hvo som tager en Fraskilt tilægte, han bedriver Hoer.","Men jeg siger Eder, at hvo som skiller sig fra sin Hustru uden for Hoers Skyld, og tager en anden tilægte, han bedriver Hoer; og hvo som tager en Fraskilt tilægte, han bedriver Hoer."],[19,10,"Hans Disciple sagde til ham: staaer Mandens Sag saaledes med Hustruen, da er det ikke godt at gifte sig.","Hans Disciple sagde til ham: staaer Mandens Sag saaledes med Hustruen, da er det ikke godt at gifte sig."],[19,11,"Men han sagde til dem: dette Ord begribe ikke Alle, men de, som det er givet.","Men han sagde til dem: dette Ord begribe ikke Alle, men de, som det er givet."],[19,12,"Thi der ere Gildinger, som ere fødte saaledes af Moders Liv; og der ere Gildinger, som ere gildede af Mennesker; og der ere Gildinger, som have gildet sig selv for Himmeriges Riges Skyld. Hvo det kan begribe, han begribe det!","Thi der ere Gildinger, som ere fødte saaledes af Moders Liv; og der ere Gildinger, som ere gildede af Mennesker; og der ere Gildinger, som have gildet sig selv for Himmeriges Riges Skyld. Hvo det kan begribe, han begribe det!"],[19,13,"Da bleve smaa Børn førte til ham, at han skulde lægge Hænderne paa dem og bede; men Disciplene truede dem.","Da bleve smaa Børn førte til ham, at han skulde lægge Hænderne paa dem og bede; men Disciplene truede dem."],[19,14,"Da sagde Jesus: lader de smaa Børn med Fred, og formener dem ikke at komme til mig; thi Himmeriges Rige hører saadanne til.","Da sagde Jesus: lader de smaa Børn med Fred, og formener dem ikke at komme til mig; thi Himmeriges Rige hører saadanne til."],[19,15,"Og han lagde Hænderne paa dem, og drog derfra.","Og han lagde Hænderne paa dem, og drog derfra."],[19,16,"Og see, En traadte frem og sagde til ham: gode Mester! hvad Godt skal jeg gjøre, at jeg maa have det evige Liv?","Og see, En traadte frem og sagde til ham: gode Mester! hvad Godt skal jeg gjøre, at jeg maa have det evige Liv?"],[19,17,"Men han sagde til ham: hvi kalder du mig god? Ingen er god, uden Een, som er Gud. Men vil du indgaae til Livet, da hold Budene.","Men han sagde til ham: hvi kalder du mig god? Ingen er god, uden Een, som er Gud. Men vil du indgaae til Livet, da hold Budene."],[19,18,"Han sagde til ham: hvilke? Men Jesus sagde: dette: du skal ikke ihjelslaae; du skal ikke bedrive Hoer; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd;","Han sagde til ham: hvilke? Men Jesus sagde: dette: du skal ikke ihjelslaae; du skal ikke bedrive Hoer; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd;"],[19,19,"ær din Fader og din Moder, og du skal elske din Næste som dig selv.","ær din Fader og din Moder, og du skal elske din Næste som dig selv."],[19,20,"Da siger den unge Karl til ham: det haver jeg holdet altsammen fra min Ungdom; hvad fattes mig endnu?","Da siger den unge Karl til ham: det haver jeg holdet altsammen fra min Ungdom; hvad fattes mig endnu?"],[19,21,"Jesus sagde til ham: vil du være fuldkommen, da gak hen, sælg, hvad du haver, og giv Fattige det, og du skal have et Liggendefæ i Himmelen; og kom, følg mig.","Jesus sagde til ham: vil du være fuldkommen, da gak hen, sælg, hvad du haver, og giv Fattige det, og du skal have et Liggendefæ i Himmelen; og kom, følg mig."],[19,22,"Men der den unge Karl hørte det Ord, gik han bedrøvet bort; thi han havde meget Gods.","Men der den unge Karl hørte det Ord, gik han bedrøvet bort; thi han havde meget Gods."],[19,23,"Da sagde Jesus til sine Disciple: sandelig siger jeg Eder, at en Rig kommer vanskelig ind i Himmeriges Rige.","Da sagde Jesus til sine Disciple: sandelig siger jeg Eder, at en Rig kommer vanskelig ind i Himmeriges Rige."],[19,24,"Atter siger jeg Eder: det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige.","Atter siger jeg Eder: det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige."],[19,25,"Men der hans Disciple hørte det, bleve de saare forfærdede og sagde: hvo kan da blive salig?","Men der hans Disciple hørte det, bleve de saare forfærdede og sagde: hvo kan da blive salig?"],[19,26,"Da saae Jesus paa dem og sagde: for Mennesker er dette umuligt, men for Gud ere alle Ting mulige.","Da saae Jesus paa dem og sagde: for Mennesker er dette umuligt, men for Gud ere alle Ting mulige."],[19,27,"Da svarede Peter og sagde til ham: see, vi have forladt alle Ting og fulgt dig; hvad skulle da vi have?","Da svarede Peter og sagde til ham: see, vi have forladt alle Ting og fulgt dig; hvad skulle da vi have?"],[19,28,"Men Jesus sagde til dem: sandelig siger jeg Eder, at I, som have efterfulgt mig, udi Igjenfødelsen, naar Menneskens Søn skal sidde paa sin Herligheds Throne, skulle I og sidde paa tolv Throner og dømme de tolv Israels Stammer.","Men Jesus sagde til dem: sandelig siger jeg Eder, at I, som have efterfulgt mig, udi Igjenfødelsen, naar Menneskens Søn skal sidde paa sin Herligheds Throne, skulle I og sidde paa tolv Throner og dømme de tolv Israels Stammer."],[19,29,"Og hver, som haver forladt Huus eller Brødre eller Søstre eller Fader eller Moder eller Hustru eller Børn eller Agre for mit Navns Skyld, skal faae hundredefold igjen, og arve det evige Liv.","Og hver, som haver forladt Huus eller Brødre eller Søstre eller Fader eller Moder eller Hustru eller Børn eller Agre for mit Navns Skyld, skal faae hundredefold igjen, og arve det evige Liv."],[19,30,"Men Mange, som ere de Første, skulle blive de Sidste, og de Sidste de Første.","Men Mange, som ere de Første, skulle blive de Sidste, og de Sidste de Første."],[20,1,"Thi Himmeriges Rige lignes ved en Huusbonde, som udgik tidlig om Morgenen, at leie Arbeidere til sin Viingaard.","Thi Himmeriges Rige lignes ved en Huusbonde, som udgik tidlig om Morgenen, at leie Arbeidere til sin Viingaard."],[20,2,"Men der han blev eens med Arbeiderne om en Penning om Dagen, sendte han dem i sin Viingaard.","Men der han blev eens med Arbeiderne om en Penning om Dagen, sendte han dem i sin Viingaard."],[20,3,"Og han gik ud ved den tredie Time, og saae Andre staae ledige paa Torvet,","Og han gik ud ved den tredie Time, og saae Andre staae ledige paa Torvet,"],[20,4,"og han sagde til dem: gaaer I og hen i Viingaarden, og jeg vil give Eder, hvad som ret er. Men de gik hen.","og han sagde til dem: gaaer I og hen i Viingaarden, og jeg vil give Eder, hvad som ret er. Men de gik hen."],[20,5,"Han gik atter ud ved den sjette og niende Time, og gjorde ligesaa.","Han gik atter ud ved den sjette og niende Time, og gjorde ligesaa."],[20,6,"Men ved den ellevte Time gik han ud, og fandt Andre staae ledige, og sagde til dem: hvi staae I her den ganske Dag ledige?","Men ved den ellevte Time gik han ud, og fandt Andre staae ledige, og sagde til dem: hvi staae I her den ganske Dag ledige?"],[20,7,"De sagde til ham: fordi Ingen leiede os. Han sagde til dem: gaaer I ogsaa hen i Viingaarden, og hvad som ret er, skulle I faae.","De sagde til ham: fordi Ingen leiede os. Han sagde til dem: gaaer I ogsaa hen i Viingaarden, og hvad som ret er, skulle I faae."],[20,8,"Men der det blev Aften, siger Viingaardens Herre til sin Foged: kald Arbeiderne, og giv dem Lønnen, og begynd fra de Sidste til de Første.","Men der det blev Aften, siger Viingaardens Herre til sin Foged: kald Arbeiderne, og giv dem Lønnen, og begynd fra de Sidste til de Første."],[20,9,"Og de kom, som vare leiede ved den ellevte Time og fik hver en Penning.","Og de kom, som vare leiede ved den ellevte Time og fik hver en Penning."],[20,10,"Men der de Første kom, meente de, at de skulde faae mere; og de fik og hver en Penning.","Men der de Første kom, meente de, at de skulde faae mere; og de fik og hver en Penning."],[20,11,"Men der de fik den, knurrede de imod Huusbonden og sagde:","Men der de fik den, knurrede de imod Huusbonden og sagde:"],[20,12,"disse Sidste have ikkun arbeidet een Time, og du haver gjort dem lige med os, som have baaret Dagens Byrde og Hede.","disse Sidste have ikkun arbeidet een Time, og du haver gjort dem lige med os, som have baaret Dagens Byrde og Hede."],[20,13,"Men han svarede og sagde til een af dem: Ven! jeg gjør dig ikke Uret; er du ikke bleven eens med mig om en Penning?","Men han svarede og sagde til een af dem: Ven! jeg gjør dig ikke Uret; er du ikke bleven eens med mig om en Penning?"],[20,14,"Tag Dit, og gak hen. Men jeg vil give denne Sidste ligesom dig.","Tag Dit, og gak hen. Men jeg vil give denne Sidste ligesom dig."],[20,15,"Eller haver jeg ikke Magt til at gjøre med Mit, hvad jeg vil? eller er dit Øie ondt, fordi jeg er god?","Eller haver jeg ikke Magt til at gjøre med Mit, hvad jeg vil? eller er dit Øie ondt, fordi jeg er god?"],[20,16,"Saaledes skulle de Sidste blive de Første, og de Første de Sidste; thi Mange ere kaldede, men Faa ere udvalgte.","Saaledes skulle de Sidste blive de Første, og de Første de Sidste; thi Mange ere kaldede, men Faa ere udvalgte."],[20,17,"Og Jesus drog op til Jerusalem, og tog de tolv Disciple tilside paa Veien, og sagde til dem:","Og Jesus drog op til Jerusalem, og tog de tolv Disciple tilside paa Veien, og sagde til dem:"],[20,18,"see, vi reise op til Jerusalem, og Menneskens Søn skal overantvordes de Ypperstepræster og Skriftkloge; og de skulle fordømme ham til Døden,","see, vi reise op til Jerusalem, og Menneskens Søn skal overantvordes de Ypperstepræster og Skriftkloge; og de skulle fordømme ham til Døden,"],[20,19,"og overantvorde Hedningerne ham og bespotte og hudstryge og korsfæste; og paa den tredie Dag skal han opstaae.","og overantvorde Hedningerne ham og bespotte og hudstryge og korsfæste; og paa den tredie Dag skal han opstaae."],[20,20,"Da gik Zebedæus’ Sønners Moder til ham med sine Sønner, faldt ned for ham og bad ham om Noget.","Da gik Zebedæus’ Sønners Moder til ham med sine Sønner, faldt ned for ham og bad ham om Noget."],[20,21,"Men han sagde til hende: hvad vil du? Hun sagde til ham: siig, at disse mine to Sønner skulle sidde i dit Rige, den ene ved din høire, den anden ved din venstre Side.","Men han sagde til hende: hvad vil du? Hun sagde til ham: siig, at disse mine to Sønner skulle sidde i dit Rige, den ene ved din høire, den anden ved din venstre Side."],[20,22,"Men Jesus svarede og sagde: I vide ikke, hvad I bede. Kunne I drikke den Kalk, som jeg skal drikke, og døbes med den Daab, som jeg skal døbes med? De sige til ham: vi kunne.","Men Jesus svarede og sagde: I vide ikke, hvad I bede. Kunne I drikke den Kalk, som jeg skal drikke, og døbes med den Daab, som jeg skal døbes med? De sige til ham: vi kunne."],[20,23,"Og han sagde til dem: min Kalk skulle I vel drikke og med den Daab, som jeg døbes med, skulle I døbes; men at sidde ved min høire og ved min venstre Side, hører ikke mig til at give Nogen, uden dem, som det er beredt af min Fader.","Og han sagde til dem: min Kalk skulle I vel drikke og med den Daab, som jeg døbes med, skulle I døbes; men at sidde ved min høire og ved min venstre Side, hører ikke mig til at give Nogen, uden dem, som det er beredt af min Fader."],[20,24,"Og der de Ti det hørte, bleve de vrede paa de to Brødre.","Og der de Ti det hørte, bleve de vrede paa de to Brødre."],[20,25,"Men Jesus kaldte dem til sig og sagde: I vide, at Folkenes Fyrster herske over dem, og de Store bruge Myndighed over dem.","Men Jesus kaldte dem til sig og sagde: I vide, at Folkenes Fyrster herske over dem, og de Store bruge Myndighed over dem."],[20,26,"Men saa skal det ikke være iblandt Eder; men hvo som vil være stor iblandt Eder, han være Eders Tjener;","Men saa skal det ikke være iblandt Eder; men hvo som vil være stor iblandt Eder, han være Eders Tjener;"],[20,27,"og hvo som vil være den Ypperste iblandt Eder, han være Eder underdanig.","og hvo som vil være den Ypperste iblandt Eder, han være Eder underdanig."],[20,28,"Ligesom Menneskens Søn ikke er kommen at lade sig tjene, men at tjene og at give sit Liv til en Gjenløsning for Mange.","Ligesom Menneskens Søn ikke er kommen at lade sig tjene, men at tjene og at give sit Liv til en Gjenløsning for Mange."],[20,29,"Og der de gik ud fra Jericho, fulgte ham meget Folk.","Og der de gik ud fra Jericho, fulgte ham meget Folk."],[20,30,"Og see, to Blinde sadde ved Veien, og der de hørte, at Jesus gik forbi, raabte de og sagde: Herre, Davids Søn, forbarme dig over os.","Og see, to Blinde sadde ved Veien, og der de hørte, at Jesus gik forbi, raabte de og sagde: Herre, Davids Søn, forbarme dig over os."],[20,31,"Men Folket truede dem, at de skulde tie; men de raabte mere og sagde: Herre, Davids Søn, forbarme dig over os!","Men Folket truede dem, at de skulde tie; men de raabte mere og sagde: Herre, Davids Søn, forbarme dig over os!"],[20,32,"Og Jesus stod stille og kaldte ad dem og sagde: hvad ville I, at jeg skal gjøre Eder?","Og Jesus stod stille og kaldte ad dem og sagde: hvad ville I, at jeg skal gjøre Eder?"],[20,33,"De sagde til ham: Herre! at vore Øine maatte oplades.","De sagde til ham: Herre! at vore Øine maatte oplades."],[20,34,"Men Jesus ynkedes inderligen, og rørte ved deres Øine. Og strax bleve deres Øine seende, og de fulgte ham.","Men Jesus ynkedes inderligen, og rørte ved deres Øine. Og strax bleve deres Øine seende, og de fulgte ham."],[21,1,"Og der de kom nær til Jerusalem, og var komne til Bethphage ved Oliebjerget, da sendte Jesus tvende Disciple og sagde til dem:","Og der de kom nær til Jerusalem, og var komne til Bethphage ved Oliebjerget, da sendte Jesus tvende Disciple og sagde til dem:"],[21,2,"gaaer hen i den By, som ligger for Eder, og strax skulle I finde en Aseninde bunden og et Føl hos hende; løser dem og fører dem til mig.","gaaer hen i den By, som ligger for Eder, og strax skulle I finde en Aseninde bunden og et Føl hos hende; løser dem og fører dem til mig."],[21,3,"Og dersom Nogen taler Eder Noget til, da siger, at Herren haver dem behov, saa skal han strax fremsende dem.","Og dersom Nogen taler Eder Noget til, da siger, at Herren haver dem behov, saa skal han strax fremsende dem."],[21,4,"Men dette skete altsammen, at det skulde fuldkommes, som er talet ved Propheten, som siger:","Men dette skete altsammen, at det skulde fuldkommes, som er talet ved Propheten, som siger:"],[21,5,"forkynder Zions Datter! see, din Konge kommer til dig, sagtmodig og ridende paa et Asen og paa Asenindens Føl.","forkynder Zions Datter! see, din Konge kommer til dig, sagtmodig og ridende paa et Asen og paa Asenindens Føl."],[21,6,"Men Disciplene gik hen og gjorde, som Jesus befoel dem;","Men Disciplene gik hen og gjorde, som Jesus befoel dem;"],[21,7,"og de hentede Aseninden og Føllet, og lagde deres Klæder paa dem; og han satte sig derpaa.","og de hentede Aseninden og Føllet, og lagde deres Klæder paa dem; og han satte sig derpaa."],[21,8,"Men de Fleste af Folket bredte deres Klæder paa Veien, andre huggede Grene af Træerne og strøede dem paa Veien;","Men de Fleste af Folket bredte deres Klæder paa Veien, andre huggede Grene af Træerne og strøede dem paa Veien;"],[21,9,"men Folket, som gik foran og fulgte, raabte og sagde: Hosanna den Davids Søn! velsignet være den, som kommer i Herrens Navn! Hosanna i det Høieste!","men Folket, som gik foran og fulgte, raabte og sagde: Hosanna den Davids Søn! velsignet være den, som kommer i Herrens Navn! Hosanna i det Høieste!"],[21,10,"Og der han drog ind i Jerusalem, oprørtes den ganske Stad og sagde: hvo er denne?","Og der han drog ind i Jerusalem, oprørtes den ganske Stad og sagde: hvo er denne?"],[21,11,"Men Folket sagde: det er Jesus, Propheten fra Nazareth i Galilæa.","Men Folket sagde: det er Jesus, Propheten fra Nazareth i Galilæa."],[21,12,"Og Jesus gik ind i Guds Tempel og uddrev alle dem, som solgte og kjøbte i Templet, og omstødte Vexelerernes Borde og Duekræmmernes Stole.","Og Jesus gik ind i Guds Tempel og uddrev alle dem, som solgte og kjøbte i Templet, og omstødte Vexelerernes Borde og Duekræmmernes Stole."],[21,13,"Og han sagde til dem: der er skrevet: mit Huus skal kaldes et Bedehuus, men I have gjort det til en Røverkule.","Og han sagde til dem: der er skrevet: mit Huus skal kaldes et Bedehuus, men I have gjort det til en Røverkule."],[21,14,"Og der gik Blinde og Halte til ham i Templet, og han helbredte dem.","Og der gik Blinde og Halte til ham i Templet, og han helbredte dem."],[21,15,"Men der de Ypperstepræster og Skriftkloge saae de Undergjerninger, som han gjorde, og at Børnene raabte i Templet og sagde: Hosanna den Davids Søn! bleve de vrede, og sagde til ham:","Men der de Ypperstepræster og Skriftkloge saae de Undergjerninger, som han gjorde, og at Børnene raabte i Templet og sagde: Hosanna den Davids Søn! bleve de vrede, og sagde til ham:"],[21,16,"hører du, hvad disse sige? Men Jesus sagde til dem: jo! have I aldrig læst: af de Umyndiges og Diendes Mund skal du berede Lov?","hører du, hvad disse sige? Men Jesus sagde til dem: jo! have I aldrig læst: af de Umyndiges og Diendes Mund skal du berede Lov?"],[21,17,"Og han forlod dem og gik udenfor Staden til Bethanien, og blev der.","Og han forlod dem og gik udenfor Staden til Bethanien, og blev der."],[21,18,"Men der han om Morgenen igjen gik til Staden, hungrede ham.","Men der han om Morgenen igjen gik til Staden, hungrede ham."],[21,19,"Og han saae et Figentræ ved Veien og gik til det, og fandt Intet derpaa, uden Blade alene. Og Han sagde til det: aldrig mere voxe Frugt paa dig! Og Figentræet visnede strax.","Og han saae et Figentræ ved Veien og gik til det, og fandt Intet derpaa, uden Blade alene. Og Han sagde til det: aldrig mere voxe Frugt paa dig! Og Figentræet visnede strax."],[21,20,"Og der Disciplene saae det, forundrede de sig og sagde: hvorledes visnede Figentræet saa strax?","Og der Disciplene saae det, forundrede de sig og sagde: hvorledes visnede Figentræet saa strax?"],[21,21,"Men Jesus svarede og sagde til dem: sandelig siger jeg Eder: dersom I have Tro og ikke tvivle, da skulle I ikke alene kunne gjøre det med Figentræet, men dersom I endog sige til dette Bjerg: løft dig og kast dig i Havet, da skal det skee.","Men Jesus svarede og sagde til dem: sandelig siger jeg Eder: dersom I have Tro og ikke tvivle, da skulle I ikke alene kunne gjøre det med Figentræet, men dersom I endog sige til dette Bjerg: løft dig og kast dig i Havet, da skal det skee."],[21,22,"Og alt det, I begjere i Bønnen troende, det skulle I faae.","Og alt det, I begjere i Bønnen troende, det skulle I faae."],[21,23,"Og der han kom i Templet, traadte til ham, idet han lærte, de Ypperstepræster og Folkets Ældste, og sagde: af hvad Magt gjør du dette? og hvo haver givet dig denne Magt?","Og der han kom i Templet, traadte til ham, idet han lærte, de Ypperstepræster og Folkets Ældste, og sagde: af hvad Magt gjør du dette? og hvo haver givet dig denne Magt?"],[21,24,"Men Jesus svarede og sagde til dem: jeg vil og spørge Eder om een Sag; dersom I sige mig det, vil jeg og sige Eder, af hvad Magt jeg gjør dette.","Men Jesus svarede og sagde til dem: jeg vil og spørge Eder om een Sag; dersom I sige mig det, vil jeg og sige Eder, af hvad Magt jeg gjør dette."],[21,25,"Johannes’ Daab, hveden var den? af Himmelen, eller af Menneskene? Men de betænkte ved sig selv og sagde: sige vi, den var af Himmelen, da vil han spørge os: hvi troede I ham da ikke?","Johannes’ Daab, hveden var den? af Himmelen, eller af Menneskene? Men de betænkte ved sig selv og sagde: sige vi, den var af Himmelen, da vil han spørge os: hvi troede I ham da ikke?"],[21,26,"Men sige vi: den var af Menneskene, frygte vi os for Folket; thi de holdt alle Johannes for en Prophet.","Men sige vi: den var af Menneskene, frygte vi os for Folket; thi de holdt alle Johannes for en Prophet."],[21,27,"Og de svarede Jesus og sagde: vi vide det ikke. Da sagde han og til dem: saa siger jeg ikke heller, af hvad Magt jeg gjør dette.","Og de svarede Jesus og sagde: vi vide det ikke. Da sagde han og til dem: saa siger jeg ikke heller, af hvad Magt jeg gjør dette."],[21,28,"Men hvad tykkes Eder? Et Menneske havde to Sønner; og han gik til den første og sagde: Søn! gak hen, arbeid i Dag udi min Viingaard.","Men hvad tykkes Eder? Et Menneske havde to Sønner; og han gik til den første og sagde: Søn! gak hen, arbeid i Dag udi min Viingaard."],[21,29,"Men han svarede og sagde: jeg vil ikke; men derefter angrede det ham, og han gik hen.","Men han svarede og sagde: jeg vil ikke; men derefter angrede det ham, og han gik hen."],[21,30,"Og han gik til den anden og sagde ligesaa. Men han svarede og sagde: Herre, jeg vil; og gik ikke hen.","Og han gik til den anden og sagde ligesaa. Men han svarede og sagde: Herre, jeg vil; og gik ikke hen."],[21,31,"Hvilken af de To gjorde Faderens Villie? De sagde til ham: den Første. Jesus sagde til dem: sandelig siger jeg Eder, at Toldere og Skjøger gaae for Eder i Guds Rige.","Hvilken af de To gjorde Faderens Villie? De sagde til ham: den Første. Jesus sagde til dem: sandelig siger jeg Eder, at Toldere og Skjøger gaae for Eder i Guds Rige."],[21,32,"Thi Johannes kom til Eder paa Retfærdigheds Vei, og I troede ham ikke, men Toldere og Skjøger troede ham; men enddog I det saae, angrede det Eder alligevel ikke derefter, saa I troede ham.","Thi Johannes kom til Eder paa Retfærdigheds Vei, og I troede ham ikke, men Toldere og Skjøger troede ham; men enddog I det saae, angrede det Eder alligevel ikke derefter, saa I troede ham."],[21,33,"Hører en anden Lignelse: der var en Huusbonde, som plantede en Viingaard og satte et Gjerde omkring den og gravede en Perse i den og byggede et Taarn; og han leiede den til Viingaardsmænd, og drog udenlands.","Hører en anden Lignelse: der var en Huusbonde, som plantede en Viingaard og satte et Gjerde omkring den og gravede en Perse i den og byggede et Taarn; og han leiede den til Viingaardsmænd, og drog udenlands."],[21,34,"Men der Frugtens Tid kom, sendte han sine Tjenere til Viingaardsmændene, at annamme dens Frugter.","Men der Frugtens Tid kom, sendte han sine Tjenere til Viingaardsmændene, at annamme dens Frugter."],[21,35,"Og Viingaardsmændene toge hans Tjenere; en sloge de, en anden dræbte de, en anden stenede de.","Og Viingaardsmændene toge hans Tjenere; en sloge de, en anden dræbte de, en anden stenede de."],[21,36,"Han sendte atter andre Tjenere, flere end de første; og de gjorde ligesaa med dem.","Han sendte atter andre Tjenere, flere end de første; og de gjorde ligesaa med dem."],[21,37,"Men derefter sendte han sin Søn til dem og sagde: de ville dog undsee sig for min Søn.","Men derefter sendte han sin Søn til dem og sagde: de ville dog undsee sig for min Søn."],[21,38,"Men der Viingaardsmændene saae Sønnen, sagde de til hverandre: denne er Arvingen; kommer, lader os slaae ham ihjel og tilvende os hans Arv.","Men der Viingaardsmændene saae Sønnen, sagde de til hverandre: denne er Arvingen; kommer, lader os slaae ham ihjel og tilvende os hans Arv."],[21,39,"Og de toge ham og stødte ham udenfor Viingaarden og sloge ham ihjel.","Og de toge ham og stødte ham udenfor Viingaarden og sloge ham ihjel."],[21,40,"Naar da Viingaardens Herre kommer, hvad skal han gjøre med disse Viingaardsmænd?","Naar da Viingaardens Herre kommer, hvad skal han gjøre med disse Viingaardsmænd?"],[21,41,"De sagde til ham: han skal ilde omkomme de Onde, og leie sin Viingaard til andre Viingaardsmænd, som skulle give ham Frugterne i deres Tid.","De sagde til ham: han skal ilde omkomme de Onde, og leie sin Viingaard til andre Viingaardsmænd, som skulle give ham Frugterne i deres Tid."],[21,42,"Jesus sagde til dem: have I aldrig læst i Skrifterne: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen; det er skeet af Herren, og er underligt for vore Øine.","Jesus sagde til dem: have I aldrig læst i Skrifterne: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen; det er skeet af Herren, og er underligt for vore Øine."],[21,43,"Derfor siger jeg Eder, at Guds Rige skal tages fra Eder og gives et Folk, som skal bære dets Frugter.","Derfor siger jeg Eder, at Guds Rige skal tages fra Eder og gives et Folk, som skal bære dets Frugter."],[21,44,"Og hvo som falder paa denne Steen, skal sønderstødes; men hvilken den falder paa, ham skal den knuse.","Og hvo som falder paa denne Steen, skal sønderstødes; men hvilken den falder paa, ham skal den knuse."],[21,45,"Og der de Ypperstepræster og Pharisæerne hørte hans Lignelser, mærkede de, at han talede om dem.","Og der de Ypperstepræster og Pharisæerne hørte hans Lignelser, mærkede de, at han talede om dem."],[21,46,"Og de søgte at gribe ham, men frygtede for Folket; thi de holdt ham for en Prophet.","Og de søgte at gribe ham, men frygtede for Folket; thi de holdt ham for en Prophet."],[22,1,"Og Jesus svarede og talede atter ved Lignelser til dem og sagde:","Og Jesus svarede og talede atter ved Lignelser til dem og sagde:"],[22,2,"Himmeriges Rige lignes ved en Konge, som gjorde sin Søns Bryllup.","Himmeriges Rige lignes ved en Konge, som gjorde sin Søns Bryllup."],[22,3,"Og han udsendte sine Tjenere, at kalde de Budne til Bryllup; men de vilde ikke komme.","Og han udsendte sine Tjenere, at kalde de Budne til Bryllup; men de vilde ikke komme."],[22,4,"Han udsendte atter andre Tjenere og sagde: siger de Budne; see, jeg haver beredt mit Maaltid, mine Øxen og det fede Kvæg er slagtet, og Alting er rede; kommer til Bryllup.","Han udsendte atter andre Tjenere og sagde: siger de Budne; see, jeg haver beredt mit Maaltid, mine Øxen og det fede Kvæg er slagtet, og Alting er rede; kommer til Bryllup."],[22,5,"Men de foragtede det og gik hen, den Ene paa sin Ager, den Anden til sit Kjøbmandskab;","Men de foragtede det og gik hen, den Ene paa sin Ager, den Anden til sit Kjøbmandskab;"],[22,6,"Andre grebe hans Tjenere, forhaanede og ihjelsloge dem.","Andre grebe hans Tjenere, forhaanede og ihjelsloge dem."],[22,7,"Men der Kongen det hørte, blev han vred og skikkede sine Hære ud, og ødelagde disse Manddrabere og satte Ild paa deres Stad.","Men der Kongen det hørte, blev han vred og skikkede sine Hære ud, og ødelagde disse Manddrabere og satte Ild paa deres Stad."],[22,8,"Da sagde han til sine Tjenere: Brylluppet er vel beredt, men de Budne vare det ikke værd;","Da sagde han til sine Tjenere: Brylluppet er vel beredt, men de Budne vare det ikke værd;"],[22,9,"gaaer derfor ud paa Veiskjellene, og byder til Bryllup saa mange, som I finde.","gaaer derfor ud paa Veiskjellene, og byder til Bryllup saa mange, som I finde."],[22,10,"Og de Tjenere gik ud paa Veien og samlede alle dem, de fandt baade Onde og Gode; og Bryllupshuset blev fuldt af Gjester.","Og de Tjenere gik ud paa Veien og samlede alle dem, de fandt baade Onde og Gode; og Bryllupshuset blev fuldt af Gjester."],[22,11,"Da gik Kongen ind at besee Gjesterne, og han saae der et Menneske, som ikke var iført Bryllups-Klædningen.","Da gik Kongen ind at besee Gjesterne, og han saae der et Menneske, som ikke var iført Bryllups-Klædningen."],[22,12,"Og han sagde til ham: Ven! hvorledes er du kommen hid ind, og haver ikke Bryllups-Klædningen paa? Men han taug.","Og han sagde til ham: Ven! hvorledes er du kommen hid ind, og haver ikke Bryllups-Klædningen paa? Men han taug."],[22,13,"Da sagde Kongen til Tjenerne: binder Hænder og Fødder paa ham, og tager ham og kaster ham ud i det yderste Mørke; der skal være Graad og Tænders Gnidsel.","Da sagde Kongen til Tjenerne: binder Hænder og Fødder paa ham, og tager ham og kaster ham ud i det yderste Mørke; der skal være Graad og Tænders Gnidsel."],[22,14,"Thi mange ere kaldede, men Faa udvalgte.","Thi mange ere kaldede, men Faa udvalgte."],[22,15,"Da gik Pharisæerne hen og holdt Raad, hvorledes de kunde besnære ham i Ord.","Da gik Pharisæerne hen og holdt Raad, hvorledes de kunde besnære ham i Ord."],[22,16,"Og de sendte deres Disciple til ham med de Herodianer og sagde: Mester! vi vide, at du er sanddru, og lærer Guds Vei i Sandhed, og skjøtter om Ingen; thi du anser ikke Menneskers Person.","Og de sendte deres Disciple til ham med de Herodianer og sagde: Mester! vi vide, at du er sanddru, og lærer Guds Vei i Sandhed, og skjøtter om Ingen; thi du anser ikke Menneskers Person."],[22,17,"Siig os derfor: hvad tykkes dig? er det tilladt at give Keiseren Skat eller ei?","Siig os derfor: hvad tykkes dig? er det tilladt at give Keiseren Skat eller ei?"],[22,18,"Men som Jesus havde mærket deres Ondskab, sagde ham: I Øienskalke, hvi friste I mig?","Men som Jesus havde mærket deres Ondskab, sagde ham: I Øienskalke, hvi friste I mig?"],[22,19,"Viser mig Skattens Mynt. Men de bragte ham en Penning.","Viser mig Skattens Mynt. Men de bragte ham en Penning."],[22,20,"Og han sagde til dem: hvis Billede og Overskrift er dette?","Og han sagde til dem: hvis Billede og Overskrift er dette?"],[22,21,"De sagde til ham: Keiserens. Da sagde han til dem: saa giver Keiseren det, som Keiserens er, og Gud det, som Guds er.","De sagde til ham: Keiserens. Da sagde han til dem: saa giver Keiseren det, som Keiserens er, og Gud det, som Guds er."],[22,22,"Og der de hørte det, forundrede de sig, og forlode ham og gik bort.","Og der de hørte det, forundrede de sig, og forlode ham og gik bort."],[22,23,"Paa den samme Dag traadte Sadducæerne til ham, som sige, at der ikke er Opstandelse, og spurgte ham og sagde:","Paa den samme Dag traadte Sadducæerne til ham, som sige, at der ikke er Opstandelse, og spurgte ham og sagde:"],[22,24,"Mester! Moses haver sagt: naar Nogen døer, og haver ikke Børn, skal hans Broder for Svogerskabs Skyld tage hans Hustru tilægte og opreise sin Broder Sæd.","Mester! Moses haver sagt: naar Nogen døer, og haver ikke Børn, skal hans Broder for Svogerskabs Skyld tage hans Hustru tilægte og opreise sin Broder Sæd."],[22,25,"Men nu have været hos os syv Brødre; og den første giftede sig og døde, og efterdi han ikke havde Sæd, efterlod han sin Broder sin Hustru.","Men nu have været hos os syv Brødre; og den første giftede sig og døde, og efterdi han ikke havde Sæd, efterlod han sin Broder sin Hustru."],[22,26,"Og den anden ligesaa, og den tredie, indtil den syvende;","Og den anden ligesaa, og den tredie, indtil den syvende;"],[22,27,"men sidst af dem alle døde og Kvinden.","men sidst af dem alle døde og Kvinden."],[22,28,"Hvis Hustru af disse syv skal hun da være i Opstandelsen? thi de have alle havt hende.","Hvis Hustru af disse syv skal hun da være i Opstandelsen? thi de have alle havt hende."],[22,29,"Men Jesus svarede: I fare vild, idet I ikke kjende Skrifterne, ei heller Guds Kraft.","Men Jesus svarede: I fare vild, idet I ikke kjende Skrifterne, ei heller Guds Kraft."],[22,30,"Thi i Opstandelsen skulle de hverken tage tilægte, ei heller bortgiftes; men de ere ligesom Guds Engle i Himmelen.","Thi i Opstandelsen skulle de hverken tage tilægte, ei heller bortgiftes; men de ere ligesom Guds Engle i Himmelen."],[22,31,"Men have I ikke læst om de Dødes Opstandelse, hvad som er talet til Eder af Gud, naar han siger:","Men have I ikke læst om de Dødes Opstandelse, hvad som er talet til Eder af Gud, naar han siger:"],[22,32,"Jeg er Abrahams Gud og Isaaks Gud og Jakobs Gud. Men Gud er ikke de Dødes Gud, men de Levendes.","Jeg er Abrahams Gud og Isaaks Gud og Jakobs Gud. Men Gud er ikke de Dødes Gud, men de Levendes."],[22,33,"Og der Folket det hørte, forundrede de sig saare over hans Lærdom.","Og der Folket det hørte, forundrede de sig saare over hans Lærdom."],[22,34,"Men der Pharisæerne hørte, at han havde stoppet Munden paa Sadducæerne, forsamlede de sig.","Men der Pharisæerne hørte, at han havde stoppet Munden paa Sadducæerne, forsamlede de sig."],[22,35,"Og En af dem, en Lovkyndig spurgte og fristede ham og sagde:","Og En af dem, en Lovkyndig spurgte og fristede ham og sagde:"],[22,36,"Mester, hvilket er det store Bud i Loven?","Mester, hvilket er det store Bud i Loven?"],[22,37,"Men Jesus sagde til ham: du skal elske Herren din Gud i dit ganske Hjerte, og i din ganske Sjæl, og i dit ganske Sind.","Men Jesus sagde til ham: du skal elske Herren din Gud i dit ganske Hjerte, og i din ganske Sjæl, og i dit ganske Sind."],[22,38,"Dette er det første og store Bud.","Dette er det første og store Bud."],[22,39,"Men det andet er ligesom dette: du skal elske din Næste som dig selv.","Men det andet er ligesom dette: du skal elske din Næste som dig selv."],[22,40,"Af disse to Bud hænger al Loven og Propheterne.","Af disse to Bud hænger al Loven og Propheterne."],[22,41,"Men der Pharisæerne vare forsamlede, spurgte Jesus dem og sagde:","Men der Pharisæerne vare forsamlede, spurgte Jesus dem og sagde:"],[22,42,"Hvad tykkes Eder om Christus? hvis Søn er han? De sagde til ham: Davids.","Hvad tykkes Eder om Christus? hvis Søn er han? De sagde til ham: Davids."],[22,43,"Han sagde til dem: hvorledes kalder da David ham i Aanden en Herre, da han siger:","Han sagde til dem: hvorledes kalder da David ham i Aanden en Herre, da han siger:"],[22,44,"Herren sagde til min Herre: sæt dig ved min høire Haand, indtil jeg lægger dine Fjender til dine Fødders Skammel?","Herren sagde til min Herre: sæt dig ved min høire Haand, indtil jeg lægger dine Fjender til dine Fødders Skammel?"],[22,45,"Efterdi David nu kalder ham en Herre, hvorledes er han da hans Søn?","Efterdi David nu kalder ham en Herre, hvorledes er han da hans Søn?"],[22,46,"Og Ingen kunde svare ham et Ord, og Ingen turde ydermere gjøre Spørgsmaal til ham efter den Dag.","Og Ingen kunde svare ham et Ord, og Ingen turde ydermere gjøre Spørgsmaal til ham efter den Dag."],[23,1,"Da talede Jesus til Folket og til sine Disciple og sagde:","Da talede Jesus til Folket og til sine Disciple og sagde:"],[23,2,"Paa Moses’ Stol sidde Skriftkloge og Pharisæer.","Paa Moses’ Stol sidde Skriftkloge og Pharisæer."],[23,3,"Alt det derfor, som de sige Eder, at I skulle holde, det holder og gjører; men gjører ikke efter deres Gjerninger; thi de sige det vel, men gjøre det ikke.","Alt det derfor, som de sige Eder, at I skulle holde, det holder og gjører; men gjører ikke efter deres Gjerninger; thi de sige det vel, men gjøre det ikke."],[23,4,"Thi de binde svare Byrder, vanskelige at bære, og lægge Menneskene dem paa Skuldrene; men selv ville de ikke røre dem med en Finger.","Thi de binde svare Byrder, vanskelige at bære, og lægge Menneskene dem paa Skuldrene; men selv ville de ikke røre dem med en Finger."],[23,5,"Men de gjøre alle deres Gjerninger for at ansees af Menneskene; thi de gjøre deres Tankeremme brede, og Sømmene paa deres Klæder store.","Men de gjøre alle deres Gjerninger for at ansees af Menneskene; thi de gjøre deres Tankeremme brede, og Sømmene paa deres Klæder store."],[23,6,"Og de ville gjerne sidde øverst tilbords ved Nadverne og paa de fornemste Sæder i Synagogerne.","Og de ville gjerne sidde øverst tilbords ved Nadverne og paa de fornemste Sæder i Synagogerne."],[23,7,"Og de ville gjerne være hilsede paa Torvene, og kaldes Rabbi, Rabbi af Menneskene.","Og de ville gjerne være hilsede paa Torvene, og kaldes Rabbi, Rabbi af Menneskene."],[23,8,"Men I skulle ikke ville kaldes Rabbi; thi Een er Eders Veileder, Christus, men I ere alle Brødre.","Men I skulle ikke ville kaldes Rabbi; thi Een er Eders Veileder, Christus, men I ere alle Brødre."],[23,9,"Og I skulle ingen kalde Eders Fader paa Jorden; thi Een er Eders Fader, som er i Himlene.","Og I skulle ingen kalde Eders Fader paa Jorden; thi Een er Eders Fader, som er i Himlene."],[23,10,"Og I skulle ikke lade Eder kalde Veiledere; thi Een er Eders Veileder, Christus.","Og I skulle ikke lade Eder kalde Veiledere; thi Een er Eders Veileder, Christus."],[23,11,"Men den Største iblandt Eder skal være Eders Tjener.","Men den Største iblandt Eder skal være Eders Tjener."],[23,12,"Men hvo sig selv ophøier, skal fornedres, og hvo sig selv fornedrer, skal ophøies.","Men hvo sig selv ophøier, skal fornedres, og hvo sig selv fornedrer, skal ophøies."],[23,13,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I tillukke Himmeriges Rige for Menneskene; thi I gaae ikke derind, og dem, som ville gaae ind, tillade I det ikke.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I tillukke Himmeriges Rige for Menneskene; thi I gaae ikke derind, og dem, som ville gaae ind, tillade I det ikke."],[23,14,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I opæde Enkers Huse, og paa Skrømt bede længe; derfor skulle I faae des haardere Dom.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I opæde Enkers Huse, og paa Skrømt bede længe; derfor skulle I faae des haardere Dom."],[23,15,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I drage om til Vands og Lands for at vinde en Tilhænger; og naar han er bleven det, gjøre I et Helvedes Barn af ham, dobbelt mere end I ere.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I drage om til Vands og Lands for at vinde en Tilhænger; og naar han er bleven det, gjøre I et Helvedes Barn af ham, dobbelt mere end I ere."],[23,16,"Vee Eder, I Blinde Veiledere! I, som sige: hvo som sværger ved Templet, det er Intet; men hvo som sværger ved Guldet i Templet, er skyldig.","Vee Eder, I Blinde Veiledere! I, som sige: hvo som sværger ved Templet, det er Intet; men hvo som sværger ved Guldet i Templet, er skyldig."],[23,17,"I Daarer og Blinde! hvilket er størst? Guldet, eller Templet, som helliger Guldet?","I Daarer og Blinde! hvilket er størst? Guldet, eller Templet, som helliger Guldet?"],[23,18,"Fremdeles: hvo som sværger ved Alteret, det er Intet; men hvo som sværger ved Gaven, som er derpaa, er skyldig.","Fremdeles: hvo som sværger ved Alteret, det er Intet; men hvo som sværger ved Gaven, som er derpaa, er skyldig."],[23,19,"I Daarer og Blinde! hvilket er størst? Gaven, eller Alteret, som helliger Gaven?","I Daarer og Blinde! hvilket er størst? Gaven, eller Alteret, som helliger Gaven?"],[23,20,"Derfor, hvo som sværger ved Alteret, sværger ved det og ved Alt, som er derpaa.","Derfor, hvo som sværger ved Alteret, sværger ved det og ved Alt, som er derpaa."],[23,21,"Og hvo som sværger ved Templet, sværger ved det og ved den, som boer deri.","Og hvo som sværger ved Templet, sværger ved det og ved den, som boer deri."],[23,22,"Og hvo som sværger ved Himmelen, sværger ved Guds Throne og ved den, som sidder derpaa.","Og hvo som sværger ved Himmelen, sværger ved Guds Throne og ved den, som sidder derpaa."],[23,23,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I tiende af Mynte og Dild og Kommen, og efterlade de Ting, som svarere ere i Loven, Dom og Barmhjertighed og Tro. Disse Ting burde man gjøre, og ikke forsømme de andre.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I tiende af Mynte og Dild og Kommen, og efterlade de Ting, som svarere ere i Loven, Dom og Barmhjertighed og Tro. Disse Ting burde man gjøre, og ikke forsømme de andre."],[23,24,"I Blinde Veiledere, I, som sie Myggen af, men nedsluge Kamelen!","I Blinde Veiledere, I, som sie Myggen af, men nedsluge Kamelen!"],[23,25,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I rense Bægere og Fade udvortes, men indentil ere de fulde af Rov og Uretfærdighed.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I rense Bægere og Fade udvortes, men indentil ere de fulde af Rov og Uretfærdighed."],[23,26,"Du blinde Pharisæer! rens først det, som er inden i Bægeret og Fadet, at ogsaa det Udvortes paa dem maa blive reent.","Du blinde Pharisæer! rens først det, som er inden i Bægeret og Fadet, at ogsaa det Udvortes paa dem maa blive reent."],[23,27,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! thi I ere ligesom kalkede Grave, hvilke synes deilige udvortes, men indentil ere fulde af døde Been og al Ureenhed.","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! thi I ere ligesom kalkede Grave, hvilke synes deilige udvortes, men indentil ere fulde af døde Been og al Ureenhed."],[23,28,"Ligesaa synes og I vel udvortes retfærdige for Menneskene, men indvortes ere I fulde af Øienskalkhed og Uret.","Ligesaa synes og I vel udvortes retfærdige for Menneskene, men indvortes ere I fulde af Øienskalkhed og Uret."],[23,29,"Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I bygge Propheternes Grave og pryde de Retfærdiges Gravsteder, og sige:","Vee Eder, I Skriftkloge og Pharisæer, I Øienskalke! at I bygge Propheternes Grave og pryde de Retfærdiges Gravsteder, og sige:"],[23,30,"havde vi været i vore Fædres Tid, da havde vi ikke været deelagtige med dem i Propheternes Blod.","havde vi været i vore Fædres Tid, da havde vi ikke været deelagtige med dem i Propheternes Blod."],[23,31,"Saa bære I da Vidnesbyrd om Eder selv, at I ere deres Børn, som have ihjelslaget Propheterne.","Saa bære I da Vidnesbyrd om Eder selv, at I ere deres Børn, som have ihjelslaget Propheterne."],[23,32,"Saa fylder og I Eders Fædres Maal!","Saa fylder og I Eders Fædres Maal!"],[23,33,"I Slanger! I Øgleunger! hvorledes kunne I undflye Helvedes Dom?","I Slanger! I Øgleunger! hvorledes kunne I undflye Helvedes Dom?"],[23,34,"Derfor, see, jeg sender til Eder Propheter og Vise og Skriftkloge; og nogle af dem skulle I ihjelslaae og korsfæste, og nogle af dem skulle I hudstryge i Eders Synagoger, og forfølge dem fra en Stad til en anden,","Derfor, see, jeg sender til Eder Propheter og Vise og Skriftkloge; og nogle af dem skulle I ihjelslaae og korsfæste, og nogle af dem skulle I hudstryge i Eders Synagoger, og forfølge dem fra en Stad til en anden,"],[23,35,"at alt det retfærdige Blod skal komme over Eder, som er udgydt paa Jorden, fra den retfærdige Abels Blod indtil Sacharias’, Barachias’ Søns, Blod, hvilken I sloge ihjel mellem Templet og Alteret.","at alt det retfærdige Blod skal komme over Eder, som er udgydt paa Jorden, fra den retfærdige Abels Blod indtil Sacharias’, Barachias’ Søns, Blod, hvilken I sloge ihjel mellem Templet og Alteret."],[23,36,"Sandelig siger jeg Eder, alt dette skal komme over denne Slægt.","Sandelig siger jeg Eder, alt dette skal komme over denne Slægt."],[23,37,"Jerusalem! Jerusalem! som ihjelslaaer Propheterne og stener dem, som ere sendte til dig: hvor ofte vilde jeg forsamlet dine Børn, ligerviis som en Høne forsamler sine Kyllinger under Vingerne! Og I vilde ikke.","Jerusalem! Jerusalem! som ihjelslaaer Propheterne og stener dem, som ere sendte til dig: hvor ofte vilde jeg forsamlet dine Børn, ligerviis som en Høne forsamler sine Kyllinger under Vingerne! Og I vilde ikke."],[23,38,"See, Eders Huus skal lades Eder øde.","See, Eders Huus skal lades Eder øde."],[23,39,"Thi jeg siger Eder: I skulle fra nu af ikke see mig, indtil I sige: velsignet være den, som kommer i Herrens Navn!","Thi jeg siger Eder: I skulle fra nu af ikke see mig, indtil I sige: velsignet være den, som kommer i Herrens Navn!"],[24,1,"Og Jesus gik ud, bort fra Templet, og hans Disciple gik til ham, for at vise ham Templets Bygninger.","Og Jesus gik ud, bort fra Templet, og hans Disciple gik til ham, for at vise ham Templets Bygninger."],[24,2,"Men Jesus sagde til dem: see I ikke alt dette? Sandelig siger jeg Eder: her skal ikke lades Steen paa Steen, som jo skal nedbrydes.","Men Jesus sagde til dem: see I ikke alt dette? Sandelig siger jeg Eder: her skal ikke lades Steen paa Steen, som jo skal nedbrydes."],[24,3,"Men da han sad paa Oliebjerget, gik hans Disciple til ham afsides og sagde: siig os, naar skal dette skee? og hvad Tegn skal der være paa din Tilkommelse og Verdens Ende?","Men da han sad paa Oliebjerget, gik hans Disciple til ham afsides og sagde: siig os, naar skal dette skee? og hvad Tegn skal der være paa din Tilkommelse og Verdens Ende?"],[24,4,"Og Jesus svarede og sagde til dem: seer til, at Ingen forfører Eder.","Og Jesus svarede og sagde til dem: seer til, at Ingen forfører Eder."],[24,5,"Thi Mange skulle komme i mit Navn og sige; jeg er Christus; og de skulle forføre Mange.","Thi Mange skulle komme i mit Navn og sige; jeg er Christus; og de skulle forføre Mange."],[24,6,"Men I skulle høre Krige og Rygte om Krige, Seer til, at I ikke forskrækkes; thi dette maa altsammen skee; men Enden er ikke endda.","Men I skulle høre Krige og Rygte om Krige, Seer til, at I ikke forskrækkes; thi dette maa altsammen skee; men Enden er ikke endda."],[24,7,"Thi Folk skal reise sig imod Folk, og Rige imod Rige; og der skal være Hunger og Pestilentse og Jordskjælv her og der.","Thi Folk skal reise sig imod Folk, og Rige imod Rige; og der skal være Hunger og Pestilentse og Jordskjælv her og der."],[24,8,"Men alt dette er kun Veernes Begyndelse.","Men alt dette er kun Veernes Begyndelse."],[24,9,"Da skulle de overantvorde Eder til Trængsel og slaae Eder ihjel, og I skulle hades af alle Folkene for mit Navns Skyld.","Da skulle de overantvorde Eder til Trængsel og slaae Eder ihjel, og I skulle hades af alle Folkene for mit Navns Skyld."],[24,10,"Og da skulle Mange forarges og forraade hverandre og hade hverandre.","Og da skulle Mange forarges og forraade hverandre og hade hverandre."],[24,11,"Og mange falske Propheter skulle opstaae og forføre Mange.","Og mange falske Propheter skulle opstaae og forføre Mange."],[24,12,"Og efterdi Uretfærdighed vil være bleven mangfoldig, skal Kjærligheden blive kold i Mange.","Og efterdi Uretfærdighed vil være bleven mangfoldig, skal Kjærligheden blive kold i Mange."],[24,13,"Men hvo som bliver bestandig indtil Enden, han skal blive salig.","Men hvo som bliver bestandig indtil Enden, han skal blive salig."],[24,14,"Og dette Riges Evangelium skal prædikes i den ganske Verden, til et Vidnesbyrd for alle Folk; og da skal Enden komme.","Og dette Riges Evangelium skal prædikes i den ganske Verden, til et Vidnesbyrd for alle Folk; og da skal Enden komme."],[24,15,"Naar I da see Ødelæggelsens Vederstyggelighed, om hvilken Propheten Daniel haver talet, og staae paa det hellige Sted, (hvo som det læser, give Agt derpaa!)","Naar I da see Ødelæggelsens Vederstyggelighed, om hvilken Propheten Daniel haver talet, og staae paa det hellige Sted, (hvo som det læser, give Agt derpaa!)"],[24,16,"da flye paa Bjergene, hvo, som er i Judæa;","da flye paa Bjergene, hvo, som er i Judæa;"],[24,17,"og hvo som er paa Taget, stige ikke ned, at hente Noget af sit Huus;","og hvo som er paa Taget, stige ikke ned, at hente Noget af sit Huus;"],[24,18,"og hvo som er paa Ageren, vende ikke tilbage, at hente sine Klæder.","og hvo som er paa Ageren, vende ikke tilbage, at hente sine Klæder."],[24,19,"Men vee de Frugtsommelige og dem, som give Die, i de Dage!","Men vee de Frugtsommelige og dem, som give Die, i de Dage!"],[24,20,"Men beder, at Eders Flugt skal ikke skee om Vinteren, ei heller paa Sabbaten;","Men beder, at Eders Flugt skal ikke skee om Vinteren, ei heller paa Sabbaten;"],[24,21,"thi da skal være saa stor en Trængsel, som ikke haver været fra Verdens Begyndelse hidindtil, som ikke heller skal blive.","thi da skal være saa stor en Trængsel, som ikke haver været fra Verdens Begyndelse hidindtil, som ikke heller skal blive."],[24,22,"Og dersom disse Dage ikke bleve forkortede, da blev intet Menneske frelst; men for de Udvalgtes Skyld skulle disse Dage forkortes.","Og dersom disse Dage ikke bleve forkortede, da blev intet Menneske frelst; men for de Udvalgtes Skyld skulle disse Dage forkortes."],[24,23,"Dersom Nogen da siger til Eder: see, her er Christus, eller der! da skulle I ikke troe det.","Dersom Nogen da siger til Eder: see, her er Christus, eller der! da skulle I ikke troe det."],[24,24,"Thi falske Christi og falske Propheter skulle opstaae og gjøre store Tegn og Undergjerninger, at de Udvalgte skulde og forføres, om det var muligt.","Thi falske Christi og falske Propheter skulle opstaae og gjøre store Tegn og Undergjerninger, at de Udvalgte skulde og forføres, om det var muligt."],[24,25,"See, jeg haver sagt Eder det forud.","See, jeg haver sagt Eder det forud."],[24,26,"Derfor, om de sige Eder: see, han er i Ørken, da gaaer ikke ud; see, han er i Kammerne, da troer det ikke.","Derfor, om de sige Eder: see, han er i Ørken, da gaaer ikke ud; see, han er i Kammerne, da troer det ikke."],[24,27,"Thi ligesom Lynet udgaaer fra Østen og skinner indtil Vesten, saa skal og Menneskens Søns Tilkommelse være.","Thi ligesom Lynet udgaaer fra Østen og skinner indtil Vesten, saa skal og Menneskens Søns Tilkommelse være."],[24,28,"Thi hvor Aadslet er, der skulle Ørnene forsamles.","Thi hvor Aadslet er, der skulle Ørnene forsamles."],[24,29,"Men strax efter de Dages Trængsel skal Solen formørkes, og Maanen ikke give sit Skin, og Stjerne falde af Himmelen, og Himmelens Kræfter røres.","Men strax efter de Dages Trængsel skal Solen formørkes, og Maanen ikke give sit Skin, og Stjerne falde af Himmelen, og Himmelens Kræfter røres."],[24,30,"Og da skal Menneskens Søns Tegn aabenbares i Himmelen; og da skulle alle Jordens Slægter hyle, og de skulle see Menneskens Søn komme i Himmelens Skyer med Kraft og megen Herlighed.","Og da skal Menneskens Søns Tegn aabenbares i Himmelen; og da skulle alle Jordens Slægter hyle, og de skulle see Menneskens Søn komme i Himmelens Skyer med Kraft og megen Herlighed."],[24,31,"Og han skal udsende sine Engle med stærktlydende Basune, og de skulle forsamle hans Udvalgte fra de fire Veir, fra den ene Ende af Himmelen til den anden.","Og han skal udsende sine Engle med stærktlydende Basune, og de skulle forsamle hans Udvalgte fra de fire Veir, fra den ene Ende af Himmelen til den anden."],[24,32,"Lærer en Lignelse af Figentræet: naar Vædsken er kommen i dets Grene, og Bladene skyde ud, da vide I, at Sommeren er nær.","Lærer en Lignelse af Figentræet: naar Vædsken er kommen i dets Grene, og Bladene skyde ud, da vide I, at Sommeren er nær."],[24,33,"Saaledes og I, naar I see alt dette, vider, at han er nær for Døren.","Saaledes og I, naar I see alt dette, vider, at han er nær for Døren."],[24,34,"Sandelig siger jeg Eder, denne Slægt skal ikke forgaae, førend dette skeer altsammen.","Sandelig siger jeg Eder, denne Slægt skal ikke forgaae, førend dette skeer altsammen."],[24,35,"Himmelen og Jorden skulle forgaae, men mine Ord skulle ingenlunde forgaae.","Himmelen og Jorden skulle forgaae, men mine Ord skulle ingenlunde forgaae."],[24,36,"Men om den Dag og den Time veed Ingen, end ikke Himmelens Engle, uden min Fader alene.","Men om den Dag og den Time veed Ingen, end ikke Himmelens Engle, uden min Fader alene."],[24,37,"Men ligesom Noahs Dage vare, saa skal og Menneskens Søns Tilkommelse være.","Men ligesom Noahs Dage vare, saa skal og Menneskens Søns Tilkommelse være."],[24,38,"Thi ligesom de i Dagene før syndfloden aade og drak, toge tilægte og bortgiftede indtil den Dag, der Noah gik ind i Arken;","Thi ligesom de i Dagene før syndfloden aade og drak, toge tilægte og bortgiftede indtil den Dag, der Noah gik ind i Arken;"],[24,39,"og de agtede det ikke, indtil Syndfloden kom og tog dem alle bort: saaledes skal og Menneskens Søns Tilkommelse være.","og de agtede det ikke, indtil Syndfloden kom og tog dem alle bort: saaledes skal og Menneskens Søns Tilkommelse være."],[24,40,"Da skulle To være paa Ageren; den Ene skal annammes, og den Anden lades tilbage.","Da skulle To være paa Ageren; den Ene skal annammes, og den Anden lades tilbage."],[24,41,"To Kvinder skulle male paa Kværnen; den ene skal annammes, og den anden lades tilbage.","To Kvinder skulle male paa Kværnen; den ene skal annammes, og den anden lades tilbage."],[24,42,"Vaager derfor, thi I vide ikke, i hvilken Time Eders Herre kommer.","Vaager derfor, thi I vide ikke, i hvilken Time Eders Herre kommer."],[24,43,"Men dette skulle I vide, at dersom Huusbonden vidste, i hvilken Nattevagt Tyven vilde komme, da vaagede han og lod ikke bryde ind i sit Huus.","Men dette skulle I vide, at dersom Huusbonden vidste, i hvilken Nattevagt Tyven vilde komme, da vaagede han og lod ikke bryde ind i sit Huus."],[24,44,"Derfor værer I og rede; thi Menneskens Søn kommer paa den Time, som I ikke mene.","Derfor værer I og rede; thi Menneskens Søn kommer paa den Time, som I ikke mene."],[24,45,"Hvo er vel den troe og snilde Tjener, som hans Herre haver sat over sit Tyende, at give dem Mad i Tide?","Hvo er vel den troe og snilde Tjener, som hans Herre haver sat over sit Tyende, at give dem Mad i Tide?"],[24,46,"Salig er den Tjener, hvilken hans Herre, naar han kommer, finder at gjøre saaledes.","Salig er den Tjener, hvilken hans Herre, naar han kommer, finder at gjøre saaledes."],[24,47,"Sandelig siger jeg Eder, at han skal sætte ham over alt sit Gods.","Sandelig siger jeg Eder, at han skal sætte ham over alt sit Gods."],[24,48,"Men dersom nogen ond Tjener vilde sige i sit Hjerte: min Herre tøver at komme;","Men dersom nogen ond Tjener vilde sige i sit Hjerte: min Herre tøver at komme;"],[24,49,"og begynde at slaae Medtjenerne, men at æde og drikke med de Drukne:","og begynde at slaae Medtjenerne, men at æde og drikke med de Drukne:"],[24,50,"saa skal den Tjeners Herre komme paa den Dag, som han ikke forventer, og paa den Time, som han ikke veed,","saa skal den Tjeners Herre komme paa den Dag, som han ikke forventer, og paa den Time, som han ikke veed,"],[24,51,"og slaae ham sønder, og giver ham sin Deel med Øienskalke; der skal være Graad og Tænders Gnidsel.","og slaae ham sønder, og giver ham sin Deel med Øienskalke; der skal være Graad og Tænders Gnidsel."],[25,1,"Da skal Himmeriges Rige lignes ved ti Jomfruer, som toge deres Lamper og gik Brudgommen imøde.","Da skal Himmeriges Rige lignes ved ti Jomfruer, som toge deres Lamper og gik Brudgommen imøde."],[25,2,"Men de fem af dem vare kloge, og de fem daarlige.","Men de fem af dem vare kloge, og de fem daarlige."],[25,3,"De daarlige toge deres Lamper, men toge ikke Olie med sig.","De daarlige toge deres Lamper, men toge ikke Olie med sig."],[25,4,"Men de kloge toge Olie i deres Kar tilligemed deres Lamper.","Men de kloge toge Olie i deres Kar tilligemed deres Lamper."],[25,5,"Og der Brudgommen tøvede, slumrede de alle og sov ind.","Og der Brudgommen tøvede, slumrede de alle og sov ind."],[25,6,"Men ved Midnat skete Anskrig: see, Brudgommen kommer; gaaer ham imøde!","Men ved Midnat skete Anskrig: see, Brudgommen kommer; gaaer ham imøde!"],[25,7,"Da bleve Jomfruerne alle opvakte, og gjorde deres Lamper tilrette.","Da bleve Jomfruerne alle opvakte, og gjorde deres Lamper tilrette."],[25,8,"Men de daarlige sagde til de kloge: giver os af Eders Olie; thi vore Lamper udslukkes.","Men de daarlige sagde til de kloge: giver os af Eders Olie; thi vore Lamper udslukkes."],[25,9,"Men de kloge svarede og sagde: det maatte ikke blive nok til os og Eder; men gaaer hellere hen til Sælgerne, og kjøber for Eder selv.","Men de kloge svarede og sagde: det maatte ikke blive nok til os og Eder; men gaaer hellere hen til Sælgerne, og kjøber for Eder selv."],[25,10,"Men der de vare bortgangne at kjøbe, kom Brudgommen, og de, som vare rede, gik ind med ham til Bryllup; og Døren blev tillukt.","Men der de vare bortgangne at kjøbe, kom Brudgommen, og de, som vare rede, gik ind med ham til Bryllup; og Døren blev tillukt."],[25,11,"Siden kom og de andre Jomfruer, og sagde: Herre, Herre, lad op for os!","Siden kom og de andre Jomfruer, og sagde: Herre, Herre, lad op for os!"],[25,12,"Men han svarede og sagde: sandelig siger jeg Eder, jeg kjender Eder ikke.","Men han svarede og sagde: sandelig siger jeg Eder, jeg kjender Eder ikke."],[25,13,"Vaager derfor, thi I vide hverken Dag eller Time, paa hvilken Menneskens Søn kommer.","Vaager derfor, thi I vide hverken Dag eller Time, paa hvilken Menneskens Søn kommer."],[25,14,"Thi ligesom en Mand, der drog udenlands, kaldte sine Tjenere og overantvordede dem sit Gods,","Thi ligesom en Mand, der drog udenlands, kaldte sine Tjenere og overantvordede dem sit Gods,"],[25,15,"og gav en fem Talenter, en anden to, og en anden eet, hver efter hans Evne; og han drog strax udenlands.","og gav en fem Talenter, en anden to, og en anden eet, hver efter hans Evne; og han drog strax udenlands."],[25,16,"Da gik den, som havde annammet fem Talenter, hen og kjøbslog med dem, og vandt andre fem Talenter.","Da gik den, som havde annammet fem Talenter, hen og kjøbslog med dem, og vandt andre fem Talenter."],[25,17,"Ligesaa og den, som havde annammet de to Talenter, ogsaa han vandt andre to.","Ligesaa og den, som havde annammet de to Talenter, ogsaa han vandt andre to."],[25,18,"Men den, som havde annammet det ene, gik bort og grov i Jorden og skjulte sin Herres Penge.","Men den, som havde annammet det ene, gik bort og grov i Jorden og skjulte sin Herres Penge."],[25,19,"Men en lang Tid derefter kom disse Tjeneres Herre, og holdt Regnskab med dem.","Men en lang Tid derefter kom disse Tjeneres Herre, og holdt Regnskab med dem."],[25,20,"Da gik den frem som havde annammet fem Talenter, og frembragte andre fem Talenter, og sagde: Herre! du overantvordede mig fem Talenter; see, jeg haver vundet fem andre Talenter med dem.","Da gik den frem som havde annammet fem Talenter, og frembragte andre fem Talenter, og sagde: Herre! du overantvordede mig fem Talenter; see, jeg haver vundet fem andre Talenter med dem."],[25,21,"Men hans Herre sagde til ham: vel, du gode og troe Tjener! du haver været tro over det Lidet, jeg vil sætte dig over Meget; gak ind til din Herres Glæde.","Men hans Herre sagde til ham: vel, du gode og troe Tjener! du haver været tro over det Lidet, jeg vil sætte dig over Meget; gak ind til din Herres Glæde."],[25,22,"Da gik og den frem, som havde annammet to Talenter, og sagde: Herre! du overantvordede mig to Talenter; see, jeg haver vundet to andre Talenter med dem.","Da gik og den frem, som havde annammet to Talenter, og sagde: Herre! du overantvordede mig to Talenter; see, jeg haver vundet to andre Talenter med dem."],[25,23,"Hans Herre sagde til ham: vel, du gode og troe Tjener; du haver været tro over Lidet, jeg vil sætte dig over Meget; gak ind til din Herres Glæde.","Hans Herre sagde til ham: vel, du gode og troe Tjener; du haver været tro over Lidet, jeg vil sætte dig over Meget; gak ind til din Herres Glæde."],[25,24,"Men den traadte frem, som havde annammet eet Talent, og sagde: Herre! jeg kjendte dig, at du er en haard Mand, som høster, der du ikke saaede, og samler, der du ikke spredte;","Men den traadte frem, som havde annammet eet Talent, og sagde: Herre! jeg kjendte dig, at du er en haard Mand, som høster, der du ikke saaede, og samler, der du ikke spredte;"],[25,25,"frygtende herfor gik jeg hen, og skjulte dit Talent i Jorden; see, der haver du, hvad dit er.","frygtende herfor gik jeg hen, og skjulte dit Talent i Jorden; see, der haver du, hvad dit er."],[25,26,"Men hans Herre svarede og sagde til ham: du onde og lade Tjener! du vidste, at jeg høster, der jeg ikke saaede, og samler, der jeg ikke spredte;","Men hans Herre svarede og sagde til ham: du onde og lade Tjener! du vidste, at jeg høster, der jeg ikke saaede, og samler, der jeg ikke spredte;"],[25,27,"derfor burde det dig, at have overantvordet Vexelererne mine Penge; og naar jeg kom, da havde jeg faaet Mit igjen med Rente.","derfor burde det dig, at have overantvordet Vexelererne mine Penge; og naar jeg kom, da havde jeg faaet Mit igjen med Rente."],[25,28,"Tager derfor det Talent fra ham og giver det til den, som haver ti Talenter.","Tager derfor det Talent fra ham og giver det til den, som haver ti Talenter."],[25,29,"Thi hver, som haver, ham skal gives, og han skal have til Overflod; men hvo som ikke haver, ham skal endog fratages det, han haver.","Thi hver, som haver, ham skal gives, og han skal have til Overflod; men hvo som ikke haver, ham skal endog fratages det, han haver."],[25,30,"Og kaster den udygtige Tjener ud i det yderste Mørke; der skal være Graad og Tænders Gnidsel.","Og kaster den udygtige Tjener ud i det yderste Mørke; der skal være Graad og Tænders Gnidsel."],[25,31,"Men naar Menneskens Søn kommer i sin Herlighed, og alle hellige Engle med ham, da skal han sidde paa sin Herligheds Throne.","Men naar Menneskens Søn kommer i sin Herlighed, og alle hellige Engle med ham, da skal han sidde paa sin Herligheds Throne."],[25,32,"Og alle Folkeslag skulle forsamles for ham, og han skal skille dem fra hverandre, ligesom en Hyrde skiller Faarene fra Bukkene.","Og alle Folkeslag skulle forsamles for ham, og han skal skille dem fra hverandre, ligesom en Hyrde skiller Faarene fra Bukkene."],[25,33,"Og han skal stille Faarene ved sin høire Side, men Bukkene ved den venstre.","Og han skal stille Faarene ved sin høire Side, men Bukkene ved den venstre."],[25,34,"Da skal Kongen sige til dem ved hans høire Side: kommer hid, min Faders Velsignede! arver det Rige, som Eder er beredt, fra Verdens Grundvold blev lagt.","Da skal Kongen sige til dem ved hans høire Side: kommer hid, min Faders Velsignede! arver det Rige, som Eder er beredt, fra Verdens Grundvold blev lagt."],[25,35,"Thi jeg var hungrig, og I gave mig at æde; jeg var tørstig, og I gave mig at drikke; jeg var fremmed, og I toge mig til Eder;","Thi jeg var hungrig, og I gave mig at æde; jeg var tørstig, og I gave mig at drikke; jeg var fremmed, og I toge mig til Eder;"],[25,36,"jeg var nøgen, og I klædte mig; jeg var syg, og I besøgte mig; jeg var i Fængsel, og I kom til mig.","jeg var nøgen, og I klædte mig; jeg var syg, og I besøgte mig; jeg var i Fængsel, og I kom til mig."],[25,37,"Da skulle de Retfærdige svare ham og sige: Herre! naar saae vi dig hungrig, og gave dig Mad? eller tørstig, og gave dig at drikke?","Da skulle de Retfærdige svare ham og sige: Herre! naar saae vi dig hungrig, og gave dig Mad? eller tørstig, og gave dig at drikke?"],[25,38,"Naar have vi seet dig fremmed, og taget dig til os? eller nøgen, og have klædt dig?","Naar have vi seet dig fremmed, og taget dig til os? eller nøgen, og have klædt dig?"],[25,39,"Naar have vi seet dig syg, eller i Fængsel, og ere komne til dig?","Naar have vi seet dig syg, eller i Fængsel, og ere komne til dig?"],[25,40,"Og Kongen skal svare: sandelig siger jeg Eder: hvad I have gjort mod een af disse mine mindste Brødre, have I gjort mod mig.","Og Kongen skal svare: sandelig siger jeg Eder: hvad I have gjort mod een af disse mine mindste Brødre, have I gjort mod mig."],[25,41,"Da skal han sige til dem ved den venstre Side: gaaer bort fra mig, I Forbandede! i den evige Ild, som er beredt Djævelen og hans Engle.","Da skal han sige til dem ved den venstre Side: gaaer bort fra mig, I Forbandede! i den evige Ild, som er beredt Djævelen og hans Engle."],[25,42,"Thi jeg var hungrig, og I gave mig ikke at æde; jeg var tørstig, og I gave mig ikke at drikke;","Thi jeg var hungrig, og I gave mig ikke at æde; jeg var tørstig, og I gave mig ikke at drikke;"],[25,43,"jeg var fremmed, og I toge mig ikke til Eder; jeg var nøgen, og I klædte mig ikke; jeg var syg, og i Fængsel, og I besøgte mig ikke.","jeg var fremmed, og I toge mig ikke til Eder; jeg var nøgen, og I klædte mig ikke; jeg var syg, og i Fængsel, og I besøgte mig ikke."],[25,44,"Da skulle de ogsaa svare ham og sige: Herre! naar have vi seet dig hungrig eller tørstig eller fremmed eller nøgen eller syg eller i Fængsel, og have ikke tjent dig?","Da skulle de ogsaa svare ham og sige: Herre! naar have vi seet dig hungrig eller tørstig eller fremmed eller nøgen eller syg eller i Fængsel, og have ikke tjent dig?"],[25,45,"Da skal han svare dem og sige; sandelig siger jeg Eder: hvad I ikke have gjort mod een af disse Mindste, have I heller ikke gjort mod mig.","Da skal han svare dem og sige; sandelig siger jeg Eder: hvad I ikke have gjort mod een af disse Mindste, have I heller ikke gjort mod mig."],[25,46,"Og de skulle gaae hen, disse til den evige Pine, men de Retfærdige til det evige Liv.","Og de skulle gaae hen, disse til den evige Pine, men de Retfærdige til det evige Liv."],[26,1,"Og det skete, der Jesus havde endt alle disse Ord, sagde han til sine Disciple:","Og det skete, der Jesus havde endt alle disse Ord, sagde han til sine Disciple:"],[26,2,"I vide, at om to Dage er det Paaske, og Menneskens Søn skal forraades til at korsfæstes.","I vide, at om to Dage er det Paaske, og Menneskens Søn skal forraades til at korsfæstes."],[26,3,"Da forsamledes de Ypperstepræster og Skriftkloge og Folkets Ældste i den Ypperstepræstes Pallads; han hedte Caiphas.","Da forsamledes de Ypperstepræster og Skriftkloge og Folkets Ældste i den Ypperstepræstes Pallads; han hedte Caiphas."],[26,4,"Og de holdt Raad, at de kunde gribe Jesus med List og ihjelslaae ham.","Og de holdt Raad, at de kunde gribe Jesus med List og ihjelslaae ham."],[26,5,"Men de sagde: ikke paa Høitiden, at der ikke skal blive Larm iblandt Folket.","Men de sagde: ikke paa Høitiden, at der ikke skal blive Larm iblandt Folket."],[26,6,"Men der Jesus var i Bethania udi Simon den Spedalskes Huus,","Men der Jesus var i Bethania udi Simon den Spedalskes Huus,"],[26,7,"da kom en Kvinde til ham, som havde en Alabasters Krukke med meget kostelig Salve, og udøste den paa hans Hoved, der han sad tilbords.","da kom en Kvinde til ham, som havde en Alabasters Krukke med meget kostelig Salve, og udøste den paa hans Hoved, der han sad tilbords."],[26,8,"Men der hans Disciple det saae, bleve de fortrydelige og sagde: hvortil tjener denne Spilde?","Men der hans Disciple det saae, bleve de fortrydelige og sagde: hvortil tjener denne Spilde?"],[26,9,"Thi denne Salve kunde været solgt til en høi Priis og givet til de Fattige.","Thi denne Salve kunde været solgt til en høi Priis og givet til de Fattige."],[26,10,"Men der Jesus det mærkte, sagde han til dem: hvi gjøre I denne Kvinde Fortred? Hun haver jo gjort en god Gjerning imod mig.","Men der Jesus det mærkte, sagde han til dem: hvi gjøre I denne Kvinde Fortred? Hun haver jo gjort en god Gjerning imod mig."],[26,11,"Thi I have altid Fattige hos Eder; men mig have I ikke altid.","Thi I have altid Fattige hos Eder; men mig have I ikke altid."],[26,12,"Thi at hun udgød denne Salve paa mit Legeme, det haver hun gjort for at flye mig tiljorde.","Thi at hun udgød denne Salve paa mit Legeme, det haver hun gjort for at flye mig tiljorde."],[26,13,"Sandelig siger jeg Eder, hvorsomhelst dette Evangelium bliver prædiket i den ganske Verden, skal og det, hun haver gjort, omtales til hendes Ihukommelse.","Sandelig siger jeg Eder, hvorsomhelst dette Evangelium bliver prædiket i den ganske Verden, skal og det, hun haver gjort, omtales til hendes Ihukommelse."],[26,14,"Da gik een af de Tolv, ved Navn Judas Ischariotes, hen til de Ypperstepræster,","Da gik een af de Tolv, ved Navn Judas Ischariotes, hen til de Ypperstepræster,"],[26,15,"og sagde: hvad ville I give mig, saa vil jeg forraade Eder ham? Men de udtællede ham tredive Sølvpenninge.","og sagde: hvad ville I give mig, saa vil jeg forraade Eder ham? Men de udtællede ham tredive Sølvpenninge."],[26,16,"Og fra den Stund søgte han beleilig Tid til at forraade ham.","Og fra den Stund søgte han beleilig Tid til at forraade ham."],[26,17,"Men paa den første Dag af de usyrede Brøds Høitid gik Disciplene til Jesus, og sagde til ham; hvor vil du, at vi skulle berede for dig at æde Paaskelammet?","Men paa den første Dag af de usyrede Brøds Høitid gik Disciplene til Jesus, og sagde til ham; hvor vil du, at vi skulle berede for dig at æde Paaskelammet?"],[26,18,"Men han sagde: gaaer ind i Staden til en vis Mand, og siger til ham: Mesteren siger; min Tid er nær; jeg vil holde Paaske hos dig med mine Disciple.","Men han sagde: gaaer ind i Staden til en vis Mand, og siger til ham: Mesteren siger; min Tid er nær; jeg vil holde Paaske hos dig med mine Disciple."],[26,19,"Og Disciplene gjorde, ligesom Jesus befoel dem, og beredte Paaskelammet.","Og Disciplene gjorde, ligesom Jesus befoel dem, og beredte Paaskelammet."],[26,20,"Men der det var blevet Aften, satte han sig tilbords med de Tolv.","Men der det var blevet Aften, satte han sig tilbords med de Tolv."],[26,21,"Og der de aade, sagde han: sandelig siger jeg Eder, at Een af Eder skal forraade mig.","Og der de aade, sagde han: sandelig siger jeg Eder, at Een af Eder skal forraade mig."],[26,22,"Og de bleve saare bedrøvede, og begyndte hver især at sige til ham: Herre, er det mig?","Og de bleve saare bedrøvede, og begyndte hver især at sige til ham: Herre, er det mig?"],[26,23,"Men han svarede og sagde: den, som dyppede Haanden tilligemed mig i Fadet, han skal forraade mig.","Men han svarede og sagde: den, som dyppede Haanden tilligemed mig i Fadet, han skal forraade mig."],[26,24,"Menneskens Søn gaaer vel bort, som der er skrevet om ham; men vee det Menneske, ved hvilket Menneskens Søn bliver forraadt! Det var dette Menneske bedre, om han aldrig var født.","Menneskens Søn gaaer vel bort, som der er skrevet om ham; men vee det Menneske, ved hvilket Menneskens Søn bliver forraadt! Det var dette Menneske bedre, om han aldrig var født."],[26,25,"Men Judas, som ham forraadte, svarede og sagde: er det mig, Mester? Han sagde til ham: du haver sagt det.","Men Judas, som ham forraadte, svarede og sagde: er det mig, Mester? Han sagde til ham: du haver sagt det."],[26,26,"Men der de aade, tog Jesus Brødet og takkede, brød det og gav Disciplene det, og sagde: tager, æder; dette er mit Legeme.","Men der de aade, tog Jesus Brødet og takkede, brød det og gav Disciplene det, og sagde: tager, æder; dette er mit Legeme."],[26,27,"Og han tog Kalken og takkede, gav dem den og sagde: drikker Alle deraf;","Og han tog Kalken og takkede, gav dem den og sagde: drikker Alle deraf;"],[26,28,"thi dette er mit Blod, det nye Testamentes, hvilket udgydes for Mange til Syndernes Forladelse.","thi dette er mit Blod, det nye Testamentes, hvilket udgydes for Mange til Syndernes Forladelse."],[26,29,"Men jeg siger Eder, at jeg skal herefter ikke mere drikke af denne Viintræets Frugt, indtil den Dag, da jeg skal drikke den nye med Eder i min Faders Rige.","Men jeg siger Eder, at jeg skal herefter ikke mere drikke af denne Viintræets Frugt, indtil den Dag, da jeg skal drikke den nye med Eder i min Faders Rige."],[26,30,"Og der de havde sjunget Lovsangen, gik de ud til Oliebjerget.","Og der de havde sjunget Lovsangen, gik de ud til Oliebjerget."],[26,31,"Da siger Jesus til dem: i denne Nat skulle I alle forarges paa mig; thi der er skrevet: jeg skal slaae Hyrden, og Hjordens Faar skulle adspredes.","Da siger Jesus til dem: i denne Nat skulle I alle forarges paa mig; thi der er skrevet: jeg skal slaae Hyrden, og Hjordens Faar skulle adspredes."],[26,32,"Men efterat jeg er opstanden, vil jeg gaae forud for Eder til Galilæa.","Men efterat jeg er opstanden, vil jeg gaae forud for Eder til Galilæa."],[26,33,"Men Peter svarede og sagde til ham: dersom de og alle skulle forarges paa dig, saa vil jeg dog aldrig forarges.","Men Peter svarede og sagde til ham: dersom de og alle skulle forarges paa dig, saa vil jeg dog aldrig forarges."],[26,34,"Jesus sagde til ham: sandelig siger jeg dig, at i denne Nat, førend Hanen galer, skal du fornegte mig tre Gange.","Jesus sagde til ham: sandelig siger jeg dig, at i denne Nat, førend Hanen galer, skal du fornegte mig tre Gange."],[26,35,"Peter sagde til ham; dersom jeg og skulde døe med dig, vil jeg ikke fornegte dig. Ligesaa sagde og alle Disciplene.","Peter sagde til ham; dersom jeg og skulde døe med dig, vil jeg ikke fornegte dig. Ligesaa sagde og alle Disciplene."],[26,36,"Da kom Jesus med dem til en Gaard, som kaldes Gethsemane, og sagde til Disciplene: sætter Eder her, medens jeg gaaer derhen og beder.","Da kom Jesus med dem til en Gaard, som kaldes Gethsemane, og sagde til Disciplene: sætter Eder her, medens jeg gaaer derhen og beder."],[26,37,"Og han tog Peter og de to Zebedæus’ Sønner til sig, og begyndte at bedrøves og svarligen at ængstes.","Og han tog Peter og de to Zebedæus’ Sønner til sig, og begyndte at bedrøves og svarligen at ængstes."],[26,38,"Da siger han til dem: min Sjæl er ganske bedrøvet indtil Døden; bliver her og vaager med mig.","Da siger han til dem: min Sjæl er ganske bedrøvet indtil Døden; bliver her og vaager med mig."],[26,39,"Og han gik lidet frem, faldt paa sit Ansigt, og bad og sagde: min Fader er det muligt, da gaae denne Kalk fra mig; dog ikke som jeg vil, men som du vil.","Og han gik lidet frem, faldt paa sit Ansigt, og bad og sagde: min Fader er det muligt, da gaae denne Kalk fra mig; dog ikke som jeg vil, men som du vil."],[26,40,"Og han kom til Disciplene, og fandt dem sovende, og sagde til Peter: saa kunde I da ikke vaage een Time med mig!","Og han kom til Disciplene, og fandt dem sovende, og sagde til Peter: saa kunde I da ikke vaage een Time med mig!"],[26,41,"Vaager og beder, at I ikke falde i Fristelse! Aanden er vel redebon, men Kjødet er skrøbeligt.","Vaager og beder, at I ikke falde i Fristelse! Aanden er vel redebon, men Kjødet er skrøbeligt."],[26,42,"Han gik atter anden Gang hen, bad og sagde; min Fader! er det ikke muligt, at denne Kalk kan gaae fra mig, uden jeg skal drikke den, da skee din Villie.","Han gik atter anden Gang hen, bad og sagde; min Fader! er det ikke muligt, at denne Kalk kan gaae fra mig, uden jeg skal drikke den, da skee din Villie."],[26,43,"Og han kom og fandt dem atter sovende; thi deres Øine vare betyngede.","Og han kom og fandt dem atter sovende; thi deres Øine vare betyngede."],[26,44,"Og han lod dem blive, og gik atter hen, og bad tredie Gang, og talede de samme Ord.","Og han lod dem blive, og gik atter hen, og bad tredie Gang, og talede de samme Ord."],[26,45,"Da kom han til sine Disciple og sagde til dem: sove I fremdeles og hvile Eder? See, Timen er nær, og Menneskens Søn skal forraades i Synderes Hænder.","Da kom han til sine Disciple og sagde til dem: sove I fremdeles og hvile Eder? See, Timen er nær, og Menneskens Søn skal forraades i Synderes Hænder."],[26,46,"Staaer op, lader os gaae; see, han er nær, som forraader mig.","Staaer op, lader os gaae; see, han er nær, som forraader mig."],[26,47,"Og der han endnu talede, see, da kom Judas, een af de tolv, og en stor Skare med ham, med Sværd og Stænger, fra de Ypperstepræster og Folkets Ældste.","Og der han endnu talede, see, da kom Judas, een af de tolv, og en stor Skare med ham, med Sværd og Stænger, fra de Ypperstepræster og Folkets Ældste."],[26,48,"Men den, som ham forraadte, havde givet dem et Tegn og sagt: hvilken jeg monne kysse, den er det; griber ham!","Men den, som ham forraadte, havde givet dem et Tegn og sagt: hvilken jeg monne kysse, den er det; griber ham!"],[26,49,"Og han traadte strax til Jesus og sagde: hil være dig, Rabbi! og kyssede ham.","Og han traadte strax til Jesus og sagde: hil være dig, Rabbi! og kyssede ham."],[26,50,"Men Jesus sagde til ham: Ven, hvorfor er du kommen? Da traadte de frem og lagde Hænder paa Jesus og grebe ham.","Men Jesus sagde til ham: Ven, hvorfor er du kommen? Da traadte de frem og lagde Hænder paa Jesus og grebe ham."],[26,51,"Og see, Een af dem, som vare med Jesus, udrakte Haanden, og uddrog sit Sværd, og slog den Ypperstepræstes Tjener, og huggede hans Øre af.","Og see, Een af dem, som vare med Jesus, udrakte Haanden, og uddrog sit Sværd, og slog den Ypperstepræstes Tjener, og huggede hans Øre af."],[26,52,"Da sagde Jesus til ham: stik dit Sværd paa sit Sted; thi alle de, som tage Sværd, skulle omkomme ved Sværd.","Da sagde Jesus til ham: stik dit Sværd paa sit Sted; thi alle de, som tage Sværd, skulle omkomme ved Sværd."],[26,53,"Eller mener du, at jeg nu ikke kunde bede min Fader, at han skulde tilskikke mig mere end tolv Legioner Engle?","Eller mener du, at jeg nu ikke kunde bede min Fader, at han skulde tilskikke mig mere end tolv Legioner Engle?"],[26,54,"Hvorledes skulde da Skrifterne fuldkommes, at det bør saaledes gaae til?","Hvorledes skulde da Skrifterne fuldkommes, at det bør saaledes gaae til?"],[26,55,"Paa den samme Tid sagde Jesus til Skaren: I ere udgangne ligesom til en Røver, med Sværd og Stænger at tage fat paa mig. Jeg haver siddet daglig hos Eder og lært i Templet, og I grebe mig ikke.","Paa den samme Tid sagde Jesus til Skaren: I ere udgangne ligesom til en Røver, med Sværd og Stænger at tage fat paa mig. Jeg haver siddet daglig hos Eder og lært i Templet, og I grebe mig ikke."],[26,56,"Men det er altsammen skeet, at Propheternes Skrifter skulle fuldkommes. Da forlode alle Disciplene ham og flyede.","Men det er altsammen skeet, at Propheternes Skrifter skulle fuldkommes. Da forlode alle Disciplene ham og flyede."],[26,57,"Men de, som havde grebet Jesus, førte ham hen til den Ypperstepræst Caiphas, der hvor de Skrifkloge og Ældste vare forsamlede.","Men de, som havde grebet Jesus, førte ham hen til den Ypperstepræst Caiphas, der hvor de Skrifkloge og Ældste vare forsamlede."],[26,58,"Men Peter fulgte langt fra efter ham indtil den Ypperstepræstes Pallads, og gik indenfor og sad hos Svendene, at see Enden.","Men Peter fulgte langt fra efter ham indtil den Ypperstepræstes Pallads, og gik indenfor og sad hos Svendene, at see Enden."],[26,59,"Men de Ypperstepræster og de Ældste og det ganske Raad søgte falsk Vidnesbyrd mod Jesus, paa det de kunde aflive ham; og de fandt intet.","Men de Ypperstepræster og de Ældste og det ganske Raad søgte falsk Vidnesbyrd mod Jesus, paa det de kunde aflive ham; og de fandt intet."],[26,60,"Og alligevel at der traadte mange falske Vidner frem, fandt de dog intet. Men paa det Sidste traadte to falske Vidner frem og sagde:","Og alligevel at der traadte mange falske Vidner frem, fandt de dog intet. Men paa det Sidste traadte to falske Vidner frem og sagde:"],[26,61,"denne har sagt: jeg kan nedbryde Guds Tempel og bygge det i tre Dage.","denne har sagt: jeg kan nedbryde Guds Tempel og bygge det i tre Dage."],[26,62,"Og den Ypperstepræst stod op og sagde til ham: svarer du Intet? hvad vidne disse imod dig?","Og den Ypperstepræst stod op og sagde til ham: svarer du Intet? hvad vidne disse imod dig?"],[26,63,"Men Jesus taug. Og den Ypperstepræst svarede og sagde til ham: jeg besværger dig ved den levende Gud, at du siger os, om du er den Christus, den levende Guds Søn.","Men Jesus taug. Og den Ypperstepræst svarede og sagde til ham: jeg besværger dig ved den levende Gud, at du siger os, om du er den Christus, den levende Guds Søn."],[26,64,"Jesus sagde til ham: du haver sagt det; dog siger jeg Eder: nu herefter skulle I see Menneskens Søn sidde hos Kraftens høire Haand og komme i Himmelens Skyer.","Jesus sagde til ham: du haver sagt det; dog siger jeg Eder: nu herefter skulle I see Menneskens Søn sidde hos Kraftens høire Haand og komme i Himmelens Skyer."],[26,65,"Da sønderrev den Ypperstepræst sine Klæder og sagde: han haver bespottet Gud; hvad have vi længere Vidner behov? see, nu have I hørt hans Bespottelse.","Da sønderrev den Ypperstepræst sine Klæder og sagde: han haver bespottet Gud; hvad have vi længere Vidner behov? see, nu have I hørt hans Bespottelse."],[26,66,"Hvad tykkes Eder? Men de svarede og sagde: han er skyldig til Døden.","Hvad tykkes Eder? Men de svarede og sagde: han er skyldig til Døden."],[26,67,"Da spyttede de udi hans Ansigt og sloge ham paa Munden; men de Andre sloge ham med Kjeppe.","Da spyttede de udi hans Ansigt og sloge ham paa Munden; men de Andre sloge ham med Kjeppe."],[26,68,"Og de sagde: spaa os, Christus, hvo er den, der dig slog?","Og de sagde: spaa os, Christus, hvo er den, der dig slog?"],[26,69,"Men Peter sad udenfor i Gaarden; og en Pige kom til ham og sagde: du haver og været med Jesus den Galilæer.","Men Peter sad udenfor i Gaarden; og en Pige kom til ham og sagde: du haver og været med Jesus den Galilæer."],[26,70,"Men han negtede det for dem alle og sagde: jeg veed ikke, hvad du siger.","Men han negtede det for dem alle og sagde: jeg veed ikke, hvad du siger."],[26,71,"Men der han gik hen til Indgangen, saae en anden ham; og hun sagde til dem, som der vare: denne var og med Jesus af Nazareth.","Men der han gik hen til Indgangen, saae en anden ham; og hun sagde til dem, som der vare: denne var og med Jesus af Nazareth."],[26,72,"Og han negtede det atter med en Ed, sigende: jeg kjender ikke det Menneske.","Og han negtede det atter med en Ed, sigende: jeg kjender ikke det Menneske."],[26,73,"Men lidet derefter gik de frem, som stode der, og sagde til Peter: sandelig, du er og een af dem, thi og dit Maal røber dig.","Men lidet derefter gik de frem, som stode der, og sagde til Peter: sandelig, du er og een af dem, thi og dit Maal røber dig."],[26,74,"Da begyndte han at forbande sig og sværge: jeg kjender ikke det Menneske. Og strax goel Hanen.","Da begyndte han at forbande sig og sværge: jeg kjender ikke det Menneske. Og strax goel Hanen."],[26,75,"Og Peter kom Jesu Ord ihu, der han sagde til ham: førend Hanen galer, skal du fornegte mig tre Gange. Og han gik udenfor og græd bitterlig.","Og Peter kom Jesu Ord ihu, der han sagde til ham: førend Hanen galer, skal du fornegte mig tre Gange. Og han gik udenfor og græd bitterlig."],[27,1,"Men der det var blevet Morgen, holdt alle de Ypperstepræster og Folkets Ældste Raad imod Jesus, at de kunde aflive ham.","Men der det var blevet Morgen, holdt alle de Ypperstepræster og Folkets Ældste Raad imod Jesus, at de kunde aflive ham."],[27,2,"Og de bandt ham og førte ham hen, og overantvordede Landshøvdingen Pontius Pilatus ham.","Og de bandt ham og førte ham hen, og overantvordede Landshøvdingen Pontius Pilatus ham."],[27,3,"Der Judas, som ham forraadte, da saae, at han var fordømt, angrede det ham, og han bar de tredive Sølvpenninge til de Ypperstepræster og Ældste igjen og sagde:","Der Judas, som ham forraadte, da saae, at han var fordømt, angrede det ham, og han bar de tredive Sølvpenninge til de Ypperstepræster og Ældste igjen og sagde:"],[27,4,"jeg haver syndet, at jeg forraadte uskyldigt Blod. Men de sagde: hvad kommer det os ved? see du dertil.","jeg haver syndet, at jeg forraadte uskyldigt Blod. Men de sagde: hvad kommer det os ved? see du dertil."],[27,5,"Og han kastede Sølvpenningene i Templet, veg bort, og gik hen og hængte sig.","Og han kastede Sølvpenningene i Templet, veg bort, og gik hen og hængte sig."],[27,6,"Men de Ypperstepræster toge Sølvpenningene og sagde; det er ikke tilladt at lægge dem i Templets Kiste, thi det er Blodpenge.","Men de Ypperstepræster toge Sølvpenningene og sagde; det er ikke tilladt at lægge dem i Templets Kiste, thi det er Blodpenge."],[27,7,"Men de holdt Raad og kjøbte den Pottemagers Ager derfor, til at jorde Fremmede udi.","Men de holdt Raad og kjøbte den Pottemagers Ager derfor, til at jorde Fremmede udi."],[27,8,"Derfor blev den Ager kaldet Blodager indtil denne Dag.","Derfor blev den Ager kaldet Blodager indtil denne Dag."],[27,9,"Da fuldkommedes det, som talet er ved Propheten Jeremias, som siger: og de toge de tredive Sølvpenninge, den Vurderedes Værd, hvilken Israels Børn vurderede,","Da fuldkommedes det, som talet er ved Propheten Jeremias, som siger: og de toge de tredive Sølvpenninge, den Vurderedes Værd, hvilken Israels Børn vurderede,"],[27,10,"og de gave dem for en Pottemagers Ager, som Herren befoel mig.","og de gave dem for en Pottemagers Ager, som Herren befoel mig."],[27,11,"Men Jesus stod for Landshøvdingen; og Landshøvdingen spurgte ham og sagde: er du Jødernes Konge? Men Jesus sagde til ham: du siger det.","Men Jesus stod for Landshøvdingen; og Landshøvdingen spurgte ham og sagde: er du Jødernes Konge? Men Jesus sagde til ham: du siger det."],[27,12,"Og der han blev anklaget af de Ypperstepræster og Ældste, svarede han Intet.","Og der han blev anklaget af de Ypperstepræster og Ældste, svarede han Intet."],[27,13,"Da sagde Pilatus til ham: hører du ikke, hvor meget de vidne imod dig?","Da sagde Pilatus til ham: hører du ikke, hvor meget de vidne imod dig?"],[27,14,"Og han svarede ham end ikke til eet Ord, saa at Landshøvdingen forundrede sig saare.","Og han svarede ham end ikke til eet Ord, saa at Landshøvdingen forundrede sig saare."],[27,15,"Men paa Høitiden pleiede Landshøvdingen at give Folket een Fange løs, hvilken de vilde.","Men paa Høitiden pleiede Landshøvdingen at give Folket een Fange løs, hvilken de vilde."],[27,16,"Men de havde da en mærkelig Fange, som hedte Barrabas.","Men de havde da en mærkelig Fange, som hedte Barrabas."],[27,17,"Derfor, der de vare forsamlede, sagde Pilatus til dem: hvilken ville I, at jeg skal give Eder løs: Barrabas? eller Jesus, som kaldes Christus?","Derfor, der de vare forsamlede, sagde Pilatus til dem: hvilken ville I, at jeg skal give Eder løs: Barrabas? eller Jesus, som kaldes Christus?"],[27,18,"Thi han vidste, at de havde af Avind overantvordet ham.","Thi han vidste, at de havde af Avind overantvordet ham."],[27,19,"Men der han sad paa Domstolen, skikkede hans Hustru til ham og lod sige: befat dig intet med denne Retfærdige! thi jeg haver lidt meget i Dag i en Drøm for hans Skyld.","Men der han sad paa Domstolen, skikkede hans Hustru til ham og lod sige: befat dig intet med denne Retfærdige! thi jeg haver lidt meget i Dag i en Drøm for hans Skyld."],[27,20,"Men de Ypperstepræster og de Ældste overtalede Folket, at de skulde begjere Barrabas, men omkomme Jesus.","Men de Ypperstepræster og de Ældste overtalede Folket, at de skulde begjere Barrabas, men omkomme Jesus."],[27,21,"Men Landshøvdingen svarede og sagde til dem: hvilken ville I, at jeg skal give Eder løs af disse To? Men de sagde: Barrabas.","Men Landshøvdingen svarede og sagde til dem: hvilken ville I, at jeg skal give Eder løs af disse To? Men de sagde: Barrabas."],[27,22,"Pilatus sagde til dem: hvad skal jeg da gjøre med Jesus, som kaldes Christus? De sagde alle til ham: lad ham korsfæstes!","Pilatus sagde til dem: hvad skal jeg da gjøre med Jesus, som kaldes Christus? De sagde alle til ham: lad ham korsfæstes!"],[27,23,"Men Landshøvdingen sagde: hvad Ondt haver han da gjort? Men de raabte end mere: lad ham korsfæstes!","Men Landshøvdingen sagde: hvad Ondt haver han da gjort? Men de raabte end mere: lad ham korsfæstes!"],[27,24,"Men der Pilatus saae, at han udrettede Intet, men at der blev større Bulder, tog han Vand, og toede Hænderne for Folket og sagde: jeg er uskyldig i denne Retfærdiges Blod; seer I dertil.","Men der Pilatus saae, at han udrettede Intet, men at der blev større Bulder, tog han Vand, og toede Hænderne for Folket og sagde: jeg er uskyldig i denne Retfærdiges Blod; seer I dertil."],[27,25,"Og det ganske Folk svarede og sagde: hans Blod komme over os, og over vore Børn!","Og det ganske Folk svarede og sagde: hans Blod komme over os, og over vore Børn!"],[27,26,"Da gav han dem Barrabas løs; men Jesus lod han hudstryge, og overantvordede ham, at han skulde korsfæstes.","Da gav han dem Barrabas løs; men Jesus lod han hudstryge, og overantvordede ham, at han skulde korsfæstes."],[27,27,"Da toge Landshøvdingens Stridsmænd Jesus til sig i Domhuset, og samlede om ham den ganske Rode.","Da toge Landshøvdingens Stridsmænd Jesus til sig i Domhuset, og samlede om ham den ganske Rode."],[27,28,"Og de afklædte ham og kastede en Purpurkaabe om ham.","Og de afklædte ham og kastede en Purpurkaabe om ham."],[27,29,"Og de flettede en Krone af Torne og satte den paa hans Hoved, og et Rør i hans høire Haand; og de faldt paa Knæ for ham, og bespottede ham og sagde: hil være dig, du Jødernes Konge!","Og de flettede en Krone af Torne og satte den paa hans Hoved, og et Rør i hans høire Haand; og de faldt paa Knæ for ham, og bespottede ham og sagde: hil være dig, du Jødernes Konge!"],[27,30,"Og de spyttede paa ham, og toge Røret og sloge paa hans Hoved.","Og de spyttede paa ham, og toge Røret og sloge paa hans Hoved."],[27,31,"Og der de havde bespottet ham, toge de Kaaben af han, og iførte ham hans egne Klæder, og førte ham hen at Korsfæstes.","Og der de havde bespottet ham, toge de Kaaben af han, og iførte ham hans egne Klæder, og førte ham hen at Korsfæstes."],[27,32,"Men idet de gik ud, fandt de et Menneske fra Cyrene ved Navn Simon; ham tvang de til at bære hans Kors.","Men idet de gik ud, fandt de et Menneske fra Cyrene ved Navn Simon; ham tvang de til at bære hans Kors."],[27,33,"Og der de kom til et Sted, kaldet Golgatha, der er udlagt: Hovedpandested,","Og der de kom til et Sted, kaldet Golgatha, der er udlagt: Hovedpandested,"],[27,34,"da gave de ham at drikke Eddike, blandet med Galde; og der han smagte det, vilde han ikke drikke.","da gave de ham at drikke Eddike, blandet med Galde; og der han smagte det, vilde han ikke drikke."],[27,35,"Men de, som havde korsfæstet ham, skiftede hans Klæder og kastede Lod om dem, at det skulde fuldkommes, som er sagt af Propheten: de skiftede mine Klæder og kastede Lod om min Klædebon.","Men de, som havde korsfæstet ham, skiftede hans Klæder og kastede Lod om dem, at det skulde fuldkommes, som er sagt af Propheten: de skiftede mine Klæder og kastede Lod om min Klædebon."],[27,36,"Og de sadde der og toge vare paa ham.","Og de sadde der og toge vare paa ham."],[27,37,"Og oven over hans Hoved satte de Beskyldningen mod ham skreven: denne er Jesus, den Jødernes Konge.","Og oven over hans Hoved satte de Beskyldningen mod ham skreven: denne er Jesus, den Jødernes Konge."],[27,38,"Da korsfæstede de med ham to Røvere, een ved den høire, og een ved den venstre Side.","Da korsfæstede de med ham to Røvere, een ved den høire, og een ved den venstre Side."],[27,39,"Men de, som gik forbi, bespottede ham, og rystede deres Hoveder og sagde:","Men de, som gik forbi, bespottede ham, og rystede deres Hoveder og sagde:"],[27,40,"du, som nedbryder Templet og bygger det i tre Dage, frels dig selv; er du Guds Søn, da stig ned af Korset.","du, som nedbryder Templet og bygger det i tre Dage, frels dig selv; er du Guds Søn, da stig ned af Korset."],[27,41,"Ligesaa bespottede de Ypperstepræster ham, med de Skriftkloge og Ældste, og sagde:","Ligesaa bespottede de Ypperstepræster ham, med de Skriftkloge og Ældste, og sagde:"],[27,42,"han haver frelst Andre, sig selv kan han ikke frelse; er han Israels Konge, da stige han nu ned af Korset, saa ville vi troe ham;","han haver frelst Andre, sig selv kan han ikke frelse; er han Israels Konge, da stige han nu ned af Korset, saa ville vi troe ham;"],[27,43,"han forlod sig paa Gud, han frie ham nu, om han haver Behag i ham; thi han haver sagt: jeg er Guds Søn.","han forlod sig paa Gud, han frie ham nu, om han haver Behag i ham; thi han haver sagt: jeg er Guds Søn."],[27,44,"Men det Samme bebreidede og Røverne ham, som vare korsfæstede med ham.","Men det Samme bebreidede og Røverne ham, som vare korsfæstede med ham."],[27,45,"Men fra den sjette Time blev et Mørke over det ganske Land, indtil de niende Time.","Men fra den sjette Time blev et Mørke over det ganske Land, indtil de niende Time."],[27,46,"Men ved den niende Time raabte Jesus med stor Røst og sagde: Eli! Eli! Lama Sabachtani? det er: min Gud! min Gud! hvorfor haver du forladt mig?","Men ved den niende Time raabte Jesus med stor Røst og sagde: Eli! Eli! Lama Sabachtani? det er: min Gud! min Gud! hvorfor haver du forladt mig?"],[27,47,"Men Nogle af dem, som der stode, da de hørte det, sagde de: han kalder paa Elias.","Men Nogle af dem, som der stode, da de hørte det, sagde de: han kalder paa Elias."],[27,48,"Og strax løb Een af dem og tog en Svamp, og fyldte den med Eddike og stak den paa et Rør, og gav ham at drikke.","Og strax løb Een af dem og tog en Svamp, og fyldte den med Eddike og stak den paa et Rør, og gav ham at drikke."],[27,49,"Men de Andre sagde: holdt! lader os see, om Elias kommer og vil frelse ham.","Men de Andre sagde: holdt! lader os see, om Elias kommer og vil frelse ham."],[27,50,"Men Jesus raabte atter med stor Røst, og udgav Aanden.","Men Jesus raabte atter med stor Røst, og udgav Aanden."],[27,51,"Og see, Forhænget i Templet splittedes i to, fra det Øverste indtil det Nederste, og Jorden skjalv, og Klipperne revnede;","Og see, Forhænget i Templet splittedes i to, fra det Øverste indtil det Nederste, og Jorden skjalv, og Klipperne revnede;"],[27,52,"og Gravene oplodes; og mange af de hensovne Helliges Legemer opstode,","og Gravene oplodes; og mange af de hensovne Helliges Legemer opstode,"],[27,53,"og de gik ud af Gravene efter hans Opstandelse, og kom ind i den hellige Stad, og aabenbaredes for Mange.","og de gik ud af Gravene efter hans Opstandelse, og kom ind i den hellige Stad, og aabenbaredes for Mange."],[27,54,"Men Høvedsmanden og de, som vare med ham og bevogtede Jesus, der de saae det Jordskjælv, og hvad der skete, frygtede de saare og sagde: sandelig, denne var Guds Søn.","Men Høvedsmanden og de, som vare med ham og bevogtede Jesus, der de saae det Jordskjælv, og hvad der skete, frygtede de saare og sagde: sandelig, denne var Guds Søn."],[27,55,"Men der vare mange Kvinder, som langt fra saae det an, hvilke have fulgt Jesus fra Galilæa og tjent ham.","Men der vare mange Kvinder, som langt fra saae det an, hvilke have fulgt Jesus fra Galilæa og tjent ham."],[27,56,"Iblandt disse vare Maria Magdalene, og Maria, Jakobs og Joses’ Moder, og Zebedæus’ Sønners Moder.","Iblandt disse vare Maria Magdalene, og Maria, Jakobs og Joses’ Moder, og Zebedæus’ Sønners Moder."],[27,57,"Men der det var blevet Aften, kom en rig Mand af Arimathæa, ved Navn Joseph, hvilken og selv havde været Jesu Discipel.","Men der det var blevet Aften, kom en rig Mand af Arimathæa, ved Navn Joseph, hvilken og selv havde været Jesu Discipel."],[27,58,"Denne gik til Pilatus, og begjerede Jesu Legeme. Da befoel Pilatus, at man skulde overantvorde ham Legemet.","Denne gik til Pilatus, og begjerede Jesu Legeme. Da befoel Pilatus, at man skulde overantvorde ham Legemet."],[27,59,"Og Joseph tog Legemet og svøbte det i et reent fiint Linklæde,","Og Joseph tog Legemet og svøbte det i et reent fiint Linklæde,"],[27,60,"og lagde det i sin nye Grav, hvilken han havde ladet hugge i en Klippe, og væltede en stor Steen for Indgangen til Graven, og gik bort.","og lagde det i sin nye Grav, hvilken han havde ladet hugge i en Klippe, og væltede en stor Steen for Indgangen til Graven, og gik bort."],[27,61,"Men Maria Magdalene var der og den anden Maria; og de satte sig tvert over for Graven.","Men Maria Magdalene var der og den anden Maria; og de satte sig tvert over for Graven."],[27,62,"Men den anden Dag, som fulgte paa Beredelsens Dag, forsamledes de Ypperstepræster og Pharisæer til Pilatus,","Men den anden Dag, som fulgte paa Beredelsens Dag, forsamledes de Ypperstepræster og Pharisæer til Pilatus,"],[27,63,"og sagde: Herre! vi komme ihu, at denne Forfører sagde, der han endnu levede: efter tre Dage opreises jeg.","og sagde: Herre! vi komme ihu, at denne Forfører sagde, der han endnu levede: efter tre Dage opreises jeg."],[27,64,"Befal derfor, at man med Flid forvarer Graven indtil den tredie Dag, at ikke hans Disciple skulle komme om Natten og stjæle ham, og sige til Folket: han er opreist fra de Døde; og da vil det sidste Bedrag blive værre end det første.","Befal derfor, at man med Flid forvarer Graven indtil den tredie Dag, at ikke hans Disciple skulle komme om Natten og stjæle ham, og sige til Folket: han er opreist fra de Døde; og da vil det sidste Bedrag blive værre end det første."],[27,65,"Men Pilatus sagde til dem: der have I Vagten; gaaer hen, forvarer med Flid, som I bedst vide.","Men Pilatus sagde til dem: der have I Vagten; gaaer hen, forvarer med Flid, som I bedst vide."],[27,66,"Men de gik hen, og forvarede med Flid Graven ved Vagten, der de havde beseglet Stenen.","Men de gik hen, og forvarede med Flid Graven ved Vagten, der de havde beseglet Stenen."],[28,1,"Men efter Sabbaten, da det gryede ad den første Dag i Ugen, kom Maria Magdalene og den anden Marie for at see Graven.","Men efter Sabbaten, da det gryede ad den første Dag i Ugen, kom Maria Magdalene og den anden Marie for at see Graven."],[28,2,"Og see, der skete et stort Jordskjælv; thi Herrens Engel nedfoer af Himmelen, traadte til og væltede Stenen fra Indgangen og satte sig der.","Og see, der skete et stort Jordskjælv; thi Herrens Engel nedfoer af Himmelen, traadte til og væltede Stenen fra Indgangen og satte sig der."],[28,3,"Men hans Skikkelse var ligesom Lynet, og hans Klædebon hvidt som Snee.","Men hans Skikkelse var ligesom Lynet, og hans Klædebon hvidt som Snee."],[28,4,"Men Vægterne skjælvede af Frygt for ham, og bleve som Døde.","Men Vægterne skjælvede af Frygt for ham, og bleve som Døde."],[28,5,"Men Engelen tiltalede Kvinderne og sagde: frygter I ikke! thi jeg veed, at I lede efter Jesus den Korsfæstede.","Men Engelen tiltalede Kvinderne og sagde: frygter I ikke! thi jeg veed, at I lede efter Jesus den Korsfæstede."],[28,6,"Han er ikke her, thi han er opstanden, som han haver sagt. Kommer hid, seer Stedet, hvor Herren laae;","Han er ikke her, thi han er opstanden, som han haver sagt. Kommer hid, seer Stedet, hvor Herren laae;"],[28,7,"og gaaer hastelig hen og siger hans Disciple, at han er opstanden fra de Døde; og see, han gaaer forud for Eder til Galilæa, der skulle I see ham. See, jeg haver sagt Eder det.","og gaaer hastelig hen og siger hans Disciple, at han er opstanden fra de Døde; og see, han gaaer forud for Eder til Galilæa, der skulle I see ham. See, jeg haver sagt Eder det."],[28,8,"Og de gik hastelig ud af Graven med Frygt og stor Glæde, og løb at bebude hans Disciple det.","Og de gik hastelig ud af Graven med Frygt og stor Glæde, og løb at bebude hans Disciple det."],[28,9,"Men der de gik at bebude hans Disciple det, see, da mødte Jesus dem og sagde: hil være Eder! Men de traadte til, og omfavnede hans Fødder, og tilbade ham.","Men der de gik at bebude hans Disciple det, see, da mødte Jesus dem og sagde: hil være Eder! Men de traadte til, og omfavnede hans Fødder, og tilbade ham."],[28,10,"Da sagde Jesus til dem: frygter ikke! gaaer hen, forkynder mine Brødre, at de drage til Galilæa, og der skulle de see mig.","Da sagde Jesus til dem: frygter ikke! gaaer hen, forkynder mine Brødre, at de drage til Galilæa, og der skulle de see mig."],[28,11,"Men der de gik hen, see, da kom Nogle af Vagten i Staden, og forkyndte de Ypperstepræster alt det, som var skeet.","Men der de gik hen, see, da kom Nogle af Vagten i Staden, og forkyndte de Ypperstepræster alt det, som var skeet."],[28,12,"Og de forsamledes med de Ældste, og holdt et Raad, og gave Stridsmændene rigeligen Penge,","Og de forsamledes med de Ældste, og holdt et Raad, og gave Stridsmændene rigeligen Penge,"],[28,13,"og sagde: siger, hans Disciple kom om Natten og stjal ham, da vi sov.","og sagde: siger, hans Disciple kom om Natten og stjal ham, da vi sov."],[28,14,"Og dersom Landshøvdingen faaer det at høre, ville vi stille ham tilfreds og holde Eder angerløse.","Og dersom Landshøvdingen faaer det at høre, ville vi stille ham tilfreds og holde Eder angerløse."],[28,15,"Men de toge Pengene, og gjorde, som de vare underviste. Og Rygtet om denne Sag blev udspredt iblandt Jøderne indtil denne Dag.","Men de toge Pengene, og gjorde, som de vare underviste. Og Rygtet om denne Sag blev udspredt iblandt Jøderne indtil denne Dag."],[28,16,"Men de elleve Disciple gik til Galilæa, til det Bjerg, hvor Jesus havde bestilt dem.","Men de elleve Disciple gik til Galilæa, til det Bjerg, hvor Jesus havde bestilt dem."],[28,17,"Og der de saae ham, tilbade de ham; men Nogle tvivlede.","Og der de saae ham, tilbade de ham; men Nogle tvivlede."],[28,18,"Og Jesus traadte frem, talede med dem og sagde: Mig er given al Magt i Himmelen og paa Jorden.","Og Jesus traadte frem, talede med dem og sagde: Mig er given al Magt i Himmelen og paa Jorden."],[28,19,"Gaaer derfor hen, og lærer alle Folk, og døber dem i Navnet Faderens og Sønnens og den Hellig Aands;","Gaaer derfor hen, og lærer alle Folk, og døber dem i Navnet Faderens og Sønnens og den Hellig Aands;"],[28,20,"og lærer dem at holde alt det, jeg haver befalet Eder. Og see, jeg er med Eder alle Dage, indtil Verdens Ende. Amen.","og lærer dem at holde alt det, jeg haver befalet Eder. Og see, jeg er med Eder alle Dage, indtil Verdens Ende. Amen."]],"epo-londona":[[1,1,"La genealogia registro de Jesuo Kristo, filo de David, filo de Abraham.","La genealogia registro de Jesuo Kristo, filo de David, filo de Abraham."],[1,2,"Al Abraham naskiĝis Isaak, kaj al Isaak naskiĝis Jakob, kaj al Jakob naskiĝis Jehuda kaj liaj fratoj,","Al Abraham naskiĝis Isaak, kaj al Isaak naskiĝis Jakob, kaj al Jakob naskiĝis Jehuda kaj liaj fratoj,"],[1,3,"kaj al Jehuda naskiĝis Perec kaj Zeraĥ el Tamar, kaj al Perec naskiĝis Ĥecron, kaj al Ĥecron naskiĝis Ram,","kaj al Jehuda naskiĝis Perec kaj Zeraĥ el Tamar, kaj al Perec naskiĝis Ĥecron, kaj al Ĥecron naskiĝis Ram,"],[1,4,"kaj al Ram naskiĝis Aminadab, kaj al Aminadab naskiĝis Naĥŝon, kaj al Naĥŝon naskiĝis Salma,","kaj al Ram naskiĝis Aminadab, kaj al Aminadab naskiĝis Naĥŝon, kaj al Naĥŝon naskiĝis Salma,"],[1,5,"kaj al Salma naskiĝis Boaz el Raĥab, kaj al Boaz naskiĝis Obed el Rut, kaj al Obed naskiĝis Jiŝaj,","kaj al Salma naskiĝis Boaz el Raĥab, kaj al Boaz naskiĝis Obed el Rut, kaj al Obed naskiĝis Jiŝaj,"],[1,6,"kaj al Jiŝaj naskiĝis David, la reĝo. Kaj al David naskiĝis Salomono el la edzino de Urija,","kaj al Jiŝaj naskiĝis David, la reĝo. Kaj al David naskiĝis Salomono el la edzino de Urija,"],[1,7,"kaj al Salomono naskiĝis Reĥabeam, kaj al Reĥabeam naskiĝis Abija, kaj al Abija naskiĝis Asa,","kaj al Salomono naskiĝis Reĥabeam, kaj al Reĥabeam naskiĝis Abija, kaj al Abija naskiĝis Asa,"],[1,8,"kaj al Asa naskiĝis Jehoŝafat, kaj al Jehoŝafat naskiĝis Joram, kaj al Joram naskiĝis Uzija,","kaj al Asa naskiĝis Jehoŝafat, kaj al Jehoŝafat naskiĝis Joram, kaj al Joram naskiĝis Uzija,"],[1,9,"kaj al Uzija naskiĝis Jotam, kaj al Jotam naskiĝis Aĥaz, kaj al Aĥaz naskiĝis Ĥizkija,","kaj al Uzija naskiĝis Jotam, kaj al Jotam naskiĝis Aĥaz, kaj al Aĥaz naskiĝis Ĥizkija,"],[1,10,"kaj al Ĥizkija naskiĝis Manase, kaj al Manase naskiĝis Amon, kaj al Amon naskiĝis Joŝija,","kaj al Ĥizkija naskiĝis Manase, kaj al Manase naskiĝis Amon, kaj al Amon naskiĝis Joŝija,"],[1,11,"kaj al Joŝija naskiĝis Jeĥonja kaj liaj fratoj, je la tempo de la transloĝiĝo en Babelon.","kaj al Joŝija naskiĝis Jeĥonja kaj liaj fratoj, je la tempo de la transloĝiĝo en Babelon."],[1,12,"Kaj post la transloĝiĝo en Babelon, al Jeĥonja naskiĝis Ŝealtiel, kaj al Ŝealtiel naskiĝis Zerubabel,","Kaj post la transloĝiĝo en Babelon, al Jeĥonja naskiĝis Ŝealtiel, kaj al Ŝealtiel naskiĝis Zerubabel,"],[1,13,"kaj al Zerubabel naskiĝis Abiud, kaj al Abiud naskiĝis Eljakim, kaj al Eljakim naskiĝis Azor,","kaj al Zerubabel naskiĝis Abiud, kaj al Abiud naskiĝis Eljakim, kaj al Eljakim naskiĝis Azor,"],[1,14,"kaj al Azor naskiĝis Cadok, kaj al Cadok naskiĝis Aĥim, kaj al Aĥim naskiĝis Eliud,","kaj al Azor naskiĝis Cadok, kaj al Cadok naskiĝis Aĥim, kaj al Aĥim naskiĝis Eliud,"],[1,15,"kaj al Eliud naskiĝis Eleazar, kaj al Eleazar naskiĝis Mattan, kaj al Mattan naskiĝis Jakob,","kaj al Eliud naskiĝis Eleazar, kaj al Eleazar naskiĝis Mattan, kaj al Mattan naskiĝis Jakob,"],[1,16,"kaj al Jakob naskiĝis Jozef, edzo de Maria, el kiu estis naskita Jesuo, kiu estas nomata Kristo.","kaj al Jakob naskiĝis Jozef, edzo de Maria, el kiu estis naskita Jesuo, kiu estas nomata Kristo."],[1,17,"Tial ĉiuj generacioj de Abraham ĝis David estas dek kvar generacioj, kaj de David ĝis la transloĝiĝo en Babelon dek kvar generacioj, kaj de la transloĝiĝo en Babelon ĝis la Kristo dek kvar generacioj.","Tial ĉiuj generacioj de Abraham ĝis David estas dek kvar generacioj, kaj de David ĝis la transloĝiĝo en Babelon dek kvar generacioj, kaj de la transloĝiĝo en Babelon ĝis la Kristo dek kvar generacioj."],[1,18,"Kaj la naskiĝo de Jesuo Kristo estis tiamaniere: kiam lia patrino Maria estis fianĉinigita al Jozef, antaŭ ol ili kunvenis, ŝi troviĝis graveda per la Sankta Spirito.","Kaj la naskiĝo de Jesuo Kristo estis tiamaniere: kiam lia patrino Maria estis fianĉinigita al Jozef, antaŭ ol ili kunvenis, ŝi troviĝis graveda per la Sankta Spirito."],[1,19,"Kaj ŝia edzo Jozef, estante justulo, kaj ne volante meti ŝin al publika malhonoro, volis ŝin sekrete forsendi.","Kaj ŝia edzo Jozef, estante justulo, kaj ne volante meti ŝin al publika malhonoro, volis ŝin sekrete forsendi."],[1,20,"Sed kiam li pripensis tion, jen anĝelo de la Eternulo aperis al li en sonĝo, dirante: Jozef, filo de David, ne timu preni al vi vian edzinon Maria; ĉar tio, kio naskiĝos de ŝi, estas per la Sankta Spirito.","Sed kiam li pripensis tion, jen anĝelo de la Eternulo aperis al li en sonĝo, dirante: Jozef, filo de David, ne timu preni al vi vian edzinon Maria; ĉar tio, kio naskiĝos de ŝi, estas per la Sankta Spirito."],[1,21,"Kaj ŝi naskos filon; kaj vi nomos lin JESUO; ĉar li savos sian popolon de ĝiaj pekoj.","Kaj ŝi naskos filon; kaj vi nomos lin JESUO; ĉar li savos sian popolon de ĝiaj pekoj."],[1,22,"Kaj ĉio tio okazis, por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante:","Kaj ĉio tio okazis, por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante:"],[1,23,"Jen virgulino gravediĝos kaj naskos filon, Kaj oni donos al li la nomon Emanuel; tio estas, Dio kun ni.","Jen virgulino gravediĝos kaj naskos filon, Kaj oni donos al li la nomon Emanuel; tio estas, Dio kun ni."],[1,24,"Kaj Jozef, leviĝinte el sia dormo, faris, kiel ordonis al li la anĝelo de la Eternulo, kaj prenis al si sian edzinon;","Kaj Jozef, leviĝinte el sia dormo, faris, kiel ordonis al li la anĝelo de la Eternulo, kaj prenis al si sian edzinon;"],[1,25,"kaj li ne ekkonis ŝin, ĝis ŝi naskis filon; kaj li donis al li la nomon JESUO.","kaj li ne ekkonis ŝin, ĝis ŝi naskis filon; kaj li donis al li la nomon JESUO."],[2,1,"Kaj kiam Jesuo estis naskita en Bet-Leĥem de Judujo en la tempo de la reĝo Herodo, jen saĝuloj el la oriento venis al Jerusalem, dirante:","Kaj kiam Jesuo estis naskita en Bet-Leĥem de Judujo en la tempo de la reĝo Herodo, jen saĝuloj el la oriento venis al Jerusalem, dirante:"],[2,2,"Kie estas tiu, kiu estas naskita Reĝo de la Judoj? ĉar ni vidis lian stelon en la oriento, kaj venis, por adorkliniĝi al li.","Kie estas tiu, kiu estas naskita Reĝo de la Judoj? ĉar ni vidis lian stelon en la oriento, kaj venis, por adorkliniĝi al li."],[2,3,"Kaj kiam la reĝo Herodo tion aŭdis, li maltrankviliĝis, kaj la tuta Jerusalem kun li.","Kaj kiam la reĝo Herodo tion aŭdis, li maltrankviliĝis, kaj la tuta Jerusalem kun li."],[2,4,"Kaj kunveniginte ĉiujn ĉefpastrojn kaj skribistojn de la popolo, li demandis al ili, kie la Kristo devas naskiĝi.","Kaj kunveniginte ĉiujn ĉefpastrojn kaj skribistojn de la popolo, li demandis al ili, kie la Kristo devas naskiĝi."],[2,5,"Kaj ili diris al li: En Bet-Leĥem de Judujo, ĉar per la profeto estas skribite jene:","Kaj ili diris al li: En Bet-Leĥem de Judujo, ĉar per la profeto estas skribite jene:"],[2,6,"Kaj vi, ho Bet-Leĥem, lando de Judujo, Neniel estas plej malgranda inter la regantoj de Judujo; Ĉar el vi venos reganto, Kiu paŝtos Mian popolon Izrael.","Kaj vi, ho Bet-Leĥem, lando de Judujo, Neniel estas plej malgranda inter la regantoj de Judujo; Ĉar el vi venos reganto, Kiu paŝtos Mian popolon Izrael."],[2,7,"Tiam Herodo sekrete venigis la saĝulojn, kaj precize sciiĝis de ili pri la tempo, kiam aperis la stelo.","Tiam Herodo sekrete venigis la saĝulojn, kaj precize sciiĝis de ili pri la tempo, kiam aperis la stelo."],[2,8,"Kaj li sendis ilin al Bet-Leĥem, dirante: Iru kaj elserĉu zorge pri la knabeto; kaj kiam vi lin trovos, sciigu al mi, por ke mi ankaŭ venu kaj adorkliniĝu al li.","Kaj li sendis ilin al Bet-Leĥem, dirante: Iru kaj elserĉu zorge pri la knabeto; kaj kiam vi lin trovos, sciigu al mi, por ke mi ankaŭ venu kaj adorkliniĝu al li."],[2,9,"Kaj aŭdinte la reĝon, ili ekvojiris; kaj jen la stelo, kiun ili vidis en la oriento, antaŭiris ilin, ĝis ĝi venis kaj staris super la loko, kie estis la juna knabeto.","Kaj aŭdinte la reĝon, ili ekvojiris; kaj jen la stelo, kiun ili vidis en la oriento, antaŭiris ilin, ĝis ĝi venis kaj staris super la loko, kie estis la juna knabeto."],[2,10,"Kaj vidante la stelon, ili ĝojis kun tre granda ĝojo.","Kaj vidante la stelon, ili ĝojis kun tre granda ĝojo."],[2,11,"Kaj veninte en la domon, ili vidis la knabeton kun lia patrino Maria, kaj adorkliniĝis al li; kaj malferminte siajn trezorojn, ili faligis sin kaj prezentis al li donacojn: oron kaj olibanon kaj mirhon.","Kaj veninte en la domon, ili vidis la knabeton kun lia patrino Maria, kaj adorkliniĝis al li; kaj malferminte siajn trezorojn, ili faligis sin kaj prezentis al li donacojn: oron kaj olibanon kaj mirhon."],[2,12,"Kaj avertite de Dio en sonĝo, ke ili ne iru returne al Herodo, ili foriris per alia vojo al sia lando.","Kaj avertite de Dio en sonĝo, ke ili ne iru returne al Herodo, ili foriris per alia vojo al sia lando."],[2,13,"Kaj post ilia foriro jen anĝelo de la Eternulo aperis en sonĝo al Jozef, dirante: Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj forrapidu en Egiptujon, kaj restu tie, ĝis mi parolos al vi; ĉar Herodo serĉos la knabeton, por lin pereigi.","Kaj post ilia foriro jen anĝelo de la Eternulo aperis en sonĝo al Jozef, dirante: Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj forrapidu en Egiptujon, kaj restu tie, ĝis mi parolos al vi; ĉar Herodo serĉos la knabeton, por lin pereigi."],[2,14,"Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon nokte, kaj migris en Egiptujon,","Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon nokte, kaj migris en Egiptujon,"],[2,15,"kaj restis tie ĝis la morto de Herodo; por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante: El Egiptujo Mi vokis Mian filon.","kaj restis tie ĝis la morto de Herodo; por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante: El Egiptujo Mi vokis Mian filon."],[2,16,"Tiam Herodo, ekvidinte, ke li estas trompita de la saĝuloj, tre koleris; kaj sendinte, li mortigis ĉiujn knabojn en Bet-Leĥem kaj en ĉiuj ĝiaj ĉirkaŭaĵoj, havantajn du jarojn aŭ malpli, laŭ la tempo, pri kiu li precize sciiĝis de la saĝuloj.","Tiam Herodo, ekvidinte, ke li estas trompita de la saĝuloj, tre koleris; kaj sendinte, li mortigis ĉiujn knabojn en Bet-Leĥem kaj en ĉiuj ĝiaj ĉirkaŭaĵoj, havantajn du jarojn aŭ malpli, laŭ la tempo, pri kiu li precize sciiĝis de la saĝuloj."],[2,17,"Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome:","Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome:"],[2,18,"Voĉo estas aŭdita en Rama, Ĝemado kaj maldolĉa plorado, Raĥel priploras siajn infanojn, Kaj ŝi ne volas konsoliĝi, ĉar ili forestas.","Voĉo estas aŭdita en Rama, Ĝemado kaj maldolĉa plorado, Raĥel priploras siajn infanojn, Kaj ŝi ne volas konsoliĝi, ĉar ili forestas."],[2,19,"Sed kiam Herodo mortis, jen anĝelo de la Eternulo aperis en sonĝo al Jozef en Egiptujo, dirante:","Sed kiam Herodo mortis, jen anĝelo de la Eternulo aperis en sonĝo al Jozef en Egiptujo, dirante:"],[2,20,"Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj iru en la landon de Izrael; ĉar mortis tiuj, kiuj atencis la vivon de la knabeto.","Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj iru en la landon de Izrael; ĉar mortis tiuj, kiuj atencis la vivon de la knabeto."],[2,21,"Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon, kaj venis en la landon de Izrael.","Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon, kaj venis en la landon de Izrael."],[2,22,"Sed kiam li aŭdis, ke Arĥelao reĝas en Judujo anstataŭ sia patro Herodo, li timis iri tien; kaj avertite de Dio en sonĝo, li fortiris sin en la regionojn de Galileo,","Sed kiam li aŭdis, ke Arĥelao reĝas en Judujo anstataŭ sia patro Herodo, li timis iri tien; kaj avertite de Dio en sonĝo, li fortiris sin en la regionojn de Galileo,"],[2,23,"kaj venis al kaj loĝis en urbo nomata Nazaret, por ke plenumiĝu tio, kio estis dirita per la profetoj, ke li estos nomata Nazaretano.","kaj venis al kaj loĝis en urbo nomata Nazaret, por ke plenumiĝu tio, kio estis dirita per la profetoj, ke li estos nomata Nazaretano."],[3,1,"En tiuj tagoj venis Johano, la Baptisto, predikante en la dezerto de Judujo,","En tiuj tagoj venis Johano, la Baptisto, predikante en la dezerto de Judujo,"],[3,2,"kaj dirante: Pentu, ĉar alproksimiĝis la regno de la ĉielo.","kaj dirante: Pentu, ĉar alproksimiĝis la regno de la ĉielo."],[3,3,"Ĉar li estas tiu, pri kiu estis dirite per la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn.","Ĉar li estas tiu, pri kiu estis dirite per la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn."],[3,4,"Kaj tiu Johano havis sian vestaĵon el kamelaj haroj, kaj ledan zonon ĉirkaŭ siaj lumboj, kaj lia nutraĵo estis akridoj kaj sovaĝa mielo.","Kaj tiu Johano havis sian vestaĵon el kamelaj haroj, kaj ledan zonon ĉirkaŭ siaj lumboj, kaj lia nutraĵo estis akridoj kaj sovaĝa mielo."],[3,5,"Tiam eliris al li Jerusalem kaj la tuta Judujo kaj la tuta ĉirkaŭaĵo de Jordan;","Tiam eliris al li Jerusalem kaj la tuta Judujo kaj la tuta ĉirkaŭaĵo de Jordan;"],[3,6,"kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn.","kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn."],[3,7,"Kaj vidante multajn el la Fariseoj kaj Sadukeoj venantajn al lia baptado, li diris al ili: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?","Kaj vidante multajn el la Fariseoj kaj Sadukeoj venantajn al lia baptado, li diris al ili: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?"],[3,8,"Donu do fruktojn taŭgajn por pento;","Donu do fruktojn taŭgajn por pento;"],[3,9,"kaj ne pensu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham.","kaj ne pensu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham."],[3,10,"Kaj jam la hakilo kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron.","Kaj jam la hakilo kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron."],[3,11,"Mi ja vin baptas per akvo por pento; sed tiu, kiu venas post mi, estas pli potenca ol mi; liajn ŝuojn mi ne estas inda porti; li vin baptos per la Sankta Spirito kaj per fajro;","Mi ja vin baptas per akvo por pento; sed tiu, kiu venas post mi, estas pli potenca ol mi; liajn ŝuojn mi ne estas inda porti; li vin baptos per la Sankta Spirito kaj per fajro;"],[3,12,"lia ventumilo estas en lia mano, kaj li elpurigos sian draŝejon, kaj li kolektos sian tritikon en la grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla.","lia ventumilo estas en lia mano, kaj li elpurigos sian draŝejon, kaj li kolektos sian tritikon en la grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla."],[3,13,"Tiam venis Jesuo el Galileo al Jordan al Johano, por esti baptata de li.","Tiam venis Jesuo el Galileo al Jordan al Johano, por esti baptata de li."],[3,14,"Sed tiu lin malakceptis, dirante: Mi bezonas esti baptata de vi, kaj ĉu vi venas al mi?","Sed tiu lin malakceptis, dirante: Mi bezonas esti baptata de vi, kaj ĉu vi venas al mi?"],[3,15,"Sed Jesuo responde diris al li: Lasu do, ĉar tiel decas al ni plenumi ĉian justecon. Tiam li lasis lin.","Sed Jesuo responde diris al li: Lasu do, ĉar tiel decas al ni plenumi ĉian justecon. Tiam li lasis lin."],[3,16,"Kaj Jesuo, baptite, supreniris tuj el la akvo; kaj jen la ĉielo malfermiĝis, kaj li vidis la Spiriton de Dio malsuprenirantan kiel kolombo, kaj venantan sur lin;","Kaj Jesuo, baptite, supreniris tuj el la akvo; kaj jen la ĉielo malfermiĝis, kaj li vidis la Spiriton de Dio malsuprenirantan kiel kolombo, kaj venantan sur lin;"],[3,17,"kaj jen voĉo el la ĉielo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron.","kaj jen voĉo el la ĉielo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron."],[4,1,"Tiam Jesuo estis kondukita supren de la Spirito en la dezerton, por esti tentata de la diablo.","Tiam Jesuo estis kondukita supren de la Spirito en la dezerton, por esti tentata de la diablo."],[4,2,"Kaj fastinte kvardek tagojn kaj kvardek noktojn, li poste malsatis.","Kaj fastinte kvardek tagojn kaj kvardek noktojn, li poste malsatis."],[4,3,"Kaj la tentanto venis, kaj diris al li: Se vi estas Filo de Dio, ordonu, ke tiuj ŝtonoj fariĝu panoj.","Kaj la tentanto venis, kaj diris al li: Se vi estas Filo de Dio, ordonu, ke tiuj ŝtonoj fariĝu panoj."],[4,4,"Sed responde li diris: Estas skribite: Ne per la pano sole vivas homo, sed per ĉiu vorto, kiu eliras el la buŝo de Dio.","Sed responde li diris: Estas skribite: Ne per la pano sole vivas homo, sed per ĉiu vorto, kiu eliras el la buŝo de Dio."],[4,5,"Poste la diablo portis lin en la sanktan urbon, kaj starigis lin sur la tegmenta pinto de la templo,","Poste la diablo portis lin en la sanktan urbon, kaj starigis lin sur la tegmenta pinto de la templo,"],[4,6,"kaj diris al li: Se vi estas Filo de Dio, ĵetu vin malsupren, ĉar estas skribite: Al Siaj anĝeloj Li ordonos pri vi, Kaj sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo.","kaj diris al li: Se vi estas Filo de Dio, ĵetu vin malsupren, ĉar estas skribite: Al Siaj anĝeloj Li ordonos pri vi, Kaj sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo."],[4,7,"Jesuo diris al li: Ankaŭ estas skribite: Ne provu la Eternulon, vian Dion.","Jesuo diris al li: Ankaŭ estas skribite: Ne provu la Eternulon, vian Dion."],[4,8,"Denove la diablo portis lin al monto tre alta, kaj montris al li ĉiujn regnojn de la mondo kaj ilian gloron,","Denove la diablo portis lin al monto tre alta, kaj montris al li ĉiujn regnojn de la mondo kaj ilian gloron,"],[4,9,"kaj diris al li: Ĉion tion mi donos al vi, se vi faligos vin kaj adorkliniĝos al mi.","kaj diris al li: Ĉion tion mi donos al vi, se vi faligos vin kaj adorkliniĝos al mi."],[4,10,"Tiam Jesuo diris al li: Foriru, Satano! ĉar estas skribite: Al la Eternulo, via Dio, vi adorkliniĝu, kaj al Li sola vi servu.","Tiam Jesuo diris al li: Foriru, Satano! ĉar estas skribite: Al la Eternulo, via Dio, vi adorkliniĝu, kaj al Li sola vi servu."],[4,11,"Tiam la diablo forlasis lin, kaj jen anĝeloj venis kaj servadis al li.","Tiam la diablo forlasis lin, kaj jen anĝeloj venis kaj servadis al li."],[4,12,"Kaj aŭdinte, ke Johano estas arestita, li foriris en Galileon;","Kaj aŭdinte, ke Johano estas arestita, li foriris en Galileon;"],[4,13,"kaj lasinte Nazareton, li venis al kaj loĝis en Kapernaum apudmara, en la limoj de Zebulun kaj Naftali;","kaj lasinte Nazareton, li venis al kaj loĝis en Kapernaum apudmara, en la limoj de Zebulun kaj Naftali;"],[4,14,"por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:","por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:"],[4,15,"Lando de Zebulun kaj lando de Naftali, Laŭvoje de la maro, transe de Jordan, Galileo de la nacioj,","Lando de Zebulun kaj lando de Naftali, Laŭvoje de la maro, transe de Jordan, Galileo de la nacioj,"],[4,16,"La popolo, sidanta en mallumo, Ekvidis grandan lumon, Kaj al homoj, sidantaj en lando de ombra morto, ekbrilis lumo.","La popolo, sidanta en mallumo, Ekvidis grandan lumon, Kaj al homoj, sidantaj en lando de ombra morto, ekbrilis lumo."],[4,17,"De tiam Jesuo komencis prediki, kaj diri: Pentu, ĉar la regno de la ĉielo alproksimiĝis.","De tiam Jesuo komencis prediki, kaj diri: Pentu, ĉar la regno de la ĉielo alproksimiĝis."],[4,18,"Kaj piedirante apud la maro de Galileo, li vidis du fratojn, Simonon, kiu estis nomata Petro, kaj Andreon, lian fraton, ĵetantajn reton en la maron, ĉar ili estis fiŝkaptistoj.","Kaj piedirante apud la maro de Galileo, li vidis du fratojn, Simonon, kiu estis nomata Petro, kaj Andreon, lian fraton, ĵetantajn reton en la maron, ĉar ili estis fiŝkaptistoj."],[4,19,"Kaj li diris al ili: Venu post mi, kaj mi faros vin kaptistoj de homoj.","Kaj li diris al ili: Venu post mi, kaj mi faros vin kaptistoj de homoj."],[4,20,"Kaj ili tuj forlasis la retojn, kaj sekvis lin.","Kaj ili tuj forlasis la retojn, kaj sekvis lin."],[4,21,"Kaj antaŭenirinte de tie, li vidis aliajn du fratojn, Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, en la ŝipeto kun ilia patro Zebedeo, riparantajn siajn retojn; kaj li vokis ilin.","Kaj antaŭenirinte de tie, li vidis aliajn du fratojn, Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, en la ŝipeto kun ilia patro Zebedeo, riparantajn siajn retojn; kaj li vokis ilin."],[4,22,"Kaj ili tuj forlasis la ŝipeton kaj sian patron, kaj sekvis lin.","Kaj ili tuj forlasis la ŝipeton kaj sian patron, kaj sekvis lin."],[4,23,"Kaj Jesuo trairis tra la tuta Galileo, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj kuracante ĉian malsanon kaj ĉian malfortaĵon inter la popolo.","Kaj Jesuo trairis tra la tuta Galileo, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj kuracante ĉian malsanon kaj ĉian malfortaĵon inter la popolo."],[4,24,"Kaj lia famo disvastiĝis en la tuta Sirio; kaj oni alkondukis al li ĉiujn malsanulojn, malfortigitajn de diversaj malsanoj kaj turmentoj, demonhavantojn, epilepsiulojn, kaj paralizulojn, kaj li resanigis ilin.","Kaj lia famo disvastiĝis en la tuta Sirio; kaj oni alkondukis al li ĉiujn malsanulojn, malfortigitajn de diversaj malsanoj kaj turmentoj, demonhavantojn, epilepsiulojn, kaj paralizulojn, kaj li resanigis ilin."],[4,25,"Kaj grandaj homamasoj lin sekvis el Galileo kaj Dekapolis kaj Jerusalem kaj Judujo kaj el trans Jordan.","Kaj grandaj homamasoj lin sekvis el Galileo kaj Dekapolis kaj Jerusalem kaj Judujo kaj el trans Jordan."],[5,1,"Kaj vidinte la homamasojn, li supreniris sur la monton, kaj kiam li sidiĝis, liaj disĉiploj venis al li;","Kaj vidinte la homamasojn, li supreniris sur la monton, kaj kiam li sidiĝis, liaj disĉiploj venis al li;"],[5,2,"kaj malferminte la buŝon, li instruis ilin, dirante:","kaj malferminte la buŝon, li instruis ilin, dirante:"],[5,3,"Feliĉaj estas la malriĉaj en spirito, ĉar ilia estas la regno de la ĉielo.","Feliĉaj estas la malriĉaj en spirito, ĉar ilia estas la regno de la ĉielo."],[5,4,"Feliĉaj estas la plorantaj, ĉar ili konsoliĝos.","Feliĉaj estas la plorantaj, ĉar ili konsoliĝos."],[5,5,"Feliĉaj estas la humilaj, ĉar ili heredos la teron.","Feliĉaj estas la humilaj, ĉar ili heredos la teron."],[5,6,"Feliĉaj estas tiuj, kiuj malsatas kaj soifas justecon, ĉar ili satiĝos.","Feliĉaj estas tiuj, kiuj malsatas kaj soifas justecon, ĉar ili satiĝos."],[5,7,"Feliĉaj estas la kompatemaj, ĉar ili ricevos kompaton.","Feliĉaj estas la kompatemaj, ĉar ili ricevos kompaton."],[5,8,"Feliĉaj estas la kore puraj, ĉar ili vidos Dion.","Feliĉaj estas la kore puraj, ĉar ili vidos Dion."],[5,9,"Feliĉaj estas la pacigantoj, ĉar filoj de Dio ili estos nomataj.","Feliĉaj estas la pacigantoj, ĉar filoj de Dio ili estos nomataj."],[5,10,"Feliĉaj estas tiuj, kiuj estas persekutitaj pro justeco, ĉar ilia estas la regno de la ĉielo.","Feliĉaj estas tiuj, kiuj estas persekutitaj pro justeco, ĉar ilia estas la regno de la ĉielo."],[5,11,"Feliĉaj estas vi, kiam oni vin riproĉos kaj persekutos kaj false vin kalumnios pro mi.","Feliĉaj estas vi, kiam oni vin riproĉos kaj persekutos kaj false vin kalumnios pro mi."],[5,12,"Ĝoju kaj raviĝu, ĉar via rekompenco estos granda en la ĉielo; ĉar tiel oni persekutis la profetojn, kiuj estis antaŭ vi.","Ĝoju kaj raviĝu, ĉar via rekompenco estos granda en la ĉielo; ĉar tiel oni persekutis la profetojn, kiuj estis antaŭ vi."],[5,13,"Vi estas la salo de la tero; sed se la salo sengustiĝis, per kio ĝi estos salita? ĝi jam taŭgas por nenio, krom por esti elĵetita kaj piedpremita de homoj.","Vi estas la salo de la tero; sed se la salo sengustiĝis, per kio ĝi estos salita? ĝi jam taŭgas por nenio, krom por esti elĵetita kaj piedpremita de homoj."],[5,14,"Vi estas la lumo de la mondo. Urbo starigita sur monto ne povas esti kaŝita.","Vi estas la lumo de la mondo. Urbo starigita sur monto ne povas esti kaŝita."],[5,15,"Kiam oni bruligas lampon, oni metas ĝin ne sub grenmezurilon, sed sur la lampingon; kaj ĝi lumas sur ĉiujn, kiuj estas en la domo.","Kiam oni bruligas lampon, oni metas ĝin ne sub grenmezurilon, sed sur la lampingon; kaj ĝi lumas sur ĉiujn, kiuj estas en la domo."],[5,16,"Tiel same via lumo lumu antaŭ homoj, por ke ili vidu viajn bonajn farojn, kaj gloru vian Patron, kiu estas en la ĉielo.","Tiel same via lumo lumu antaŭ homoj, por ke ili vidu viajn bonajn farojn, kaj gloru vian Patron, kiu estas en la ĉielo."],[5,17,"Ne pensu, ke mi venis, por detrui la leĝon aŭ la profetojn; mi venis, ne por detrui, sed por plenumi.","Ne pensu, ke mi venis, por detrui la leĝon aŭ la profetojn; mi venis, ne por detrui, sed por plenumi."],[5,18,"Vere mi diras al vi: Ĝis la ĉielo kaj la tero forpasos, nek unu joto nek unu streketo forpasos de la leĝo, ĝis ĉio plenumiĝos.","Vere mi diras al vi: Ĝis la ĉielo kaj la tero forpasos, nek unu joto nek unu streketo forpasos de la leĝo, ĝis ĉio plenumiĝos."],[5,19,"Tial, kiu malobservos unu el ĉi tiuj plej malgrandaj ordonoj kaj tiel instruos homojn, tiu estos nomata la plej malgranda en la regno de la ĉielo; sed kiu faros ilin kaj instruos, tiu estos nomata granda en la regno de la ĉielo.","Tial, kiu malobservos unu el ĉi tiuj plej malgrandaj ordonoj kaj tiel instruos homojn, tiu estos nomata la plej malgranda en la regno de la ĉielo; sed kiu faros ilin kaj instruos, tiu estos nomata granda en la regno de la ĉielo."],[5,20,"Ĉar mi diras al vi, ke se via justeco ne superos la justecon de la skribistoj kaj la Fariseoj, vi tute ne eniros en la regnon de la ĉielo.","Ĉar mi diras al vi, ke se via justeco ne superos la justecon de la skribistoj kaj la Fariseoj, vi tute ne eniros en la regnon de la ĉielo."],[5,21,"Vi aŭdis, ke estas dirite al la antikvuloj: Ne mortigu, kaj kiu mortigos, tiu estos en danĝero de juĝado;","Vi aŭdis, ke estas dirite al la antikvuloj: Ne mortigu, kaj kiu mortigos, tiu estos en danĝero de juĝado;"],[5,22,"sed mi diras al vi, ke kiu koleras kontraŭ sia frato, tiu estos en danĝero de juĝado; kaj kiu diros al sia frato: Raka, tiu estos en danĝero de la sinedrio; kaj kiu diros: Malsaĝulo, tiu estos en danĝero de Gehena de fajro.","sed mi diras al vi, ke kiu koleras kontraŭ sia frato, tiu estos en danĝero de juĝado; kaj kiu diros al sia frato: Raka, tiu estos en danĝero de la sinedrio; kaj kiu diros: Malsaĝulo, tiu estos en danĝero de Gehena de fajro."],[5,23,"Tial, se vi prezentas vian oferon ĉe la altaro, kaj tie memoras, ke via frato havas ion kontraŭ vi,","Tial, se vi prezentas vian oferon ĉe la altaro, kaj tie memoras, ke via frato havas ion kontraŭ vi,"],[5,24,"lasu tie vian oferon antaŭ la altaro, kaj foriru, unue paciĝu kun via frato, kaj poste venu kaj prezentu vian oferon.","lasu tie vian oferon antaŭ la altaro, kaj foriru, unue paciĝu kun via frato, kaj poste venu kaj prezentu vian oferon."],[5,25,"Konsentu rapide kun via kontraŭulo, dum vi estas kun li sur la vojo, por ke la kontraŭulo ne transdonu vin al la juĝisto, kaj la juĝisto al la subulo, kaj por ke vi ne estu ĵetita en malliberejon.","Konsentu rapide kun via kontraŭulo, dum vi estas kun li sur la vojo, por ke la kontraŭulo ne transdonu vin al la juĝisto, kaj la juĝisto al la subulo, kaj por ke vi ne estu ĵetita en malliberejon."],[5,26,"Vere mi diras al vi, ke vi neniel eliros el tie, ĝis vi pagos la lastan kodranton.","Vere mi diras al vi, ke vi neniel eliros el tie, ĝis vi pagos la lastan kodranton."],[5,27,"Vi aŭdis, ke estas dirite: Ne adultu;","Vi aŭdis, ke estas dirite: Ne adultu;"],[5,28,"sed mi diras al vi, ke ĉiu, kiu rigardas virinon, por deziri ŝin, jam adultis je ŝi en sia koro.","sed mi diras al vi, ke ĉiu, kiu rigardas virinon, por deziri ŝin, jam adultis je ŝi en sia koro."],[5,29,"Kaj se via dekstra okulo faligas vin, elŝiru kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo estus ĵetita en Gehenan.","Kaj se via dekstra okulo faligas vin, elŝiru kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo estus ĵetita en Gehenan."],[5,30,"Kaj se via dekstra mano faligas vin, detranĉu kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo irus en Gehenan.","Kaj se via dekstra mano faligas vin, detranĉu kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo irus en Gehenan."],[5,31,"Estas ankaŭ dirite: Kiu forsendos sian edzinon, tiu donu al ŝi eksedzigan leteron;","Estas ankaŭ dirite: Kiu forsendos sian edzinon, tiu donu al ŝi eksedzigan leteron;"],[5,32,"sed mi diras al vi, ke ĉiu, kiu forsendas sian edzinon, krom pro malĉasteco, igas ŝin adulti; kaj kiu edziĝos kun forsenditino, tiu adultas.","sed mi diras al vi, ke ĉiu, kiu forsendas sian edzinon, krom pro malĉasteco, igas ŝin adulti; kaj kiu edziĝos kun forsenditino, tiu adultas."],[5,33,"Plue, vi aŭdis, ke estas dirite al la antikvuloj: Ne rompu ĵurojn, sed plenumu viajn ĵurojn antaŭ la Eternulo;","Plue, vi aŭdis, ke estas dirite al la antikvuloj: Ne rompu ĵurojn, sed plenumu viajn ĵurojn antaŭ la Eternulo;"],[5,34,"sed mi diras al vi: Tute ne ĵuru; nek per la ĉielo, ĉar ĝi estas la trono de Dio;","sed mi diras al vi: Tute ne ĵuru; nek per la ĉielo, ĉar ĝi estas la trono de Dio;"],[5,35,"nek per la tero, ĉar ĝi estas la benketo de Liaj piedoj; nek per Jerusalem, ĉar ĝi estas urbo de la granda Reĝo.","nek per la tero, ĉar ĝi estas la benketo de Liaj piedoj; nek per Jerusalem, ĉar ĝi estas urbo de la granda Reĝo."],[5,36,"Nek ĵuru per via kapo, ĉar vi ne povas fari eĉ unu haron blanka aŭ nigra.","Nek ĵuru per via kapo, ĉar vi ne povas fari eĉ unu haron blanka aŭ nigra."],[5,37,"Sed via parolo estu: Jes, jes, ne, ne; ĉio ekster tio estas el malbono.","Sed via parolo estu: Jes, jes, ne, ne; ĉio ekster tio estas el malbono."],[5,38,"Vi aŭdis, ke estas dirite: Okulon pro okulo, kaj denton pro dento;","Vi aŭdis, ke estas dirite: Okulon pro okulo, kaj denton pro dento;"],[5,39,"sed mi diras al vi: Ne rezistu al malbono; sed al tiu, kiu frapas vian dekstran vangon, turnu ankaŭ la alian.","sed mi diras al vi: Ne rezistu al malbono; sed al tiu, kiu frapas vian dekstran vangon, turnu ankaŭ la alian."],[5,40,"Kaj se iu deziras procesi kontraŭ vi, por forpreni vian tunikon, lasu lin preni ankaŭ vian mantelon.","Kaj se iu deziras procesi kontraŭ vi, por forpreni vian tunikon, lasu lin preni ankaŭ vian mantelon."],[5,41,"Kaj se iu devigas vin iri unu mejlon, iru kun li du.","Kaj se iu devigas vin iri unu mejlon, iru kun li du."],[5,42,"Donu al tiu, kiu petas de vi; kaj ne deturnu vin de tiu, kiu deziras prunti de vi.","Donu al tiu, kiu petas de vi; kaj ne deturnu vin de tiu, kiu deziras prunti de vi."],[5,43,"Vi aŭdis, ke estas dirite: Amu vian proksimulon, kaj malamu vian malamikon;","Vi aŭdis, ke estas dirite: Amu vian proksimulon, kaj malamu vian malamikon;"],[5,44,"sed mi diras al vi: Amu viajn malamikojn, kaj preĝu por viaj persekutantoj;","sed mi diras al vi: Amu viajn malamikojn, kaj preĝu por viaj persekutantoj;"],[5,45,"por ke vi estu filoj de via Patro, kiu estas en la ĉielo; ĉar Li levas Sian sunon sur la malbonulojn kaj bonulojn, kaj sendas pluvon sur la justulojn kaj la maljustulojn.","por ke vi estu filoj de via Patro, kiu estas en la ĉielo; ĉar Li levas Sian sunon sur la malbonulojn kaj bonulojn, kaj sendas pluvon sur la justulojn kaj la maljustulojn."],[5,46,"Ĉar se vi amas tiujn, kiuj amas vin, kian rekompencon vi havas? ĉu ne tion saman faras eĉ la impostistoj?","Ĉar se vi amas tiujn, kiuj amas vin, kian rekompencon vi havas? ĉu ne tion saman faras eĉ la impostistoj?"],[5,47,"Kaj se vi salutas nur sole viajn fratojn, kion ekstran vi faras? ĉu ne tion saman faras eĉ la nacianoj?","Kaj se vi salutas nur sole viajn fratojn, kion ekstran vi faras? ĉu ne tion saman faras eĉ la nacianoj?"],[5,48,"Estu do perfektaj, kiel ankaŭ via ĉiela Patro estas perfekta.","Estu do perfektaj, kiel ankaŭ via ĉiela Patro estas perfekta."],[6,1,"Gardu vin, ke vi ne faru vian justaĵon antaŭ homoj, por esti alrigardataj de ili; alie vi ne havas rekompencon ĉe via Patro, kiu estas en la ĉielo.","Gardu vin, ke vi ne faru vian justaĵon antaŭ homoj, por esti alrigardataj de ili; alie vi ne havas rekompencon ĉe via Patro, kiu estas en la ĉielo."],[6,2,"Tial, kiam vi donos almozon, ne sonigu trumpeton antaŭ vi, kiel faras la hipokrituloj en la sinagogoj kaj sur la stratoj, por havi gloron ĉe homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon.","Tial, kiam vi donos almozon, ne sonigu trumpeton antaŭ vi, kiel faras la hipokrituloj en la sinagogoj kaj sur la stratoj, por havi gloron ĉe homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon."],[6,3,"Sed kiam vi donas almozon, ne lasu vian maldekstran manon scii, kion faras via dekstra;","Sed kiam vi donas almozon, ne lasu vian maldekstran manon scii, kion faras via dekstra;"],[6,4,"por ke via almozo estu en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.","por ke via almozo estu en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos."],[6,5,"Kaj kiam vi preĝas, ne estu kiel la hipokrituloj; ĉar ili amas preĝi, starante en la sinagogoj kaj ĉe la anguloj de la stratoj, por montri sin al homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon.","Kaj kiam vi preĝas, ne estu kiel la hipokrituloj; ĉar ili amas preĝi, starante en la sinagogoj kaj ĉe la anguloj de la stratoj, por montri sin al homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon."],[6,6,"Sed vi, kiam vi preĝas, eniru en vian ĉambreton, kaj ŝlosinte vian pordon, preĝu al via Patro, kiu estas en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.","Sed vi, kiam vi preĝas, eniru en vian ĉambreton, kaj ŝlosinte vian pordon, preĝu al via Patro, kiu estas en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos."],[6,7,"Kaj dum via preĝado ne vante ripetadu, kiel la nacianoj; ĉar ili supozas, ke ili estos aŭskultitaj pro sia multvorteco.","Kaj dum via preĝado ne vante ripetadu, kiel la nacianoj; ĉar ili supozas, ke ili estos aŭskultitaj pro sia multvorteco."],[6,8,"Ne estu similaj al ili; ĉar via Patro scias, kion vi bezonas, antaŭ ol vi petas de Li.","Ne estu similaj al ili; ĉar via Patro scias, kion vi bezonas, antaŭ ol vi petas de Li."],[6,9,"Vi do preĝu jene: Patro nia, kiu estas en la ĉielo, Via nomo estu sanktigita.","Vi do preĝu jene: Patro nia, kiu estas en la ĉielo, Via nomo estu sanktigita."],[6,10,"Venu Via regno, plenumiĝu Via volo, kiel en la ĉielo, tiel ankaŭ sur la tero.","Venu Via regno, plenumiĝu Via volo, kiel en la ĉielo, tiel ankaŭ sur la tero."],[6,11,"Nian panon ĉiutagan donu al ni hodiaŭ.","Nian panon ĉiutagan donu al ni hodiaŭ."],[6,12,"Kaj pardonu al ni niajn ŝuldojn, kiel ankaŭ ni pardonas al niaj ŝuldantoj.","Kaj pardonu al ni niajn ŝuldojn, kiel ankaŭ ni pardonas al niaj ŝuldantoj."],[6,13,"Kaj ne konduku nin en tenton, sed liberigu nin de la malbono.","Kaj ne konduku nin en tenton, sed liberigu nin de la malbono."],[6,14,"Ĉar se vi pardonas al homoj iliajn kulpojn, via Patro ĉiela ankaŭ pardonos al vi.","Ĉar se vi pardonas al homoj iliajn kulpojn, via Patro ĉiela ankaŭ pardonos al vi."],[6,15,"Sed se vi ne pardonas al homoj iliajn kulpojn, via Patro ankaŭ ne pardonos viajn kulpojn.","Sed se vi ne pardonas al homoj iliajn kulpojn, via Patro ankaŭ ne pardonos viajn kulpojn."],[6,16,"Kaj kiam vi fastas, ne estu kiel la hipokrituloj, kun malĝoja mieno; ĉar ili malbeligas sian vizaĝon, por ke al homoj ili ŝajnu fasti. Vere mi diras al vi: Ili jam ricevas sian rekompencon.","Kaj kiam vi fastas, ne estu kiel la hipokrituloj, kun malĝoja mieno; ĉar ili malbeligas sian vizaĝon, por ke al homoj ili ŝajnu fasti. Vere mi diras al vi: Ili jam ricevas sian rekompencon."],[6,17,"Sed fastante, vi oleu vian kapon kaj lavu vian vizaĝon;","Sed fastante, vi oleu vian kapon kaj lavu vian vizaĝon;"],[6,18,"por ke vi ne al homoj ŝajnu fasti, sed al via Patro en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.","por ke vi ne al homoj ŝajnu fasti, sed al via Patro en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos."],[6,19,"Ne provizu al vi trezorojn sur la tero, kie tineo kaj rusto konsumas, kaj kie ŝtelistoj trafosas kaj ŝtelas;","Ne provizu al vi trezorojn sur la tero, kie tineo kaj rusto konsumas, kaj kie ŝtelistoj trafosas kaj ŝtelas;"],[6,20,"sed provizu al vi trezorojn en la ĉielo, kie nek tineo nek rusto konsumas, kaj kie ŝtelistoj nek trafosas nek ŝtelas;","sed provizu al vi trezorojn en la ĉielo, kie nek tineo nek rusto konsumas, kaj kie ŝtelistoj nek trafosas nek ŝtelas;"],[6,21,"ĉar kie estas via trezoro, tie estos ankaŭ via koro.","ĉar kie estas via trezoro, tie estos ankaŭ via koro."],[6,22,"La lampo de la korpo estas la okulo; se do via okulo estas sendifekta, via tuta korpo estos luma.","La lampo de la korpo estas la okulo; se do via okulo estas sendifekta, via tuta korpo estos luma."],[6,23,"Sed se via okulo estas malbona, via tuta korpo estos malluma. Se do la lumo en vi estas mallumo, kiel densa estas la mallumo!","Sed se via okulo estas malbona, via tuta korpo estos malluma. Se do la lumo en vi estas mallumo, kiel densa estas la mallumo!"],[6,24,"Neniu povas esti sklavo por du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!","Neniu povas esti sklavo por du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!"],[6,25,"Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu, aŭ kion vi trinku; nek pri via korpo, kion vi surmetu. Ĉu la vivo ne estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo?","Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu, aŭ kion vi trinku; nek pri via korpo, kion vi surmetu. Ĉu la vivo ne estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo?"],[6,26,"Rigardu la birdojn de la ĉielo, ke ili ne semas, nek rikoltas, nek kolektas en grenejojn, kaj via Patro ĉiela ilin nutras. Ĉu vi ne multe pli valoras ol ili?","Rigardu la birdojn de la ĉielo, ke ili ne semas, nek rikoltas, nek kolektas en grenejojn, kaj via Patro ĉiela ilin nutras. Ĉu vi ne multe pli valoras ol ili?"],[6,27,"Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?","Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?"],[6,28,"Kaj kial vi zorgas pri vestaĵo? Pripensu la liliojn de la kampo, kiel ili kreskas; ili ne laboras, nek ŝpinas;","Kaj kial vi zorgas pri vestaĵo? Pripensu la liliojn de la kampo, kiel ili kreskas; ili ne laboras, nek ŝpinas;"],[6,29,"tamen mi diras al vi, ke eĉ Salomono en sia tuta gloro ne estis ornamita, kiel unu el ĉi tiuj.","tamen mi diras al vi, ke eĉ Salomono en sia tuta gloro ne estis ornamita, kiel unu el ĉi tiuj."],[6,30,"Sed se Dio tiel vestas la kampan herbaĵon, kiu ekzistas hodiaŭ, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj?","Sed se Dio tiel vestas la kampan herbaĵon, kiu ekzistas hodiaŭ, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj?"],[6,31,"Tial ne zorgu, dirante: Kion ni manĝu? aŭ: Kion ni trinku? aŭ: Kion ni surmetu?","Tial ne zorgu, dirante: Kion ni manĝu? aŭ: Kion ni trinku? aŭ: Kion ni surmetu?"],[6,32,"Ĉar pri ĉio tio serĉas la nacianoj; ĉar via Patro ĉiela scias, ke vi bezonas ĉion tion.","Ĉar pri ĉio tio serĉas la nacianoj; ĉar via Patro ĉiela scias, ke vi bezonas ĉion tion."],[6,33,"Sed celu unue Lian regnon kaj Lian justecon, kaj ĉio tio estos aldonita al vi.","Sed celu unue Lian regnon kaj Lian justecon, kaj ĉio tio estos aldonita al vi."],[6,34,"Tial ne zorgu pri la morgaŭa tago, ĉar la morgaŭa tago zorgos pri si mem. Sufiĉa por la tago estas ĝia propra malbono.","Tial ne zorgu pri la morgaŭa tago, ĉar la morgaŭa tago zorgos pri si mem. Sufiĉa por la tago estas ĝia propra malbono."],[7,1,"Ne juĝu, por ke vi ne estu juĝataj.","Ne juĝu, por ke vi ne estu juĝataj."],[7,2,"Ĉar per kia juĝo vi juĝos, per tia vi estos juĝitaj; kaj per kia mezuro vi mezuros, per tia oni mezuros al vi.","Ĉar per kia juĝo vi juĝos, per tia vi estos juĝitaj; kaj per kia mezuro vi mezuros, per tia oni mezuros al vi."],[7,3,"Kaj kial vi rigardas la lignereton en la okulo de via frato, kaj ne pripensas la trabon en via okulo?","Kaj kial vi rigardas la lignereton en la okulo de via frato, kaj ne pripensas la trabon en via okulo?"],[7,4,"Kiel vi diros al via frato: Lasu min eltiri la lignereton el via okulo; kaj jen la trabo en via propra okulo?","Kiel vi diros al via frato: Lasu min eltiri la lignereton el via okulo; kaj jen la trabo en via propra okulo?"],[7,5,"Hipokritulo, eligu unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton el la okulo de via frato.","Hipokritulo, eligu unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton el la okulo de via frato."],[7,6,"Ne donu sanktaĵon al la hundoj, nek ĵetu viajn perlojn antaŭ la porkoj; por ke ili ne premu ilin sub la piedoj, nek poste, sin turninte, disŝiru vin.","Ne donu sanktaĵon al la hundoj, nek ĵetu viajn perlojn antaŭ la porkoj; por ke ili ne premu ilin sub la piedoj, nek poste, sin turninte, disŝiru vin."],[7,7,"Petu, kaj estos donite al vi; serĉu, kaj vi trovos; frapu, kaj estos malfermite al vi;","Petu, kaj estos donite al vi; serĉu, kaj vi trovos; frapu, kaj estos malfermite al vi;"],[7,8,"ĉar ĉiu petanto ricevas, kaj la serĉanto trovas, kaj al la frapanto estos malfermite.","ĉar ĉiu petanto ricevas, kaj la serĉanto trovas, kaj al la frapanto estos malfermite."],[7,9,"Plue, kiu homo el vi, kies filo de li petos panon, donos al li ŝtonon;","Plue, kiu homo el vi, kies filo de li petos panon, donos al li ŝtonon;"],[7,10,"aŭ se li petos fiŝon, donos al li serpenton?","aŭ se li petos fiŝon, donos al li serpenton?"],[7,11,"Se do vi, estante malbonaj, scias doni bonajn donacojn al viaj filoj, kiom pli certe via Patro, kiu estas en la ĉielo, donos bonaĵojn al tiuj, kiuj petas de Li?","Se do vi, estante malbonaj, scias doni bonajn donacojn al viaj filoj, kiom pli certe via Patro, kiu estas en la ĉielo, donos bonaĵojn al tiuj, kiuj petas de Li?"],[7,12,"Ĉion ajn do, kion vi deziras, ke la homoj faru al vi, vi ankaŭ faru al ili; ĉar ĉi tio estas la leĝo kaj la profetoj.","Ĉion ajn do, kion vi deziras, ke la homoj faru al vi, vi ankaŭ faru al ili; ĉar ĉi tio estas la leĝo kaj la profetoj."],[7,13,"Eniru tra la mallarĝa pordo, ĉar larĝa estas la pordego kaj vasta estas la vojo kondukanta al la pereo, kaj multaj tra ĝi eniras.","Eniru tra la mallarĝa pordo, ĉar larĝa estas la pordego kaj vasta estas la vojo kondukanta al la pereo, kaj multaj tra ĝi eniras."],[7,14,"Ĉar mallarĝa estas la pordo kaj malvastigita estas la vojo kondukanta al la vivo, kaj malmultaj ĝin trovas.","Ĉar mallarĝa estas la pordo kaj malvastigita estas la vojo kondukanta al la vivo, kaj malmultaj ĝin trovas."],[7,15,"Gardu vin kontraŭ la falsaj profetoj, kiuj venas al vi en ŝafaj feloj, sed interne estas rabemaj lupoj.","Gardu vin kontraŭ la falsaj profetoj, kiuj venas al vi en ŝafaj feloj, sed interne estas rabemaj lupoj."],[7,16,"Per iliaj fruktoj vi konos ilin. Ĉu el dornarbetoj oni kolektas vinberojn, aŭ el kardoj figojn?","Per iliaj fruktoj vi konos ilin. Ĉu el dornarbetoj oni kolektas vinberojn, aŭ el kardoj figojn?"],[7,17,"Tiel ĉiu bona arbo donas bonajn fruktojn, sed putra arbo donas malbonajn fruktojn.","Tiel ĉiu bona arbo donas bonajn fruktojn, sed putra arbo donas malbonajn fruktojn."],[7,18,"Bona arbo ne povas doni malbonajn fruktojn, nek putra arbo doni bonajn fruktojn.","Bona arbo ne povas doni malbonajn fruktojn, nek putra arbo doni bonajn fruktojn."],[7,19,"Ĉiu arbo, kiu ne donas bonan frukton, estas dehakata kaj ĵetata en fajron.","Ĉiu arbo, kiu ne donas bonan frukton, estas dehakata kaj ĵetata en fajron."],[7,20,"Tial per iliaj fruktoj vi konos ilin.","Tial per iliaj fruktoj vi konos ilin."],[7,21,"Ne ĉiu, kiu diras al mi: Sinjoro, Sinjoro, eniros en la regnon de la ĉielo; sed tiu, kiu plenumas la volon de mia Patro, kiu estas en la ĉielo.","Ne ĉiu, kiu diras al mi: Sinjoro, Sinjoro, eniros en la regnon de la ĉielo; sed tiu, kiu plenumas la volon de mia Patro, kiu estas en la ĉielo."],[7,22,"Multaj diros al mi en tiu tago: Sinjoro, Sinjoro, ĉu ni ne profetis en via nomo, kaj en via nomo elpelis demonojn, kaj en via nomo faris multajn potencaĵojn?","Multaj diros al mi en tiu tago: Sinjoro, Sinjoro, ĉu ni ne profetis en via nomo, kaj en via nomo elpelis demonojn, kaj en via nomo faris multajn potencaĵojn?"],[7,23,"Kaj tiam mi konfesos al ili: Mi neniam konis vin; foriĝu de mi, vi farantoj de maljusteco.","Kaj tiam mi konfesos al ili: Mi neniam konis vin; foriĝu de mi, vi farantoj de maljusteco."],[7,24,"Tial ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj plenumas ilin, estos komparata al saĝa viro, kiu konstruis sian domon sur roko;","Tial ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj plenumas ilin, estos komparata al saĝa viro, kiu konstruis sian domon sur roko;"],[7,25,"kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj albatis tiun domon, kaj ĝi ne falis; ĉar ĝi estis fondita sur roko.","kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj albatis tiun domon, kaj ĝi ne falis; ĉar ĝi estis fondita sur roko."],[7,26,"Kaj ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj ne plenumas ilin, estos komparata al viro malsaĝa, kiu konstruis sian domon sur la sablo;","Kaj ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj ne plenumas ilin, estos komparata al viro malsaĝa, kiu konstruis sian domon sur la sablo;"],[7,27,"kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj sin ĵetis sur tiun domon, kaj ĝi falis; kaj granda estis ĝia falo.","kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj sin ĵetis sur tiun domon, kaj ĝi falis; kaj granda estis ĝia falo."],[7,28,"Kaj kiam Jesuo finis tiujn parolojn, la homamasoj miregis pri lia instruado;","Kaj kiam Jesuo finis tiujn parolojn, la homamasoj miregis pri lia instruado;"],[7,29,"ĉar li instruis ilin, kiel havanta aŭtoritaton, kaj ne kiel iliaj skribistoj.","ĉar li instruis ilin, kiel havanta aŭtoritaton, kaj ne kiel iliaj skribistoj."],[8,1,"Kaj kiam li malsupreniris de la monto, lin sekvis grandaj homamasoj.","Kaj kiam li malsupreniris de la monto, lin sekvis grandaj homamasoj."],[8,2,"Kaj jen venis al li leprulo kaj adorkliniĝis al li, dirante: Sinjoro, se vi volas, vi povas min purigi.","Kaj jen venis al li leprulo kaj adorkliniĝis al li, dirante: Sinjoro, se vi volas, vi povas min purigi."],[8,3,"Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj lia lepro estis purigita.","Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj lia lepro estis purigita."],[8,4,"Kaj Jesuo diris al li: Zorgu, ke vi diru al neniu. Sed iru, montru vin al la pastro, kaj oferu la donon, kiun Moseo ordonis, por atesto al ili.","Kaj Jesuo diris al li: Zorgu, ke vi diru al neniu. Sed iru, montru vin al la pastro, kaj oferu la donon, kiun Moseo ordonis, por atesto al ili."],[8,5,"Kaj kiam li eniris en Kapernaumon, venis al li centestro, petante lin,","Kaj kiam li eniris en Kapernaumon, venis al li centestro, petante lin,"],[8,6,"kaj dirante: Sinjoro, mia knabo kuŝas paralizulo en la domo, kaj terure suferas.","kaj dirante: Sinjoro, mia knabo kuŝas paralizulo en la domo, kaj terure suferas."],[8,7,"Kaj li diris al li: Mi venos, kaj sanigos lin.","Kaj li diris al li: Mi venos, kaj sanigos lin."],[8,8,"Kaj la centestro responde diris: Sinjoro, mi ne estas inda, ke vi venu sub mian tegmenton; sed nur parolu vorte, kaj mia knabo saniĝos.","Kaj la centestro responde diris: Sinjoro, mi ne estas inda, ke vi venu sub mian tegmenton; sed nur parolu vorte, kaj mia knabo saniĝos."],[8,9,"Ĉar mi ankaŭ estas homo sub aŭtoritato, havante soldatojn sub mi; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras.","Ĉar mi ankaŭ estas homo sub aŭtoritato, havante soldatojn sub mi; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras."],[8,10,"Kaj kiam Jesuo tion aŭdis, li miris, kaj diris al la sekvantoj: Vere mi diras al vi, ke ĉe neniu en Izrael mi trovis tiom da fido.","Kaj kiam Jesuo tion aŭdis, li miris, kaj diris al la sekvantoj: Vere mi diras al vi, ke ĉe neniu en Izrael mi trovis tiom da fido."],[8,11,"Kaj mi diras al vi, ke multaj venos el la oriento kaj la okcidento, kaj sidiĝos kun Abraham kaj Isaak kaj Jakob en la regno de la ĉielo;","Kaj mi diras al vi, ke multaj venos el la oriento kaj la okcidento, kaj sidiĝos kun Abraham kaj Isaak kaj Jakob en la regno de la ĉielo;"],[8,12,"sed la filoj de la regno estos elĵetitaj en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.","sed la filoj de la regno estos elĵetitaj en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj."],[8,13,"Kaj Jesuo diris al la centestro: Iru; kiel vi kredis, tiel estu farite al vi. Kaj lia knabo saniĝis en tiu sama horo.","Kaj Jesuo diris al la centestro: Iru; kiel vi kredis, tiel estu farite al vi. Kaj lia knabo saniĝis en tiu sama horo."],[8,14,"Kaj kiam Jesuo venis en la domon de Petro, li vidis lian bopatrinon kuŝanta, malsana de febro.","Kaj kiam Jesuo venis en la domon de Petro, li vidis lian bopatrinon kuŝanta, malsana de febro."],[8,15,"Kaj li tuŝis ŝian manon, kaj la febro forlasis ŝin; kaj ŝi leviĝis kaj servis al li.","Kaj li tuŝis ŝian manon, kaj la febro forlasis ŝin; kaj ŝi leviĝis kaj servis al li."],[8,16,"Kaj kiam vesperiĝis, oni venigis al li multajn demonhavantojn; kaj li elpelis la spiritojn per vorto, kaj sanigis ĉiujn malsanulojn;","Kaj kiam vesperiĝis, oni venigis al li multajn demonhavantojn; kaj li elpelis la spiritojn per vorto, kaj sanigis ĉiujn malsanulojn;"],[8,17,"por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome: Li mem prenis niajn malfortaĵojn kaj portis niajn malsanojn.","por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome: Li mem prenis niajn malfortaĵojn kaj portis niajn malsanojn."],[8,18,"Kaj kiam Jesuo vidis ĉirkaŭ si grandan homamason, li ordonis transiri al la alia bordo.","Kaj kiam Jesuo vidis ĉirkaŭ si grandan homamason, li ordonis transiri al la alia bordo."],[8,19,"Kaj venis unu skribisto, kaj diris al li: Majstro, mi vin sekvos, kien ajn vi iros.","Kaj venis unu skribisto, kaj diris al li: Majstro, mi vin sekvos, kien ajn vi iros."],[8,20,"Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon.","Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon."],[8,21,"Kaj alia el la disĉiploj diris al li: Sinjoro, permesu al mi unue iri kaj enterigi mian patron.","Kaj alia el la disĉiploj diris al li: Sinjoro, permesu al mi unue iri kaj enterigi mian patron."],[8,22,"Sed Jesuo diris al li: Sekvu min, kaj lasu la mortintojn enterigi siajn mortintojn.","Sed Jesuo diris al li: Sekvu min, kaj lasu la mortintojn enterigi siajn mortintojn."],[8,23,"Kaj kiam li eniris en ŝipeton, liaj disĉiploj lin sekvis.","Kaj kiam li eniris en ŝipeton, liaj disĉiploj lin sekvis."],[8,24,"Kaj jen okazis granda malsereno sur la maro, tiel ke la ŝipeto estis kovrita de la ondoj; sed li dormadis.","Kaj jen okazis granda malsereno sur la maro, tiel ke la ŝipeto estis kovrita de la ondoj; sed li dormadis."],[8,25,"Kaj ili venis, kaj vekis lin, dirante: Sinjoro, savu; ni pereas.","Kaj ili venis, kaj vekis lin, dirante: Sinjoro, savu; ni pereas."],[8,26,"Kaj li diris al ili: Kial vi estas timemaj, ho malgrandfiduloj? Tiam li leviĝis, kaj admonis la ventojn kaj la maron; kaj fariĝis granda sereno.","Kaj li diris al ili: Kial vi estas timemaj, ho malgrandfiduloj? Tiam li leviĝis, kaj admonis la ventojn kaj la maron; kaj fariĝis granda sereno."],[8,27,"Kaj la homoj miregis, dirante: Kia estas ĉi tiu, ke eĉ la ventoj kaj la maro lin obeas?","Kaj la homoj miregis, dirante: Kia estas ĉi tiu, ke eĉ la ventoj kaj la maro lin obeas?"],[8,28,"Kaj kiam li venis al la alia bordo, en la landon de la Gadaranoj, lin renkontis du demonhavantoj, elvenante el inter la tomboj, tre furiozaj, tiel, ke neniu povis preterpasi per tiu vojo.","Kaj kiam li venis al la alia bordo, en la landon de la Gadaranoj, lin renkontis du demonhavantoj, elvenante el inter la tomboj, tre furiozaj, tiel, ke neniu povis preterpasi per tiu vojo."],[8,29,"Kaj jen ili kriis, dirante: Kio estas inter ni kaj vi, ho Filo de Dio? ĉu vi venis ĉi tien, por turmenti nin antaŭ la tempo?","Kaj jen ili kriis, dirante: Kio estas inter ni kaj vi, ho Filo de Dio? ĉu vi venis ĉi tien, por turmenti nin antaŭ la tempo?"],[8,30,"Kaj malproksime de ili estis granda grego da porkoj, paŝtiĝantaj tie.","Kaj malproksime de ili estis granda grego da porkoj, paŝtiĝantaj tie."],[8,31,"Kaj la demonoj petegis lin, dirante: Se vi elpelos nin, forsendu nin en la gregon da porkoj.","Kaj la demonoj petegis lin, dirante: Se vi elpelos nin, forsendu nin en la gregon da porkoj."],[8,32,"Kaj li diris al ili: Iru. Kaj elirinte, ili foriris en la porkojn; kaj jen kuris la tuta grego malsupren de la krutaĵo en la maron, kaj pereis en la akvoj.","Kaj li diris al ili: Iru. Kaj elirinte, ili foriris en la porkojn; kaj jen kuris la tuta grego malsupren de la krutaĵo en la maron, kaj pereis en la akvoj."],[8,33,"Kaj la paŝtistoj forkuris kaj iris en la urbon, kaj rakontis ĉion, kaj pri la demonhavintoj.","Kaj la paŝtistoj forkuris kaj iris en la urbon, kaj rakontis ĉion, kaj pri la demonhavintoj."],[8,34,"Kaj jen la tuta urbo elvenis renkonte al Jesuo; kaj vidinte lin, ili petegis, ke li transiru el iliaj limoj.","Kaj jen la tuta urbo elvenis renkonte al Jesuo; kaj vidinte lin, ili petegis, ke li transiru el iliaj limoj."],[9,1,"Kaj enirinte en ŝipeton, li transiris, kaj venis en sian propran urbon.","Kaj enirinte en ŝipeton, li transiris, kaj venis en sian propran urbon."],[9,2,"Kaj jen oni alportis al li paralizulon, kuŝantan sur lito; kaj Jesuo, vidinte ilian fidon, diris al la paralizulo: Kuraĝu, filo, viaj pekoj estas pardonitaj.","Kaj jen oni alportis al li paralizulon, kuŝantan sur lito; kaj Jesuo, vidinte ilian fidon, diris al la paralizulo: Kuraĝu, filo, viaj pekoj estas pardonitaj."],[9,3,"Kaj jen iuj el la skribistoj diris en si: Ĉi tiu blasfemas.","Kaj jen iuj el la skribistoj diris en si: Ĉi tiu blasfemas."],[9,4,"Kaj Jesuo, eksciante iliajn pensojn, diris: Kial vi pensas malbonon en viaj koroj?","Kaj Jesuo, eksciante iliajn pensojn, diris: Kial vi pensas malbonon en viaj koroj?"],[9,5,"Ĉar kio estas pli facila, diri: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu kaj piediru?","Ĉar kio estas pli facila, diri: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu kaj piediru?"],[9,6,"Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — tiam li diris al la paralizulo: Leviĝu, prenu vian liton, kaj iru al via domo.","Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — tiam li diris al la paralizulo: Leviĝu, prenu vian liton, kaj iru al via domo."],[9,7,"Kaj li leviĝis, kaj iris al sia domo.","Kaj li leviĝis, kaj iris al sia domo."],[9,8,"Kaj vidinte tion, la homamasoj timis, kaj gloris Dion, kiu donis tian aŭtoritaton al homoj.","Kaj vidinte tion, la homamasoj timis, kaj gloris Dion, kiu donis tian aŭtoritaton al homoj."],[9,9,"Kaj Jesuo, forpasante de tie, vidis viron nomatan Mateo, sidantan ĉe la impostejo; kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin.","Kaj Jesuo, forpasante de tie, vidis viron nomatan Mateo, sidantan ĉe la impostejo; kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin."],[9,10,"Kaj dum li sidis ĉe manĝo en la domo, jen multaj impostistoj kaj pekuloj venis kaj sidiĝis tie kun Jesuo kaj liaj disĉiploj.","Kaj dum li sidis ĉe manĝo en la domo, jen multaj impostistoj kaj pekuloj venis kaj sidiĝis tie kun Jesuo kaj liaj disĉiploj."],[9,11,"Kaj vidinte tion, la Fariseoj diris al liaj disĉiploj: Kial via instruisto manĝas kun impostistoj kaj pekuloj?","Kaj vidinte tion, la Fariseoj diris al liaj disĉiploj: Kial via instruisto manĝas kun impostistoj kaj pekuloj?"],[9,12,"Kaj aŭdinte tion, li diris: Ne la sanuloj bezonas kuraciston, sed la malsanuloj.","Kaj aŭdinte tion, li diris: Ne la sanuloj bezonas kuraciston, sed la malsanuloj."],[9,13,"Sed iru, kaj lernu, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; ĉar mi venis, por alvoki ne justulojn, sed pekulojn.","Sed iru, kaj lernu, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; ĉar mi venis, por alvoki ne justulojn, sed pekulojn."],[9,14,"Tiam alvenis al li la disĉiploj de Johano, dirante: Kial ni kaj la Fariseoj fastas ofte, sed viaj disĉiploj ne fastas?","Tiam alvenis al li la disĉiploj de Johano, dirante: Kial ni kaj la Fariseoj fastas ofte, sed viaj disĉiploj ne fastas?"],[9,15,"Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas malĝoji, dum la fianĉo estas kun ili? Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos.","Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas malĝoji, dum la fianĉo estas kun ili? Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos."],[9,16,"Kaj neniu alkudras flikaĵon el nefulita drapo sur malnovan veston, ĉar la plenigaĵo forprenas de la vesto, kaj pli malbona ŝiraĵo fariĝas.","Kaj neniu alkudras flikaĵon el nefulita drapo sur malnovan veston, ĉar la plenigaĵo forprenas de la vesto, kaj pli malbona ŝiraĵo fariĝas."],[9,17,"Ankaŭ oni ne enverŝas novan vinon en malnovajn felsakojn; alie la felsakoj krevos, kaj la vino elfluos, kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn, kaj ambaŭ konserviĝas.","Ankaŭ oni ne enverŝas novan vinon en malnovajn felsakojn; alie la felsakoj krevos, kaj la vino elfluos, kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn, kaj ambaŭ konserviĝas."],[9,18,"Dum li tion parolis al ili, jen unu estro, alveninte, adorkliniĝis al li, dirante: Mia filino ĵus mortis; sed venu kaj metu vian manon sur ŝin, kaj ŝi vivos.","Dum li tion parolis al ili, jen unu estro, alveninte, adorkliniĝis al li, dirante: Mia filino ĵus mortis; sed venu kaj metu vian manon sur ŝin, kaj ŝi vivos."],[9,19,"Kaj Jesuo leviĝis, kaj sekvis lin, kaj ankaŭ liaj disĉiploj.","Kaj Jesuo leviĝis, kaj sekvis lin, kaj ankaŭ liaj disĉiploj."],[9,20,"Kaj jen virino, kiu jam dek du jarojn havis sangofluon, venis malantaŭ lin kaj tuŝis la randon de lia mantelo;","Kaj jen virino, kiu jam dek du jarojn havis sangofluon, venis malantaŭ lin kaj tuŝis la randon de lia mantelo;"],[9,21,"ĉar ŝi diris en si: Se mi nur tuŝos lian mantelon, mi estos sanigita.","ĉar ŝi diris en si: Se mi nur tuŝos lian mantelon, mi estos sanigita."],[9,22,"Kaj Jesuo, sin turninte kaj vidinte ŝin, diris: Kuraĝu, filino; via fido vin savis. Kaj en tiu sama horo la virino resaniĝis.","Kaj Jesuo, sin turninte kaj vidinte ŝin, diris: Kuraĝu, filino; via fido vin savis. Kaj en tiu sama horo la virino resaniĝis."],[9,23,"Kaj Jesuo, veninte en la domon de la estro kaj vidinte la flutistojn kaj la homamason bruantajn,","Kaj Jesuo, veninte en la domon de la estro kaj vidinte la flutistojn kaj la homamason bruantajn,"],[9,24,"diris: Foriru; ĉar la knabineto ne mortis, sed dormas. Kaj ili mokridis lin.","diris: Foriru; ĉar la knabineto ne mortis, sed dormas. Kaj ili mokridis lin."],[9,25,"Sed kiam la homamaso estis elpelita, li eniris, kaj prenis ŝian manon; kaj la knabineto leviĝis.","Sed kiam la homamaso estis elpelita, li eniris, kaj prenis ŝian manon; kaj la knabineto leviĝis."],[9,26,"Kaj disiris tiu famo en tiun tutan regionon.","Kaj disiris tiu famo en tiun tutan regionon."],[9,27,"Kaj kiam Jesuo foriris de tie, du blinduloj sekvis lin, kriante kaj dirante: Kompatu nin, ho filo de David.","Kaj kiam Jesuo foriris de tie, du blinduloj sekvis lin, kriante kaj dirante: Kompatu nin, ho filo de David."],[9,28,"Kaj kiam li venis en la domon, la blinduloj alvenis al li, kaj Jesuo diris al ili: Ĉu vi kredas, ke mi povas fari ĉi tion? Ili diris al li: Jes, Sinjoro.","Kaj kiam li venis en la domon, la blinduloj alvenis al li, kaj Jesuo diris al ili: Ĉu vi kredas, ke mi povas fari ĉi tion? Ili diris al li: Jes, Sinjoro."],[9,29,"Tiam li tuŝis iliajn okulojn, dirante: Estu al vi laŭ via fido.","Tiam li tuŝis iliajn okulojn, dirante: Estu al vi laŭ via fido."],[9,30,"Kaj iliaj okuloj malfermiĝis. Kaj Jesuo severe ordonis al ili: Gardu vin, ke neniu tion sciu.","Kaj iliaj okuloj malfermiĝis. Kaj Jesuo severe ordonis al ili: Gardu vin, ke neniu tion sciu."],[9,31,"Sed elirinte, ili disvastigis lian famon en tiu tuta regiono.","Sed elirinte, ili disvastigis lian famon en tiu tuta regiono."],[9,32,"Kaj dum ili eliris, jen oni alportis al li mutan demonhavanton.","Kaj dum ili eliris, jen oni alportis al li mutan demonhavanton."],[9,33,"Kaj kiam la demono estis elpelita, la mutulo parolis; kaj la homamasoj miris, dirante: Neniam tia afero estas vidita en Izrael.","Kaj kiam la demono estis elpelita, la mutulo parolis; kaj la homamasoj miris, dirante: Neniam tia afero estas vidita en Izrael."],[9,34,"Sed la Fariseoj diris: Per la estro de la demonoj li elpelas demonojn.","Sed la Fariseoj diris: Per la estro de la demonoj li elpelas demonojn."],[9,35,"Kaj Jesuo trairis ĉiujn urbojn kaj vilaĝojn, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj sanigante ĉian malsanon kaj ĉian malfortaĵon.","Kaj Jesuo trairis ĉiujn urbojn kaj vilaĝojn, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj sanigante ĉian malsanon kaj ĉian malfortaĵon."],[9,36,"Kaj vidante la homamasojn, li estis kortuŝita pri ili, ĉar ili estis mizerigitaj kaj disigitaj, kiel ŝafoj ne havantaj paŝtiston.","Kaj vidante la homamasojn, li estis kortuŝita pri ili, ĉar ili estis mizerigitaj kaj disigitaj, kiel ŝafoj ne havantaj paŝtiston."],[9,37,"Tiam li diris al siaj disĉiploj: La rikolto ja estas abunda, sed la laborantoj estas malmultaj.","Tiam li diris al siaj disĉiploj: La rikolto ja estas abunda, sed la laborantoj estas malmultaj."],[9,38,"Petu do la Sinjoron de la rikolto, ke Li sendu laborantojn en Sian rikolton.","Petu do la Sinjoron de la rikolto, ke Li sendu laborantojn en Sian rikolton."],[10,1,"Kaj li alvokis al si la dek du disĉiplojn, kaj donis al ili aŭtoritaton super malpuraj spiritoj, por elpeli ilin, kaj por sanigi ĉian malsanon kaj ĉian malfortaĵon.","Kaj li alvokis al si la dek du disĉiplojn, kaj donis al ili aŭtoritaton super malpuraj spiritoj, por elpeli ilin, kaj por sanigi ĉian malsanon kaj ĉian malfortaĵon."],[10,2,"Kaj la nomoj de la dek du apostoloj estas jenaj: la unua, Simon, kiu estis nomata Petro, kaj lia frato Andreo, Jakobo, filo de Zebedeo, kaj lia frato Johano,","Kaj la nomoj de la dek du apostoloj estas jenaj: la unua, Simon, kiu estis nomata Petro, kaj lia frato Andreo, Jakobo, filo de Zebedeo, kaj lia frato Johano,"],[10,3,"Filipo kaj Bartolomeo, Tomaso, kaj Mateo, impostisto, Jakobo, filo de Alfeo, kaj Tadeo,","Filipo kaj Bartolomeo, Tomaso, kaj Mateo, impostisto, Jakobo, filo de Alfeo, kaj Tadeo,"],[10,4,"Simon, la Fervorulo, kaj Judas Iskariota, kiu ankaŭ perfidis lin.","Simon, la Fervorulo, kaj Judas Iskariota, kiu ankaŭ perfidis lin."],[10,5,"Ĉi tiujn dek du Jesuo forsendis, kaj ordonis al ili, dirante: Ne iru sur vojon de nacianoj, kaj ne eniru en urbon de Samarianoj;","Ĉi tiujn dek du Jesuo forsendis, kaj ordonis al ili, dirante: Ne iru sur vojon de nacianoj, kaj ne eniru en urbon de Samarianoj;"],[10,6,"sed iru prefere al la perditaj ŝafoj de la domo de Izrael.","sed iru prefere al la perditaj ŝafoj de la domo de Izrael."],[10,7,"Kaj dum vi iros, prediku, dirante: La regno de la ĉielo alproksimiĝis.","Kaj dum vi iros, prediku, dirante: La regno de la ĉielo alproksimiĝis."],[10,8,"Malsanulojn sanigu, mortintojn levu, leprulojn purigu, demonojn elpelu: donace vi ricevis, donace donu.","Malsanulojn sanigu, mortintojn levu, leprulojn purigu, demonojn elpelu: donace vi ricevis, donace donu."],[10,9,"Ne provizu oron nek arĝenton nek kupron en viajn zonojn,","Ne provizu oron nek arĝenton nek kupron en viajn zonojn,"],[10,10,"nek saketon por vojaĝo, nek du tunikojn, nek ŝuojn, nek bastonon; ĉar la laboranto meritas sian nutraĵon.","nek saketon por vojaĝo, nek du tunikojn, nek ŝuojn, nek bastonon; ĉar la laboranto meritas sian nutraĵon."],[10,11,"Kaj en iu ajn urbo aŭ vilaĝo, en kiun vi eniros, demandu, kiu tie estas inda; kaj loĝu tie, ĝis vi foriros.","Kaj en iu ajn urbo aŭ vilaĝo, en kiun vi eniros, demandu, kiu tie estas inda; kaj loĝu tie, ĝis vi foriros."],[10,12,"Kaj venante en la domon, salutu ĝin.","Kaj venante en la domon, salutu ĝin."],[10,13,"Kaj se la domo estas inda, via paco venu sur ĝin; sed se ĝi ne estas inda, via paco revenu al vi.","Kaj se la domo estas inda, via paco venu sur ĝin; sed se ĝi ne estas inda, via paco revenu al vi."],[10,14,"Kaj se iu ne akceptos vin, nek aŭskultos viajn vortojn, tiam forirante el tiu domo aŭ tiu urbo, deskuu la polvon de viaj piedoj.","Kaj se iu ne akceptos vin, nek aŭskultos viajn vortojn, tiam forirante el tiu domo aŭ tiu urbo, deskuu la polvon de viaj piedoj."],[10,15,"Vere mi diras al vi: Pli elporteble estos por la lando de Sodom kaj Gomora en la tago de juĝado, ol por tiu urbo.","Vere mi diras al vi: Pli elporteble estos por la lando de Sodom kaj Gomora en la tago de juĝado, ol por tiu urbo."],[10,16,"Jen mi forsendas vin kiel ŝafojn meze de lupoj; estu do prudentaj kiel serpentoj, kaj simplaj kiel kolomboj.","Jen mi forsendas vin kiel ŝafojn meze de lupoj; estu do prudentaj kiel serpentoj, kaj simplaj kiel kolomboj."],[10,17,"Sed gardu vin kontraŭ la homoj; ĉar ili transdonos vin al sinedrioj, kaj en siaj sinagogoj ili vin skurĝos;","Sed gardu vin kontraŭ la homoj; ĉar ili transdonos vin al sinedrioj, kaj en siaj sinagogoj ili vin skurĝos;"],[10,18,"kaj antaŭ provincestrojn kaj reĝojn vi estos kondukitaj pro mi, por atesto al ili kaj al la nacianoj.","kaj antaŭ provincestrojn kaj reĝojn vi estos kondukitaj pro mi, por atesto al ili kaj al la nacianoj."],[10,19,"Sed kiam ili transdonos vin, ne zorgu, kiel aŭ kion vi parolos; ĉar estos donita al vi en tiu horo tio, kion vi parolos.","Sed kiam ili transdonos vin, ne zorgu, kiel aŭ kion vi parolos; ĉar estos donita al vi en tiu horo tio, kion vi parolos."],[10,20,"Ĉar parolas ne vi, sed la Spirito de via Patro parolas en vi.","Ĉar parolas ne vi, sed la Spirito de via Patro parolas en vi."],[10,21,"Kaj frato transdonos fraton al morto, kaj patro filon; kaj infanoj ribelos kontraŭ gepatroj kaj mortigos ilin.","Kaj frato transdonos fraton al morto, kaj patro filon; kaj infanoj ribelos kontraŭ gepatroj kaj mortigos ilin."],[10,22,"Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita.","Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita."],[10,23,"Kaj kiam oni vin persekutos en unu urbo, forkuru en alian; ĉar vere mi diras al vi: Vi ne trairos la urbojn de Izrael, antaŭ ol venos la Filo de homo.","Kaj kiam oni vin persekutos en unu urbo, forkuru en alian; ĉar vere mi diras al vi: Vi ne trairos la urbojn de Izrael, antaŭ ol venos la Filo de homo."],[10,24,"Disĉiplo ne estas super sia instruanto, nek sklavo super sia sinjoro.","Disĉiplo ne estas super sia instruanto, nek sklavo super sia sinjoro."],[10,25,"Sufiĉas por la disĉiplo, ke li estu kiel lia instruanto, kaj la sklavo, kiel lia sinjoro. Se oni nomis la dommastron Baal-Zebub, kiom pli ankaŭ liajn domanojn!","Sufiĉas por la disĉiplo, ke li estu kiel lia instruanto, kaj la sklavo, kiel lia sinjoro. Se oni nomis la dommastron Baal-Zebub, kiom pli ankaŭ liajn domanojn!"],[10,26,"Tial ne timu ilin, ĉar nenio estas kovrita, kio ne estos elmontrita, kaj nenio kaŝita, kio ne estos konigita.","Tial ne timu ilin, ĉar nenio estas kovrita, kio ne estos elmontrita, kaj nenio kaŝita, kio ne estos konigita."],[10,27,"Kion mi diras al vi en la mallumo, tion parolu en la lumo; kaj kion vi aŭdas en la orelon, tion proklamu sur la tegmentoj.","Kion mi diras al vi en la mallumo, tion parolu en la lumo; kaj kion vi aŭdas en la orelon, tion proklamu sur la tegmentoj."],[10,28,"Kaj ne timu tiujn, kiuj mortigas la korpon, sed ne povas mortigi la animon; sed prefere timu Tiun, kiu povas pereigi kaj animon kaj korpon en Gehena.","Kaj ne timu tiujn, kiuj mortigas la korpon, sed ne povas mortigi la animon; sed prefere timu Tiun, kiu povas pereigi kaj animon kaj korpon en Gehena."],[10,29,"Ĉu oni ne vendas du paserojn por asaro? tamen unu el ili ne falos teren sen via Patro;","Ĉu oni ne vendas du paserojn por asaro? tamen unu el ili ne falos teren sen via Patro;"],[10,30,"sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj.","sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj."],[10,31,"Tial ne timu; vi valoras pli, ol multaj paseroj.","Tial ne timu; vi valoras pli, ol multaj paseroj."],[10,32,"Ĉiun do, kiu konfesos min antaŭ homoj, mi ankaŭ konfesos antaŭ mia Patro, kiu estas en la ĉielo.","Ĉiun do, kiu konfesos min antaŭ homoj, mi ankaŭ konfesos antaŭ mia Patro, kiu estas en la ĉielo."],[10,33,"Sed kiu malkonfesos min antaŭ homoj, tiun mi ankaŭ malkonfesos antaŭ mia Patro, kiu estas en la ĉielo.","Sed kiu malkonfesos min antaŭ homoj, tiun mi ankaŭ malkonfesos antaŭ mia Patro, kiu estas en la ĉielo."],[10,34,"Ne supozu, ke mi venis, por enkonduki pacon sur la teron; mi venis, por enkonduki ne pacon, sed glavon.","Ne supozu, ke mi venis, por enkonduki pacon sur la teron; mi venis, por enkonduki ne pacon, sed glavon."],[10,35,"Ĉar mi venis, por kontraŭmeti viron kontraŭ lian patron, kaj filinon kontraŭ ŝian patrinon, kaj bofilinon kontraŭ ŝian bopatrinon;","Ĉar mi venis, por kontraŭmeti viron kontraŭ lian patron, kaj filinon kontraŭ ŝian patrinon, kaj bofilinon kontraŭ ŝian bopatrinon;"],[10,36,"kaj la domanoj de homo estos liaj malamikoj.","kaj la domanoj de homo estos liaj malamikoj."],[10,37,"Kiu amas patron aŭ patrinon pli ol min, tiu ne estas inda je mi; kaj kiu amas filon aŭ filinon pli ol min, tiu ne estas inda je mi.","Kiu amas patron aŭ patrinon pli ol min, tiu ne estas inda je mi; kaj kiu amas filon aŭ filinon pli ol min, tiu ne estas inda je mi."],[10,38,"Kaj kiu ne prenas sian krucon kaj sekvas post mi, tiu ne estas inda je mi.","Kaj kiu ne prenas sian krucon kaj sekvas post mi, tiu ne estas inda je mi."],[10,39,"Kiu trovas sian vivon, tiu ĝin perdos; kaj kiu perdas sian vivon pro mi, tiu ĝin trovos.","Kiu trovas sian vivon, tiu ĝin perdos; kaj kiu perdas sian vivon pro mi, tiu ĝin trovos."],[10,40,"Kiu vin akceptas, tiu min akceptas; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis.","Kiu vin akceptas, tiu min akceptas; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis."],[10,41,"Kiu akceptas profeton en la nomo de profeto, tiu ricevos rekompencon de profeto; kaj kiu akceptas justulon en la nomo de justulo, tiu ricevos rekompencon de justulo.","Kiu akceptas profeton en la nomo de profeto, tiu ricevos rekompencon de profeto; kaj kiu akceptas justulon en la nomo de justulo, tiu ricevos rekompencon de justulo."],[10,42,"Kaj kiu trinkigos nur tason da malvarma akvo al unu el ĉi tiuj malgranduloj en la nomo de disĉiplo, vere mi diras al vi, tiu neniel perdos sian rekompencon.","Kaj kiu trinkigos nur tason da malvarma akvo al unu el ĉi tiuj malgranduloj en la nomo de disĉiplo, vere mi diras al vi, tiu neniel perdos sian rekompencon."],[11,1,"Kaj kiam Jesuo finis siajn ordonojn al siaj dek du disĉiploj, li foriris de tie, por instrui kaj prediki en iliaj urboj.","Kaj kiam Jesuo finis siajn ordonojn al siaj dek du disĉiploj, li foriris de tie, por instrui kaj prediki en iliaj urboj."],[11,2,"Kaj kiam Johano aŭdis en la malliberejo pri la faroj de Kristo, li sendis per siaj disĉiploj,","Kaj kiam Johano aŭdis en la malliberejo pri la faroj de Kristo, li sendis per siaj disĉiploj,"],[11,3,"por diri al li: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?","por diri al li: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?"],[11,4,"Kaj Jesuo responde diris al ili: Iru kaj sciigu al Johano tion, kion vi aŭdas kaj vidas:","Kaj Jesuo responde diris al ili: Iru kaj sciigu al Johano tion, kion vi aŭdas kaj vidas:"],[11,5,"blinduloj ricevas vidpovon, kaj lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, kaj mortintoj leviĝas, kaj al malriĉuloj evangelio estas predikata.","blinduloj ricevas vidpovon, kaj lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, kaj mortintoj leviĝas, kaj al malriĉuloj evangelio estas predikata."],[11,6,"Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi.","Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi."],[11,7,"Kaj kiam ili foriris, Jesuo komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton por rigardi? ĉu junkon skuatan de la vento?","Kaj kiam ili foriris, Jesuo komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton por rigardi? ĉu junkon skuatan de la vento?"],[11,8,"Sed kion vi eliris por vidi? ĉu homon mole vestitan? Jen tiuj, kiuj portas molajn vestojn, troviĝas en domoj de reĝoj.","Sed kion vi eliris por vidi? ĉu homon mole vestitan? Jen tiuj, kiuj portas molajn vestojn, troviĝas en domoj de reĝoj."],[11,9,"Sed kion vi eliris por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton.","Sed kion vi eliris por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton."],[11,10,"Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon.","Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon."],[11,11,"Vere mi diras al vi: Inter naskitoj de virinoj ne aperis iu pli granda ol Johano, la Baptisto; tamen tiu, kiu estas nur malgranda en la regno de la ĉielo, estas pli granda ol li.","Vere mi diras al vi: Inter naskitoj de virinoj ne aperis iu pli granda ol Johano, la Baptisto; tamen tiu, kiu estas nur malgranda en la regno de la ĉielo, estas pli granda ol li."],[11,12,"Kaj de post la tagoj de Johano, la Baptisto, ĝis nun, la regno de la ĉielo estas perfortata, kaj perfortuloj kaptas ĝin.","Kaj de post la tagoj de Johano, la Baptisto, ĝis nun, la regno de la ĉielo estas perfortata, kaj perfortuloj kaptas ĝin."],[11,13,"Ĉar ĉiuj profetoj kaj la leĝo profetis ĝis Johano.","Ĉar ĉiuj profetoj kaj la leĝo profetis ĝis Johano."],[11,14,"Kaj se vi volas tion ricevi, tiu estas Elija, kiu estis venonta.","Kaj se vi volas tion ricevi, tiu estas Elija, kiu estis venonta."],[11,15,"Kiu havas orelon por aŭdi, tiu aŭdu.","Kiu havas orelon por aŭdi, tiu aŭdu."],[11,16,"Sed al kio mi komparu ĉi tiun generacion? Ĝi similas al infanoj, kiuj sidas sur la placoj, kaj vokas al la ceteraj,","Sed al kio mi komparu ĉi tiun generacion? Ĝi similas al infanoj, kiuj sidas sur la placoj, kaj vokas al la ceteraj,"],[11,17,"dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris.","dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris."],[11,18,"Ĉar venis Johano, nek manĝante nek trinkante, kaj ili diras: Li havas demonon.","Ĉar venis Johano, nek manĝante nek trinkante, kaj ili diras: Li havas demonon."],[11,19,"La Filo de homo venis, manĝante kaj trinkante, kaj ili diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj! Kaj la saĝeco estas pravigita de siaj faroj.","La Filo de homo venis, manĝante kaj trinkante, kaj ili diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj! Kaj la saĝeco estas pravigita de siaj faroj."],[11,20,"Tiam li komenci riproĉi la urbojn, en kiuj estis faritaj la plej multaj el liaj potencaj faroj; ĉar ili ne pentis.","Tiam li komenci riproĉi la urbojn, en kiuj estis faritaj la plej multaj el liaj potencaj faroj; ĉar ili ne pentis."],[11,21,"Ve al vi, Ĥorazin! Ve al vi, Betsaida! Ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, antaŭ longe ili jam pentus en sakaĵo kaj cindro.","Ve al vi, Ĥorazin! Ve al vi, Betsaida! Ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, antaŭ longe ili jam pentus en sakaĵo kaj cindro."],[11,22,"Tamen mi diras al vi: Estos pli elporteble por Tiro kaj Cidon en la tago de juĝado, ol por vi.","Tamen mi diras al vi: Estos pli elporteble por Tiro kaj Cidon en la tago de juĝado, ol por vi."],[11,23,"Kaj vi, Kapernaum! ĉu vi estos altigita ĝis la ĉielo? vi malsupreniĝos ĝis Hades; ĉar se en Sodom estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, ĝi restus ĝis hodiaŭ.","Kaj vi, Kapernaum! ĉu vi estos altigita ĝis la ĉielo? vi malsupreniĝos ĝis Hades; ĉar se en Sodom estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, ĝi restus ĝis hodiaŭ."],[11,24,"Tamen mi diras al vi: Estos pli elporteble por la lando de Sodom en la tago de juĝado, ol por vi.","Tamen mi diras al vi: Estos pli elporteble por la lando de Sodom en la tago de juĝado, ol por vi."],[11,25,"En tiu tempo Jesuo ekparolis kaj diris: Mi Vin gloras, ho Patro, Sinjoro de la ĉielo kaj la tero, ke tion Vi kaŝis for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanoj;","En tiu tempo Jesuo ekparolis kaj diris: Mi Vin gloras, ho Patro, Sinjoro de la ĉielo kaj la tero, ke tion Vi kaŝis for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanoj;"],[11,26,"jes, Patro, ĉar tiel estis bone antaŭ Vi.","jes, Patro, ĉar tiel estis bone antaŭ Vi."],[11,27,"Ĉio estas transdonita al mi de mia Patro, kaj neniu konas la Filon krom la Patro, nek iu konas la Patron krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin.","Ĉio estas transdonita al mi de mia Patro, kaj neniu konas la Filon krom la Patro, nek iu konas la Patron krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin."],[11,28,"Venu al mi ĉiuj, kiuj estas laborantaj kaj ŝarĝitaj, kaj mi vin ripozigos.","Venu al mi ĉiuj, kiuj estas laborantaj kaj ŝarĝitaj, kaj mi vin ripozigos."],[11,29,"Metu sur vin mian jugon, kaj lernu ĉe mi, ĉar mi estas milda kaj korhumila; kaj vi trovos ripozon por viaj animoj.","Metu sur vin mian jugon, kaj lernu ĉe mi, ĉar mi estas milda kaj korhumila; kaj vi trovos ripozon por viaj animoj."],[11,30,"Ĉar mia jugo estas facila, kaj mia ŝarĝo estas malpeza.","Ĉar mia jugo estas facila, kaj mia ŝarĝo estas malpeza."],[12,1,"En tiu tempo Jesuo iris en sabato tra la grenkampoj, kaj liaj disĉiploj malsatis, kaj komencis deŝiri spikojn, kaj manĝi.","En tiu tempo Jesuo iris en sabato tra la grenkampoj, kaj liaj disĉiploj malsatis, kaj komencis deŝiri spikojn, kaj manĝi."],[12,2,"Sed la Fariseoj, vidinte, diris al li: Jen viaj disĉiploj faras tion, kio ne estas permesata en sabato.","Sed la Fariseoj, vidinte, diris al li: Jen viaj disĉiploj faras tion, kio ne estas permesata en sabato."],[12,3,"Sed li diris al ili: Ĉu vi ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?","Sed li diris al ili: Ĉu vi ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?"],[12,4,"ke li eniris en la domon de Dio, kaj manĝis la panojn de propono, kiujn manĝi ne estis permesate al li, nek al liaj kunuloj, sed nur al la pastroj?","ke li eniris en la domon de Dio, kaj manĝis la panojn de propono, kiujn manĝi ne estis permesate al li, nek al liaj kunuloj, sed nur al la pastroj?"],[12,5,"Kaj ĉu vi ne legis en la leĝo, kiel en sabato la pastroj en la templo profanas la sabaton kaj estas senkulpaj?","Kaj ĉu vi ne legis en la leĝo, kiel en sabato la pastroj en la templo profanas la sabaton kaj estas senkulpaj?"],[12,6,"Sed mi diras al vi, ke alestas ĉi tie io pli granda ol la templo.","Sed mi diras al vi, ke alestas ĉi tie io pli granda ol la templo."],[12,7,"Sed se vi komprenus, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; vi ne kondamnus la senkulpajn.","Sed se vi komprenus, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; vi ne kondamnus la senkulpajn."],[12,8,"Ĉar la Filo de homo estas sinjoro de la sabato.","Ĉar la Filo de homo estas sinjoro de la sabato."],[12,9,"Kaj li foriris de tie, kaj eniris en ilian sinagogon;","Kaj li foriris de tie, kaj eniris en ilian sinagogon;"],[12,10,"kaj jen viro, havanta manon velkintan. Kaj oni demandis al li, dirante: Ĉu estas permesate sanigi en sabato? por ke ili povu lin akuzi.","kaj jen viro, havanta manon velkintan. Kaj oni demandis al li, dirante: Ĉu estas permesate sanigi en sabato? por ke ili povu lin akuzi."],[12,11,"Kaj li diris al ili: Kiu el vi, havanta unu ŝafon, se ĝi falos en fosaĵon en sabato, ne ekprenos kaj levos ĝin?","Kaj li diris al ili: Kiu el vi, havanta unu ŝafon, se ĝi falos en fosaĵon en sabato, ne ekprenos kaj levos ĝin?"],[12,12,"Kiom do viro superas ŝafon! Tial estas permesate bonfari en sabato.","Kiom do viro superas ŝafon! Tial estas permesate bonfari en sabato."],[12,13,"Tiam li diris al la viro: Etendu vian manon. Kaj ĉi tiu etendis ĝin, kaj ĝi tute resaniĝis kiel la alia.","Tiam li diris al la viro: Etendu vian manon. Kaj ĉi tiu etendis ĝin, kaj ĝi tute resaniĝis kiel la alia."],[12,14,"Sed la Fariseoj eliris, kaj konsiliĝis kontraŭ li, kiamaniere lin pereigi.","Sed la Fariseoj eliris, kaj konsiliĝis kontraŭ li, kiamaniere lin pereigi."],[12,15,"Kaj Jesuo, eksciante, foriris de tie, kaj multaj lin sekvis; kaj li sanigis ilin ĉiujn,","Kaj Jesuo, eksciante, foriris de tie, kaj multaj lin sekvis; kaj li sanigis ilin ĉiujn,"],[12,16,"kaj admonis ilin, ke ili ne konatigu lin;","kaj admonis ilin, ke ili ne konatigu lin;"],[12,17,"por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:","por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:"],[12,18,"Jen estas Mia servanto, kiun Mi elektis, Mia amata, en kiu Mia animo havas plezuron. Mi metos Mian Spiriton sur lin; Kaj li proklamos justecon al la nacioj.","Jen estas Mia servanto, kiun Mi elektis, Mia amata, en kiu Mia animo havas plezuron. Mi metos Mian Spiriton sur lin; Kaj li proklamos justecon al la nacioj."],[12,19,"Li ne disputados, nek laŭte krios; Kaj oni ne aŭdos sur la stratoj lian voĉon.","Li ne disputados, nek laŭte krios; Kaj oni ne aŭdos sur la stratoj lian voĉon."],[12,20,"Kanon rompetitan li ne rompos, Kaj meĉon senfajriĝantan li ne estingos, Ĝis li elsendos juĝon por venko.","Kanon rompetitan li ne rompos, Kaj meĉon senfajriĝantan li ne estingos, Ĝis li elsendos juĝon por venko."],[12,21,"Kaj al lia nomo esperos la nacioj.","Kaj al lia nomo esperos la nacioj."],[12,22,"Tiam oni kondukis al li demonhavanton, blindan kaj mutan; kaj li sanigis lin, tiel ke la mutulo parolis kaj vidis.","Tiam oni kondukis al li demonhavanton, blindan kaj mutan; kaj li sanigis lin, tiel ke la mutulo parolis kaj vidis."],[12,23,"Kaj miris ĉiuj homamasoj, kaj diris: Ĉu ĉi tiu estas la filo de David?","Kaj miris ĉiuj homamasoj, kaj diris: Ĉu ĉi tiu estas la filo de David?"],[12,24,"Sed la Fariseoj, aŭdinte, diris: Ĉi tiu ne elpelas demonojn krom per Baal-Zebub, estro de la demonoj.","Sed la Fariseoj, aŭdinte, diris: Ĉi tiu ne elpelas demonojn krom per Baal-Zebub, estro de la demonoj."],[12,25,"Kaj sciante iliajn pensojn, li diris al ili: Ĉiu regno dividita kontraŭ si dezertiĝas, kaj ĉiu urbo aŭ domo dividita kontraŭ si ne starados;","Kaj sciante iliajn pensojn, li diris al ili: Ĉiu regno dividita kontraŭ si dezertiĝas, kaj ĉiu urbo aŭ domo dividita kontraŭ si ne starados;"],[12,26,"kaj se Satano elpelas Satanon, li estas dividita kontraŭ si; kiel do staros lia regno?","kaj se Satano elpelas Satanon, li estas dividita kontraŭ si; kiel do staros lia regno?"],[12,27,"Kaj se mi per Baal-Zebub elpelas demonojn, per kiu viaj filoj elpelas ilin? tial ili estos viaj juĝantoj.","Kaj se mi per Baal-Zebub elpelas demonojn, per kiu viaj filoj elpelas ilin? tial ili estos viaj juĝantoj."],[12,28,"Sed se mi per la Spirito de Dio elpelas demonojn, tiam la regno de Dio estas veninta sur vin.","Sed se mi per la Spirito de Dio elpelas demonojn, tiam la regno de Dio estas veninta sur vin."],[12,29,"Kaj kiel oni povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon? kaj poste li trarabos lian domon.","Kaj kiel oni povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon? kaj poste li trarabos lian domon."],[12,30,"Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas.","Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas."],[12,31,"Tial mi diras al vi: Ĉia peko kaj ĉia blasfemo estos pardonita el homoj; sed la blasfemo kontraŭ la Spirito ne estos pardonita.","Tial mi diras al vi: Ĉia peko kaj ĉia blasfemo estos pardonita el homoj; sed la blasfemo kontraŭ la Spirito ne estos pardonita."],[12,32,"Kaj al iu, kiu parolos vorton kontraŭ la Filo de homo, tio estos pardonita; sed al iu, kiu parolos kontraŭ la Sankta Spirito, tio ne estos pardonita en ĉi tiu mondo, nek en la venonta.","Kaj al iu, kiu parolos vorton kontraŭ la Filo de homo, tio estos pardonita; sed al iu, kiu parolos kontraŭ la Sankta Spirito, tio ne estos pardonita en ĉi tiu mondo, nek en la venonta."],[12,33,"Aŭ faru la arbon bona kaj ĝian frukton bona, aŭ faru la arbon malbona kaj ĝian frukton malbona; ĉar la arbo estas konata per la frukto.","Aŭ faru la arbon bona kaj ĝian frukton bona, aŭ faru la arbon malbona kaj ĝian frukton malbona; ĉar la arbo estas konata per la frukto."],[12,34,"Ho vipuridoj! kiel vi povas paroli bonaĵojn, estante malbonaj? ĉar el la abundo de la koro la buŝo parolas.","Ho vipuridoj! kiel vi povas paroli bonaĵojn, estante malbonaj? ĉar el la abundo de la koro la buŝo parolas."],[12,35,"La bona homo el sia bona trezoro elmetas bonaĵojn; kaj la malbona homo el sia malbona trezoro elmetas malbonaĵojn.","La bona homo el sia bona trezoro elmetas bonaĵojn; kaj la malbona homo el sia malbona trezoro elmetas malbonaĵojn."],[12,36,"Kaj mi diras al vi, ke pro ĉiu senutila vorto, kiun homoj parolos, ili donos respondon en la tago de juĝado.","Kaj mi diras al vi, ke pro ĉiu senutila vorto, kiun homoj parolos, ili donos respondon en la tago de juĝado."],[12,37,"Ĉar laŭ viaj vortoj vi estos pravigitaj, kaj laŭ viaj vortoj vi estos kondamnitaj.","Ĉar laŭ viaj vortoj vi estos pravigitaj, kaj laŭ viaj vortoj vi estos kondamnitaj."],[12,38,"Tiam iuj el la skribistoj kaj Fariseoj respondis al li, dirante: Majstro, ni deziras vidi signon de vi.","Tiam iuj el la skribistoj kaj Fariseoj respondis al li, dirante: Majstro, ni deziras vidi signon de vi."],[12,39,"Sed li respondis kaj diris al ili: Malbona kaj adultema generacio serĉas signon; kaj neniu signo estos donita al ĝi krom la signo de la profeto Jona;","Sed li respondis kaj diris al ili: Malbona kaj adultema generacio serĉas signon; kaj neniu signo estos donita al ĝi krom la signo de la profeto Jona;"],[12,40,"ĉar kiel Jona estis tri tagojn kaj tri noktojn en la ventro de la marmonstro, tiel la Filo de homo estos tri tagojn kaj tri noktojn en la koro de la tero.","ĉar kiel Jona estis tri tagojn kaj tri noktojn en la ventro de la marmonstro, tiel la Filo de homo estos tri tagojn kaj tri noktojn en la koro de la tero."],[12,41,"Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie.","Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie."],[12,42,"La reĝino de la sudo leviĝos en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie.","La reĝino de la sudo leviĝos en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie."],[12,43,"Sed kiam la malpura spirito eliras el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon, sed ne trovas ĝin.","Sed kiam la malpura spirito eliras el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon, sed ne trovas ĝin."],[12,44,"Tiam ĝi diras: Mi reiros al mia domo, el kie mi eliris. Kaj alveninte, ĝi trovas ĝin vakanta, balaita, kaj ornamita.","Tiam ĝi diras: Mi reiros al mia domo, el kie mi eliris. Kaj alveninte, ĝi trovas ĝin vakanta, balaita, kaj ornamita."],[12,45,"Tiam ĝi iras, kaj kunprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili eniras kaj loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua. Tiel estos ankaŭ al ĉi tiu malbona generacio.","Tiam ĝi iras, kaj kunprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili eniras kaj loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua. Tiel estos ankaŭ al ĉi tiu malbona generacio."],[12,46,"Dum li ankoraŭ parolis al la homamasoj, jen lia patrino kaj liaj fratoj staris ekstere, dezirantaj paroli kun li.","Dum li ankoraŭ parolis al la homamasoj, jen lia patrino kaj liaj fratoj staris ekstere, dezirantaj paroli kun li."],[12,47,"Kaj iu diris al li: Jen via patrino kaj viaj fratoj staras ekstere, dezirantaj paroli kun vi.","Kaj iu diris al li: Jen via patrino kaj viaj fratoj staras ekstere, dezirantaj paroli kun vi."],[12,48,"Sed li responde diris al tiu, kiu parolis al li: Kiu estas mia patrino? kaj kiuj estas miaj fratoj?","Sed li responde diris al tiu, kiu parolis al li: Kiu estas mia patrino? kaj kiuj estas miaj fratoj?"],[12,49,"Kaj etendinte la manon al siaj disĉiploj, li diris: Jen mia patrino kaj miaj fratoj!","Kaj etendinte la manon al siaj disĉiploj, li diris: Jen mia patrino kaj miaj fratoj!"],[12,50,"Ĉar kiu ajn faros la volon de mia Patro, kiu estas en la ĉielo, tiu estas mia frato kaj mia fratino kaj mia patrino.","Ĉar kiu ajn faros la volon de mia Patro, kiu estas en la ĉielo, tiu estas mia frato kaj mia fratino kaj mia patrino."],[13,1,"En tiu tago Jesuo eliris el la domo kaj sidiĝis apud la maro.","En tiu tago Jesuo eliris el la domo kaj sidiĝis apud la maro."],[13,2,"Kaj kolektiĝis al li grandaj homamasoj, tiel ke li eniris en ŝipeton, kaj sidis; kaj la tuta homamaso staris sur la marbordo.","Kaj kolektiĝis al li grandaj homamasoj, tiel ke li eniris en ŝipeton, kaj sidis; kaj la tuta homamaso staris sur la marbordo."],[13,3,"Kaj li multe parolis al ili per paraboloj, dirante: Jen semisto eliris, por semi;","Kaj li multe parolis al ili per paraboloj, dirante: Jen semisto eliris, por semi;"],[13,4,"kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin;","kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin;"],[13,5,"kaj aliaj falis sur ŝtonajn lokojn, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;","kaj aliaj falis sur ŝtonajn lokojn, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;"],[13,6,"kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis.","kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis."],[13,7,"Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin;","Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin;"],[13,8,"kaj aliaj falis sur la bonan teron, kaj donis frukton, jen centoble, jen sesdekoble, jen tridekoble.","kaj aliaj falis sur la bonan teron, kaj donis frukton, jen centoble, jen sesdekoble, jen tridekoble."],[13,9,"Kiu havas orelojn, tiu aŭdu.","Kiu havas orelojn, tiu aŭdu."],[13,10,"Kaj la disĉiploj venis, kaj diris al li: Kial vi parolas al ili per paraboloj?","Kaj la disĉiploj venis, kaj diris al li: Kial vi parolas al ili per paraboloj?"],[13,11,"Kaj li respondis kaj diris al ili: Al vi estas donite scii la misterojn de la regno de la ĉielo, sed al ili ne estas donite.","Kaj li respondis kaj diris al ili: Al vi estas donite scii la misterojn de la regno de la ĉielo, sed al ili ne estas donite."],[13,12,"Ĉar kiu ajn havas, al tiu estos donite, kaj li havos abundon; sed kiu ajn ne havas, for de tiu estos prenita eĉ tio, kion li havas.","Ĉar kiu ajn havas, al tiu estos donite, kaj li havos abundon; sed kiu ajn ne havas, for de tiu estos prenita eĉ tio, kion li havas."],[13,13,"Tial mi parolas al ili per paraboloj; ĉar vidante, ili ne rimarkas, kaj aŭdante, ili ne aŭdas nek komprenas.","Tial mi parolas al ili per paraboloj; ĉar vidante, ili ne rimarkas, kaj aŭdante, ili ne aŭdas nek komprenas."],[13,14,"Kaj por ili plenumiĝis tiu profetaĵo de Jesaja, kiu diras: Aŭdante, vi aŭdos, sed ne komprenos; Kaj vidante, vi vidos, sed ne rimarkos;","Kaj por ili plenumiĝis tiu profetaĵo de Jesaja, kiu diras: Aŭdante, vi aŭdos, sed ne komprenos; Kaj vidante, vi vidos, sed ne rimarkos;"],[13,15,"Ĉar la koro de tiu popolo grasiĝis, Kaj iliaj oreloj aŭdas malklare, Kaj siajn okulojn ili fermis; Por ke ili ne vidu per siaj okuloj, Kaj ne aŭdu per siaj oreloj, Kaj ne komprenu per sia koro, Kaj ne rekonvertiĝu, Kaj ke Mi ne sanigu ilin.","Ĉar la koro de tiu popolo grasiĝis, Kaj iliaj oreloj aŭdas malklare, Kaj siajn okulojn ili fermis; Por ke ili ne vidu per siaj okuloj, Kaj ne aŭdu per siaj oreloj, Kaj ne komprenu per sia koro, Kaj ne rekonvertiĝu, Kaj ke Mi ne sanigu ilin."],[13,16,"Sed feliĉaj estas viaj okuloj, ĉar ili vidas; kaj viaj oreloj, ĉar ili aŭdas.","Sed feliĉaj estas viaj okuloj, ĉar ili vidas; kaj viaj oreloj, ĉar ili aŭdas."],[13,17,"Vere mi diras al vi, ke multaj profetoj kaj justuloj deziris vidi tion, kion vi vidas, sed ili ne vidis; kaj aŭdi tion, kion vi aŭdas, sed ili ne aŭdis.","Vere mi diras al vi, ke multaj profetoj kaj justuloj deziris vidi tion, kion vi vidas, sed ili ne vidis; kaj aŭdi tion, kion vi aŭdas, sed ili ne aŭdis."],[13,18,"Vi do aŭdu la parabolon de la semisto.","Vi do aŭdu la parabolon de la semisto."],[13,19,"Kiam iu aŭdas la vorton de la regno kaj ne komprenas ĝin, tiam venas la malbonulo, kaj forprenas tion, kio estas semita en lia koro. Ĉi tiu estas la ricevinta semon apud la vojo.","Kiam iu aŭdas la vorton de la regno kaj ne komprenas ĝin, tiam venas la malbonulo, kaj forprenas tion, kio estas semita en lia koro. Ĉi tiu estas la ricevinta semon apud la vojo."],[13,20,"Kaj tiu, kiu ricevis semon sur la ŝtonaj lokoj, estas tiu, kiu aŭdas la vorton kaj tuj kun ĝojo akceptas ĝin;","Kaj tiu, kiu ricevis semon sur la ŝtonaj lokoj, estas tiu, kiu aŭdas la vorton kaj tuj kun ĝojo akceptas ĝin;"],[13,21,"sed li ne havas radikon en si, sed restas nur portempe, kaj kiam venas sufero aŭ persekuto pro la vorto, tuj li falpuŝiĝas.","sed li ne havas radikon en si, sed restas nur portempe, kaj kiam venas sufero aŭ persekuto pro la vorto, tuj li falpuŝiĝas."],[13,22,"Kaj kiu ricevis semon inter la dornoj, estas tiu, kiu aŭdas la vorton; sed la zorgoj de la mondo kaj la trompo de riĉo sufokas la vorton, kaj li fariĝas senfrukta.","Kaj kiu ricevis semon inter la dornoj, estas tiu, kiu aŭdas la vorton; sed la zorgoj de la mondo kaj la trompo de riĉo sufokas la vorton, kaj li fariĝas senfrukta."],[13,23,"Kaj kiu ricevis semon sur la bona tero, estas tiu, kiu aŭdas la vorton kaj komprenas ĝin; kaj tiu ja portas frukton, kaj donas, jen centoble, jen sesdekoble, jen tridekoble.","Kaj kiu ricevis semon sur la bona tero, estas tiu, kiu aŭdas la vorton kaj komprenas ĝin; kaj tiu ja portas frukton, kaj donas, jen centoble, jen sesdekoble, jen tridekoble."],[13,24,"Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al homo, kiu semis bonan semon en sia kampo;","Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al homo, kiu semis bonan semon en sia kampo;"],[13,25,"sed dum homoj dormis, lia malamiko venis kaj semis lolon meze de la tritiko, kaj foriris.","sed dum homoj dormis, lia malamiko venis kaj semis lolon meze de la tritiko, kaj foriris."],[13,26,"Kaj kiam la trunketo kreskis kaj donis frukton, tiam aperis ankaŭ la lolo.","Kaj kiam la trunketo kreskis kaj donis frukton, tiam aperis ankaŭ la lolo."],[13,27,"Kaj la sklavoj de la dommastro venis, kaj diris al li: Sinjoro, ĉu vi ne semis bonan semon en via kampo? De kie do ĝi havas lolon?","Kaj la sklavoj de la dommastro venis, kaj diris al li: Sinjoro, ĉu vi ne semis bonan semon en via kampo? De kie do ĝi havas lolon?"],[13,28,"Kaj li diris al ili: Iu malamiko faris tion. Kaj la sklavoj diris al li: Ĉu vi do volas, ke ni iru kaj kolektu ĝin?","Kaj li diris al ili: Iu malamiko faris tion. Kaj la sklavoj diris al li: Ĉu vi do volas, ke ni iru kaj kolektu ĝin?"],[13,29,"Sed li diris: Ne; por ke, kolektante la lolon, vi ne elradikigu ankaŭ la tritikon.","Sed li diris: Ne; por ke, kolektante la lolon, vi ne elradikigu ankaŭ la tritikon."],[13,30,"Lasu al ambaŭ kreski kune ĝis la rikolto; kaj en la tempo de la rikolto mi diros al la rikoltistoj: Kolektu unue la lolon, kaj ligu ĝin en faskojn, por bruligi ĝin; sed kolektu la tritikon en mian grenejon.","Lasu al ambaŭ kreski kune ĝis la rikolto; kaj en la tempo de la rikolto mi diros al la rikoltistoj: Kolektu unue la lolon, kaj ligu ĝin en faskojn, por bruligi ĝin; sed kolektu la tritikon en mian grenejon."],[13,31,"Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al sinapa semeto, kiun viro prenis kaj semis en sia kampo;","Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al sinapa semeto, kiun viro prenis kaj semis en sia kampo;"],[13,32,"ĝi vere estas pli malgranda ol ĉiuj semoj, sed kreskinte, ĝi estas pli granda ol la legomoj, kaj fariĝas arbo, tiel ke venas la birdoj de la ĉielo kaj loĝas en ĝiaj branĉoj.","ĝi vere estas pli malgranda ol ĉiuj semoj, sed kreskinte, ĝi estas pli granda ol la legomoj, kaj fariĝas arbo, tiel ke venas la birdoj de la ĉielo kaj loĝas en ĝiaj branĉoj."],[13,33,"Alian parabolon li parolis al ili: La regno de la ĉielo similas al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezurojn da faruno, ĝis la tuto fermentis.","Alian parabolon li parolis al ili: La regno de la ĉielo similas al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezurojn da faruno, ĝis la tuto fermentis."],[13,34,"Ĉion tion parolis Jesuo per paraboloj al la homamasoj, kaj sen parabolo li parolis nenion al ili;","Ĉion tion parolis Jesuo per paraboloj al la homamasoj, kaj sen parabolo li parolis nenion al ili;"],[13,35,"por ke plenumiĝu tio, kio estis dirita per la profeto, nome: Mi malfermos per sentenco mian buŝon; Mi eldiros enigmojn el tempo antikva.","por ke plenumiĝu tio, kio estis dirita per la profeto, nome: Mi malfermos per sentenco mian buŝon; Mi eldiros enigmojn el tempo antikva."],[13,36,"Tiam forsendinte la homamasojn, li venis en la domon; kaj liaj disĉiploj venis al li, dirante: Klarigu al ni la parabolon pri la lolo de la kampo.","Tiam forsendinte la homamasojn, li venis en la domon; kaj liaj disĉiploj venis al li, dirante: Klarigu al ni la parabolon pri la lolo de la kampo."],[13,37,"Kaj responde li diris: Tiu, kiu semas la bonan semon, estas la Filo de homo;","Kaj responde li diris: Tiu, kiu semas la bonan semon, estas la Filo de homo;"],[13,38,"kaj la kampo estas la mondo; kaj la bonaj semoj estas la filoj de la regno; kaj la lolo estas la filoj de la malbonulo;","kaj la kampo estas la mondo; kaj la bonaj semoj estas la filoj de la regno; kaj la lolo estas la filoj de la malbonulo;"],[13,39,"kaj la malamiko, kiu ilin semis, estas la diablo; kaj la rikolto estas la fino de la mondaĝo; kaj la rikoltistoj estas anĝeloj.","kaj la malamiko, kiu ilin semis, estas la diablo; kaj la rikolto estas la fino de la mondaĝo; kaj la rikoltistoj estas anĝeloj."],[13,40,"Kiel do la lolo estas kolektita kaj bruligita per fajro, tiel estos ĉe la fino de la mondaĝo.","Kiel do la lolo estas kolektita kaj bruligita per fajro, tiel estos ĉe la fino de la mondaĝo."],[13,41,"La Filo de homo elsendos siajn anĝelojn, kaj ili kolektos el lia regno ĉiun falpuŝilon, kaj ĉiujn, kiuj faras maljustecon,","La Filo de homo elsendos siajn anĝelojn, kaj ili kolektos el lia regno ĉiun falpuŝilon, kaj ĉiujn, kiuj faras maljustecon,"],[13,42,"kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj.","kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj."],[13,43,"Tiam la justuloj brilos kiel la suno en la regno de sia Patro. Kiu havas orelojn, tiu aŭdu.","Tiam la justuloj brilos kiel la suno en la regno de sia Patro. Kiu havas orelojn, tiu aŭdu."],[13,44,"La regno de la ĉielo similas al kaŝita en kampo trezoro, kiun viro trovis kaj kaŝis, kaj pro ĝojo li iras kaj vendas ĉion, kion li posedas, kaj aĉetas tiun kampon.","La regno de la ĉielo similas al kaŝita en kampo trezoro, kiun viro trovis kaj kaŝis, kaj pro ĝojo li iras kaj vendas ĉion, kion li posedas, kaj aĉetas tiun kampon."],[13,45,"Cetere, la regno de la ĉielo similas al komercisto, serĉanta belajn perlojn;","Cetere, la regno de la ĉielo similas al komercisto, serĉanta belajn perlojn;"],[13,46,"kaj trovinte unu multevaloran perlon, li iris kaj vendis ĉion, kion li posedis, kaj aĉetis ĝin.","kaj trovinte unu multevaloran perlon, li iris kaj vendis ĉion, kion li posedis, kaj aĉetis ĝin."],[13,47,"Plue, la regno de la ĉielo similas al reto, kiu estis ĵetita en la maron kaj kolektis el ĉiu speco,","Plue, la regno de la ĉielo similas al reto, kiu estis ĵetita en la maron kaj kolektis el ĉiu speco,"],[13,48,"kaj kiun, kiam ĝi pleniĝis, oni suprentiris al la marbordo; kaj sidiĝinte, ili kolektis la bonajn en ujojn, sed la malbonajn ili ĵetis eksteren.","kaj kiun, kiam ĝi pleniĝis, oni suprentiris al la marbordo; kaj sidiĝinte, ili kolektis la bonajn en ujojn, sed la malbonajn ili ĵetis eksteren."],[13,49,"Tiel estos en la fino de la mondaĝo: la anĝeloj eliros, kaj apartigos la malbonulojn el inter la justuloj,","Tiel estos en la fino de la mondaĝo: la anĝeloj eliros, kaj apartigos la malbonulojn el inter la justuloj,"],[13,50,"kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj.","kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj."],[13,51,"Ĉu vi komprenis ĉion tion? Ili diris al li: Jes.","Ĉu vi komprenis ĉion tion? Ili diris al li: Jes."],[13,52,"Kaj li diris al ili: Tial ĉiu skribisto, disĉipligita en la regnon de la ĉielo, similas al dommastro, kiu elportas el sia trezorejo objektojn novajn kaj malnovajn.","Kaj li diris al ili: Tial ĉiu skribisto, disĉipligita en la regnon de la ĉielo, similas al dommastro, kiu elportas el sia trezorejo objektojn novajn kaj malnovajn."],[13,53,"Kaj kiam Jesuo finis tiujn parabolojn, li foriris de tie.","Kaj kiam Jesuo finis tiujn parabolojn, li foriris de tie."],[13,54,"Kaj veninte en sian patrujon, li instruis ilin en ilia sinagogo, tiel ke ili miris, kaj diris: De kie ĉi tiu viro havas tian saĝecon kaj la potencaĵojn?","Kaj veninte en sian patrujon, li instruis ilin en ilia sinagogo, tiel ke ili miris, kaj diris: De kie ĉi tiu viro havas tian saĝecon kaj la potencaĵojn?"],[13,55,"Ĉu ĉi tiu ne estas la filo de la ĉarpentisto? ĉu lia patrino ne estas nomata Maria? kaj liaj fratoj Jakobo kaj Joses kaj Simon kaj Judas?","Ĉu ĉi tiu ne estas la filo de la ĉarpentisto? ĉu lia patrino ne estas nomata Maria? kaj liaj fratoj Jakobo kaj Joses kaj Simon kaj Judas?"],[13,56,"Kaj ĉu liaj fratinoj ne estas ĉiuj ĉe ni? De kie do li ĉion tion havas?","Kaj ĉu liaj fratinoj ne estas ĉiuj ĉe ni? De kie do li ĉion tion havas?"],[13,57,"Kaj ili ofendiĝis pro li. Sed Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj en sia domo.","Kaj ili ofendiĝis pro li. Sed Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj en sia domo."],[13,58,"Kaj pro ilia nekredemo li faris tie ne multajn potencaĵojn.","Kaj pro ilia nekredemo li faris tie ne multajn potencaĵojn."],[14,1,"En tiu tempo la tetrarĥo Herodo aŭdis la famon pri Jesuo,","En tiu tempo la tetrarĥo Herodo aŭdis la famon pri Jesuo,"],[14,2,"kaj diris al siaj servantoj: Tiu estas Johano, la Baptisto; li leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li.","kaj diris al siaj servantoj: Tiu estas Johano, la Baptisto; li leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li."],[14,3,"Ĉar Herodo jam arestis Johanon kaj ligis lin kaj metis lin en malliberejon pro Herodias, kiu estis edzino de lia frato Filipo.","Ĉar Herodo jam arestis Johanon kaj ligis lin kaj metis lin en malliberejon pro Herodias, kiu estis edzino de lia frato Filipo."],[14,4,"Ĉar Johano diris al li: Ne decas, ke vi havu ŝin.","Ĉar Johano diris al li: Ne decas, ke vi havu ŝin."],[14,5,"Kaj dezirante mortigi lin, li timis la popolon, ĉar oni opiniis lin profeto.","Kaj dezirante mortigi lin, li timis la popolon, ĉar oni opiniis lin profeto."],[14,6,"Sed kiam venis la naskotaga festo de Herodo, la filino de Herodias dancis en la mezo, kaj plaĉis al Herodo.","Sed kiam venis la naskotaga festo de Herodo, la filino de Herodias dancis en la mezo, kaj plaĉis al Herodo."],[14,7,"Tiam li ĵure promesis doni al ŝi ion ajn, kion ŝi petos.","Tiam li ĵure promesis doni al ŝi ion ajn, kion ŝi petos."],[14,8,"Kaj ŝi, instigite de sia patrino, diris: Donu al mi ĉi tie sur plado la kapon de Johano, la Baptisto.","Kaj ŝi, instigite de sia patrino, diris: Donu al mi ĉi tie sur plado la kapon de Johano, la Baptisto."],[14,9,"Kaj la reĝo malĝojis; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ordonis doni ĝin;","Kaj la reĝo malĝojis; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ordonis doni ĝin;"],[14,10,"kaj sendinte, li senkapigis Johanon en la malliberejo.","kaj sendinte, li senkapigis Johanon en la malliberejo."],[14,11,"Kaj oni alportis lian kapon sur plado, kaj donis ĝin al la knabino, kaj ŝi alportis ĝin al sia patrino.","Kaj oni alportis lian kapon sur plado, kaj donis ĝin al la knabino, kaj ŝi alportis ĝin al sia patrino."],[14,12,"Kaj liaj disĉiploj venis kaj forportis la korpon kaj enterigis ĝin, kaj ili iris kaj rakontis tion al Jesuo.","Kaj liaj disĉiploj venis kaj forportis la korpon kaj enterigis ĝin, kaj ili iris kaj rakontis tion al Jesuo."],[14,13,"Kaj Jesuo, aŭdinte, foriris de tie en ŝipeto al dezerta loko aparte; kaj la homamasoj, aŭdinte, sekvis lin, piedirante el la urboj.","Kaj Jesuo, aŭdinte, foriris de tie en ŝipeto al dezerta loko aparte; kaj la homamasoj, aŭdinte, sekvis lin, piedirante el la urboj."],[14,14,"Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, kaj sanigis iliajn malsanulojn.","Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, kaj sanigis iliajn malsanulojn."],[14,15,"Kaj kiam venis la vespero, liaj disĉiploj venis al li, dirante: La loko estas dezerta, kaj la horo jam pasis; forsendu la homamason, por ke ili iru en la vilaĝojn kaj aĉetu por si manĝaĵon.","Kaj kiam venis la vespero, liaj disĉiploj venis al li, dirante: La loko estas dezerta, kaj la horo jam pasis; forsendu la homamason, por ke ili iru en la vilaĝojn kaj aĉetu por si manĝaĵon."],[14,16,"Sed Jesuo diris al ili: Ili ne bezonas foriri; vi donu al ili manĝi.","Sed Jesuo diris al ili: Ili ne bezonas foriri; vi donu al ili manĝi."],[14,17,"Kaj ili diris al li: Ni nenion havas ĉi tie, krom kvin panoj kaj du fiŝoj.","Kaj ili diris al li: Ni nenion havas ĉi tie, krom kvin panoj kaj du fiŝoj."],[14,18,"Kaj li diris: Alportu ilin ĉi tien al mi.","Kaj li diris: Alportu ilin ĉi tien al mi."],[14,19,"Kaj li ordonis al la homamasoj sidiĝi sur la herbo; kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj.","Kaj li ordonis al la homamasoj sidiĝi sur la herbo; kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj."],[14,20,"Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du plenajn korbojn.","Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du plenajn korbojn."],[14,21,"Kaj la manĝantoj estis ĉirkaŭ kvin mil viroj, krom virinoj kaj infanoj.","Kaj la manĝantoj estis ĉirkaŭ kvin mil viroj, krom virinoj kaj infanoj."],[14,22,"Kaj tuj li devigis la disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, ĝis li forsendos la homamason.","Kaj tuj li devigis la disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, ĝis li forsendos la homamason."],[14,23,"Kaj forsendinte la homamason, li supreniris sur la monton sola, por preĝi; kaj kiam vesperiĝis, li estis tie sola.","Kaj forsendinte la homamason, li supreniris sur la monton sola, por preĝi; kaj kiam vesperiĝis, li estis tie sola."],[14,24,"Sed la ŝipeto jam estis meze de la maro, turmentata de la ondoj; ĉar la vento estis kontraŭa.","Sed la ŝipeto jam estis meze de la maro, turmentata de la ondoj; ĉar la vento estis kontraŭa."],[14,25,"Kaj en la kvara gardoparto de la nokto li venis al ili, irante sur la maro.","Kaj en la kvara gardoparto de la nokto li venis al ili, irante sur la maro."],[14,26,"Sed la disĉiploj, vidante lin iranta sur la maro, maltrankviliĝis, dirante: Jen fantomo; kaj ili ekkriis pro timo.","Sed la disĉiploj, vidante lin iranta sur la maro, maltrankviliĝis, dirante: Jen fantomo; kaj ili ekkriis pro timo."],[14,27,"Sed tuj Jesuo parolis al ili, dirante: Kuraĝu; ĝi estas mi; ne timu.","Sed tuj Jesuo parolis al ili, dirante: Kuraĝu; ĝi estas mi; ne timu."],[14,28,"Kaj responde al li Petro diris: Sinjoro, se ĝi estas vi, ordonu min veni al vi sur la akvo.","Kaj responde al li Petro diris: Sinjoro, se ĝi estas vi, ordonu min veni al vi sur la akvo."],[14,29,"Kaj li diris: Venu. Kaj Petro, malsuprenirinte el la ŝipeto, iris sur la akvo, por veni al Jesuo.","Kaj li diris: Venu. Kaj Petro, malsuprenirinte el la ŝipeto, iris sur la akvo, por veni al Jesuo."],[14,30,"Sed vidante la venton, li timis, kaj komencante subakviĝi, li ekkriis, dirante: Sinjoro, savu min.","Sed vidante la venton, li timis, kaj komencante subakviĝi, li ekkriis, dirante: Sinjoro, savu min."],[14,31,"Kaj tuj Jesuo etendis la manon kaj ektenis lin, dirante al li: Ho malgrandfidulo, kial vi dubis?","Kaj tuj Jesuo etendis la manon kaj ektenis lin, dirante al li: Ho malgrandfidulo, kial vi dubis?"],[14,32,"Kaj kiam ili supreniris en la ŝipeton, la vento ĉesiĝis.","Kaj kiam ili supreniris en la ŝipeton, la vento ĉesiĝis."],[14,33,"Kaj tiuj, kiuj estis en la ŝipeto, adorkliniĝis al li, dirante: Vere vi estas Filo de Dio.","Kaj tiuj, kiuj estis en la ŝipeto, adorkliniĝis al li, dirante: Vere vi estas Filo de Dio."],[14,34,"Kaj transirinte, ili alvenis teren ĉe Genesaret.","Kaj transirinte, ili alvenis teren ĉe Genesaret."],[14,35,"Kaj kiam la viroj de tiu loko ekkonis lin, ili sendis en la tutan ĉirkaŭaĵon, kaj venigis al li ĉiujn malsanulojn;","Kaj kiam la viroj de tiu loko ekkonis lin, ili sendis en la tutan ĉirkaŭaĵon, kaj venigis al li ĉiujn malsanulojn;"],[14,36,"kaj ili petis lin, ke ili nur tuŝu la randon de lia mantelo; kaj ĉiuj, kiuj tuŝis, estis tute resanigitaj.","kaj ili petis lin, ke ili nur tuŝu la randon de lia mantelo; kaj ĉiuj, kiuj tuŝis, estis tute resanigitaj."],[15,1,"Tiam alvenis al Jesuo el Jerusalem Fariseoj kaj skribistoj, dirante:","Tiam alvenis al Jesuo el Jerusalem Fariseoj kaj skribistoj, dirante:"],[15,2,"Kial viaj disĉiploj transpaŝas la tradicion de la antaŭuloj? ĉar ili ne lavas siajn manojn, kiam ili manĝas panon.","Kial viaj disĉiploj transpaŝas la tradicion de la antaŭuloj? ĉar ili ne lavas siajn manojn, kiam ili manĝas panon."],[15,3,"Kaj li responde diris al ili: Kial vi ankaŭ transpaŝas la ordonon de Dio per via tradicio?","Kaj li responde diris al ili: Kial vi ankaŭ transpaŝas la ordonon de Dio per via tradicio?"],[15,4,"Ĉar Dio diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu.","Ĉar Dio diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu."],[15,5,"Sed vi diras: Se iu diros al sia patro aŭ al sia patrino: Oferdono estu tio, per kio vi povus profiti de mi,","Sed vi diras: Se iu diros al sia patro aŭ al sia patrino: Oferdono estu tio, per kio vi povus profiti de mi,"],[15,6,"tiu ne devas respekti sian patron aŭ sian patrinon. Kaj vi vantigis la vorton de Dio per via tradicio.","tiu ne devas respekti sian patron aŭ sian patrinon. Kaj vi vantigis la vorton de Dio per via tradicio."],[15,7,"Ho hipokrituloj, bone profetis Jesaja pri vi, dirante:","Ho hipokrituloj, bone profetis Jesaja pri vi, dirante:"],[15,8,"Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi.","Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi."],[15,9,"Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj.","Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj."],[15,10,"Kaj alvokinte al si la homamason, li diris al ili: Aŭskultu kaj komprenu:","Kaj alvokinte al si la homamason, li diris al ili: Aŭskultu kaj komprenu:"],[15,11,"Ne tio, kio eniras en la buŝon, profanas la homon; sed kio eliras el la buŝo, tio profanas la homon.","Ne tio, kio eniras en la buŝon, profanas la homon; sed kio eliras el la buŝo, tio profanas la homon."],[15,12,"Tiam veninte, la disĉiploj diris al li: Ĉu vi scias, ke la Fariseoj ofendiĝis, kiam ili aŭdis tiun diron?","Tiam veninte, la disĉiploj diris al li: Ĉu vi scias, ke la Fariseoj ofendiĝis, kiam ili aŭdis tiun diron?"],[15,13,"Sed li responde diris: Ĉiu kreskaĵo, kiun mia ĉiela Patro ne plantis, estos elradikigita.","Sed li responde diris: Ĉiu kreskaĵo, kiun mia ĉiela Patro ne plantis, estos elradikigita."],[15,14,"Lasu ilin; ili estas blindaj kondukantoj de blinduloj. Kaj se blindulo kondukos blindulon, ambaŭ falos en fosaĵon.","Lasu ilin; ili estas blindaj kondukantoj de blinduloj. Kaj se blindulo kondukos blindulon, ambaŭ falos en fosaĵon."],[15,15,"Kaj Petro responde diris al li: Klarigu al ni tiun parabolon.","Kaj Petro responde diris al li: Klarigu al ni tiun parabolon."],[15,16,"Kaj li diris: Ĉu vi ankaŭ estas eĉ ankoraŭ sen kompreno?","Kaj li diris: Ĉu vi ankaŭ estas eĉ ankoraŭ sen kompreno?"],[15,17,"Ĉu vi ne konscias, ke ĉio, eniranta en la buŝon, pasas en la ventron kaj estas elĵetata en apartan lokon?","Ĉu vi ne konscias, ke ĉio, eniranta en la buŝon, pasas en la ventron kaj estas elĵetata en apartan lokon?"],[15,18,"Sed tio, kio eliras el la buŝo, elvenas el la koro, kaj profanas la homon.","Sed tio, kio eliras el la buŝo, elvenas el la koro, kaj profanas la homon."],[15,19,"Ĉar el la koro eliras malvirtaj pensoj, mortigoj, adultoj, malĉastaĵoj, ŝteloj, falsatestoj, blasfemoj:","Ĉar el la koro eliras malvirtaj pensoj, mortigoj, adultoj, malĉastaĵoj, ŝteloj, falsatestoj, blasfemoj:"],[15,20,"jen tio, kio profanas la homon, sed manĝi kun manoj nelavitaj ne profanas la homon.","jen tio, kio profanas la homon, sed manĝi kun manoj nelavitaj ne profanas la homon."],[15,21,"Kaj elirinte de tie, Jesuo foriris en la regionojn apud Tiro kaj Cidon.","Kaj elirinte de tie, Jesuo foriris en la regionojn apud Tiro kaj Cidon."],[15,22,"Kaj jen virino Kanaana, veninte el tiuj limlandoj, kriis, dirante: Ho Sinjoro, filo de David, kompatu min; mia filino estas terure turmentata de demono.","Kaj jen virino Kanaana, veninte el tiuj limlandoj, kriis, dirante: Ho Sinjoro, filo de David, kompatu min; mia filino estas terure turmentata de demono."],[15,23,"Sed li ne respondis al ŝi eĉ unu vorton. Kaj alveninte, liaj disĉiploj petis lin, dirante: Forsendu ŝin, ĉar ŝi krias post ni.","Sed li ne respondis al ŝi eĉ unu vorton. Kaj alveninte, liaj disĉiploj petis lin, dirante: Forsendu ŝin, ĉar ŝi krias post ni."],[15,24,"Kaj li responde diris: Mi ne estas sendita, krom al la perditaj ŝafoj el la domo de Izrael.","Kaj li responde diris: Mi ne estas sendita, krom al la perditaj ŝafoj el la domo de Izrael."],[15,25,"Sed ŝi venis kaj adorkliniĝis al li, dirante: Sinjoro, helpu min.","Sed ŝi venis kaj adorkliniĝis al li, dirante: Sinjoro, helpu min."],[15,26,"Sed li responde diris: Ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj.","Sed li responde diris: Ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj."],[15,27,"Sed ŝi diris: Jes, Sinjoro; ĉar eĉ la hundetoj manĝas el la panpecetoj, kiuj falas de la tablo de iliaj sinjoroj.","Sed ŝi diris: Jes, Sinjoro; ĉar eĉ la hundetoj manĝas el la panpecetoj, kiuj falas de la tablo de iliaj sinjoroj."],[15,28,"Tiam responde Jesuo diris al ŝi: Ho virino, granda estas via fido; estu al vi, kiel vi volas. Kaj ŝia filino estis sanigita de post tiu horo.","Tiam responde Jesuo diris al ŝi: Ho virino, granda estas via fido; estu al vi, kiel vi volas. Kaj ŝia filino estis sanigita de post tiu horo."],[15,29,"Kaj transirinte de tie, Jesuo venis apud la maron de Galileo; kaj suprenirinte sur la monton, li sidiĝis tie.","Kaj transirinte de tie, Jesuo venis apud la maron de Galileo; kaj suprenirinte sur la monton, li sidiĝis tie."],[15,30,"Kaj alvenis al li grandaj homamasoj, havante kun si homojn lamajn, blindajn, mutajn, kriplajn, kun multaj aliaj, kaj metis ilin apud liajn piedojn; kaj li sanigis ilin;","Kaj alvenis al li grandaj homamasoj, havante kun si homojn lamajn, blindajn, mutajn, kriplajn, kun multaj aliaj, kaj metis ilin apud liajn piedojn; kaj li sanigis ilin;"],[15,31,"tiel ke la homamaso miris, vidante mutulojn parolantaj, kriplulojn sanaj, kaj lamulojn piedirantaj, kaj blindulojn vidantaj; kaj ili gloris la Dion de Izrael.","tiel ke la homamaso miris, vidante mutulojn parolantaj, kriplulojn sanaj, kaj lamulojn piedirantaj, kaj blindulojn vidantaj; kaj ili gloris la Dion de Izrael."],[15,32,"Kaj Jesuo, alvokinte al si siajn disĉiplojn, diris: Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi, kaj nenion havas manĝi; kaj mi ne volas forsendi ilin fastantaj, por ke ili ne laciĝu sur la vojo.","Kaj Jesuo, alvokinte al si siajn disĉiplojn, diris: Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi, kaj nenion havas manĝi; kaj mi ne volas forsendi ilin fastantaj, por ke ili ne laciĝu sur la vojo."],[15,33,"Kaj la disĉiploj diris al li: De kie ni povas ricevi en la dezerto tiom da panoj, por satigi tiom da homoj?","Kaj la disĉiploj diris al li: De kie ni povas ricevi en la dezerto tiom da panoj, por satigi tiom da homoj?"],[15,34,"Kaj Jesuo diris al ili: Kiom da panoj vi havas? Kaj ili diris: Sep, kaj kelkajn malgrandajn fiŝojn.","Kaj Jesuo diris al ili: Kiom da panoj vi havas? Kaj ili diris: Sep, kaj kelkajn malgrandajn fiŝojn."],[15,35,"Kaj li ordonis al la homamaso sidiĝi sur la tero;","Kaj li ordonis al la homamaso sidiĝi sur la tero;"],[15,36,"kaj li prenis la sep panojn kaj la fiŝojn; kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj.","kaj li prenis la sep panojn kaj la fiŝojn; kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj."],[15,37,"Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn plenajn.","Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn plenajn."],[15,38,"Kaj la manĝantoj estis kvar mil viroj, krom virinoj kaj infanoj.","Kaj la manĝantoj estis kvar mil viroj, krom virinoj kaj infanoj."],[15,39,"Kaj forsendinte la homamasojn, li eniris en la ŝipeton, kaj venis en la regionojn de Magadan.","Kaj forsendinte la homamasojn, li eniris en la ŝipeton, kaj venis en la regionojn de Magadan."],[16,1,"Kaj alvenis la Fariseoj kaj la Sadukeoj, kaj por provi lin postulis, ke li montru al ili signon el la ĉielo.","Kaj alvenis la Fariseoj kaj la Sadukeoj, kaj por provi lin postulis, ke li montru al ili signon el la ĉielo."],[16,2,"Kaj responde li diris al ili: Kiam vesperiĝas, vi diras: Estos bona vetero, ĉar la ĉielo ruĝiĝas;","Kaj responde li diris al ili: Kiam vesperiĝas, vi diras: Estos bona vetero, ĉar la ĉielo ruĝiĝas;"],[16,3,"kaj frumatene: Estos hodiaŭ malbona vetero, ĉar la ĉielo ruĝiĝas kolere. La vizaĝon de la ĉielo vi povas juĝi, sed la signojn de la tempo vi ne povas.","kaj frumatene: Estos hodiaŭ malbona vetero, ĉar la ĉielo ruĝiĝas kolere. La vizaĝon de la ĉielo vi povas juĝi, sed la signojn de la tempo vi ne povas."],[16,4,"Generacio malbona kaj adultema serĉas signon; kaj signo ne estos donita al ĝi, krom la signo de Jona. Kaj lasinte ilin, li foriris.","Generacio malbona kaj adultema serĉas signon; kaj signo ne estos donita al ĝi, krom la signo de Jona. Kaj lasinte ilin, li foriris."],[16,5,"Kaj la disĉiploj, transirinte al la alia bordo, forgesis preni panojn.","Kaj la disĉiploj, transirinte al la alia bordo, forgesis preni panojn."],[16,6,"Sed Jesuo diris al ili: Zorgu, kaj gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj.","Sed Jesuo diris al ili: Zorgu, kaj gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj."],[16,7,"Kaj ili diskutis inter si, dirante: Ĉar ni ne prenis panojn.","Kaj ili diskutis inter si, dirante: Ĉar ni ne prenis panojn."],[16,8,"Sed Jesuo, eksciante tion, diris: Kial vi diskutas inter vi, ho malgrandfiduloj, pro tio, ke vi ne prenis panojn?","Sed Jesuo, eksciante tion, diris: Kial vi diskutas inter vi, ho malgrandfiduloj, pro tio, ke vi ne prenis panojn?"],[16,9,"Ĉu vi ankoraŭ ne konscias, nek memoras la kvin panojn de la kvin mil, kaj kiom da korboj vi kolektis?","Ĉu vi ankoraŭ ne konscias, nek memoras la kvin panojn de la kvin mil, kaj kiom da korboj vi kolektis?"],[16,10,"Nek la sep panojn de la kvar mil, kaj kiom da korbegoj vi kolektis?","Nek la sep panojn de la kvar mil, kaj kiom da korbegoj vi kolektis?"],[16,11,"Kial vi ne komprenas, ke ne pri panoj mi diris al vi: Gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj?","Kial vi ne komprenas, ke ne pri panoj mi diris al vi: Gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj?"],[16,12,"Tiam ili ekkomprenis, ke li admonis ilin sin gardi ne kontraŭ la fermentaĵo de panoj, sed kontraŭ la instruado de la Fariseoj kaj Sadukeoj.","Tiam ili ekkomprenis, ke li admonis ilin sin gardi ne kontraŭ la fermentaĵo de panoj, sed kontraŭ la instruado de la Fariseoj kaj Sadukeoj."],[16,13,"Kaj Jesuo, veninte en la regionojn de Cezarea Filipi, demandis siajn disĉiplojn, dirante: Kiu, diras la homoj, ke mi, la Filo de homo, estas?","Kaj Jesuo, veninte en la regionojn de Cezarea Filipi, demandis siajn disĉiplojn, dirante: Kiu, diras la homoj, ke mi, la Filo de homo, estas?"],[16,14,"Kaj ili diris: Laŭ iuj: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Jeremia, aŭ unu el la profetoj.","Kaj ili diris: Laŭ iuj: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Jeremia, aŭ unu el la profetoj."],[16,15,"Li diris al ili: Sed vi, kiu vi diras, ke mi estas?","Li diris al ili: Sed vi, kiu vi diras, ke mi estas?"],[16,16,"Kaj responde Simon Petro diris: Vi estas la Kristo, la Filo de la vivanta Dio.","Kaj responde Simon Petro diris: Vi estas la Kristo, la Filo de la vivanta Dio."],[16,17,"Kaj Jesuo responde diris al li: Feliĉa vi estas, Simon Bar-Jona; ĉar ne karno kaj sango tion malkaŝis al vi, sed mia Patro, kiu estas en la ĉielo.","Kaj Jesuo responde diris al li: Feliĉa vi estas, Simon Bar-Jona; ĉar ne karno kaj sango tion malkaŝis al vi, sed mia Patro, kiu estas en la ĉielo."],[16,18,"Kaj mi diras al vi, ke vi estas Petro, kaj sur ĉi tiu roko mi konstruos mian eklezion; kaj pordegoj de Hades ne superfortos ĝin.","Kaj mi diras al vi, ke vi estas Petro, kaj sur ĉi tiu roko mi konstruos mian eklezion; kaj pordegoj de Hades ne superfortos ĝin."],[16,19,"Mi donos al vi la ŝlosilojn de la regno de la ĉielo; kaj kion ajn vi ligos sur la tero, tio estos ligita en la ĉielo; kaj kion ajn vi malligos sur la tero, tio estos malligita en la ĉielo.","Mi donos al vi la ŝlosilojn de la regno de la ĉielo; kaj kion ajn vi ligos sur la tero, tio estos ligita en la ĉielo; kaj kion ajn vi malligos sur la tero, tio estos malligita en la ĉielo."],[16,20,"Tiam li admonis la disĉiplojn, ke ili diru al neniu, ke li estas la Kristo.","Tiam li admonis la disĉiplojn, ke ili diru al neniu, ke li estas la Kristo."],[16,21,"De post tiu tempo Jesuo komencis montri al siaj disĉiploj, ke li devas iri al Jerusalem, kaj multe suferi ĉe la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi.","De post tiu tempo Jesuo komencis montri al siaj disĉiploj, ke li devas iri al Jerusalem, kaj multe suferi ĉe la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi."],[16,22,"Kaj Petro prenis lin, kaj komencis admoni lin, dirante: Kompaton al vi, Sinjoro! tio ne estu al vi!","Kaj Petro prenis lin, kaj komencis admoni lin, dirante: Kompaton al vi, Sinjoro! tio ne estu al vi!"],[16,23,"Sed turninte sin, li diris al Petro: Iru malantaŭ min, Satano; vi estas faligilo por mi, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj.","Sed turninte sin, li diris al Petro: Iru malantaŭ min, Satano; vi estas faligilo por mi, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj."],[16,24,"Tiam Jesuo diris al siaj disĉiploj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min;","Tiam Jesuo diris al siaj disĉiploj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min;"],[16,25,"ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi, tiu ĝin trovos.","ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi, tiu ĝin trovos."],[16,26,"Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon? Aŭ kion homo donu interŝanĝe por sia animo?","Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon? Aŭ kion homo donu interŝanĝe por sia animo?"],[16,27,"Ĉar la Filo de homo venos en la gloro de sia Patro kun siaj anĝeloj, kaj tiam li redonos al ĉiu laŭ liaj faroj.","Ĉar la Filo de homo venos en la gloro de sia Patro kun siaj anĝeloj, kaj tiam li redonos al ĉiu laŭ liaj faroj."],[16,28,"Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la Filon de homo venantan en sia regno.","Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la Filon de homo venantan en sia regno."],[17,1,"Kaj post ses tagoj Jesuo prenis kun si Petron, kaj Jakobon, kaj Johanon, lian fraton, kaj kondukis ilin sur altan monton aparte;","Kaj post ses tagoj Jesuo prenis kun si Petron, kaj Jakobon, kaj Johanon, lian fraton, kaj kondukis ilin sur altan monton aparte;"],[17,2,"kaj li estis aliformita antaŭ ili, kaj lia vizaĝo lumis kiel la suno, kaj liaj vestoj fariĝis blankaj kiel la lumo.","kaj li estis aliformita antaŭ ili, kaj lia vizaĝo lumis kiel la suno, kaj liaj vestoj fariĝis blankaj kiel la lumo."],[17,3,"Kaj jen aperis al ili Moseo kaj Elija, parolantaj kun li.","Kaj jen aperis al ili Moseo kaj Elija, parolantaj kun li."],[17,4,"Kaj Petro responde diris al Jesuo: Sinjoro, estas bone por ni esti ĉi tie. Se vi volas, mi faros ĉi tie tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija.","Kaj Petro responde diris al Jesuo: Sinjoro, estas bone por ni esti ĉi tie. Se vi volas, mi faros ĉi tie tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija."],[17,5,"Dum li ankoraŭ parolis, jen luma nubo superombris ilin; kaj jen voĉo el la nubo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron; aŭskultu lin.","Dum li ankoraŭ parolis, jen luma nubo superombris ilin; kaj jen voĉo el la nubo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron; aŭskultu lin."],[17,6,"Kaj aŭdinte tion, la disĉiploj falis sur sian vizaĝon, kaj tre timis.","Kaj aŭdinte tion, la disĉiploj falis sur sian vizaĝon, kaj tre timis."],[17,7,"Kaj Jesuo alvenis kaj ektuŝis ilin, kaj diris: Leviĝu, kaj ne timu.","Kaj Jesuo alvenis kaj ektuŝis ilin, kaj diris: Leviĝu, kaj ne timu."],[17,8,"Kaj levinte siajn okulojn, ili vidis neniun krom Jesuo sola.","Kaj levinte siajn okulojn, ili vidis neniun krom Jesuo sola."],[17,9,"Kaj dum ili malsupreniris de la monto, Jesuo ordonis al ili, dirante: Rakontu al neniu la vizion, ĝis la Filo de homo releviĝos el la mortintoj.","Kaj dum ili malsupreniris de la monto, Jesuo ordonis al ili, dirante: Rakontu al neniu la vizion, ĝis la Filo de homo releviĝos el la mortintoj."],[17,10,"Kaj liaj disĉiploj demandis lin, dirante: Kial do diras la skribistoj, ke Elija devas veni antaŭe?","Kaj liaj disĉiploj demandis lin, dirante: Kial do diras la skribistoj, ke Elija devas veni antaŭe?"],[17,11,"Kaj li responde diris: Vere Elija venas antaŭe, kaj restarigos ĉion;","Kaj li responde diris: Vere Elija venas antaŭe, kaj restarigos ĉion;"],[17,12,"sed mi diras al vi, ke Elija jam venis, kaj oni ne konis lin, sed faris al li ĉion, kion ili volis. Tiel ankaŭ la Filo de homo estas suferonta sub ili.","sed mi diras al vi, ke Elija jam venis, kaj oni ne konis lin, sed faris al li ĉion, kion ili volis. Tiel ankaŭ la Filo de homo estas suferonta sub ili."],[17,13,"Tiam la disĉiploj komprenis, ke li parolis al ili pri Johano, la Baptisto.","Tiam la disĉiploj komprenis, ke li parolis al ili pri Johano, la Baptisto."],[17,14,"Kaj kiam li venis al la homamaso, venis al li viro, genuante antaŭ li, kaj dirante:","Kaj kiam li venis al la homamaso, venis al li viro, genuante antaŭ li, kaj dirante:"],[17,15,"Sinjoro, kompatu mian filon, ĉar li frenezas kaj forte suferas; ĉar ofte li falas en la fajron kaj ofte en la akvon.","Sinjoro, kompatu mian filon, ĉar li frenezas kaj forte suferas; ĉar ofte li falas en la fajron kaj ofte en la akvon."],[17,16,"Kaj mi venigis lin al viaj disĉiploj, kaj ili ne povis lin sanigi.","Kaj mi venigis lin al viaj disĉiploj, kaj ili ne povis lin sanigi."],[17,17,"Kaj Jesuo responde diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi ĉi tien.","Kaj Jesuo responde diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi ĉi tien."],[17,18,"Kaj Jesuo severe admonis lin; kaj la demono eliris el li, kaj la knabo resaniĝis en tiu sama horo.","Kaj Jesuo severe admonis lin; kaj la demono eliris el li, kaj la knabo resaniĝis en tiu sama horo."],[17,19,"Tiam la disĉiploj, veninte al Jesuo aparte, diris: Pro kio ni ne povis elpeli ĝin?","Tiam la disĉiploj, veninte al Jesuo aparte, diris: Pro kio ni ne povis elpeli ĝin?"],[17,20,"Kaj li respondis al ili: Pro la malgrandeco de via fido; ĉar vere mi diras al vi: Se vi havas fidon, kiel semero de sinapo, vi diros al ĉi tiu monto: Translokiĝu tien de ĉi tie, kaj ĝi translokiĝos; kaj nenio estos neebla por vi.","Kaj li respondis al ili: Pro la malgrandeco de via fido; ĉar vere mi diras al vi: Se vi havas fidon, kiel semero de sinapo, vi diros al ĉi tiu monto: Translokiĝu tien de ĉi tie, kaj ĝi translokiĝos; kaj nenio estos neebla por vi."],[17,21,"Sed ĉi tiu speco ne eliras, krom per preĝado kaj fastado.","Sed ĉi tiu speco ne eliras, krom per preĝado kaj fastado."],[17,22,"Kaj kiam ili kolektiĝis en Galileo, Jesuo diris al ili: La Filo de homo estos transdonita en la manojn de homoj;","Kaj kiam ili kolektiĝis en Galileo, Jesuo diris al ili: La Filo de homo estos transdonita en la manojn de homoj;"],[17,23,"kaj ili mortigos lin, kaj la trian tagon li leviĝos. Kaj ili tre malĝojis.","kaj ili mortigos lin, kaj la trian tagon li leviĝos. Kaj ili tre malĝojis."],[17,24,"Kaj kiam ili venis en Kapernaumon, venis al Petro la ricevistoj de la du draĥmoj, kaj diris: Ĉu via majstro pagas la du draĥmojn?","Kaj kiam ili venis en Kapernaumon, venis al Petro la ricevistoj de la du draĥmoj, kaj diris: Ĉu via majstro pagas la du draĥmojn?"],[17,25,"Li respondis: Jes. Kaj kiam li venis en la domon, Jesuo unue parolis al li, dirante: Kiel ŝajnas al vi, Simon? de kiuj prenas la reĝoj de la tero imposton aŭ tributon? de siaj filoj aŭ de la fremduloj?","Li respondis: Jes. Kaj kiam li venis en la domon, Jesuo unue parolis al li, dirante: Kiel ŝajnas al vi, Simon? de kiuj prenas la reĝoj de la tero imposton aŭ tributon? de siaj filoj aŭ de la fremduloj?"],[17,26,"Kaj kiam li diris: De la fremduloj; Jesuo diris: Sekve la filoj estas liberaj.","Kaj kiam li diris: De la fremduloj; Jesuo diris: Sekve la filoj estas liberaj."],[17,27,"Sed, por ke ni ne ofendu ilin, iru al la maro kaj ĵetu hoketon, kaj prenu la fiŝon unue venintan, kaj malferminte ĝian buŝon, vi trovos stateron. Prenu ĝin, kaj donu al ili por mi kaj vi.","Sed, por ke ni ne ofendu ilin, iru al la maro kaj ĵetu hoketon, kaj prenu la fiŝon unue venintan, kaj malferminte ĝian buŝon, vi trovos stateron. Prenu ĝin, kaj donu al ili por mi kaj vi."],[18,1,"En tiu horo la disĉiploj venis al Jesuo, dirante: Kiu do estas la plej granda en la regno de la ĉielo?","En tiu horo la disĉiploj venis al Jesuo, dirante: Kiu do estas la plej granda en la regno de la ĉielo?"],[18,2,"Kaj alvokinte al si infanon, li starigis ĝin meze de ili,","Kaj alvokinte al si infanon, li starigis ĝin meze de ili,"],[18,3,"kaj diris: Vere mi diras al vi: Se vi ne turniĝos kaj ne fariĝos kiel infanoj, vi neniel eniros en la regnon de la ĉielo.","kaj diris: Vere mi diras al vi: Se vi ne turniĝos kaj ne fariĝos kiel infanoj, vi neniel eniros en la regnon de la ĉielo."],[18,4,"Kiu do humiligos sin, kiel ĉi tiu infano, tiu estas la plej granda en la regno de la ĉielo.","Kiu do humiligos sin, kiel ĉi tiu infano, tiu estas la plej granda en la regno de la ĉielo."],[18,5,"Kaj kiu akceptos unu tian infanon en mia nomo, tiu akceptas min;","Kaj kiu akceptos unu tian infanon en mia nomo, tiu akceptas min;"],[18,6,"sed kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus subakvigita en la profundon de la maro.","sed kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus subakvigita en la profundon de la maro."],[18,7,"Ve al la mondo pro faliloj! ĉar estas necese, ke venu faliloj, sed ve al tiu homo, per kiu la falilo venas!","Ve al la mondo pro faliloj! ĉar estas necese, ke venu faliloj, sed ve al tiu homo, per kiu la falilo venas!"],[18,8,"Kaj se via mano aŭ via piedo faligas vin, detranĉu ĝin kaj forĵetu ĝin de vi: estas bone por vi eniri en vivon kripla aŭ lama prefere ol, havante du manojn aŭ du piedojn, esti enĵetita en la eternan fajron.","Kaj se via mano aŭ via piedo faligas vin, detranĉu ĝin kaj forĵetu ĝin de vi: estas bone por vi eniri en vivon kripla aŭ lama prefere ol, havante du manojn aŭ du piedojn, esti enĵetita en la eternan fajron."],[18,9,"Kaj se via okulo faligas vin, elŝiru ĝin kaj forĵetu ĝin de vi; estas bone por vi eniri en vivon unuokula prefere ol, havante du okulojn, esti enĵetita en Gehenan de fajro.","Kaj se via okulo faligas vin, elŝiru ĝin kaj forĵetu ĝin de vi; estas bone por vi eniri en vivon unuokula prefere ol, havante du okulojn, esti enĵetita en Gehenan de fajro."],[18,10,"Gardu vin, ke vi ne malestimu unu el tiuj malgranduloj; ĉar mi diras al vi, ke iliaj anĝeloj en la ĉielo ĉiam rigardas la vizaĝon de mia Patro, kiu estas en la ĉielo.","Gardu vin, ke vi ne malestimu unu el tiuj malgranduloj; ĉar mi diras al vi, ke iliaj anĝeloj en la ĉielo ĉiam rigardas la vizaĝon de mia Patro, kiu estas en la ĉielo."],[18,11,"Ĉar la Filo de homo venis, por savi tion, kio estis perdita.","Ĉar la Filo de homo venis, por savi tion, kio estis perdita."],[18,12,"Kiel vi pensas? Se viro havas cent ŝafojn, kaj unu el ili erarvagis, ĉu li ne lasas la naŭdek naŭ, kaj iras al la montoj, kaj serĉas tiun, kiu erarvagis?","Kiel vi pensas? Se viro havas cent ŝafojn, kaj unu el ili erarvagis, ĉu li ne lasas la naŭdek naŭ, kaj iras al la montoj, kaj serĉas tiun, kiu erarvagis?"],[18,13,"Kaj se okazas, ke li trovas ĝin, vere mi diras al vi, li plimulte ĝojas pri ĝi, ol pri la naŭdek naŭ, kiuj ne erarvagis.","Kaj se okazas, ke li trovas ĝin, vere mi diras al vi, li plimulte ĝojas pri ĝi, ol pri la naŭdek naŭ, kiuj ne erarvagis."],[18,14,"Tiel same ne estas la volo de via Patro, kiu estas en la ĉielo, ke unu el ĉi tiuj malgranduloj pereu.","Tiel same ne estas la volo de via Patro, kiu estas en la ĉielo, ke unu el ĉi tiuj malgranduloj pereu."],[18,15,"Kaj se via frato pekos kontraŭ vi, iru kaj montru al li la kulpon inter vi kaj li sola. Se li aŭskultos vin, vi gajnos vian fraton.","Kaj se via frato pekos kontraŭ vi, iru kaj montru al li la kulpon inter vi kaj li sola. Se li aŭskultos vin, vi gajnos vian fraton."],[18,16,"Sed se li ne aŭskultos, prenu ankaŭ unu aŭ du kun vi, por ke per la buŝo de du aŭ tri atestantoj ĉiu vorto estu konfirmita.","Sed se li ne aŭskultos, prenu ankaŭ unu aŭ du kun vi, por ke per la buŝo de du aŭ tri atestantoj ĉiu vorto estu konfirmita."],[18,17,"Kaj se li rifuzos aŭskulti ilin, diru la aferon al la eklezio; kaj se li ankaŭ rifuzos aŭskulti la eklezion, li estu por vi kiel fremdulo kaj impostisto.","Kaj se li rifuzos aŭskulti ilin, diru la aferon al la eklezio; kaj se li ankaŭ rifuzos aŭskulti la eklezion, li estu por vi kiel fremdulo kaj impostisto."],[18,18,"Vere mi diras al vi, ke ĉio, kion vi ligos sur la tero, estos ligita en la ĉielo; kaj ĉio, kion vi malligos sur la tero, estos malligita en la ĉielo.","Vere mi diras al vi, ke ĉio, kion vi ligos sur la tero, estos ligita en la ĉielo; kaj ĉio, kion vi malligos sur la tero, estos malligita en la ĉielo."],[18,19,"Cetere mi diras al vi, ke se du el vi konsentos sur la tero pri ia pripetota afero, ĝi estos farita al ili de mia Patro, kiu estas en la ĉielo.","Cetere mi diras al vi, ke se du el vi konsentos sur la tero pri ia pripetota afero, ĝi estos farita al ili de mia Patro, kiu estas en la ĉielo."],[18,20,"Ĉar kie du aŭ tri kunvenas en mia nomo, tie mi estas meze de ili.","Ĉar kie du aŭ tri kunvenas en mia nomo, tie mi estas meze de ili."],[18,21,"Tiam Petro venis kaj diris al li: Sinjoro, kiomfoje povu peki mia frato kontraŭ mi, kaj mi pardonu lin? ĝis sep fojoj?","Tiam Petro venis kaj diris al li: Sinjoro, kiomfoje povu peki mia frato kontraŭ mi, kaj mi pardonu lin? ĝis sep fojoj?"],[18,22,"Jesuo diris al li: Mi ne diras al vi: Ĝis sep fojoj; sed: Ĝis sepdekoble sep fojoj.","Jesuo diris al li: Mi ne diras al vi: Ĝis sep fojoj; sed: Ĝis sepdekoble sep fojoj."],[18,23,"Tial la regno de la ĉielo similas al reĝo, kiu volis fari kalkulon kun siaj servistoj.","Tial la regno de la ĉielo similas al reĝo, kiu volis fari kalkulon kun siaj servistoj."],[18,24,"Kaj kiam li komencis la kunkalkuladon, oni alkondukis al li unu, kiu estis ŝuldanto por dek mil talantoj.","Kaj kiam li komencis la kunkalkuladon, oni alkondukis al li unu, kiu estis ŝuldanto por dek mil talantoj."],[18,25,"Sed ĉar li ne havis, per kio pagi, lia sinjoro ordonis, ke estu venditaj li kaj lia edzino kaj liaj infanoj, kaj ĉio, kion li posedis, kaj ke estu pago.","Sed ĉar li ne havis, per kio pagi, lia sinjoro ordonis, ke estu venditaj li kaj lia edzino kaj liaj infanoj, kaj ĉio, kion li posedis, kaj ke estu pago."],[18,26,"Tiam la servisto, falinte, kliniĝis antaŭ li, dirante: Sinjoro, paciencu pri mi, kaj mi pagos al vi ĉion.","Tiam la servisto, falinte, kliniĝis antaŭ li, dirante: Sinjoro, paciencu pri mi, kaj mi pagos al vi ĉion."],[18,27,"Kaj la sinjoro de tiu servisto, kortuŝite, liberigis lin kaj pardonis al li la ŝuldon.","Kaj la sinjoro de tiu servisto, kortuŝite, liberigis lin kaj pardonis al li la ŝuldon."],[18,28,"Sed elirinte, tiu servisto trovis kunserviston, kiu ŝuldis al li cent denarojn; kaj li kaptis kaj eksufokis lin, dirante: Pagu tion, kion vi ŝuldas.","Sed elirinte, tiu servisto trovis kunserviston, kiu ŝuldis al li cent denarojn; kaj li kaptis kaj eksufokis lin, dirante: Pagu tion, kion vi ŝuldas."],[18,29,"Kaj falinte antaŭ li, la kunservisto petegis lin, dirante: Paciencu pri mi, kaj mi pagos al vi.","Kaj falinte antaŭ li, la kunservisto petegis lin, dirante: Paciencu pri mi, kaj mi pagos al vi."],[18,30,"Sed li ne volis; sed foriris kaj ĵetis lin en malliberejon, ĝis li pagos tion, kio estas ŝuldata.","Sed li ne volis; sed foriris kaj ĵetis lin en malliberejon, ĝis li pagos tion, kio estas ŝuldata."],[18,31,"Tiam liaj kunservistoj, vidinte tion, kio okazis, tre ĉagreniĝis; kaj veninte, rakontis al sia sinjoro ĉion, kio okazis.","Tiam liaj kunservistoj, vidinte tion, kio okazis, tre ĉagreniĝis; kaj veninte, rakontis al sia sinjoro ĉion, kio okazis."],[18,32,"Tiam lia sinjoro, alvokinte lin, diris: Vi malbona servisto, mi pardonis al vi tiun tutan ŝuldon, ĉar vi petegis min;","Tiam lia sinjoro, alvokinte lin, diris: Vi malbona servisto, mi pardonis al vi tiun tutan ŝuldon, ĉar vi petegis min;"],[18,33,"ĉu vi ankaŭ ne devis kompati vian kunserviston, kiel mi kompatis vin?","ĉu vi ankaŭ ne devis kompati vian kunserviston, kiel mi kompatis vin?"],[18,34,"Kaj lia sinjoro koleris, kaj transdonis lin al la turmentistoj, ĝis li pagos ĉion al li ŝuldatan.","Kaj lia sinjoro koleris, kaj transdonis lin al la turmentistoj, ĝis li pagos ĉion al li ŝuldatan."],[18,35,"Tiel same mia ĉiela Patro faros al vi, se vi ne pardonas el viaj koroj, ĉiu al sia frato.","Tiel same mia ĉiela Patro faros al vi, se vi ne pardonas el viaj koroj, ĉiu al sia frato."],[19,1,"Kaj kiam Jesuo finis ĉi tiujn parolojn, li foriris el Galileo, kaj venis en la limojn de Judujo trans Jordan;","Kaj kiam Jesuo finis ĉi tiujn parolojn, li foriris el Galileo, kaj venis en la limojn de Judujo trans Jordan;"],[19,2,"kaj grandaj homamasoj lin sekvis, kaj li sanigis ilin tie.","kaj grandaj homamasoj lin sekvis, kaj li sanigis ilin tie."],[19,3,"Kaj venis al li Fariseoj, provante lin, kaj dirante: Ĉu estas permesate forsendi sian edzinon pro ĉia kaŭzo?","Kaj venis al li Fariseoj, provante lin, kaj dirante: Ĉu estas permesate forsendi sian edzinon pro ĉia kaŭzo?"],[19,4,"Kaj responde li diris: Ĉu vi ne legis, ke en la komenco la Kreinto faris ilin vira kaj virina,","Kaj responde li diris: Ĉu vi ne legis, ke en la komenco la Kreinto faris ilin vira kaj virina,"],[19,5,"kaj diris: Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino; kaj ili estos unu karno?","kaj diris: Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino; kaj ili estos unu karno?"],[19,6,"Sekve ili jam estas ne du, sed unu karno. Kion do Dio kunigis, tion homo ne disigu.","Sekve ili jam estas ne du, sed unu karno. Kion do Dio kunigis, tion homo ne disigu."],[19,7,"Ili diris al li: Kial do Moseo ordonis doni eksedzigan leteron, kaj forsendi ŝin?","Ili diris al li: Kial do Moseo ordonis doni eksedzigan leteron, kaj forsendi ŝin?"],[19,8,"Li diris al ili: Moseo, pro la malmoleco de via koro, permesis al vi forsendi viajn edzinojn; sed ne estis tiel de la komenco.","Li diris al ili: Moseo, pro la malmoleco de via koro, permesis al vi forsendi viajn edzinojn; sed ne estis tiel de la komenco."],[19,9,"Sed mi diras al vi: Kiu forsendos sian edzinon krom pro malĉasteco, kaj edziĝos kun alia, tiu adultas; kaj kiu edziĝas kun la forsenditino, tiu adultas.","Sed mi diras al vi: Kiu forsendos sian edzinon krom pro malĉasteco, kaj edziĝos kun alia, tiu adultas; kaj kiu edziĝas kun la forsenditino, tiu adultas."],[19,10,"La disĉiploj diris al li: Se tia estas la rilato de viro al virino, ne estas oportune edziĝi.","La disĉiploj diris al li: Se tia estas la rilato de viro al virino, ne estas oportune edziĝi."],[19,11,"Sed li diris al ili: Ne ĉiuj homoj akceptas ĉi tiun diron, sed nur tiuj, al kiuj tio estas donita.","Sed li diris al ili: Ne ĉiuj homoj akceptas ĉi tiun diron, sed nur tiuj, al kiuj tio estas donita."],[19,12,"Ĉar estas eŭnukoj, kiuj estas naskitaj tiaj el la patrina ventro; kaj estas eŭnukoj, kiuj estis eŭnukigitaj de homoj; kaj estas eŭnukoj, kiuj eŭnukigis sin pro la regno de la ĉielo. Kiu povas tion akcepti, tiu akceptu.","Ĉar estas eŭnukoj, kiuj estas naskitaj tiaj el la patrina ventro; kaj estas eŭnukoj, kiuj estis eŭnukigitaj de homoj; kaj estas eŭnukoj, kiuj eŭnukigis sin pro la regno de la ĉielo. Kiu povas tion akcepti, tiu akceptu."],[19,13,"Tiam oni venigis al li infanojn, por ke li metu la manojn sur ilin kaj preĝu; kaj la disĉiploj admonis ilin.","Tiam oni venigis al li infanojn, por ke li metu la manojn sur ilin kaj preĝu; kaj la disĉiploj admonis ilin."],[19,14,"Sed Jesuo diris: Lasu la infanojn, kaj ne malhelpu ilin, veni al mi; ĉar el tiaj estas la regno de la ĉielo.","Sed Jesuo diris: Lasu la infanojn, kaj ne malhelpu ilin, veni al mi; ĉar el tiaj estas la regno de la ĉielo."],[19,15,"Kaj metinte la manojn sur ilin, li foriris de tie.","Kaj metinte la manojn sur ilin, li foriris de tie."],[19,16,"Kaj jen unu viro, veninte al li, diris: Majstro, kian bonon mi faru, por ke mi ricevu eternan vivon?","Kaj jen unu viro, veninte al li, diris: Majstro, kian bonon mi faru, por ke mi ricevu eternan vivon?"],[19,17,"Li diris al li: Kial vi min demandas pri bono? Ekzistas Unu, kiu estas bona; sed se vi deziras eniri en la vivon, observu la ordonojn.","Li diris al li: Kial vi min demandas pri bono? Ekzistas Unu, kiu estas bona; sed se vi deziras eniri en la vivon, observu la ordonojn."],[19,18,"Li diris al li: Kiujn? Kaj Jesuo diris: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston;","Li diris al li: Kiujn? Kaj Jesuo diris: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston;"],[19,19,"Respektu vian patron kaj vian patrinon; kaj: Amu vian proksimulon kiel vin mem.","Respektu vian patron kaj vian patrinon; kaj: Amu vian proksimulon kiel vin mem."],[19,20,"La junulo diris al li: Ĉion tion mi observis; kio ankoraŭ mankas al mi?","La junulo diris al li: Ĉion tion mi observis; kio ankoraŭ mankas al mi?"],[19,21,"Jesuo diris al li: Se vi deziras esti perfekta, iru, vendu viajn posedaĵojn, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.","Jesuo diris al li: Se vi deziras esti perfekta, iru, vendu viajn posedaĵojn, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min."],[19,22,"Sed aŭdinte tiun diron, la junulo foriris malĝoja, ĉar li havis multajn posedaĵojn.","Sed aŭdinte tiun diron, la junulo foriris malĝoja, ĉar li havis multajn posedaĵojn."],[19,23,"Kaj Jesuo diris al siaj disĉiploj: Vere mi diras al vi: Malfacile riĉulo eniros en la regnon de la ĉielo.","Kaj Jesuo diris al siaj disĉiploj: Vere mi diras al vi: Malfacile riĉulo eniros en la regnon de la ĉielo."],[19,24,"Kaj cetere mi diras al vi: Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.","Kaj cetere mi diras al vi: Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio."],[19,25,"Kiam la disĉiploj tion aŭdis, ili forte miregis, dirante: Kiu do povas esti savita?","Kiam la disĉiploj tion aŭdis, ili forte miregis, dirante: Kiu do povas esti savita?"],[19,26,"Kaj Jesuo, rigardante ilin, diris al ili: Ĉe homoj tio estas neebla, sed ĉe Dio ĉio estas ebla.","Kaj Jesuo, rigardante ilin, diris al ili: Ĉe homoj tio estas neebla, sed ĉe Dio ĉio estas ebla."],[19,27,"Tiam Petro responde diris al li: Jen ni ĉion forlasis, kaj vin sekvis; kion do ni havos?","Tiam Petro responde diris al li: Jen ni ĉion forlasis, kaj vin sekvis; kion do ni havos?"],[19,28,"Jesuo diris al ili: Vere mi diras al vi, ke vi, kiuj min sekvis, en la renaskado, kiam la Filo de homo sidos sur la trono de sia gloro, vi ankaŭ sidos sur dek du tronoj, juĝante la dek du tribojn de Izrael.","Jesuo diris al ili: Vere mi diras al vi, ke vi, kiuj min sekvis, en la renaskado, kiam la Filo de homo sidos sur la trono de sia gloro, vi ankaŭ sidos sur dek du tronoj, juĝante la dek du tribojn de Izrael."],[19,29,"Kaj ĉiu, kiu forlasis domojn aŭ fratojn aŭ fratinojn aŭ patron aŭ patrinon aŭ infanojn aŭ kampojn pro mia nomo, ricevos multoble kaj heredos eternan vivon.","Kaj ĉiu, kiu forlasis domojn aŭ fratojn aŭ fratinojn aŭ patron aŭ patrinon aŭ infanojn aŭ kampojn pro mia nomo, ricevos multoble kaj heredos eternan vivon."],[19,30,"Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj.","Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj."],[20,1,"Ĉar la regno de la ĉielo similas al domomastro, kiu eliris frumatene, por dungi laboristojn por sia vinberĝardeno.","Ĉar la regno de la ĉielo similas al domomastro, kiu eliris frumatene, por dungi laboristojn por sia vinberĝardeno."],[20,2,"Kaj kontraktinte kun la laboristoj po unu denaro por la tago, li ilin sendis en sian vinberejon.","Kaj kontraktinte kun la laboristoj po unu denaro por la tago, li ilin sendis en sian vinberejon."],[20,3,"Kaj elirinte ĉirkaŭ la tria horo, li vidis aliajn starantajn senokupe sur la placo;","Kaj elirinte ĉirkaŭ la tria horo, li vidis aliajn starantajn senokupe sur la placo;"],[20,4,"kaj li diris al ili: Vi ankaŭ iru en la vinberejon, kaj kiom estas justa, tiom mi donos al vi. Kaj ili iris.","kaj li diris al ili: Vi ankaŭ iru en la vinberejon, kaj kiom estas justa, tiom mi donos al vi. Kaj ili iris."],[20,5,"Denove elirinte ĉirkaŭ la sesa horo kaj la naŭa, li agis simile.","Denove elirinte ĉirkaŭ la sesa horo kaj la naŭa, li agis simile."],[20,6,"Kaj elirinte ĉirkaŭ la dek-unua horo, li trovis aliajn starantajn; kaj li diris al ili: Kial vi staras ĉi tie senokupe la tutan tagon?","Kaj elirinte ĉirkaŭ la dek-unua horo, li trovis aliajn starantajn; kaj li diris al ili: Kial vi staras ĉi tie senokupe la tutan tagon?"],[20,7,"Ili diris al li: Ĉar neniu nin dungis. Li diris al ili: Vi ankaŭ iru en la vinberejon.","Ili diris al li: Ĉar neniu nin dungis. Li diris al ili: Vi ankaŭ iru en la vinberejon."],[20,8,"Kaj kiam vesperiĝis, la sinjoro de la vinberejo diris al sia administranto: Alvoku la laboristojn, kaj donu al ili la salajron, komencante de la lastaj ĝis la unuaj.","Kaj kiam vesperiĝis, la sinjoro de la vinberejo diris al sia administranto: Alvoku la laboristojn, kaj donu al ili la salajron, komencante de la lastaj ĝis la unuaj."],[20,9,"Kaj venis tiuj, kiuj estis dungitaj ĉirkaŭ la dek-unua horo, kaj ili ricevis po unu denaro.","Kaj venis tiuj, kiuj estis dungitaj ĉirkaŭ la dek-unua horo, kaj ili ricevis po unu denaro."],[20,10,"Kaj kiam la unuaj venis, ili supozis, ke ili ricevos pli; kaj ili ankaŭ ricevis po unu denaro.","Kaj kiam la unuaj venis, ili supozis, ke ili ricevos pli; kaj ili ankaŭ ricevis po unu denaro."],[20,11,"Kaj tion ricevinte, ili murmuris kontraŭ la domomastro,","Kaj tion ricevinte, ili murmuris kontraŭ la domomastro,"],[20,12,"dirante: Tiuj lastaj laboris nur unu horon, kaj vi faris ilin egalaj kun ni, kiuj elportis la ŝarĝon de la tago kaj la varmegon.","dirante: Tiuj lastaj laboris nur unu horon, kaj vi faris ilin egalaj kun ni, kiuj elportis la ŝarĝon de la tago kaj la varmegon."],[20,13,"Sed li responde diris al unu el ili: Amiko, mi ne faras al vi maljustaĵon; ĉu vi ne kontraktis kun mi por unu denaro?","Sed li responde diris al unu el ili: Amiko, mi ne faras al vi maljustaĵon; ĉu vi ne kontraktis kun mi por unu denaro?"],[20,14,"Prenu do la vian kaj foriru; mi volas doni al ĉi tiu lasta tiel same, kiel al vi.","Prenu do la vian kaj foriru; mi volas doni al ĉi tiu lasta tiel same, kiel al vi."],[20,15,"Ĉu ne estas permesate al mi, fari kun la mia tion, kion mi volas? aŭ ĉu via okulo estas malbona tial, ke mi estas bona?","Ĉu ne estas permesate al mi, fari kun la mia tion, kion mi volas? aŭ ĉu via okulo estas malbona tial, ke mi estas bona?"],[20,16,"Tiel la lastaj estos unuaj, kaj la unuaj estos lastaj.","Tiel la lastaj estos unuaj, kaj la unuaj estos lastaj."],[20,17,"Kaj suprenirante al Jerusalem, Jesuo prenis la dek du disĉiplojn aparte, kaj sur la vojo li diris al ili:","Kaj suprenirante al Jerusalem, Jesuo prenis la dek du disĉiplojn aparte, kaj sur la vojo li diris al ili:"],[20,18,"Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj skribistoj; kaj ili kondamnos lin al morto,","Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj skribistoj; kaj ili kondamnos lin al morto,"],[20,19,"kaj transdonos lin al la nacianoj, por moki kaj skurĝi kaj krucumi; kaj la trian tagon li releviĝos.","kaj transdonos lin al la nacianoj, por moki kaj skurĝi kaj krucumi; kaj la trian tagon li releviĝos."],[20,20,"Tiam venis al li la patrino de la filoj de Zebedeo, kun siaj filoj, adorkliniĝante kaj farante al li peton.","Tiam venis al li la patrino de la filoj de Zebedeo, kun siaj filoj, adorkliniĝante kaj farante al li peton."],[20,21,"Li diris al ŝi: Kion vi volas? Ŝi diris al li: Ordonu, ke ĉi tiuj miaj du filoj povu sidi, unu dekstre de vi kaj la dua maldekstre, en via regno.","Li diris al ŝi: Kion vi volas? Ŝi diris al li: Ordonu, ke ĉi tiuj miaj du filoj povu sidi, unu dekstre de vi kaj la dua maldekstre, en via regno."],[20,22,"Sed Jesuo responde diris: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkos? Ili diris al li: Ni povas.","Sed Jesuo responde diris: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkos? Ili diris al li: Ni povas."],[20,23,"Li diris al ili: Mian kalikon vi ja trinkos; sed sidi dekstre de mi kaj maldekstre, tion doni ne apartenas al mi, sed ĝi estas por tiuj, por kiuj ĝi estas preparita de mia Patro.","Li diris al ili: Mian kalikon vi ja trinkos; sed sidi dekstre de mi kaj maldekstre, tion doni ne apartenas al mi, sed ĝi estas por tiuj, por kiuj ĝi estas preparita de mia Patro."],[20,24,"Kaj aŭdinte, la dek indignis kontraŭ la du fratoj.","Kaj aŭdinte, la dek indignis kontraŭ la du fratoj."],[20,25,"Sed Jesuo, alvokinte ilin al si, diris: Vi scias, ke la regantoj de la nacioj kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili.","Sed Jesuo, alvokinte ilin al si, diris: Vi scias, ke la regantoj de la nacioj kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili."],[20,26,"Ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;","Ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;"],[20,27,"kaj kiu volas esti la unua inter vi, tiu estu via servisto;","kaj kiu volas esti la unua inter vi, tiu estu via servisto;"],[20,28,"same kiel la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj.","same kiel la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj."],[20,29,"Kaj kiam ili eliris el Jeriĥo, granda homamaso lin sekvis.","Kaj kiam ili eliris el Jeriĥo, granda homamaso lin sekvis."],[20,30,"Kaj jen du blinduloj, sidantaj apud la vojo, aŭdinte, ke Jesuo preterpasas, ekkriis, dirante: Sinjoro, kompatu nin, ho filo de David.","Kaj jen du blinduloj, sidantaj apud la vojo, aŭdinte, ke Jesuo preterpasas, ekkriis, dirante: Sinjoro, kompatu nin, ho filo de David."],[20,31,"Kaj la homamaso admonis ilin, ke ili silentu, sed ili plimulte kriis, dirante: Sinjoro, kompatu nin, ho filo de David.","Kaj la homamaso admonis ilin, ke ili silentu, sed ili plimulte kriis, dirante: Sinjoro, kompatu nin, ho filo de David."],[20,32,"Kaj Jesuo, haltinte, alvokis ilin, kaj diris: Kion vi volas, ke mi faru al vi?","Kaj Jesuo, haltinte, alvokis ilin, kaj diris: Kion vi volas, ke mi faru al vi?"],[20,33,"Ili diris al li: Sinjoro, ke niaj okuloj estu malfermitaj.","Ili diris al li: Sinjoro, ke niaj okuloj estu malfermitaj."],[20,34,"Kaj Jesuo, kortuŝite, tuŝis iliajn okulojn; kaj tuj ili ricevis vidpovon, kaj sekvis lin.","Kaj Jesuo, kortuŝite, tuŝis iliajn okulojn; kaj tuj ili ricevis vidpovon, kaj sekvis lin."],[21,1,"Kaj kiam ili alproksimiĝis al Jerusalem, kaj venis al Betfage, al la monto Olivarba, tiam Jesuo sendis du disĉiplojn,","Kaj kiam ili alproksimiĝis al Jerusalem, kaj venis al Betfage, al la monto Olivarba, tiam Jesuo sendis du disĉiplojn,"],[21,2,"dirante al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj vi tuj trovos azeninon ligitan, kaj azenidon kun ĝi. Ilin malligu kaj alkonduku al mi.","dirante al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj vi tuj trovos azeninon ligitan, kaj azenidon kun ĝi. Ilin malligu kaj alkonduku al mi."],[21,3,"Kaj se iu diros ion al vi, respondu: La Sinjoro bezonas ilin; kaj tuj li sendos ilin.","Kaj se iu diros ion al vi, respondu: La Sinjoro bezonas ilin; kaj tuj li sendos ilin."],[21,4,"Kaj ĉi tio okazis, por ke plenumiĝu tio, kio estis dirita per la profeto, nome:","Kaj ĉi tio okazis, por ke plenumiĝu tio, kio estis dirita per la profeto, nome:"],[21,5,"Diru al la filino de Cion: Jen via Reĝo iras al vi, Humila kaj rajdanta sur azeno, Kaj azenido, filo de ŝarĝobesto.","Diru al la filino de Cion: Jen via Reĝo iras al vi, Humila kaj rajdanta sur azeno, Kaj azenido, filo de ŝarĝobesto."],[21,6,"Kaj la disĉiploj iris, kaj faris, kiel Jesuo ordonis al ili,","Kaj la disĉiploj iris, kaj faris, kiel Jesuo ordonis al ili,"],[21,7,"kaj alkondukis la azeninon kaj la azenidon, kaj surmetis sur ilin siajn vestojn; kaj li sidis sur tion.","kaj alkondukis la azeninon kaj la azenidon, kaj surmetis sur ilin siajn vestojn; kaj li sidis sur tion."],[21,8,"Kaj la pli granda parto de la homamaso sternis siajn vestojn sur la vojo; kaj aliaj detranĉis branĉojn de la arboj, kaj dismetis ilin sur la vojon.","Kaj la pli granda parto de la homamaso sternis siajn vestojn sur la vojo; kaj aliaj detranĉis branĉojn de la arboj, kaj dismetis ilin sur la vojon."],[21,9,"Kaj la homamaso, kiu iris antaŭ li, kaj kiu sekvis lin, kriis, dirante: Hosana al la Filo de David! Estu benata tiu, kiu venas en la nomo de la Eternulo; Hosana en la supera alto!","Kaj la homamaso, kiu iris antaŭ li, kaj kiu sekvis lin, kriis, dirante: Hosana al la Filo de David! Estu benata tiu, kiu venas en la nomo de la Eternulo; Hosana en la supera alto!"],[21,10,"Kaj li eniris en Jerusalemon, kaj la tuta urbo malkvietiĝis, dirante: Kiu estas ĉi tiu?","Kaj li eniris en Jerusalemon, kaj la tuta urbo malkvietiĝis, dirante: Kiu estas ĉi tiu?"],[21,11,"Kaj la homamasoj diris: Ĉi tiu estas la profeto, Jesuo el Nazaret en Galileo.","Kaj la homamasoj diris: Ĉi tiu estas la profeto, Jesuo el Nazaret en Galileo."],[21,12,"Kaj Jesuo eniris en la templon de Dio, kaj elpelis ĉiujn vendantojn kaj aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj, kaj la seĝojn de la vendantoj de kolomboj;","Kaj Jesuo eniris en la templon de Dio, kaj elpelis ĉiujn vendantojn kaj aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj, kaj la seĝojn de la vendantoj de kolomboj;"],[21,13,"kaj li diris al ili: Estas skribite: Mia domo estas nomata domo de preĝo; sed vi faris ĝin kaverno de rabistoj.","kaj li diris al ili: Estas skribite: Mia domo estas nomata domo de preĝo; sed vi faris ĝin kaverno de rabistoj."],[21,14,"Kaj blinduloj kaj lamuloj venis al li en la templo, kaj li sanigis ilin.","Kaj blinduloj kaj lamuloj venis al li en la templo, kaj li sanigis ilin."],[21,15,"Sed la ĉefpastroj kaj skribistoj, vidinte la mirindaĵojn, kiujn li faris, kaj la knabojn kriantajn en la templo, kaj dirantajn: Hosana al la Filo de David, indignis,","Sed la ĉefpastroj kaj skribistoj, vidinte la mirindaĵojn, kiujn li faris, kaj la knabojn kriantajn en la templo, kaj dirantajn: Hosana al la Filo de David, indignis,"],[21,16,"kaj diris al li: Ĉu vi aŭdas, kion ĉi tiuj diras? Kaj Jesuo diris al ili: Jes; ĉu vi neniam legis: El la buŝo de junaj infanoj kaj suĉinfanoj Vi perfektigis laŭdon?","kaj diris al li: Ĉu vi aŭdas, kion ĉi tiuj diras? Kaj Jesuo diris al ili: Jes; ĉu vi neniam legis: El la buŝo de junaj infanoj kaj suĉinfanoj Vi perfektigis laŭdon?"],[21,17,"Kaj lasinte ilin, li eliris el la urbo al Betania, kaj tie loĝis.","Kaj lasinte ilin, li eliris el la urbo al Betania, kaj tie loĝis."],[21,18,"Kaj matene, dum li revenis al la urbo, li malsatis.","Kaj matene, dum li revenis al la urbo, li malsatis."],[21,19,"Kaj vidante figarbon apud la vojo, li iris al ĝi, kaj trovis sur ĝi nenion krom folioj; kaj li diris al ĝi: Ne plu estu frukto sur vi por eterne. Kaj tuj la figarbo forvelkis.","Kaj vidante figarbon apud la vojo, li iris al ĝi, kaj trovis sur ĝi nenion krom folioj; kaj li diris al ĝi: Ne plu estu frukto sur vi por eterne. Kaj tuj la figarbo forvelkis."],[21,20,"Kaj kiam la disĉiploj vidis, ili miris, dirante: Kiel rapide la figarbo forvelkis!","Kaj kiam la disĉiploj vidis, ili miris, dirante: Kiel rapide la figarbo forvelkis!"],[21,21,"Kaj Jesuo responde diris al ili: Vere mi diras al vi: Se vi havos fidon kaj ne dubos, vi ne nur faros la aferon de la figarbo, sed eĉ se vi diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron; tio plenumiĝos.","Kaj Jesuo responde diris al ili: Vere mi diras al vi: Se vi havos fidon kaj ne dubos, vi ne nur faros la aferon de la figarbo, sed eĉ se vi diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron; tio plenumiĝos."],[21,22,"Kaj ĉion, kion vi petos per preĝado, kredante, vi ricevos.","Kaj ĉion, kion vi petos per preĝado, kredante, vi ricevos."],[21,23,"Kaj kiam li jam venis en la templon, la ĉefpastroj kaj la pliaĝuloj de la popolo venis al li, dum li instruis, kaj ili diris: Laŭ kia aŭtoritato vi faras ĉi tion? kaj kiu donis al vi tian aŭtoritaton?","Kaj kiam li jam venis en la templon, la ĉefpastroj kaj la pliaĝuloj de la popolo venis al li, dum li instruis, kaj ili diris: Laŭ kia aŭtoritato vi faras ĉi tion? kaj kiu donis al vi tian aŭtoritaton?"],[21,24,"Kaj Jesuo responde diris al ili: Mi ankaŭ faros al vi unu demandon; kaj se vi tion diros al mi, mi ankaŭ diros al vi, laŭ kia aŭtoritato mi faras ĉi tion.","Kaj Jesuo responde diris al ili: Mi ankaŭ faros al vi unu demandon; kaj se vi tion diros al mi, mi ankaŭ diros al vi, laŭ kia aŭtoritato mi faras ĉi tion."],[21,25,"La baptado de Johano, de kie ĝi estis? El la ĉielo, aŭ el homoj? Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros al ni: Kial do vi ne kredis al li?","La baptado de Johano, de kie ĝi estis? El la ĉielo, aŭ el homoj? Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros al ni: Kial do vi ne kredis al li?"],[21,26,"Sed se ni diros: El homoj, ni timas la popolon, ĉar ĉiuj opinias Johanon profeto.","Sed se ni diros: El homoj, ni timas la popolon, ĉar ĉiuj opinias Johanon profeto."],[21,27,"Kaj ili responde diris al Jesuo: Ni ne scias. Li ankaŭ diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.","Kaj ili responde diris al Jesuo: Ni ne scias. Li ankaŭ diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion."],[21,28,"Kiel ŝajnas al vi? Unu viro havis du filojn; kaj li venis al la unua, kaj diris: Filo, iru hodiaŭ kaj laboru en la vinberĝardeno.","Kiel ŝajnas al vi? Unu viro havis du filojn; kaj li venis al la unua, kaj diris: Filo, iru hodiaŭ kaj laboru en la vinberĝardeno."],[21,29,"Kaj li respondis kaj diris: Mi ne volas; sed poste li pentis kaj iris.","Kaj li respondis kaj diris: Mi ne volas; sed poste li pentis kaj iris."],[21,30,"Kaj li venis al la dua, kaj diris tion saman. Kaj li responde diris: Mi iros, sinjoro; kaj ne iris.","Kaj li venis al la dua, kaj diris tion saman. Kaj li responde diris: Mi iros, sinjoro; kaj ne iris."],[21,31,"Kiu el la du plenumis la volon de la patro? Ili diris: La unua. Jesuo diris al ili: Vere mi diras al vi, ke la impostistoj kaj malĉastistinoj iras antaŭ vi en la regnon de Dio.","Kiu el la du plenumis la volon de la patro? Ili diris: La unua. Jesuo diris al ili: Vere mi diras al vi, ke la impostistoj kaj malĉastistinoj iras antaŭ vi en la regnon de Dio."],[21,32,"Ĉar Johano venis al vi en vojo de justeco, kaj vi ne kredis al li; sed la impostistoj kaj malĉastistinoj kredis al li. Kaj vi, kiam vi vidis, eĉ ne pentis poste, por kredi al li.","Ĉar Johano venis al vi en vojo de justeco, kaj vi ne kredis al li; sed la impostistoj kaj malĉastistinoj kredis al li. Kaj vi, kiam vi vidis, eĉ ne pentis poste, por kredi al li."],[21,33,"Aŭskultu alian parabolon: Estis viro dommastro, kiu plantis vinberĝardenon, kaj ĉirkaŭmetis plektobarilon, kaj fosis en ĝi vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis.","Aŭskultu alian parabolon: Estis viro dommastro, kiu plantis vinberĝardenon, kaj ĉirkaŭmetis plektobarilon, kaj fosis en ĝi vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis."],[21,34,"Kaj kiam alproksimiĝis la sezono de fruktoj, li sendis siajn sklavojn al la kultivistoj, por ricevi siajn fruktojn.","Kaj kiam alproksimiĝis la sezono de fruktoj, li sendis siajn sklavojn al la kultivistoj, por ricevi siajn fruktojn."],[21,35,"Kaj la kultivistoj, kaptinte liajn sklavojn, skurĝis unu, kaj mortigis alian, kaj ŝtonbatis alian.","Kaj la kultivistoj, kaptinte liajn sklavojn, skurĝis unu, kaj mortigis alian, kaj ŝtonbatis alian."],[21,36,"Li sendis ankoraŭ aliajn sklavojn, pli multajn ol la unuaj; kaj ili faris al ili tiel same.","Li sendis ankoraŭ aliajn sklavojn, pli multajn ol la unuaj; kaj ili faris al ili tiel same."],[21,37,"Sed poste li sendis al ili sian filon, dirante: Ili respektos mian filon.","Sed poste li sendis al ili sian filon, dirante: Ili respektos mian filon."],[21,38,"Sed la kultivistoj, vidante la filon, diris inter si: Ĉi tiu estas la heredonto; venu, ni lin mortigu, kaj prenu lian heredaĵon.","Sed la kultivistoj, vidante la filon, diris inter si: Ĉi tiu estas la heredonto; venu, ni lin mortigu, kaj prenu lian heredaĵon."],[21,39,"Kaj ili kaptis lin, elĵetis lin el la vinberejo, kaj mortigis lin.","Kaj ili kaptis lin, elĵetis lin el la vinberejo, kaj mortigis lin."],[21,40,"Kiam do venos la sinjoro de la vinberejo, kion li faros al tiuj kultivistoj?","Kiam do venos la sinjoro de la vinberejo, kion li faros al tiuj kultivistoj?"],[21,41,"Ili diris al li: Tiujn malbonulojn li mizere pereigos, kaj li luigos la vinberejon al aliaj kultivistoj, kiuj donos al li la fruktojn en iliaj sezonoj.","Ili diris al li: Tiujn malbonulojn li mizere pereigos, kaj li luigos la vinberejon al aliaj kultivistoj, kiuj donos al li la fruktojn en iliaj sezonoj."],[21,42,"Jesuo diris al ili: Ĉu vi neniam legis en la Skriboj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula: De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?","Jesuo diris al ili: Ĉu vi neniam legis en la Skriboj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula: De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?"],[21,43,"Tial mi diras al vi: La regno de Dio estos prenita for de vi, kaj estos donita al nacio, kiu liveros ĝiajn fruktojn.","Tial mi diras al vi: La regno de Dio estos prenita for de vi, kaj estos donita al nacio, kiu liveros ĝiajn fruktojn."],[21,44,"Kaj kiu falas sur tiun ŝtonon, tiu rompiĝos; sed sur kiun ĝi falos, ĝi tiun polvigos.","Kaj kiu falas sur tiun ŝtonon, tiu rompiĝos; sed sur kiun ĝi falos, ĝi tiun polvigos."],[21,45,"Kaj la ĉefpastroj kaj la Fariseoj, aŭdinte liajn parabolojn, komprenis, ke li parolas pri ili.","Kaj la ĉefpastroj kaj la Fariseoj, aŭdinte liajn parabolojn, komprenis, ke li parolas pri ili."],[21,46,"Kaj celante kapti lin, ili timis la popolon, ĉar oni opiniis lin profeto.","Kaj celante kapti lin, ili timis la popolon, ĉar oni opiniis lin profeto."],[22,1,"Kaj respondante, Jesuo denove parolis al ili parabole, dirante:","Kaj respondante, Jesuo denove parolis al ili parabole, dirante:"],[22,2,"La regno de la ĉielo similas al unu reĝo, kiu faris edziĝan feston por sia filo,","La regno de la ĉielo similas al unu reĝo, kiu faris edziĝan feston por sia filo,"],[22,3,"kaj sendis siajn sklavojn, por voki la invititojn al la edziĝa festo; kaj ili ne volis veni.","kaj sendis siajn sklavojn, por voki la invititojn al la edziĝa festo; kaj ili ne volis veni."],[22,4,"Poste li sendis aliajn sklavojn, dirante: Diru al la invititoj: Jen mi preparis la manĝon; miaj bovoj kaj miaj grasigitaj brutoj estas buĉitaj, kaj ĉio estas preta; venu al la edziĝa festo.","Poste li sendis aliajn sklavojn, dirante: Diru al la invititoj: Jen mi preparis la manĝon; miaj bovoj kaj miaj grasigitaj brutoj estas buĉitaj, kaj ĉio estas preta; venu al la edziĝa festo."],[22,5,"Sed ili malatentis, kaj foriris, unu al sia bieno, alia al sia komercado;","Sed ili malatentis, kaj foriris, unu al sia bieno, alia al sia komercado;"],[22,6,"kaj la ceteraj, kaptinte liajn sklavojn, perfortis kaj mortigis ilin.","kaj la ceteraj, kaptinte liajn sklavojn, perfortis kaj mortigis ilin."],[22,7,"Kaj la reĝo koleris; kaj sendinte siajn armeojn, li pereigis tiujn mortigintojn kaj bruligis ilian urbon.","Kaj la reĝo koleris; kaj sendinte siajn armeojn, li pereigis tiujn mortigintojn kaj bruligis ilian urbon."],[22,8,"Tiam li diris al siaj sklavoj: La edziĝa festo estas preta, sed la invititoj ne estis indaj.","Tiam li diris al siaj sklavoj: La edziĝa festo estas preta, sed la invititoj ne estis indaj."],[22,9,"Iru do al la disirejoj de la vojoj, kaj ĉiujn, kiujn vi trovos, invitu al la edziĝa festo.","Iru do al la disirejoj de la vojoj, kaj ĉiujn, kiujn vi trovos, invitu al la edziĝa festo."],[22,10,"Kaj tiuj sklavoj, elirinte sur la vojojn, kunvenigis ĉiujn, kiujn ili trovis, malbonajn kaj bonajn; kaj la edziĝa festo pleniĝis de gastoj.","Kaj tiuj sklavoj, elirinte sur la vojojn, kunvenigis ĉiujn, kiujn ili trovis, malbonajn kaj bonajn; kaj la edziĝa festo pleniĝis de gastoj."],[22,11,"Sed la reĝo, enveninte por rigardi la gastojn, tie vidis viron, kiu ne havis sur si edziĝofestan veston;","Sed la reĝo, enveninte por rigardi la gastojn, tie vidis viron, kiu ne havis sur si edziĝofestan veston;"],[22,12,"kaj li diris al li: Amiko, kiel vi envenis ĉi tien, ne havante edziĝofestan veston? Kaj li silentadis.","kaj li diris al li: Amiko, kiel vi envenis ĉi tien, ne havante edziĝofestan veston? Kaj li silentadis."],[22,13,"Tiam la reĝo diris al siaj servantoj: Ligu lin mane kaj piede, kaj elĵetu lin en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.","Tiam la reĝo diris al siaj servantoj: Ligu lin mane kaj piede, kaj elĵetu lin en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj."],[22,14,"Ĉar multaj estas vokitaj, sed malmultaj estas elektitaj.","Ĉar multaj estas vokitaj, sed malmultaj estas elektitaj."],[22,15,"Tiam iris la Fariseoj, kaj konsiliĝis, kiel ili povos impliki lin per interparolado.","Tiam iris la Fariseoj, kaj konsiliĝis, kiel ili povos impliki lin per interparolado."],[22,16,"Kaj ili sendis al li siajn disĉiplojn kun la Herodanoj, por diri: Majstro, ni scias, ke vi estas verama, kaj instruas laŭ vero la vojon de Dio, kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj.","Kaj ili sendis al li siajn disĉiplojn kun la Herodanoj, por diri: Majstro, ni scias, ke vi estas verama, kaj instruas laŭ vero la vojon de Dio, kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj."],[22,17,"Diru do al ni, kiel ŝajnas al vi? ĉu konvenas doni tributon al Cezaro, aŭ ne?","Diru do al ni, kiel ŝajnas al vi? ĉu konvenas doni tributon al Cezaro, aŭ ne?"],[22,18,"Sed Jesuo, sciante ilian ruzecon, diris: Kial vi min provas, hipokrituloj?","Sed Jesuo, sciante ilian ruzecon, diris: Kial vi min provas, hipokrituloj?"],[22,19,"Montru al mi la tributan moneron. Kaj ili alportis al li denaron.","Montru al mi la tributan moneron. Kaj ili alportis al li denaron."],[22,20,"Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo?","Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo?"],[22,21,"Ili diris al li: De Cezaro. Tiam li diris al ili: Redonu do al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio.","Ili diris al li: De Cezaro. Tiam li diris al ili: Redonu do al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio."],[22,22,"Kaj aŭdinte, ili miris, kaj lin lasis kaj foriris.","Kaj aŭdinte, ili miris, kaj lin lasis kaj foriris."],[22,23,"En tiu sama tago alvenis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:","En tiu sama tago alvenis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:"],[22,24,"Majstro, Moseo diris: Se iu mortas, ne havante infanojn, lia frato edziĝu kun lia edzino kaj naskigu idaron al sia frato.","Majstro, Moseo diris: Se iu mortas, ne havante infanojn, lia frato edziĝu kun lia edzino kaj naskigu idaron al sia frato."],[22,25,"Estis ĉe ni sep fratoj; kaj la unua edziĝis kaj mortis, kaj ne havante idaron, lasis sian edzinon al sia frato;","Estis ĉe ni sep fratoj; kaj la unua edziĝis kaj mortis, kaj ne havante idaron, lasis sian edzinon al sia frato;"],[22,26,"tiel same ankaŭ la dua, kaj la tria, ĝis la sepa.","tiel same ankaŭ la dua, kaj la tria, ĝis la sepa."],[22,27,"Kaj post ĉiuj la virino mortis.","Kaj post ĉiuj la virino mortis."],[22,28,"En la releviĝo do, por kiu el la sep ŝi estos edzino? ĉar ĉiuj ŝin havis.","En la releviĝo do, por kiu el la sep ŝi estos edzino? ĉar ĉiuj ŝin havis."],[22,29,"Sed Jesuo responde diris: Vi eraras, ne sciante la Skribojn, nek la potencon de Dio.","Sed Jesuo responde diris: Vi eraras, ne sciante la Skribojn, nek la potencon de Dio."],[22,30,"Ĉar en la releviĝo oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo.","Ĉar en la releviĝo oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo."],[22,31,"Sed pri la releviĝo el la mortintoj, ĉu vi ne legis tion, kio estis dirita al vi de Dio, nome:","Sed pri la releviĝo el la mortintoj, ĉu vi ne legis tion, kio estis dirita al vi de Dio, nome:"],[22,32,"Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob? Dio estas Dio ne de la mortintoj, sed de la vivantoj.","Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob? Dio estas Dio ne de la mortintoj, sed de la vivantoj."],[22,33,"Kaj kiam la homamaso tion aŭdis, ili miregis pro lia instruado.","Kaj kiam la homamaso tion aŭdis, ili miregis pro lia instruado."],[22,34,"Sed la Fariseoj, aŭdinte, ke li silentigis la Sadukeojn, kune kolektiĝis.","Sed la Fariseoj, aŭdinte, ke li silentigis la Sadukeojn, kune kolektiĝis."],[22,35,"Kaj unu el ili, leĝisto, demandis lin, provante lin:","Kaj unu el ili, leĝisto, demandis lin, provante lin:"],[22,36,"Majstro, kiu estas la granda ordono en la leĝo?","Majstro, kiu estas la granda ordono en la leĝo?"],[22,37,"Kaj li diris al li: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso.","Kaj li diris al li: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso."],[22,38,"Ĉi tiu estas la granda kaj la unua ordono.","Ĉi tiu estas la granda kaj la unua ordono."],[22,39,"Kaj dua estas simila al ĝi: Amu vian proksimulon kiel vin mem.","Kaj dua estas simila al ĝi: Amu vian proksimulon kiel vin mem."],[22,40,"De ĉi tiuj du ordonoj dependas la tuta leĝo kaj la profetoj.","De ĉi tiuj du ordonoj dependas la tuta leĝo kaj la profetoj."],[22,41,"Kaj kiam la Fariseoj jam kunvenis, Jesuo ilin demandis,","Kaj kiam la Fariseoj jam kunvenis, Jesuo ilin demandis,"],[22,42,"dirante: Kion vi pensas pri la Kristo? kies filo li estas? Ili diris al li: De David.","dirante: Kion vi pensas pri la Kristo? kies filo li estas? Ili diris al li: De David."],[22,43,"Li diris al ili: Kial do David, en la Spirito, lin nomas Sinjoro, dirante:","Li diris al ili: Kial do David, en la Spirito, lin nomas Sinjoro, dirante:"],[22,44,"La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?","La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?"],[22,45,"Se do David nomas lin Sinjoro, kiel li estas lia filo?","Se do David nomas lin Sinjoro, kiel li estas lia filo?"],[22,46,"Kaj neniu povis respondi unu vorton al li, nek iu post tiu tago plu kuraĝis fari al li demandon.","Kaj neniu povis respondi unu vorton al li, nek iu post tiu tago plu kuraĝis fari al li demandon."],[23,1,"Tiam parolis Jesuo al la homamasoj kaj al siaj disĉiploj, dirante:","Tiam parolis Jesuo al la homamasoj kaj al siaj disĉiploj, dirante:"],[23,2,"La skribistoj kaj la Fariseoj sidas sur la seĝo de Moseo:","La skribistoj kaj la Fariseoj sidas sur la seĝo de Moseo:"],[23,3,"ĉion do, kion ili ordonas al vi, faru kaj observu; sed ne agu laŭ iliaj faroj, ĉar ili ordonas, sed ne faras.","ĉion do, kion ili ordonas al vi, faru kaj observu; sed ne agu laŭ iliaj faroj, ĉar ili ordonas, sed ne faras."],[23,4,"Ili ligas pezajn ŝarĝojn malfacile porteblajn, kaj metas ilin sur la ŝultrojn de homoj; sed ili mem ne volas movi ilin per sia fingro.","Ili ligas pezajn ŝarĝojn malfacile porteblajn, kaj metas ilin sur la ŝultrojn de homoj; sed ili mem ne volas movi ilin per sia fingro."],[23,5,"Sed ĉiujn siajn agojn ili faras, por esti rigardataj de homoj; ĉar ili larĝigas siajn filakteriojn kaj grandigas la franĝojn de siaj vestoj,","Sed ĉiujn siajn agojn ili faras, por esti rigardataj de homoj; ĉar ili larĝigas siajn filakteriojn kaj grandigas la franĝojn de siaj vestoj,"],[23,6,"kaj amas la ĉeflokojn ĉe festenoj, kaj la ĉefseĝojn en la sinagogoj,","kaj amas la ĉeflokojn ĉe festenoj, kaj la ĉefseĝojn en la sinagogoj,"],[23,7,"kaj salutojn sur la placoj, kaj esti nomataj de homoj Rabeno.","kaj salutojn sur la placoj, kaj esti nomataj de homoj Rabeno."],[23,8,"Sed vi ne estu nomataj Rabeno; ĉar unu estas via instruanto, kaj vi ĉiuj estas fratoj.","Sed vi ne estu nomataj Rabeno; ĉar unu estas via instruanto, kaj vi ĉiuj estas fratoj."],[23,9,"Kaj nomu neniun sur la tero via patro; ĉar Unu, kiu estas en la ĉielo, estas via Patro.","Kaj nomu neniun sur la tero via patro; ĉar Unu, kiu estas en la ĉielo, estas via Patro."],[23,10,"Kaj ne estu nomataj edukantoj; ĉar unu, la Kristo, estas via edukanto.","Kaj ne estu nomataj edukantoj; ĉar unu, la Kristo, estas via edukanto."],[23,11,"Sed la pli granda el vi estos via servanto.","Sed la pli granda el vi estos via servanto."],[23,12,"Kaj kiu sin plialtigos, tiu estos humiligita; kaj kiu sin humiligos, tiu estos plialtigita.","Kaj kiu sin plialtigos, tiu estos humiligita; kaj kiu sin humiligos, tiu estos plialtigita."],[23,13,"Sed ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ŝlosas la regnon de la ĉielo kontraŭ la homoj; ĉar vi mem ne eniras, nek lasas al la enirantoj eniri.","Sed ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ŝlosas la regnon de la ĉielo kontraŭ la homoj; ĉar vi mem ne eniras, nek lasas al la enirantoj eniri."],[23,14,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi formanĝas domojn de vidvinoj, kaj por preteksto vi longe preĝas; tial vi ricevos pli severan kondamnon.","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi formanĝas domojn de vidvinoj, kaj por preteksto vi longe preĝas; tial vi ricevos pli severan kondamnon."],[23,15,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ĉirkaŭiras maron kaj teron, por varbi unu prozeliton; kaj kiam li tia fariĝis, vi lin faras filo de Gehena, duoble kiom vi mem.","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ĉirkaŭiras maron kaj teron, por varbi unu prozeliton; kaj kiam li tia fariĝis, vi lin faras filo de Gehena, duoble kiom vi mem."],[23,16,"Ve al vi, blindaj gvidantoj! kiuj diras: Se iu ĵuras per la sanktejo, tio estas nenio; sed kiu ĵuras per la oro de la sanktejo, tiu estas ŝuldanto.","Ve al vi, blindaj gvidantoj! kiuj diras: Se iu ĵuras per la sanktejo, tio estas nenio; sed kiu ĵuras per la oro de la sanktejo, tiu estas ŝuldanto."],[23,17,"Vi malsaĝaj kaj blindaj! ĉar kio estas pli granda, la oro, aŭ la sanktejo, kiu sanktigas la oron?","Vi malsaĝaj kaj blindaj! ĉar kio estas pli granda, la oro, aŭ la sanktejo, kiu sanktigas la oron?"],[23,18,"Kaj: Se iu ĵuras per la altaro, tio estas nenio; sed kiu ĵuras per la ofero, kuŝanta sur ĝi, tiu estas ŝuldanto.","Kaj: Se iu ĵuras per la altaro, tio estas nenio; sed kiu ĵuras per la ofero, kuŝanta sur ĝi, tiu estas ŝuldanto."],[23,19,"Vi blinduloj! ĉar kio estas pli granda, la ofero, aŭ la altaro, kiu sanktigas la oferon?","Vi blinduloj! ĉar kio estas pli granda, la ofero, aŭ la altaro, kiu sanktigas la oferon?"],[23,20,"Tiu do, kiu ĵuras per la altaro, ĵuras per ĝi, kaj per ĉio, kuŝanta sur ĝi.","Tiu do, kiu ĵuras per la altaro, ĵuras per ĝi, kaj per ĉio, kuŝanta sur ĝi."],[23,21,"Kaj tiu, kiu ĵuras per la sanktejo, ĵuras per ĝi, kaj per Tiu, kiu loĝas en ĝi.","Kaj tiu, kiu ĵuras per la sanktejo, ĵuras per ĝi, kaj per Tiu, kiu loĝas en ĝi."],[23,22,"Kaj tiu, kiu ĵuras per la ĉielo, ĵuras per la trono de Dio, kaj per Tiu, kiu sidas sur ĝi.","Kaj tiu, kiu ĵuras per la ĉielo, ĵuras per la trono de Dio, kaj per Tiu, kiu sidas sur ĝi."],[23,23,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi pagas dekonaĵojn de mento kaj de anizo kaj de kumino, kaj forlasis la pli gravajn aferojn de la leĝo: juĝon kaj kompaton kaj fidon. Sed ĉi tiujn vi devus fari, kaj la aliajn ne preterlasi.","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi pagas dekonaĵojn de mento kaj de anizo kaj de kumino, kaj forlasis la pli gravajn aferojn de la leĝo: juĝon kaj kompaton kaj fidon. Sed ĉi tiujn vi devus fari, kaj la aliajn ne preterlasi."],[23,24,"Vi blindaj gvidantoj! kiuj elkribras la kulon kaj glutas la kamelon.","Vi blindaj gvidantoj! kiuj elkribras la kulon kaj glutas la kamelon."],[23,25,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi purigas la eksteron de la kaliko kaj de la plado; sed interne ili estas plenaj de rabado kaj malmodereco.","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi purigas la eksteron de la kaliko kaj de la plado; sed interne ili estas plenaj de rabado kaj malmodereco."],[23,26,"Vi blinda Fariseo! purigu unue la internon de la kaliko kaj de la plado, por ke ilia ekstero ankaŭ fariĝu pura.","Vi blinda Fariseo! purigu unue la internon de la kaliko kaj de la plado, por ke ilia ekstero ankaŭ fariĝu pura."],[23,27,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi similas al tomboj blankigitaj, kiuj ekstere ŝajnas belaj, sed interne estas plenaj de ostoj de mortintoj kaj de ĉia malpureco.","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi similas al tomboj blankigitaj, kiuj ekstere ŝajnas belaj, sed interne estas plenaj de ostoj de mortintoj kaj de ĉia malpureco."],[23,28,"Tiel ankaŭ vi ekstere ŝajnas justaj antaŭ homoj, sed interne vi estas plenaj de hipokriteco kaj maljusteco.","Tiel ankaŭ vi ekstere ŝajnas justaj antaŭ homoj, sed interne vi estas plenaj de hipokriteco kaj maljusteco."],[23,29,"Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi konstruas la tombojn de la profetoj kaj ornamas la monumentojn de la justuloj, kaj diras:","Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi konstruas la tombojn de la profetoj kaj ornamas la monumentojn de la justuloj, kaj diras:"],[23,30,"Se ni vivus en la tagoj de niaj patroj, ni ne partoprenus kun ili en la sango de la profetoj.","Se ni vivus en la tagoj de niaj patroj, ni ne partoprenus kun ili en la sango de la profetoj."],[23,31,"Tial vi atestas pri vi mem, ke vi estas filoj de tiuj, kiuj mortigis la profetojn.","Tial vi atestas pri vi mem, ke vi estas filoj de tiuj, kiuj mortigis la profetojn."],[23,32,"Vi do plenigu la mezuron de viaj patroj.","Vi do plenigu la mezuron de viaj patroj."],[23,33,"Serpentoj, vipuridoj! kiel vi povos eviti la juĝon de Gehena?","Serpentoj, vipuridoj! kiel vi povos eviti la juĝon de Gehena?"],[23,34,"Jen do mi sendas al vi profetojn kaj saĝulojn kaj skribistojn; iujn el ili vi mortigos kaj krucumos, kaj aliajn el ili vi skurĝos en viaj sinagogoj kaj persekutos de urbo al urbo;","Jen do mi sendas al vi profetojn kaj saĝulojn kaj skribistojn; iujn el ili vi mortigos kaj krucumos, kaj aliajn el ili vi skurĝos en viaj sinagogoj kaj persekutos de urbo al urbo;"],[23,35,"por ke venu sur vin la tuta justa sango elverŝita sur la teron, de la sango de la justulo Habel ĝis la sango de Zeĥarja, filo de Bereĥja, kiun vi mortigis inter la sanktejo kaj la altaro.","por ke venu sur vin la tuta justa sango elverŝita sur la teron, de la sango de la justulo Habel ĝis la sango de Zeĥarja, filo de Bereĥja, kiun vi mortigis inter la sanktejo kaj la altaro."],[23,36,"Vere mi diras al vi: Ĉio tio venos sur ĉi tiun generacion.","Vere mi diras al vi: Ĉio tio venos sur ĉi tiun generacion."],[23,37,"Ho Jerusalem, Jerusalem, kiu mortigas la profetojn, kaj priĵetas per ŝtonoj tiujn, kiuj estas senditaj al ĝi! kiom ofte mi volis kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis.","Ho Jerusalem, Jerusalem, kiu mortigas la profetojn, kaj priĵetas per ŝtonoj tiujn, kiuj estas senditaj al ĝi! kiom ofte mi volis kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis."],[23,38,"Jen via domo estas lasita al vi dezerta.","Jen via domo estas lasita al vi dezerta."],[23,39,"Ĉar mi diras al vi: De nun vi ne vidos min, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo.","Ĉar mi diras al vi: De nun vi ne vidos min, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo."],[24,1,"Kaj Jesuo, elirinte, ekforiris de la templo; kaj liaj disĉiploj venis al li, por montri al li la konstruaĵojn de la templo.","Kaj Jesuo, elirinte, ekforiris de la templo; kaj liaj disĉiploj venis al li, por montri al li la konstruaĵojn de la templo."],[24,2,"Sed li responde diris al ili: Ĉu vi ne vidas ĉion tion? vere mi diras al vi: Ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.","Sed li responde diris al ili: Ĉu vi ne vidas ĉion tion? vere mi diras al vi: Ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita."],[24,3,"Kaj dum ili sidis sur la monto Olivarba, la disĉiploj venis aparte al li, dirante: Diru al ni, kiam tio estos? Kaj kio estas la signo de via alesto kaj de la maturiĝo de la mondaĝo?","Kaj dum ili sidis sur la monto Olivarba, la disĉiploj venis aparte al li, dirante: Diru al ni, kiam tio estos? Kaj kio estas la signo de via alesto kaj de la maturiĝo de la mondaĝo?"],[24,4,"Kaj Jesuo, respondante, diris al ili: Gardu vin, ke neniu vin forlogu.","Kaj Jesuo, respondante, diris al ili: Gardu vin, ke neniu vin forlogu."],[24,5,"Ĉar multaj venos en mia nomo, dirante: Mi estas la Kristo; kaj ili forlogos multajn.","Ĉar multaj venos en mia nomo, dirante: Mi estas la Kristo; kaj ili forlogos multajn."],[24,6,"Kaj vi aŭdos pri militoj kaj famoj de militoj. Zorgu, ke vi ne maltrankviliĝu; ĉar tio devas okazi; sed ankoraŭ ne estas la fino.","Kaj vi aŭdos pri militoj kaj famoj de militoj. Zorgu, ke vi ne maltrankviliĝu; ĉar tio devas okazi; sed ankoraŭ ne estas la fino."],[24,7,"Ĉar leviĝos nacio kontraŭ nacion, kaj regno kontraŭ regnon; kaj estos malsatoj kaj tertremoj en diversaj lokoj.","Ĉar leviĝos nacio kontraŭ nacion, kaj regno kontraŭ regnon; kaj estos malsatoj kaj tertremoj en diversaj lokoj."],[24,8,"Sed ĉio tio estas komenco de suferoj.","Sed ĉio tio estas komenco de suferoj."],[24,9,"Tiam oni transdonos vin al afliktado, kaj mortigos vin; kaj vi estos malamataj de ĉiuj nacioj pro mia nomo.","Tiam oni transdonos vin al afliktado, kaj mortigos vin; kaj vi estos malamataj de ĉiuj nacioj pro mia nomo."],[24,10,"Tiam multaj ofendiĝos, kaj perfidos unu la alian, kaj malamos unu la alian.","Tiam multaj ofendiĝos, kaj perfidos unu la alian, kaj malamos unu la alian."],[24,11,"Kaj multaj falsaj profetoj leviĝos, kaj forlogos multajn.","Kaj multaj falsaj profetoj leviĝos, kaj forlogos multajn."],[24,12,"Kaj pro la multobligo de maljusteco, la amo de la plimulto malvarmiĝos.","Kaj pro la multobligo de maljusteco, la amo de la plimulto malvarmiĝos."],[24,13,"Sed kiu persistos ĝis la fino, tiu estos savita.","Sed kiu persistos ĝis la fino, tiu estos savita."],[24,14,"Kaj ĉi tiu evangelio de la regno estos predikita tra la tuta mondo, kiel atesto al ĉiuj nacioj; kaj tiam venos la fino.","Kaj ĉi tiu evangelio de la regno estos predikita tra la tuta mondo, kiel atesto al ĉiuj nacioj; kaj tiam venos la fino."],[24,15,"Kiam do vi vidos la abomenindaĵon de dezerteco, pri kiu estas dirite de la profeto Daniel, starantan sur la sankta loko (la leganto komprenu),","Kiam do vi vidos la abomenindaĵon de dezerteco, pri kiu estas dirite de la profeto Daniel, starantan sur la sankta loko (la leganto komprenu),"],[24,16,"tiam tiuj, kiuj estas en Judujo, forkuru al la montoj;","tiam tiuj, kiuj estas en Judujo, forkuru al la montoj;"],[24,17,"kiu estas sur la tegmento, tiu ne malsupreniru, por preni ion el sia domo;","kiu estas sur la tegmento, tiu ne malsupreniru, por preni ion el sia domo;"],[24,18,"kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon.","kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon."],[24,19,"Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!","Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!"],[24,20,"Kaj preĝu, ke via forkurado ne estu en vintro nek en sabato;","Kaj preĝu, ke via forkurado ne estu en vintro nek en sabato;"],[24,21,"ĉar tiam estos granda aflikto tia, kia ne estis de la komenco de la mondo ĝis nun, nek iam estos.","ĉar tiam estos granda aflikto tia, kia ne estis de la komenco de la mondo ĝis nun, nek iam estos."],[24,22,"Kaj se tiuj tagoj ne estus mallongigitaj, neniu karno estus savita; sed pro la elektitoj tiuj tagoj estos mallongigitaj.","Kaj se tiuj tagoj ne estus mallongigitaj, neniu karno estus savita; sed pro la elektitoj tiuj tagoj estos mallongigitaj."],[24,23,"Tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ: Tie; ne kredu;","Tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ: Tie; ne kredu;"],[24,24,"ĉar leviĝos falsaj kristoj kaj falsaj profetoj kaj faros grandajn signojn kaj miraklojn, tiel ke ili forlogus, se eble, eĉ la elektitojn.","ĉar leviĝos falsaj kristoj kaj falsaj profetoj kaj faros grandajn signojn kaj miraklojn, tiel ke ili forlogus, se eble, eĉ la elektitojn."],[24,25,"Jen mi antaŭdiris al vi.","Jen mi antaŭdiris al vi."],[24,26,"Se oni do diros al vi: Jen li estas en la dezerto; ne eliru; aŭ: Jen li estas en sekretaj ĉambroj; ne kredu.","Se oni do diros al vi: Jen li estas en la dezerto; ne eliru; aŭ: Jen li estas en sekretaj ĉambroj; ne kredu."],[24,27,"Ĉar kiel la fulmo venas el la oriento kaj montriĝas ĝis la okcidento, tiel ankaŭ estos la alesto de la Filo de homo.","Ĉar kiel la fulmo venas el la oriento kaj montriĝas ĝis la okcidento, tiel ankaŭ estos la alesto de la Filo de homo."],[24,28,"Kie ajn estos la kadavro, tien kolektiĝos la agloj.","Kie ajn estos la kadavro, tien kolektiĝos la agloj."],[24,29,"Sed tuj post la aflikto de tiuj tagoj la suno mallumiĝos, kaj la luno ne donos sian lumon, kaj la steloj falos el la ĉielo, kaj la potencoj de la ĉielo ŝanceliĝos;","Sed tuj post la aflikto de tiuj tagoj la suno mallumiĝos, kaj la luno ne donos sian lumon, kaj la steloj falos el la ĉielo, kaj la potencoj de la ĉielo ŝanceliĝos;"],[24,30,"kaj tiam aperos sur la ĉielo la signo de la Filo de homo, kaj tiam ploros ĉiuj gentoj de la tero, kaj oni vidos la Filon de homo, venantan en la nuboj de la ĉielo kun potenco kaj granda gloro.","kaj tiam aperos sur la ĉielo la signo de la Filo de homo, kaj tiam ploros ĉiuj gentoj de la tero, kaj oni vidos la Filon de homo, venantan en la nuboj de la ĉielo kun potenco kaj granda gloro."],[24,31,"Kaj li elsendos siajn anĝelojn kun granda sono de trumpeto, kaj ili kolektos liajn elektitojn el la kvar ventoj, el limo ĝis limo de la ĉielo.","Kaj li elsendos siajn anĝelojn kun granda sono de trumpeto, kaj ili kolektos liajn elektitojn el la kvar ventoj, el limo ĝis limo de la ĉielo."],[24,32,"De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝis kaj aperigas foliojn, tiam vi scias, ke la somero estas proksima;","De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝis kaj aperigas foliojn, tiam vi scias, ke la somero estas proksima;"],[24,33,"tiel same vi, kiam vi vidos ĉion tion, tiam sciu, ke li estas proksima, ĉe la pordoj.","tiel same vi, kiam vi vidos ĉion tion, tiam sciu, ke li estas proksima, ĉe la pordoj."],[24,34,"Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio tio plenumiĝos.","Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio tio plenumiĝos."],[24,35,"La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.","La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos."],[24,36,"Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj de la ĉielo, nek la Filo, sed la Patro sola.","Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj de la ĉielo, nek la Filo, sed la Patro sola."],[24,37,"Sed kiel la tagoj de Noa, tiel estos la alesto de la Filo de homo.","Sed kiel la tagoj de Noa, tiel estos la alesto de la Filo de homo."],[24,38,"Ĉar kiel dum la tagoj, kiuj estis antaŭ la diluvo, oni manĝis kaj trinkis, edziĝis kaj edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon,","Ĉar kiel dum la tagoj, kiuj estis antaŭ la diluvo, oni manĝis kaj trinkis, edziĝis kaj edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon,"],[24,39,"kaj oni ne eksciis, ĝis la diluvo venis kaj forprenis ĉiujn; tiel estos la alesto de la Filo de homo.","kaj oni ne eksciis, ĝis la diluvo venis kaj forprenis ĉiujn; tiel estos la alesto de la Filo de homo."],[24,40,"Tiam du viroj estos sur kampo: unu estos prenita, kaj la alia lasita;","Tiam du viroj estos sur kampo: unu estos prenita, kaj la alia lasita;"],[24,41,"du virinoj estos muelantaj apud muelilo: unu estos prenita, kaj la alia lasita.","du virinoj estos muelantaj apud muelilo: unu estos prenita, kaj la alia lasita."],[24,42,"Tial viglu; ĉar vi ne scias, en kiu tago via Sinjoro venos.","Tial viglu; ĉar vi ne scias, en kiu tago via Sinjoro venos."],[24,43,"Sed sciu tion, ke se la dommastro scius, en kiu gardoparto venos la ŝtelisto, li viglus kaj ne lasus sian domon trafosiĝi.","Sed sciu tion, ke se la dommastro scius, en kiu gardoparto venos la ŝtelisto, li viglus kaj ne lasus sian domon trafosiĝi."],[24,44,"Tial vi ankaŭ estu pretaj; ĉar en horo, kiam vi ne atendas, la Filo de homo venas.","Tial vi ankaŭ estu pretaj; ĉar en horo, kiam vi ne atendas, la Filo de homo venas."],[24,45,"Kiu do estas la fidela kaj prudenta servisto, kiun la sinjoro starigis super siajn domanojn, por doni al ili nutraĵon ĝustatempe?","Kiu do estas la fidela kaj prudenta servisto, kiun la sinjoro starigis super siajn domanojn, por doni al ili nutraĵon ĝustatempe?"],[24,46,"Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos tiel faranta.","Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos tiel faranta."],[24,47,"Vere mi diras al vi, ke super sian tutan havon li starigos lin.","Vere mi diras al vi, ke super sian tutan havon li starigos lin."],[24,48,"Sed se tiu malbona servisto diros en sia koro: Mia sinjoro malfruas;","Sed se tiu malbona servisto diros en sia koro: Mia sinjoro malfruas;"],[24,49,"kaj komencos bati siajn kunservistojn, kaj manĝi kaj trinki kun la drinkuloj,","kaj komencos bati siajn kunservistojn, kaj manĝi kaj trinki kun la drinkuloj,"],[24,50,"la sinjoro de tiu servisto venos en tago, kiam li ne atendas, kaj en horo, kiam li ne scias,","la sinjoro de tiu servisto venos en tago, kiam li ne atendas, kaj en horo, kiam li ne scias,"],[24,51,"kaj distranĉos lin, kaj difinos lian parton kun la hipokrituloj; tie estos la plorado kaj la grincado de dentoj.","kaj distranĉos lin, kaj difinos lian parton kun la hipokrituloj; tie estos la plorado kaj la grincado de dentoj."],[25,1,"Tiam la regno de la ĉielo estos komparata al dek virgulinoj, kiuj prenis siajn lampojn kaj eliris renkonte al la fianĉo.","Tiam la regno de la ĉielo estos komparata al dek virgulinoj, kiuj prenis siajn lampojn kaj eliris renkonte al la fianĉo."],[25,2,"Kaj kvin el ili estis malprudentaj, kaj kvin estis prudentaj.","Kaj kvin el ili estis malprudentaj, kaj kvin estis prudentaj."],[25,3,"La malprudentaj, prenante la lampojn, ne prenis oleon kun si;","La malprudentaj, prenante la lampojn, ne prenis oleon kun si;"],[25,4,"sed la prudentaj prenis oleon en la vazoj kun siaj lampoj.","sed la prudentaj prenis oleon en la vazoj kun siaj lampoj."],[25,5,"Kaj kiam la fianĉo malfruis, ili ĉiuj malviglis kaj dormis.","Kaj kiam la fianĉo malfruis, ili ĉiuj malviglis kaj dormis."],[25,6,"Sed je la noktomezo estis ekkrio: Jen la fianĉo! eliru al li renkonte.","Sed je la noktomezo estis ekkrio: Jen la fianĉo! eliru al li renkonte."],[25,7,"Tiam ĉiuj tiuj virgulinoj leviĝis, kaj ordigis siajn lampojn.","Tiam ĉiuj tiuj virgulinoj leviĝis, kaj ordigis siajn lampojn."],[25,8,"Kaj la malprudentaj diris al la prudentaj: Donu al ni el via oleo, ĉar niaj lampoj estingiĝas.","Kaj la malprudentaj diris al la prudentaj: Donu al ni el via oleo, ĉar niaj lampoj estingiĝas."],[25,9,"Sed la prudentaj respondis, dirante: Eble ne estos sufiĉe por ni kaj vi; iru prefere al la vendistoj, kaj aĉetu por vi mem.","Sed la prudentaj respondis, dirante: Eble ne estos sufiĉe por ni kaj vi; iru prefere al la vendistoj, kaj aĉetu por vi mem."],[25,10,"Kaj dum ili iris, por aĉeti, alvenis la fianĉo; kaj tiuj, kiuj estis pretaj, eniris kun li al la edziĝa festo, kaj la pordo estis fermita.","Kaj dum ili iris, por aĉeti, alvenis la fianĉo; kaj tiuj, kiuj estis pretaj, eniris kun li al la edziĝa festo, kaj la pordo estis fermita."],[25,11,"Poste venis ankaŭ la ceteraj virgulinoj, dirante: Sinjoro, sinjoro, malfermu al ni.","Poste venis ankaŭ la ceteraj virgulinoj, dirante: Sinjoro, sinjoro, malfermu al ni."],[25,12,"Sed li responde diris: Vere mi diras al vi: Mi vin ne konas.","Sed li responde diris: Vere mi diras al vi: Mi vin ne konas."],[25,13,"Tial viglu, ĉar vi ne scias la tagon nek la horon.","Tial viglu, ĉar vi ne scias la tagon nek la horon."],[25,14,"Ĉar tiel estas, kvazaŭ viro, forvojaĝonte, alvokis siajn servistojn, kaj komisiis al ili siajn posedaĵojn.","Ĉar tiel estas, kvazaŭ viro, forvojaĝonte, alvokis siajn servistojn, kaj komisiis al ili siajn posedaĵojn."],[25,15,"Kaj al unu li donis kvin talantojn, al alia du, al alia unu; al ĉiu laŭ lia kapableco; kaj li tuj forvojaĝis.","Kaj al unu li donis kvin talantojn, al alia du, al alia unu; al ĉiu laŭ lia kapableco; kaj li tuj forvojaĝis."],[25,16,"Kaj tiu, kiu ricevis la kvin talantojn, iris kaj negocadis per ili, kaj gajnis pluajn kvin talantojn.","Kaj tiu, kiu ricevis la kvin talantojn, iris kaj negocadis per ili, kaj gajnis pluajn kvin talantojn."],[25,17,"Tiel same ankaŭ tiu, kiu ricevis la du, gajnis pluajn du.","Tiel same ankaŭ tiu, kiu ricevis la du, gajnis pluajn du."],[25,18,"Sed tiu, kiu ricevis la unu, foriris kaj fosis en la tero, kaj kaŝis la monon de sia sinjoro.","Sed tiu, kiu ricevis la unu, foriris kaj fosis en la tero, kaj kaŝis la monon de sia sinjoro."],[25,19,"Kaj post longa tempo la sinjoro de tiuj servistoj venis, kaj faris kun ili kalkulon.","Kaj post longa tempo la sinjoro de tiuj servistoj venis, kaj faris kun ili kalkulon."],[25,20,"Kaj tiu, kiu ricevis la kvin talantojn, venis kaj alportis pluajn kvin talantojn, dirante: Sinjoro, vi komisiis al mi kvin talantojn; jen mi gajnis pluajn kvin talantojn.","Kaj tiu, kiu ricevis la kvin talantojn, venis kaj alportis pluajn kvin talantojn, dirante: Sinjoro, vi komisiis al mi kvin talantojn; jen mi gajnis pluajn kvin talantojn."],[25,21,"Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro.","Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro."],[25,22,"Kaj venis ankaŭ tiu, kiu ricevis la du talantojn, kaj diris: Sinjoro, vi komisiis al mi du talantojn; jen mi gajnis pluajn du talantojn.","Kaj venis ankaŭ tiu, kiu ricevis la du talantojn, kaj diris: Sinjoro, vi komisiis al mi du talantojn; jen mi gajnis pluajn du talantojn."],[25,23,"Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro.","Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro."],[25,24,"Kaj venis ankaŭ tiu, kiu ricevis la unu talanton, kaj diris: Sinjoro, mi sciis, ke vi estas severa homo, rikoltanta, kie vi ne semis, kaj kolektanta, kie vi ne disŝutis;","Kaj venis ankaŭ tiu, kiu ricevis la unu talanton, kaj diris: Sinjoro, mi sciis, ke vi estas severa homo, rikoltanta, kie vi ne semis, kaj kolektanta, kie vi ne disŝutis;"],[25,25,"kaj mi timis, kaj foriris, kaj kaŝis vian talanton en la tero; jen vi havas vian propraĵon.","kaj mi timis, kaj foriris, kaj kaŝis vian talanton en la tero; jen vi havas vian propraĵon."],[25,26,"Sed lia sinjoro responde diris al li: Vi malbona kaj mallaborema servisto, vi sciis, ke mi rikoltas, kie mi ne semis, kaj kolektas, kie mi ne disŝutis;","Sed lia sinjoro responde diris al li: Vi malbona kaj mallaborema servisto, vi sciis, ke mi rikoltas, kie mi ne semis, kaj kolektas, kie mi ne disŝutis;"],[25,27,"pro tio vi devus doni mian monon al la bankistoj, kaj veninte, mi ricevus mian propraĵon kun procento.","pro tio vi devus doni mian monon al la bankistoj, kaj veninte, mi ricevus mian propraĵon kun procento."],[25,28,"Forprenu de li do la talanton, kaj donu ĝin al tiu, kiu havas la dek talantojn.","Forprenu de li do la talanton, kaj donu ĝin al tiu, kiu havas la dek talantojn."],[25,29,"Ĉar al ĉiu, kiu havas, estos donite, kaj li havos abundegon; sed for de tiu, kiu ne havas, eĉ tio, kion li havas, estos prenita.","Ĉar al ĉiu, kiu havas, estos donite, kaj li havos abundegon; sed for de tiu, kiu ne havas, eĉ tio, kion li havas, estos prenita."],[25,30,"Kaj elĵetu la senutilan serviston en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.","Kaj elĵetu la senutilan serviston en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj."],[25,31,"Sed kiam la Filo de homo venos en sia gloro, kaj ĉiuj anĝeloj kun li, tiam li sidos sur la trono de sia gloro;","Sed kiam la Filo de homo venos en sia gloro, kaj ĉiuj anĝeloj kun li, tiam li sidos sur la trono de sia gloro;"],[25,32,"kaj antaŭ li kolektiĝos ĉiuj nacioj, kaj li apartigos ilin unu de alia, kiel paŝtisto apartigas la ŝafojn for de la kaproj;","kaj antaŭ li kolektiĝos ĉiuj nacioj, kaj li apartigos ilin unu de alia, kiel paŝtisto apartigas la ŝafojn for de la kaproj;"],[25,33,"kaj li starigos la ŝafojn dekstre de li, kaj la kaprojn maldekstre.","kaj li starigos la ŝafojn dekstre de li, kaj la kaprojn maldekstre."],[25,34,"Tiam diros la Reĝo al tiuj, kiuj staras dekstre de li: Venu, vi benataj de mia Patro, heredu la regnon preparitan por vi de post la komenco de la mondo;","Tiam diros la Reĝo al tiuj, kiuj staras dekstre de li: Venu, vi benataj de mia Patro, heredu la regnon preparitan por vi de post la komenco de la mondo;"],[25,35,"ĉar mi malsatis, kaj vi donis al mi manĝi; mi soifis, kaj vi donis al mi trinki; mi estis fremda, kaj vi gastigis min;","ĉar mi malsatis, kaj vi donis al mi manĝi; mi soifis, kaj vi donis al mi trinki; mi estis fremda, kaj vi gastigis min;"],[25,36,"nuda, kaj vi vestis min; mi malsanis, kaj vi vizitis min; mi estis en malliberejo, kaj vi venis al mi.","nuda, kaj vi vestis min; mi malsanis, kaj vi vizitis min; mi estis en malliberejo, kaj vi venis al mi."],[25,37,"Tiam respondos al li la justuloj, dirante: Sinjoro, kiam ni vin vidis malsata, kaj vin satigis? aŭ soifanta, kaj trinkigis vin?","Tiam respondos al li la justuloj, dirante: Sinjoro, kiam ni vin vidis malsata, kaj vin satigis? aŭ soifanta, kaj trinkigis vin?"],[25,38,"Kaj kiam ni vidis vin fremda kaj gastigis vin? aŭ nuda, kaj vin vestis?","Kaj kiam ni vidis vin fremda kaj gastigis vin? aŭ nuda, kaj vin vestis?"],[25,39,"Kaj kiam ni vidis vin malsana aŭ en malliberejo, kaj venis al vi?","Kaj kiam ni vidis vin malsana aŭ en malliberejo, kaj venis al vi?"],[25,40,"Kaj la Reĝo respondos kaj diros al ili: Vere mi diras al vi: Kiom vi faris al unu el ĉi tiuj miaj fratoj la plej malgrandaj, tiom vi faris al mi.","Kaj la Reĝo respondos kaj diros al ili: Vere mi diras al vi: Kiom vi faris al unu el ĉi tiuj miaj fratoj la plej malgrandaj, tiom vi faris al mi."],[25,41,"Tiam li diros al tiuj, kiuj staras maldekstre: For de mi, vi malbenitaj, en la eternan fajron, kiu estas preparita por la diablo kaj liaj anĝeloj;","Tiam li diros al tiuj, kiuj staras maldekstre: For de mi, vi malbenitaj, en la eternan fajron, kiu estas preparita por la diablo kaj liaj anĝeloj;"],[25,42,"ĉar mi malsatis, kaj vi ne donis al mi manĝi; mi soifis, kaj vi ne donis al mi trinki;","ĉar mi malsatis, kaj vi ne donis al mi manĝi; mi soifis, kaj vi ne donis al mi trinki;"],[25,43,"mi estis fremda, kaj vi ne gastigis min; nuda, kaj vi ne vestis min; malsana kaj en malliberejo, kaj vi ne vizitis min.","mi estis fremda, kaj vi ne gastigis min; nuda, kaj vi ne vestis min; malsana kaj en malliberejo, kaj vi ne vizitis min."],[25,44,"Tiam ili ankaŭ respondos, dirante: Sinjoro, kiam ni vidis vin malsata, aŭ soifanta, aŭ fremda, aŭ nuda, aŭ malsana, aŭ en malliberejo, kaj ne servis al vi?","Tiam ili ankaŭ respondos, dirante: Sinjoro, kiam ni vidis vin malsata, aŭ soifanta, aŭ fremda, aŭ nuda, aŭ malsana, aŭ en malliberejo, kaj ne servis al vi?"],[25,45,"Tiam li respondos al ili, dirante: Vere mi diras al vi: Kiom vi ne faris al unu el ĉi tiuj la plej malgrandaj, tiom vi ne faris al mi.","Tiam li respondos al ili, dirante: Vere mi diras al vi: Kiom vi ne faris al unu el ĉi tiuj la plej malgrandaj, tiom vi ne faris al mi."],[25,46,"Kaj ĉi tiuj foriros en eternan punon, sed la justuloj en eternan vivon.","Kaj ĉi tiuj foriros en eternan punon, sed la justuloj en eternan vivon."],[26,1,"Kaj kiam Jesuo finis ĉiujn tiujn vortojn, li diris al siaj disĉiploj:","Kaj kiam Jesuo finis ĉiujn tiujn vortojn, li diris al siaj disĉiploj:"],[26,2,"Vi scias, ke post du tagoj okazos la Pasko, kaj la Filo de homo estos transdonita, por esti krucumita.","Vi scias, ke post du tagoj okazos la Pasko, kaj la Filo de homo estos transdonita, por esti krucumita."],[26,3,"Tiam kunvenis la ĉefpastroj kaj la pliaĝuloj de la popolo, en la korto de la ĉefpastro, kies nomo estis Kajafas;","Tiam kunvenis la ĉefpastroj kaj la pliaĝuloj de la popolo, en la korto de la ĉefpastro, kies nomo estis Kajafas;"],[26,4,"kaj ili konsiliĝis, por ke ili povu per ruzo kapti Jesuon, kaj mortigi lin.","kaj ili konsiliĝis, por ke ili povu per ruzo kapti Jesuon, kaj mortigi lin."],[26,5,"Sed ili diris: Ne dum la festo, por ke ne leviĝu tumulto ĉe la popolo.","Sed ili diris: Ne dum la festo, por ke ne leviĝu tumulto ĉe la popolo."],[26,6,"Kaj kiam Jesuo estis en Betania, en la domo de Simon, leprulo,","Kaj kiam Jesuo estis en Betania, en la domo de Simon, leprulo,"],[26,7,"venis al li virino, havanta alabastran vazon da multekosta ŝmiraĵo, kaj ŝi verŝis ĝin sur lian kapon, dum li sidis ĉe manĝo.","venis al li virino, havanta alabastran vazon da multekosta ŝmiraĵo, kaj ŝi verŝis ĝin sur lian kapon, dum li sidis ĉe manĝo."],[26,8,"Sed kiam la disĉiploj tion vidis, ili indignis, dirante:","Sed kiam la disĉiploj tion vidis, ili indignis, dirante:"],[26,9,"Por kio estas ĉi tiu malŝparo? Ĉar ĉi tiun ŝmiraĵon oni povus vendi por granda prezo, kaj doni al malriĉuloj.","Por kio estas ĉi tiu malŝparo? Ĉar ĉi tiun ŝmiraĵon oni povus vendi por granda prezo, kaj doni al malriĉuloj."],[26,10,"Sed Jesuo, tion sciante, diris al ili: Kial vi ĝenas la virinon? ŝi faris bonan faron al mi.","Sed Jesuo, tion sciante, diris al ili: Kial vi ĝenas la virinon? ŝi faris bonan faron al mi."],[26,11,"Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas.","Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas."],[26,12,"Ĉar verŝante ĉi tiun ŝmiraĵon sur mian korpon, ŝi tion faris por mia entombigo.","Ĉar verŝante ĉi tiun ŝmiraĵon sur mian korpon, ŝi tion faris por mia entombigo."],[26,13,"Vere mi diras al vi: Kie ajn estos predikata ĉi tiu evangelio en la tuta mondo, tio ankaŭ, kion faris ĉi tiu virino, estos priparolata, por memoraĵo de ŝi.","Vere mi diras al vi: Kie ajn estos predikata ĉi tiu evangelio en la tuta mondo, tio ankaŭ, kion faris ĉi tiu virino, estos priparolata, por memoraĵo de ŝi."],[26,14,"Tiam unu el la dek du, nomata Judas Iskariota, iris al la ĉefpastroj,","Tiam unu el la dek du, nomata Judas Iskariota, iris al la ĉefpastroj,"],[26,15,"kaj diris: Kion vi volas doni al mi, se mi lin transdonos al vi? Kaj ili pesis por li tridek arĝentajn monerojn.","kaj diris: Kion vi volas doni al mi, se mi lin transdonos al vi? Kaj ili pesis por li tridek arĝentajn monerojn."],[26,16,"Kaj de tiam li serĉis okazon, por transdoni lin.","Kaj de tiam li serĉis okazon, por transdoni lin."],[26,17,"Kaj en la unua tago de macoj la disĉiploj venis al Jesuo, dirante: Kie vi volas, ke ni pretigu por vi, por manĝi la Paskon?","Kaj en la unua tago de macoj la disĉiploj venis al Jesuo, dirante: Kie vi volas, ke ni pretigu por vi, por manĝi la Paskon?"],[26,18,"Kaj li diris: Iru en la urbon al trovotulo, kaj diru al li: La Majstro diras: Mia tempo estas proksima; mi faros la Paskon ĉe vi, kun miaj disĉiploj.","Kaj li diris: Iru en la urbon al trovotulo, kaj diru al li: La Majstro diras: Mia tempo estas proksima; mi faros la Paskon ĉe vi, kun miaj disĉiploj."],[26,19,"Kaj la disĉiploj faris, kiel Jesuo ordonis al ili, kaj ili pretigis la Paskon.","Kaj la disĉiploj faris, kiel Jesuo ordonis al ili, kaj ili pretigis la Paskon."],[26,20,"Kaj kiam vesperiĝis, li sidis ĉe manĝo kun la dek du disĉiploj;","Kaj kiam vesperiĝis, li sidis ĉe manĝo kun la dek du disĉiploj;"],[26,21,"kaj dum ili manĝis, li diris: Vere mi diras al vi, ke unu el vi perfidos min.","kaj dum ili manĝis, li diris: Vere mi diras al vi, ke unu el vi perfidos min."],[26,22,"Kaj ili tre malĝojis, kaj ĉiu komencis diri al li: Sinjoro, ĉu eble mi?","Kaj ili tre malĝojis, kaj ĉiu komencis diri al li: Sinjoro, ĉu eble mi?"],[26,23,"Kaj li respondis kaj diris: Tiu, kiu trempis kun mi la manon en la pladon, perfidos min.","Kaj li respondis kaj diris: Tiu, kiu trempis kun mi la manon en la pladon, perfidos min."],[26,24,"La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! se tiu homo ne estus naskita, estus bone por li.","La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! se tiu homo ne estus naskita, estus bone por li."],[26,25,"Kaj Judas, kiu estis lin perfidonta, responde diris: Ĉu eble mi, Rabeno? Li diris al li: Vi diris.","Kaj Judas, kiu estis lin perfidonta, responde diris: Ĉu eble mi, Rabeno? Li diris al li: Vi diris."],[26,26,"Kaj dum ili manĝis, Jesuo prenis panon, kaj beninte, dispecigis ĝin kaj donis al la disĉiploj, kaj diris: Prenu, manĝu; ĉi tio estas mia korpo.","Kaj dum ili manĝis, Jesuo prenis panon, kaj beninte, dispecigis ĝin kaj donis al la disĉiploj, kaj diris: Prenu, manĝu; ĉi tio estas mia korpo."],[26,27,"Kaj li prenis kalikon, kaj doninte dankon, donis al ili, dirante: Vi ĉiuj trinku el ĝi;","Kaj li prenis kalikon, kaj doninte dankon, donis al ili, dirante: Vi ĉiuj trinku el ĝi;"],[26,28,"ĉar ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj, por la pardonado de pekoj.","ĉar ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj, por la pardonado de pekoj."],[26,29,"Sed mi diras al vi: De nun mi ne trinkos el ĉi tiu frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan kun vi en la regno de mia Patro.","Sed mi diras al vi: De nun mi ne trinkos el ĉi tiu frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan kun vi en la regno de mia Patro."],[26,30,"Kaj kantinte himnon, ili foriris al la monto Olivarba.","Kaj kantinte himnon, ili foriris al la monto Olivarba."],[26,31,"Tiam diris Jesuo al ili: Vi ĉiuj ofendiĝos pro mi dum ĉi tiu nokto; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj de la grego diskuros.","Tiam diris Jesuo al ili: Vi ĉiuj ofendiĝos pro mi dum ĉi tiu nokto; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj de la grego diskuros."],[26,32,"Tamen, post mia releviĝo mi iros antaŭ vi en Galileon.","Tamen, post mia releviĝo mi iros antaŭ vi en Galileon."],[26,33,"Sed Petro responde diris al li: Eĉ se ĉiuj ofendiĝos pro vi, mi neniam ofendiĝos.","Sed Petro responde diris al li: Eĉ se ĉiuj ofendiĝos pro vi, mi neniam ofendiĝos."],[26,34,"Jesuo diris al li: Vere mi diras al vi, ke en ĉi tiu nokto, antaŭ ol krios koko, vi trifoje malkonfesos min.","Jesuo diris al li: Vere mi diras al vi, ke en ĉi tiu nokto, antaŭ ol krios koko, vi trifoje malkonfesos min."],[26,35,"Petro diris al li: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Tiel same diris ĉiuj disĉiploj.","Petro diris al li: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Tiel same diris ĉiuj disĉiploj."],[26,36,"Tiam venis Jesuo kun ili al loko nomata Getsemane, kaj diris al siaj disĉiploj: Sidiĝu ĉi tie, dum mi iros tien, por preĝi.","Tiam venis Jesuo kun ili al loko nomata Getsemane, kaj diris al siaj disĉiploj: Sidiĝu ĉi tie, dum mi iros tien, por preĝi."],[26,37,"Kaj li prenis kun si Petron kaj la du filojn de Zebedeo, kaj komencis malĝoji kaj maltrankviliĝi.","Kaj li prenis kun si Petron kaj la du filojn de Zebedeo, kaj komencis malĝoji kaj maltrankviliĝi."],[26,38,"Tiam li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu kun mi.","Tiam li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu kun mi."],[26,39,"Kaj irinte iom antaŭen, li falis sur sian vizaĝon, preĝante, kaj dirante: Ho mia Patro, se povas esti, ĉi tiu kaliko pasu for de mi; tamen ne kiel mi volas, sed kiel Vi volas.","Kaj irinte iom antaŭen, li falis sur sian vizaĝon, preĝante, kaj dirante: Ho mia Patro, se povas esti, ĉi tiu kaliko pasu for de mi; tamen ne kiel mi volas, sed kiel Vi volas."],[26,40,"Kaj li venis al la disĉiploj kaj trovis ilin dormantaj, kaj diris al Petro: Ĉu vi do ne havis forton vigli kun mi eĉ unu horon?","Kaj li venis al la disĉiploj kaj trovis ilin dormantaj, kaj diris al Petro: Ĉu vi do ne havis forton vigli kun mi eĉ unu horon?"],[26,41,"Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta.","Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta."],[26,42,"Denove la duan fojon foririnte, li preĝis, dirante: Ho mia Patro, se ĉi tio ne povos forpasi, krom se mi trinkos ĝin, Via volo plenumiĝu.","Denove la duan fojon foririnte, li preĝis, dirante: Ho mia Patro, se ĉi tio ne povos forpasi, krom se mi trinkos ĝin, Via volo plenumiĝu."],[26,43,"Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis.","Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis."],[26,44,"Kaj li denove lasis ilin kaj foriris, kaj la trian fojon preĝis, denove dirante la samajn vortojn.","Kaj li denove lasis ilin kaj foriris, kaj la trian fojon preĝis, denove dirante la samajn vortojn."],[26,45,"Tiam li venis al la disĉiploj, kaj diris al ili: Dormu nun kaj ripozu: jen la horo alproksimiĝis, kaj la Filo de homo estas perfidata en la manojn de pekuloj.","Tiam li venis al la disĉiploj, kaj diris al ili: Dormu nun kaj ripozu: jen la horo alproksimiĝis, kaj la Filo de homo estas perfidata en la manojn de pekuloj."],[26,46,"Leviĝu, ni iru; jen mia perfidanto alproksimiĝas.","Leviĝu, ni iru; jen mia perfidanto alproksimiĝas."],[26,47,"Kaj dum li ankoraŭ parolis, jen venis Judas, unu el la dek du; kaj kun li granda homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj pliaĝuloj de la popolo.","Kaj dum li ankoraŭ parolis, jen venis Judas, unu el la dek du; kaj kun li granda homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj pliaĝuloj de la popolo."],[26,48,"Kaj lia perfidanto jam aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu lin.","Kaj lia perfidanto jam aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu lin."],[26,49,"Kaj tuj veninte al Jesuo, li diris: Saluton, Rabeno; kaj kisis lin.","Kaj tuj veninte al Jesuo, li diris: Saluton, Rabeno; kaj kisis lin."],[26,50,"Kaj Jesuo diris al li: Amiko, por kio vi venis? Tiam ili venis, kaj metis manojn sur Jesuon kaj arestis lin.","Kaj Jesuo diris al li: Amiko, por kio vi venis? Tiam ili venis, kaj metis manojn sur Jesuon kaj arestis lin."],[26,51,"Kaj jen unu el tiuj, kiuj estis kun Jesuo, etendis sian manon kaj eltiris sian glavon, kaj frapis la sklavon de la ĉefpastro, kaj detranĉis lian orelon.","Kaj jen unu el tiuj, kiuj estis kun Jesuo, etendis sian manon kaj eltiris sian glavon, kaj frapis la sklavon de la ĉefpastro, kaj detranĉis lian orelon."],[26,52,"Tiam diris Jesuo al li: Remetu vian glavon en ĝian ingon; ĉar ĉiuj, kiuj glavon prenas, per glavo pereos.","Tiam diris Jesuo al li: Remetu vian glavon en ĝian ingon; ĉar ĉiuj, kiuj glavon prenas, per glavo pereos."],[26,53,"Ĉu vi do supozas, ke mi ne povas alvoki mian Patron, kaj Li tuj liveros al mi pli ol dek du legiojn da anĝeloj?","Ĉu vi do supozas, ke mi ne povas alvoki mian Patron, kaj Li tuj liveros al mi pli ol dek du legiojn da anĝeloj?"],[26,54,"Sed kiel plenumiĝus la Skriboj, ke tiel devas okazi?","Sed kiel plenumiĝus la Skriboj, ke tiel devas okazi?"],[26,55,"En tiu horo Jesuo diris al la homamasoj: Ĉu vi elvenis kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min? Ĉiutage mi sidis en la templo, instruante, kaj vi ne arestis min.","En tiu horo Jesuo diris al la homamasoj: Ĉu vi elvenis kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min? Ĉiutage mi sidis en la templo, instruante, kaj vi ne arestis min."],[26,56,"Sed ĉio tio okazis, por ke plenumiĝu la Skriboj de la profetoj. Tiam ĉiuj disĉiploj forlasis lin kaj forkuris.","Sed ĉio tio okazis, por ke plenumiĝu la Skriboj de la profetoj. Tiam ĉiuj disĉiploj forlasis lin kaj forkuris."],[26,57,"Kaj la arestintoj de Jesuo forkondukis lin al la domo de la ĉefpastro Kajafas, kie jam kolektiĝis la skribistoj kaj pliaĝuloj.","Kaj la arestintoj de Jesuo forkondukis lin al la domo de la ĉefpastro Kajafas, kie jam kolektiĝis la skribistoj kaj pliaĝuloj."],[26,58,"Sed Petro malproksime sekvis lin ĝis la korto de la ĉefpastro, kaj eniris, kaj sidis kun la subuloj, por vidi la finon.","Sed Petro malproksime sekvis lin ĝis la korto de la ĉefpastro, kaj eniris, kaj sidis kun la subuloj, por vidi la finon."],[26,59,"Kaj la ĉefpastroj kaj la tuta sinedrio serĉis malveran ateston kontraŭ Jesuo, por ke ili povu lin mortigi;","Kaj la ĉefpastroj kaj la tuta sinedrio serĉis malveran ateston kontraŭ Jesuo, por ke ili povu lin mortigi;"],[26,60,"kaj ne trovis, kvankam multaj malveraj atestantoj venis. Sed poste venis du, kaj diris:","kaj ne trovis, kvankam multaj malveraj atestantoj venis. Sed poste venis du, kaj diris:"],[26,61,"Ĉi tiu diris: Mi povas detrui la sanktejon de Dio, kaj rekonstrui ĝin en la daŭro de tri tagoj.","Ĉi tiu diris: Mi povas detrui la sanktejon de Dio, kaj rekonstrui ĝin en la daŭro de tri tagoj."],[26,62,"Kaj la ĉefpastro stariĝis, kaj diris al li: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?","Kaj la ĉefpastro stariĝis, kaj diris al li: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?"],[26,63,"Sed Jesuo silentadis. Kaj la ĉefpastro diris al li: Mi ĵurligas vin per Dio la vivanta, ke vi diru al ni, ĉu vi estas la Kristo, la Filo de Dio.","Sed Jesuo silentadis. Kaj la ĉefpastro diris al li: Mi ĵurligas vin per Dio la vivanta, ke vi diru al ni, ĉu vi estas la Kristo, la Filo de Dio."],[26,64,"Jesuo diris al li: Vi diris; tamen mi diras al vi: Poste vi vidos la Filon de homo, sidantan ĉe la dekstra mano de la Potenco, kaj venantan sur la nuboj de la ĉielo.","Jesuo diris al li: Vi diris; tamen mi diras al vi: Poste vi vidos la Filon de homo, sidantan ĉe la dekstra mano de la Potenco, kaj venantan sur la nuboj de la ĉielo."],[26,65,"Tiam la ĉefpastro disŝiris siajn vestojn, dirante: Li blasfemis; por kio ni plu bezonas atestantojn? jen nun vi aŭdis la blasfemon:","Tiam la ĉefpastro disŝiris siajn vestojn, dirante: Li blasfemis; por kio ni plu bezonas atestantojn? jen nun vi aŭdis la blasfemon:"],[26,66,"kion vi opinias? Ili respondis kaj diris: Li estas kondamninda al morto.","kion vi opinias? Ili respondis kaj diris: Li estas kondamninda al morto."],[26,67,"Tiam oni kraĉis sur lian vizaĝon kaj vangofrapis lin, kaj iuj frapis lin per la manplatoj,","Tiam oni kraĉis sur lian vizaĝon kaj vangofrapis lin, kaj iuj frapis lin per la manplatoj,"],[26,68,"dirante: Profetu al ni, ho Kristo, kiu vin frapis?","dirante: Profetu al ni, ho Kristo, kiu vin frapis?"],[26,69,"Kaj Petro sidis ekstere sur la korto; kaj venis al li unu servantino, dirante: Vi ankaŭ estis kun Jesuo, la Galileano.","Kaj Petro sidis ekstere sur la korto; kaj venis al li unu servantino, dirante: Vi ankaŭ estis kun Jesuo, la Galileano."],[26,70,"Sed li malkonfesis antaŭ ili ĉiuj, dirante: Mi ne scias, kion vi diras.","Sed li malkonfesis antaŭ ili ĉiuj, dirante: Mi ne scias, kion vi diras."],[26,71,"Kaj post kiam li eliris en la vestiblon, alia vidis lin, kaj diris al la ĉeestantoj: Ĉi tiu estis ankaŭ kun Jesuo, la Nazaretano.","Kaj post kiam li eliris en la vestiblon, alia vidis lin, kaj diris al la ĉeestantoj: Ĉi tiu estis ankaŭ kun Jesuo, la Nazaretano."],[26,72,"Kaj denove li malkonfesis kun ĵuro: Mi ne konas tiun homon.","Kaj denove li malkonfesis kun ĵuro: Mi ne konas tiun homon."],[26,73,"Kaj post iom da tempo la apudstarantoj venis, kaj diris al Petro: Vere vi ankaŭ estas el ili, ĉar via parolmaniero malkaŝas vin.","Kaj post iom da tempo la apudstarantoj venis, kaj diris al Petro: Vere vi ankaŭ estas el ili, ĉar via parolmaniero malkaŝas vin."],[26,74,"Tiam li komencis malbeni kaj ĵuri: Mi ne konas tiun homon. Kaj tuj koko kriis.","Tiam li komencis malbeni kaj ĵuri: Mi ne konas tiun homon. Kaj tuj koko kriis."],[26,75,"Kaj Petro rememoris la vorton, kiun Jesuo parolis: Antaŭ ol krios koko, vi trifoje malkonfesos min. Kaj li eliris, kaj maldolĉe ploris.","Kaj Petro rememoris la vorton, kiun Jesuo parolis: Antaŭ ol krios koko, vi trifoje malkonfesos min. Kaj li eliris, kaj maldolĉe ploris."],[27,1,"Kaj kiam venis la mateno, ĉiuj ĉefpastroj kaj pliaĝuloj de la popolo konsiliĝis kontraŭ Jesuo, por mortigi lin;","Kaj kiam venis la mateno, ĉiuj ĉefpastroj kaj pliaĝuloj de la popolo konsiliĝis kontraŭ Jesuo, por mortigi lin;"],[27,2,"kaj ili ligis lin, kaj forkondukis lin kaj transdonis lin al Pilato, la provincestro.","kaj ili ligis lin, kaj forkondukis lin kaj transdonis lin al Pilato, la provincestro."],[27,3,"Tiam Judas, lia perfidinto, vidinte, ke li estas kondamnita, pentis, kaj reportis la tridek arĝentajn monerojn al la ĉefpastroj kaj la pliaĝuloj,","Tiam Judas, lia perfidinto, vidinte, ke li estas kondamnita, pentis, kaj reportis la tridek arĝentajn monerojn al la ĉefpastroj kaj la pliaĝuloj,"],[27,4,"dirante: Mi pekis, perfidante senkulpan sangon. Sed ili diris: Kiel tio koncernas nin? vi zorgu pri tio.","dirante: Mi pekis, perfidante senkulpan sangon. Sed ili diris: Kiel tio koncernas nin? vi zorgu pri tio."],[27,5,"Kaj li ĵetis la arĝentajn monerojn en la sanktejon, kaj eliris; kaj foririnte, pendigis sin.","Kaj li ĵetis la arĝentajn monerojn en la sanktejon, kaj eliris; kaj foririnte, pendigis sin."],[27,6,"Kaj la ĉefpastroj prenis la arĝentajn monerojn, kaj diris: Ne konvenas meti ilin en la trezorejon, ĉar tio estas prezo de sango.","Kaj la ĉefpastroj prenis la arĝentajn monerojn, kaj diris: Ne konvenas meti ilin en la trezorejon, ĉar tio estas prezo de sango."],[27,7,"Kaj ili konsiliĝis, kaj aĉetis per ili la kampon de la potisto, por enterigi fremdulojn.","Kaj ili konsiliĝis, kaj aĉetis per ili la kampon de la potisto, por enterigi fremdulojn."],[27,8,"Tial tiu kampo estas nomata Kampo de Sango, ankoraŭ ĝis hodiaŭ.","Tial tiu kampo estas nomata Kampo de Sango, ankoraŭ ĝis hodiaŭ."],[27,9,"Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome: Kaj ili prenis la tridek arĝentajn monerojn, taksoprezon de tiu, kiu estis taksita, kiujn iuj el la filoj de Izrael taksis;","Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome: Kaj ili prenis la tridek arĝentajn monerojn, taksoprezon de tiu, kiu estis taksita, kiujn iuj el la filoj de Izrael taksis;"],[27,10,"kaj donis ilin por la kampo de la potisto, kiel la Eternulo difinis al mi.","kaj donis ilin por la kampo de la potisto, kiel la Eternulo difinis al mi."],[27,11,"Kaj Jesuo staris antaŭ la provincestro; kaj la estro demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj Jesuo diris al li: Vi diras.","Kaj Jesuo staris antaŭ la provincestro; kaj la estro demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj Jesuo diris al li: Vi diras."],[27,12,"Kaj kiam la ĉefpastroj kaj pliaĝuloj akuzis lin, li respondis nenion.","Kaj kiam la ĉefpastroj kaj pliaĝuloj akuzis lin, li respondis nenion."],[27,13,"Tiam Pilato diris al li: Ĉu vi ne aŭdas, kiom da aferoj oni atestas kontraŭ vi?","Tiam Pilato diris al li: Ĉu vi ne aŭdas, kiom da aferoj oni atestas kontraŭ vi?"],[27,14,"Kaj li ne respondis al li eĉ unu vorton, tiel ke la provincestro tre forte miris.","Kaj li ne respondis al li eĉ unu vorton, tiel ke la provincestro tre forte miris."],[27,15,"Sed ĉe tiu festo la provincestro kutimis liberigi al la homamaso unu malliberulon, kiun ili deziris.","Sed ĉe tiu festo la provincestro kutimis liberigi al la homamaso unu malliberulon, kiun ili deziris."],[27,16,"Kaj oni havis tiam faman malliberulon, nomatan Barabas.","Kaj oni havis tiam faman malliberulon, nomatan Barabas."],[27,17,"Kiam do ili kolektiĝis, Pilato diris al ili: Kiun vi deziras, ke mi liberigu al vi? ĉu Barabason, aŭ Jesuon, nomatan Kristo?","Kiam do ili kolektiĝis, Pilato diris al ili: Kiun vi deziras, ke mi liberigu al vi? ĉu Barabason, aŭ Jesuon, nomatan Kristo?"],[27,18,"Ĉar li sciis, ke pro envio ili transdonis lin.","Ĉar li sciis, ke pro envio ili transdonis lin."],[27,19,"Kaj dum li sidis sur la tribunala seĝo, lia edzino sendis al li, por diri: Nenion havu kun tiu justulo, ĉar mi suferis multe hodiaŭ en sonĝo kaŭze de li.","Kaj dum li sidis sur la tribunala seĝo, lia edzino sendis al li, por diri: Nenion havu kun tiu justulo, ĉar mi suferis multe hodiaŭ en sonĝo kaŭze de li."],[27,20,"Kaj la ĉefpastroj kaj pliaĝuloj decidigis la homamason postuli Barabason kaj pereigi Jesuon.","Kaj la ĉefpastroj kaj pliaĝuloj decidigis la homamason postuli Barabason kaj pereigi Jesuon."],[27,21,"Sed la provincestro responde diris al ili: Kiun el la du vi volas, ke mi liberigu al vi? Kaj ili diris: Barabason.","Sed la provincestro responde diris al ili: Kiun el la du vi volas, ke mi liberigu al vi? Kaj ili diris: Barabason."],[27,22,"Pilato diris al ili: Kion do mi faros al Jesuo, nomata Kristo? Ĉiuj diris: Li estu krucumita.","Pilato diris al ili: Kion do mi faros al Jesuo, nomata Kristo? Ĉiuj diris: Li estu krucumita."],[27,23,"Kaj li diris: Kial? kian malbonon li faris? Sed ili des pli ekkriis, dirante: Li estu krucumita.","Kaj li diris: Kial? kian malbonon li faris? Sed ili des pli ekkriis, dirante: Li estu krucumita."],[27,24,"Tial Pilato, vidante, ke neniel prosperas al li, sed ke kontraŭe tumulto leviĝas, prenis akvon kaj lavis siajn manojn antaŭ la homamaso, dirante: Mi estas senkulpa pri la sango de tiu justulo: vi zorgu pri ĝi.","Tial Pilato, vidante, ke neniel prosperas al li, sed ke kontraŭe tumulto leviĝas, prenis akvon kaj lavis siajn manojn antaŭ la homamaso, dirante: Mi estas senkulpa pri la sango de tiu justulo: vi zorgu pri ĝi."],[27,25,"Kaj la tuta popolo responde diris: Lia sango estu sur ni kaj sur niaj infanoj.","Kaj la tuta popolo responde diris: Lia sango estu sur ni kaj sur niaj infanoj."],[27,26,"Tiam li liberigis al ili Barabason; sed skurĝinte Jesuon, li transdonis lin, por esti krucumita.","Tiam li liberigis al ili Barabason; sed skurĝinte Jesuon, li transdonis lin, por esti krucumita."],[27,27,"Tiam la soldatoj de la provincestro, kondukinte Jesuon en la palacon, kolektis al li la tutan kohorton.","Tiam la soldatoj de la provincestro, kondukinte Jesuon en la palacon, kolektis al li la tutan kohorton."],[27,28,"Kaj ili senvestigis lin, kaj surmetis al li skarlatan mantelon.","Kaj ili senvestigis lin, kaj surmetis al li skarlatan mantelon."],[27,29,"Kaj ili plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj metis kanon en lian dekstran manon; kaj ili genuis antaŭ li, kaj mokis lin, dirante: Saluton, Reĝo de la Judoj!","Kaj ili plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj metis kanon en lian dekstran manon; kaj ili genuis antaŭ li, kaj mokis lin, dirante: Saluton, Reĝo de la Judoj!"],[27,30,"Kaj ili kraĉis sur lin, kaj prenis la kanon kaj frapis lian kapon.","Kaj ili kraĉis sur lin, kaj prenis la kanon kaj frapis lian kapon."],[27,31,"Kaj mokinte lin, ili demetis de li la mantelon, kaj surmetis al li liajn proprajn vestojn, kaj forkondukis lin, por krucumi lin.","Kaj mokinte lin, ili demetis de li la mantelon, kaj surmetis al li liajn proprajn vestojn, kaj forkondukis lin, por krucumi lin."],[27,32,"Kaj elirinte, ili trovis viron Kirenanon, nomatan Simon; tiun ili devigis, ke li portu lian krucon.","Kaj elirinte, ili trovis viron Kirenanon, nomatan Simon; tiun ili devigis, ke li portu lian krucon."],[27,33,"Kaj veninte al loko nomata Golgota, tio estas, Loko de Kranio,","Kaj veninte al loko nomata Golgota, tio estas, Loko de Kranio,"],[27,34,"ili donis al li trinki vinon kun galo enmiksita; kaj li gustumis ĝin, kaj ne volis trinki.","ili donis al li trinki vinon kun galo enmiksita; kaj li gustumis ĝin, kaj ne volis trinki."],[27,35,"Kaj krucuminte lin, ili dividis inter si liajn vestojn, ĵetante lotojn;","Kaj krucuminte lin, ili dividis inter si liajn vestojn, ĵetante lotojn;"],[27,36,"kaj ili sidiĝis, kaj gardis lin tie.","kaj ili sidiĝis, kaj gardis lin tie."],[27,37,"Kaj ili metis super lia kapo lian akuzon, skribitan: ĈI TIU ESTAS JESUO, LA REĜO DE LA JUDOJ.","Kaj ili metis super lia kapo lian akuzon, skribitan: ĈI TIU ESTAS JESUO, LA REĜO DE LA JUDOJ."],[27,38,"Tiam kun li estis krucumitaj du rabistoj, unu dekstre kaj unu maldekstre.","Tiam kun li estis krucumitaj du rabistoj, unu dekstre kaj unu maldekstre."],[27,39,"Kaj la preterpasantoj insultis lin, balancante la kapon,","Kaj la preterpasantoj insultis lin, balancante la kapon,"],[27,40,"kaj dirante: Vi, kiu detruas la sanktejon kaj rekonstruas ĝin en la daŭro de tri tagoj, savu vin. Se vi estas la Filo de Dio, deiru de la kruco.","kaj dirante: Vi, kiu detruas la sanktejon kaj rekonstruas ĝin en la daŭro de tri tagoj, savu vin. Se vi estas la Filo de Dio, deiru de la kruco."],[27,41,"Tiel same ankaŭ la ĉefpastroj, mokante kun la skribistoj kaj la pliaĝuloj, diris:","Tiel same ankaŭ la ĉefpastroj, mokante kun la skribistoj kaj la pliaĝuloj, diris:"],[27,42,"Aliajn li savis; sin mem li ne povas savi. Li ja estas Reĝo de Izrael, li nun deiru de la kruco, kaj ni kredos al li.","Aliajn li savis; sin mem li ne povas savi. Li ja estas Reĝo de Izrael, li nun deiru de la kruco, kaj ni kredos al li."],[27,43,"Li apogis sin al Dio; Tiu savu lin, se Li amas lin; ĉar li diris: Mi estas la Filo de Dio.","Li apogis sin al Dio; Tiu savu lin, se Li amas lin; ĉar li diris: Mi estas la Filo de Dio."],[27,44,"Kaj ankaŭ la rabistoj, kiuj estis krucumitaj kun li, tiel same insultis lin.","Kaj ankaŭ la rabistoj, kiuj estis krucumitaj kun li, tiel same insultis lin."],[27,45,"Kaj de post la sesa horo fariĝis mallumo sur la tuta lando ĝis la naŭa horo.","Kaj de post la sesa horo fariĝis mallumo sur la tuta lando ĝis la naŭa horo."],[27,46,"Kaj ĉirkaŭ la naŭa horo Jesuo ekkriis per laŭta voĉo, dirante: Eli, Eli, lama sabaĥtani? tio estas: Mia Dio, mia Dio, kial Vi forlasis min?","Kaj ĉirkaŭ la naŭa horo Jesuo ekkriis per laŭta voĉo, dirante: Eli, Eli, lama sabaĥtani? tio estas: Mia Dio, mia Dio, kial Vi forlasis min?"],[27,47,"Kaj iuj el la apudstarantoj, aŭdinte tion, diris: Ĉi tiu vokas Elijan.","Kaj iuj el la apudstarantoj, aŭdinte tion, diris: Ĉi tiu vokas Elijan."],[27,48,"Kaj tuj unu el ili kuris kaj prenis spongon kaj plenigis ĝin per vinagro, kaj metinte ĝin sur kanon, donis al li trinki.","Kaj tuj unu el ili kuris kaj prenis spongon kaj plenigis ĝin per vinagro, kaj metinte ĝin sur kanon, donis al li trinki."],[27,49,"Kaj la aliaj diris: Lasu; ni vidu, ĉu venos Elija, por savi lin.","Kaj la aliaj diris: Lasu; ni vidu, ĉu venos Elija, por savi lin."],[27,50,"Kaj Jesuo, denove kriinte per laŭta voĉo, ellasis for la spiriton.","Kaj Jesuo, denove kriinte per laŭta voĉo, ellasis for la spiriton."],[27,51,"Kaj jen la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre; kaj la tero tremis; kaj la rokoj diskrevis;","Kaj jen la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre; kaj la tero tremis; kaj la rokoj diskrevis;"],[27,52,"kaj la tomboj malfermiĝis, kaj multaj korpoj de dormantaj sanktuloj leviĝis,","kaj la tomboj malfermiĝis, kaj multaj korpoj de dormantaj sanktuloj leviĝis,"],[27,53,"kaj elirinte el la tomboj post lia releviĝo, ili eniris en la sanktan urbon kaj aperis al multaj.","kaj elirinte el la tomboj post lia releviĝo, ili eniris en la sanktan urbon kaj aperis al multaj."],[27,54,"Kaj la centestro, kaj tiuj, kiuj estis kun li gardantaj Jesuon, kiam ili vidis la tertremon kaj la okazantaĵojn, tre timis, dirante: Vere ĉi tiu estis Filo de Dio.","Kaj la centestro, kaj tiuj, kiuj estis kun li gardantaj Jesuon, kiam ili vidis la tertremon kaj la okazantaĵojn, tre timis, dirante: Vere ĉi tiu estis Filo de Dio."],[27,55,"Kaj tie estis multaj virinoj, rigardantaj de malproksime, kiuj sekvis Jesuon el Galileo, servante al li;","Kaj tie estis multaj virinoj, rigardantaj de malproksime, kiuj sekvis Jesuon el Galileo, servante al li;"],[27,56,"inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo kaj de Joses, kaj la patrino de la filoj de Zebedeo.","inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo kaj de Joses, kaj la patrino de la filoj de Zebedeo."],[27,57,"Kaj kiam vesperiĝis, venis riĉulo, nomata Jozef, el Arimateo, kiu mem estis disĉiplo de Jesuo:","Kaj kiam vesperiĝis, venis riĉulo, nomata Jozef, el Arimateo, kiu mem estis disĉiplo de Jesuo:"],[27,58,"tiu, irinte al Pilato, petis la korpon de Jesuo. Tiam Pilato ordonis doni ĝin.","tiu, irinte al Pilato, petis la korpon de Jesuo. Tiam Pilato ordonis doni ĝin."],[27,59,"Kaj Jozef prenis la korpon, kaj envolvis ĝin en pura tolaĵo,","Kaj Jozef prenis la korpon, kaj envolvis ĝin en pura tolaĵo,"],[27,60,"kaj metis ĝin en sian novan tombon, kiun li jam elhakis en la roko; kaj li alrulis grandan ŝtonon al la enirejo de la tombo, kaj foriris.","kaj metis ĝin en sian novan tombon, kiun li jam elhakis en la roko; kaj li alrulis grandan ŝtonon al la enirejo de la tombo, kaj foriris."],[27,61,"Kaj Maria Magdalena estis tie, kaj la alia Maria, sidantaj apud la tombo.","Kaj Maria Magdalena estis tie, kaj la alia Maria, sidantaj apud la tombo."],[27,62,"La sekvantan tagon, kiu estas la tago post la Preparado, la ĉefpastroj kaj la Fariseoj kolektiĝis al Pilato,","La sekvantan tagon, kiu estas la tago post la Preparado, la ĉefpastroj kaj la Fariseoj kolektiĝis al Pilato,"],[27,63,"dirante: Sinjoro, ni ekrememoras, ke tiu trompanto diris, dum li ankoraŭ vivis: Post tri tagoj mi releviĝos.","dirante: Sinjoro, ni ekrememoras, ke tiu trompanto diris, dum li ankoraŭ vivis: Post tri tagoj mi releviĝos."],[27,64,"Ordonu do, ke oni gardu la tombon ĝis la tria tago, por ke liaj disĉiploj ne venu kaj ne forŝtelu lin kaj ne diru al la popolo: Li releviĝis el la mortintoj; kaj la lasta trompo estus pli malbona, ol la unua.","Ordonu do, ke oni gardu la tombon ĝis la tria tago, por ke liaj disĉiploj ne venu kaj ne forŝtelu lin kaj ne diru al la popolo: Li releviĝis el la mortintoj; kaj la lasta trompo estus pli malbona, ol la unua."],[27,65,"Pilato diris al ili: Vi havas gardistaron; iru, kaj gardu ĝin laŭ via eblo.","Pilato diris al ili: Vi havas gardistaron; iru, kaj gardu ĝin laŭ via eblo."],[27,66,"Tial ili foriris kaj gardis la tombon, sigelinte la ŝtonon, kune kun gardistaro.","Tial ili foriris kaj gardis la tombon, sigelinte la ŝtonon, kune kun gardistaro."],[28,1,"Kaj sabate malfrue, kiam eklumis por la unua tago de la semajno, venis Maria Magdalena kaj la alia Maria, por vidi la tombon.","Kaj sabate malfrue, kiam eklumis por la unua tago de la semajno, venis Maria Magdalena kaj la alia Maria, por vidi la tombon."],[28,2,"Kaj jen okazis granda tertremo; ĉar anĝelo de la Eternulo malsupreniris el la ĉielo, kaj venis kaj derulis la ŝtonon, kaj sidiĝis sur ĝi.","Kaj jen okazis granda tertremo; ĉar anĝelo de la Eternulo malsupreniris el la ĉielo, kaj venis kaj derulis la ŝtonon, kaj sidiĝis sur ĝi."],[28,3,"Lia aspekto estis kiel fulmo, kaj lia vestaĵo estis blanka, kiel neĝo;","Lia aspekto estis kiel fulmo, kaj lia vestaĵo estis blanka, kiel neĝo;"],[28,4,"kaj pro timo al li la gardistoj tremis, kaj fariĝis kiel malvivuloj.","kaj pro timo al li la gardistoj tremis, kaj fariĝis kiel malvivuloj."],[28,5,"Kaj la anĝelo responde diris al la virinoj: Ne timu; ĉar mi scias, ke vi serĉas Jesuon, la krucumitan.","Kaj la anĝelo responde diris al la virinoj: Ne timu; ĉar mi scias, ke vi serĉas Jesuon, la krucumitan."],[28,6,"Li ne estas ĉi tie; ĉar li leviĝis, kiel li diris. Venu, vidu la lokon, kie la Sinjoro kuŝis.","Li ne estas ĉi tie; ĉar li leviĝis, kiel li diris. Venu, vidu la lokon, kie la Sinjoro kuŝis."],[28,7,"Kaj iru rapide, kaj diru al liaj disĉiploj: Li leviĝis el la mortintoj, kaj jen li iras antaŭ vi en Galileon; tie vi vidos lin; jen mi sciigis al vi.","Kaj iru rapide, kaj diru al liaj disĉiploj: Li leviĝis el la mortintoj, kaj jen li iras antaŭ vi en Galileon; tie vi vidos lin; jen mi sciigis al vi."],[28,8,"Kaj ili rapide foriris de la tombo kun timo kaj granda ĝojo, kaj kuris, por sciigi al liaj disĉiploj.","Kaj ili rapide foriris de la tombo kun timo kaj granda ĝojo, kaj kuris, por sciigi al liaj disĉiploj."],[28,9,"Kaj jen Jesuo renkontis ilin, dirante: Saluton. Kaj alveninte, ili ekprenis liajn piedojn kaj adorkliniĝis al li.","Kaj jen Jesuo renkontis ilin, dirante: Saluton. Kaj alveninte, ili ekprenis liajn piedojn kaj adorkliniĝis al li."],[28,10,"Tiam Jesuo diris al ili: Ne timu; iru, diru al miaj fratoj, ke ili foriru en Galileon, kaj tie ili min vidos.","Tiam Jesuo diris al ili: Ne timu; iru, diru al miaj fratoj, ke ili foriru en Galileon, kaj tie ili min vidos."],[28,11,"Kaj dum ili iris, iuj el la gardistoj venis en la urbon, kaj rakontis al la ĉefpastroj ĉiujn okazintaĵojn.","Kaj dum ili iris, iuj el la gardistoj venis en la urbon, kaj rakontis al la ĉefpastroj ĉiujn okazintaĵojn."],[28,12,"Kaj kunveninte kun la pliaĝuloj, ili konsiliĝis kune, kaj ili donis al la soldatoj multe da mono,","Kaj kunveninte kun la pliaĝuloj, ili konsiliĝis kune, kaj ili donis al la soldatoj multe da mono,"],[28,13,"dirante: Diru: Liaj disĉiploj venis nokte, kaj forŝtelis lin, dum ni dormis.","dirante: Diru: Liaj disĉiploj venis nokte, kaj forŝtelis lin, dum ni dormis."],[28,14,"Kaj se la provincestro tion aŭdos, ni konvinkos lin, kaj liberigos vin de ĉia zorgo.","Kaj se la provincestro tion aŭdos, ni konvinkos lin, kaj liberigos vin de ĉia zorgo."],[28,15,"Kaj ili prenis la monon, kaj faris, kiel ili estis instruitaj; kaj tiu diro disvastiĝis inter la Judoj ĝis hodiaŭ.","Kaj ili prenis la monon, kaj faris, kiel ili estis instruitaj; kaj tiu diro disvastiĝis inter la Judoj ĝis hodiaŭ."],[28,16,"Sed la dek unu disĉiploj iris en Galileon, sur la monton, kiun Jesuo jam difinis al ili.","Sed la dek unu disĉiploj iris en Galileon, sur la monton, kiun Jesuo jam difinis al ili."],[28,17,"Kaj kiam ili vidis lin, ili adorkliniĝis al li; sed kelkaj dubis.","Kaj kiam ili vidis lin, ili adorkliniĝis al li; sed kelkaj dubis."],[28,18,"Kaj Jesuo venis al ili, kaj diris al ili: Estas donita al mi ĉia aŭtoritato en la ĉielo kaj sur la tero.","Kaj Jesuo venis al ili, kaj diris al ili: Estas donita al mi ĉia aŭtoritato en la ĉielo kaj sur la tero."],[28,19,"Iru do kaj disĉipligu ĉiujn naciojn, baptante ilin en la nomon de la Patro kaj de la Filo kaj de la Sankta Spirito;","Iru do kaj disĉipligu ĉiujn naciojn, baptante ilin en la nomon de la Patro kaj de la Filo kaj de la Sankta Spirito;"],[28,20,"instruante ilin observi ĉion, kion mi ordonis al vi. Kaj jen mi estas kun vi ĉiujn tagojn, ĝis la maturiĝo de la mondaĝo.","instruante ilin observi ĉion, kion mi ordonis al vi. Kaj jen mi estas kun vi ĉiujn tagojn, ĝis la maturiĝo de la mondaĝo."]]}};